INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('UselessXu/mino/summarize', 'summarize', 'UselessXu', 'mino', 'community', 'summarize UselessXu mino community The summarize skill provides a fast CLI to summarize URLs, local files, and YouTube links, benefiting developers and users seeking quick content insights. Summarize 是一个快速的 CLI 工具，用于摘要 URL、本地文件和 YouTube 链接。支持 Google Gemini-3-Flash-Preview 模型 Summarize は、URL、ローカルファイル、YouTube リンクを高速に要約する CLI ツールです。Google Gemini-3-Flash-Preview モデルをサポート Summarize는 URL, 로컬 파일 및 YouTube 링크를 빠르게 요약하는 CLI 도구입니다. Google Gemini-3-Flash-Preview 모델 지원 Summarize es una herramienta de línea de comandos para resumir contenido de URLs, archivos locales y enlaces de YouTube. Soporta modelos como google/gemini-3-flash-preview Summarize est un outil en ligne de commande pour résumer du contenu d''URL, de fichiers locaux et de liens YouTube. Il prend en charge des modèles tels que google/gemini-3-flash-preview Summarize ist ein Kommandozeilen-Tool, um Inhalte von URLs, lokalen Dateien und YouTube-Links zusammenzufassen. Es unterstützt Modelle wie google/gemini-3-flash-preview O Summarize é uma ferramenta de linha de comando para sumarizar URLs, arquivos locais e links do YouTube. Ele suporta modelos como o google/gemini-3-flash-preview. Summarize - это быстрый CLI для суммаризации URL, локальных файлов и ссылок на YouTube. Он поддерживает модели như google/gemini-3-flash-preview для ИИ Агентов. ملخص هو أداة سطر أوامر لملخص الروابط والملفات المحلية وروابط يوتيوب. يدعم نماذج مثل google/gemini-3-flash-preview لأدوات الذكاء الاصطناعي. how to use summarize summarize alternative summarize setup guide summarize vs transcript what is summarize summarize install summarize CLI commands summarize YouTube links summarize local files Summarize AI 工具 快速摘要 URL 要약 本地文件要약 YouTube 链接要약 Google Gemini-3-Flash-Preview CLI 工具 AI 技术 Summarizes URLs using the google/gemini-3-flash-preview model Supports local file summarization via CLI commands Extracts best-effort transcripts from YouTube links without yt-dlp Utilizes the summarize.sh command for easy execution Compatible with file formats like PDF Summarize is a fast CLI tool that extracts key information from URLs, local files, and YouTube links using models like google/gemini-3-flash-preview.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jawsbaek/openclaw-agent-configs/github-trending', 'community', 'jawsbaek', 'openclaw-agent-configs', 'jawsbaek/openclaw-agent-configs', 'github-trending', 0, 0, 57, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:42.233Z', 'e66fac42b7b5f3f3d521d65380493c2ccd2e5271869b4c04da6f8a86fbeb85f5', '{"id":"jawsbaek/openclaw-agent-configs/github-trending","name":"github-trending","description":{"en":"The github-trending skill allows developers to discover trending repositories on GitHub, filtered by language, date range, or topic, enabling efficient monitoring and response.","zh":"GitHub Trending 是一个多代理人编排系统，用于基础设施监控、事件响应和负载测试，支持 Web 抓取和 GitHub CLI 两种方法","ja":"GitHub Trending は、インフラストラクチャの 監視、インシデント対応、負荷テストを行うためのマルチエージェントオーケストレーションシステムであり、Web スクレイピングと GitHub CLI の 2 つの方法をサポートしています","ko":"GitHub Trending은 인프라 모니터링, 인시던트 응답 및 부하 테스트를 위한 멀티 에이전트 오케스트레이션 시스템으로 웹 스크레이핑 및 GitHub CLI 두 가지 방법을 지원합니다","es":"github-trending es un sistema de orquestación de agentes múltiples para monitorear la infraestructura y responder a incidentes con agentes AI autónomos","fr":"github-trending est un système d''orchestration d''agents multiples pour surveiller l''infrastructure et répondre aux incidents avec des agents AI autonomes","de":"github-trending ist ein System zur Orchestrierung mehrerer Agenten für die Überwachung der Infrastruktur und die Reaktion auf Incidenten mit autonomen AI-Agents","pt":"O GitHub Trending é um sistema de orquestração de multi-agentes para monitoramento de infraestrutura e resposta a incidentes com agentes AI autônomos","ru":"GitHub Trending - это система оркестровки многоагентной системы для мониторинга инфраструктуры и реагирования на инциденты с помощью автономных ИИ Агентов","ar":"GitHub Trending هو نظام أوركسترالية متعدد الوكلاء لمراقبة البنية التحتية واستجابة الحوادث مع وكلاء ذكاء اصطناعي مستقلين"},"seo":{"title":{"en":"github-trending: Trending Repository Setup Guide | AI Age...","zh":"GitHub Trending 设置指南 - 使用 AI 工具发现趋势仓库","ja":"GitHub Trending セットアップガイド - AI エージェントを使用したトレンドリポジトリの発見","ko":"GitHub Trending 설정 가이드 - AI 툴을 사용하여 트렌드 저장소 발견","es":"Guía de configuración de github-trending para descubrir r...","fr":"Guide de mise en route de github-trending pour découvrir ...","de":"Einrichtungsanleitung für github-trending zum Entdecken v...","pt":"Guia de Configuração do GitHub Trending: Descubra Reposit...","ru":"Настройка GitHub Trending: Поиск популярных репозиториев ...","ar":"دليل إعداد GitHub Trending: اكتشف المستودعات الشائعة مع أ..."},"description":{"en":"Unlock the power of GitHub Trending with our AI agent skill. Discover trending repos, filter by language, and more. Get started now!","zh":"使用 GitHub Trending AI 工具发现最热门的仓库，按语言、日期范围或主题进行筛选，提升开发效率","ja":"GitHub Trending AI エージェントを使用して最も人気のあるリポジトリを発見し、言語、日付範囲、またはトピックでフィルタリングして開発効率を向上させる","ko":"GitHub Trending AI 툴을 사용하여 가장 인기 있는 저장소를 발견하고 언어, 날짜 범위 또는 주제로 필터링하여 개발 효율성을 높입니다","es":"Descubre cómo configurar github-trending para monitorear la infraestructura y responder a incidentes con agentes AI autónomos","fr":"Découvrez comment configurer github-trending pour surveiller l''infrastructure et répondre aux incidents avec des agents AI autonomes","de":"Erfahren Sie, wie Sie github-trending einrichten, um die Infrastruktur zu überwachen und auf Incidenten mit autonomen AI-Agents zu reagieren","pt":"Aprenda a configurar o GitHub Trending para descobrir repositórios em alta com filtragem por linguagem, data e tópico","ru":"Узнайте, как настроить GitHub Trending для поиска популярных репозиториев с помощью ИИ Агентов и фильтрации","ar":"تعلم كيفية إعداد GitHub Trending لاكتشاف المستودعات الشائعة مع تصفية اللغة والتواريخ والمواضيع"},"definition":{"en":"github-trending is a multi-agent orchestration system for infrastructure monitoring, incident response, and load testing with autonomous AI agents","zh":"GitHub Trending 是一种使用 AI 工具发现 GitHub 上最热门仓库的方法","ja":"GitHub Trending は、AI エージェントを使用して GitHub 上の最も人気のあるリポジトリを発見する方法です","ko":"GitHub Trending은 AI 툴을 사용하여 GitHub에서 가장 인기 있는 저장소를 발견하는 방법입니다","es":"github-trending es un sistema que permite descubrir repositorios de tendencia en GitHub filtrados por lenguaje, rango de fechas o tema","fr":"github-trending est un système qui permet de découvrir des référentiels tendance sur GitHub filtrés par langage, plage de dates ou sujet","de":"github-trending ist ein System, das das Entdecken von Trend-Repositorys auf GitHub ermöglicht, gefiltert nach Sprache, Datum oder Thema","pt":"O que é GitHub Trending? É um sistema que descobre repositórios em alta no GitHub com filtragem por linguagem e data","ru":"Что такое GitHub Trending? Это система, которая обнаруживает популярные репозитории на GitHub с фильтрацией по языку и дате","ar":"ما هو GitHub Trending؟ هو نظام يكتشف المستودعات الشائعة على GitHub مع تصفية اللغة والتواريخ"},"features":{"en":["Fetches trending page using web scraping via bash","Parses trending repositories with browser tool for better extraction","Supports GitHub CLI for searching trending repos with authentication","Filters repositories by language, date range, or topic","Utilizes gh search repos command for sorting and limiting results","Enables autonomous AI agents for infrastructure monitoring and incident response"],"zh":["支持 Web 抓取和 GitHub CLI 两种方法","按语言、日期范围或主题进行筛选","发现最热门的仓库","使用 gh search repos 命令行工具搜索仓库","支持浏览器快照和网页抓取"],"ja":["Web スクレイピングと GitHub CLI の 2 つの方法をサポート","言語、日付範囲、またはトピックでフィルタリング","最も人気のあるリポジトリを発見","gh search repos コマンドラインツールを使用してリポジトリを検索","ブラウザのスナップショットと Web スクレイピングをサポート"],"ko":["웹 스크레이핑 및 GitHub CLI 두 가지 방법을 지원","언어, 날짜 범위 또는 주제로 필터링","가장 인기 있는 저장소를 발견","gh search repos 명령줄 도구를 사용하여 저장소를 검색","브라우저 스냅샷 및 웹 스크레이핑을 지원"],"es":["Descubrimiento de repositorios de tendencia en GitHub","Filtrado por lenguaje, rango de fechas o tema","Uso de la interfaz de línea de comandos de GitHub (CLI) para buscar repositorios","Uso de técnicas de scraping web para extraer información","Soporte para la autenticación con GitHub para acceder a funcionalidades avanzadas"],"fr":["Découverte de référentiels tendance sur GitHub","Filtrage par langage, plage de dates ou sujet","Utilisation de l''interface de ligne de commande de GitHub (CLI) pour rechercher des référentiels","Utilisation de techniques de scraping web pour extraire des informations","Prise en charge de l''authentification avec GitHub pour accéder à des fonctionnalités avancées"],"de":["Entdecken von Trend-Repositorys auf GitHub","Filterung nach Sprache, Datum oder Thema","Verwendung der GitHub-Command-Line-Schnittstelle (CLI) zum Suchen von Repositorys","Verwendung von Web-Scraping-Techniken zum Extrahieren von Informationen","Unterstützung für die Authentifizierung mit GitHub zum Zugriff auf erweiterte Funktionen"],"pt":["Descubra repositórios em alta no GitHub com filtragem por linguagem","Filtragem por data para encontrar repositórios recentes","Uso de web scraping para extração de dados sem necessidade de API","Integração com GitHub CLI para autenticação e busca de repositórios","Suporte a busca de repositórios por tópico"],"ru":["Обнаружение популярных репозиториев на GitHub с фильтрацией по языку","Фильтрация по дате для поиска недавних репозиториев","Использование веб-скрейпинга для извлечения данных без необходимости API","Интеграция с GitHub CLI для аутентификации и поиска репозиториев","Поддержка поиска репозиториев по теме"],"ar":["اكتشاف المستودعات الشائعة على GitHub مع تصفية اللغة","تصفية بالتواريخ لfinding المستودعات الحديثة","استخدام تقنية الويب سكرابينج لاستخراج البيانات دون حاجة إلى واجهة برمجة التطبيقات","التكامل مع GitHub CLI للتحقق من الهوية والبحث عن المستودعات","دعم البحث عن المستودعات حسب الموضوع"]},"keywords":{"en":["how to use github-trending","github-trending alternative","github-trending setup guide","what is github-trending","github-trending vs gitlab","github-trending install","github trending repositories","github-trending ai agent","github-trending web scraping","github-trending cli commands"],"zh":["GitHub Trending","AI 工具","Web 抓取","GitHub CLI","仓库发现","语言筛选","日期范围筛选","主题筛选"],"ja":["GitHub Trending","AI エージェント","Web スクレイピング","GitHub CLI","リポジトリ発見","言語フィルタリング","日付範囲フィルタリング","トピックフィルタリング"],"ko":["GitHub Trending","AI 툴","웹 스크레이핑","GitHub CLI","저장소 발견","언어 필터링","날짜 범위 필터링","주제 필터링"],"es":["github trending","agentes AI","monitoreo de infraestructura","respuesta a incidentes","CLI de GitHub","scraping web","autenticación con GitHub","desarrollo de software","herramientas de desarrollo"],"fr":["github trending","agents AI","surveillance de l''infrastructure","réponse aux incidents","CLI de GitHub","scraping web","authentification avec GitHub","développement de logiciels","outils de développement"],"de":["github trending","AI-Agents","Überwachung der Infrastruktur","Reaktion auf Incidenten","GitHub-CLI","Web-Scraping","Authentifizierung mit GitHub","Software-Entwicklung","Entwicklertools"],"pt":["github trending","repositórios em alta","filtragem por linguagem","web scraping","github cli","autenticação","busca de repositórios","tópico"],"ru":["github trending","популярные репозитории","фильтрация по языку","веб-скрейпинг","github cli","аутентификация","поиск репозиториев","тема"],"ar":["github trending","مستودعات شائعة","تصفية اللغة","تقنية الويب سكرابينج","github cli","التحقق من الهوية","البحث عن المستودعات","الموضوع"]}},"owner":"jawsbaek","repo":"openclaw-agent-configs","repoPath":"jawsbaek/openclaw-agent-configs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"github-trending","description":"Track GitHub trending repositories by language, topic, or keyword. Use for discovering popular projects, monitoring data engineering trends (Databricks, Spark), or finding learning resources.","bodyPreview":"# GitHub Trending\n\nDiscover trending repositories on GitHub filtered by language, date range, or topic.\n\n## Quick Start\n\n### Method 1: Web Scraping (No API needed)\n```bash\n# Fetch trending page\nweb_fetch \"https://github.com/trending/python?since=daily\"\n\n# Parse with browser tool for better extraction\nbrowser.open(\"https://github.com/trending\")\nbrowser.snapshot()\n```\n\n### Method 2: GitHub CLI (if authenticated)\n```bash\n# Search trending repos\ngh search repos --sort stars --order desc --limit 10","body":"# GitHub Trending\n\nDiscover trending repositories on GitHub filtered by language, date range, or topic.\n\n## Quick Start\n\n### Method 1: Web Scraping (No API needed)\n```bash\n# Fetch trending page\nweb_fetch \"https://github.com/trending/python?since=daily\"\n\n# Parse with browser tool for better extraction\nbrowser.open(\"https://github.com/trending\")\nbrowser.snapshot()\n```\n\n### Method 2: GitHub CLI (if authenticated)\n```bash\n# Search trending repos\ngh search repos --sort stars --order desc --limit 10\n\n# Filter by topic\ngh search repos --topic databricks --sort stars --order desc\n\n# Filter by language and recent updates\ngh search repos --language python --sort updated --limit 10\n```\n\n### Method 3: GitHub API (requires token)\n```bash\n# Search by stars (proxy for trending)\ncurl \"https://api.github.com/search/repositories?q=created:>$(date -v-7d +%Y-%m-%d)&sort=stars&order=desc\"\n```\n\n## Trending Time Ranges\n\n- `?since=daily` - Today''s trending\n- `?since=weekly` - This week''s trending\n- `?since=monthly` - This month''s trending\n\n## Popular Languages\n\n**Data Engineering:**\n- `python` - Data science, ML, ETL\n- `scala` - Spark, big data\n- `jupyter-notebook` - Analysis notebooks\n\n**General:**\n- `javascript`, `typescript`, `go`, `rust`\n\n## Filtering Strategies\n\n### For Databricks/Data Engineering\n```bash\n# GitHub search query\nsite:github.com databricks OR \"delta lake\" OR spark stars:>100\n\n# Topic-based search (gh CLI)\ngh search repos --topic databricks --sort stars\ngh search repos --topic spark --sort stars\ngh search repos --topic mlflow --sort stars\n```\n\n### Extract Key Info\nFrom trending page, capture:\n- Repository name (owner/repo)\n- Description\n- Stars (total)\n- Stars today/week (if shown)\n- Primary language\n- Topics/tags\n\n## Output Format\n\n```markdown\n## 🔥 GitHub Trending - [Language/Topic] - [Date]\n\n1. **owner/repo-name** (⭐ 12.3K | +234 today)\n   Description of the project\n   Topics: #databricks #spark #python\n   https://github.com/owner/repo-name\n\n2. **owner/another-repo** (⭐ 5.6K | +89 today)\n   Brief description\n   Topics: #data-engineering #etl\n   https://github.com/owner/another-repo\n```\n\n## Common Use Cases\n\n### Daily Data Engineering Trends\nTrack Databricks, Spark, Delta Lake projects:\n```\n1. Fetch https://github.com/trending/python?since=daily\n2. Filter for keywords: databricks, spark, delta, mlflow\n3. Return top 3-5 matches\n```\n\n### Weekly Learning Resources\nFind popular educational repos:\n```\n1. Search repos with topic \"data-engineering\" or \"databricks\"\n2. Sort by stars (last 7 days)\n3. Filter for tutorials, examples, courses\n```\n\n### Interview Prep Projects\nDiscover real-world implementations:\n```\n1. Search: \"databricks\" OR \"lakehouse\" language:python\n2. Filter: stars >100, updated recently\n3. Look for: example projects, best practices\n```\n\n## Tips\n\n- **Browser tool preferred** for visual parsing (stars, trends)\n- **GitHub CLI** fastest for authenticated searches\n- **Web scraping** simplest for trending pages (no auth)\n- **Cache results** - trending changes slowly (safe to cache 1-2 hours)\n\n## Example Script\n\nSee `scripts/github-trending.sh` for automated trending fetch with keyword filtering.\n"},"lastSynced":"2026-03-08T01:59:42.233Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing real-time GitHub repository monitoring and analysis capabilities.","zh":"非常适合需要实时监控和分析 GitHub 仓库的开发代理。","ja":"GitHub リポジトリのリアルタイム監視と分析機能が必要な開発エージェントに最適です。","ko":"실시간으로 GitHub 저장소를 모니터링하고 분석하는 기능이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan capacidades de monitoreo y análisis de repositorios de GitHub en tiempo real.","fr":"Parfait pour les agents de développement qui ont besoin de capacités de surveillance et d''analyse de référentiels GitHub en temps réel.","de":"Perfekt für Entwicklungsagenten, die Echtzeit-Überwachungs- und Analysefunktionen für GitHub-Repositorys benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de monitoramento e análise de repositórios GitHub em tempo real.","ru":"Идеально подходит для агентов разработки, которым необходимы возможности мониторинга и анализа репозиториев GitHub в реальном времени.","ar":"مثالي لعمليات وكيل التطوير التي تحتاج إلى مراقبة وتحليل مستودعات GitHub في الوقت الفعلي."},"recommendation":{"en":"Empowers agents to discover trending repositories on GitHub using web scraping or GitHub CLI, filtering by language, date range, or topic, and providing efficient monitoring and response through protocols like HTTPS and tools like browser snapshotting.","zh":"赋予代理发现 GitHub 上趋势仓库的能力，使用网页抓取或 GitHub CLI，通过语言、日期范围或主题进行筛选，并通过 HTTPS 等协议和浏览器快照等工具提供高效的监控和响应。","ja":"エージェントがWebスクレイピングまたはGitHub CLIを使用してGitHubのトレンドリポジトリを発見する機能を提供します。言語、日付範囲、またはトピックでフィルタリングし、HTTPSなどのプロトコルやブラウザのスナップショットなどのツールを使用して効率的な監視と対応を提供します。","ko":"에이전트가 웹 스크레이핑 또는 GitHub CLI를 사용하여 GitHub의 트렌드 저장소를 발견할 수 있는 기능을 제공하며, 언어, 날짜 범위 또는 주제로 필터링하고, HTTPS와 같은 프로토콜 및 브라우저 스냅샷과 같은 도구를 통해 효율적인 모니터링 및 응답을 제공합니다.","es":"Habilita a los agentes a descubrir repositorios de tendencias en GitHub mediante web scraping o GitHub CLI, filtrando por lenguaje, rango de fechas o tema, y proporcionando un monitoreo y respuesta eficientes a través de protocolos como HTTPS y herramientas como la captura de instantáneas del navegador.","fr":"Permet aux agents de découvrir des référentiels tendances sur GitHub à l''aide de web scraping ou de GitHub CLI, en filtrant par langage, plage de dates ou sujet, et en fournissant un suivi et une réponse efficaces via des protocoles tels que HTTPS et des outils tels que la capture d''écran du navigateur.","de":"Ermöglicht es Agenten, auf GitHub trending Repositories mithilfe von Web Scraping oder GitHub CLI zu entdecken, gefiltert nach Sprache, Datumsbereich oder Thema, und bietet effizientes Monitoring und Response durch Protokolle wie HTTPS und Tools wie Browser-Screenshot.","pt":"Habilita os agentes a descobrir repositórios em tendência no GitHub usando web scraping ou GitHub CLI, filtrando por linguagem, intervalo de datas ou tópico, e fornecendo monitoramento e resposta eficientes por meio de protocolos como HTTPS e ferramentas como captura de tela do navegador.","ru":"Позволяет агентам обнаруживать репозитории, находящиеся в тренде на GitHub, используя веб-скраппинг или GitHub CLI, фильтруя по языку, диапазону дат или теме, и обеспечивая эффективный мониторинг и ответ через протоколы, такие как HTTPS, и инструменты, такие как создание снимков браузера.","ar":"تمكّن الوكلاء من اكتشاف المستودعات التي تُعَدّ من أحدث المستودعات على منصة GitHub باستخدام تقنيات حصر المعلومات من الويب أو واجهة سطر الأوامر الخاصة بمنصة GitHub، وفرز النتائج حسب اللغة أو الفترة الزمنية أو الموضوع، وتوفير مراقبة واستجابة فعالة من خلال بروتوكولات مثل بروتوكول نقل النص الفعلي الآمن وتطبيقات مثل لقطة الشاشة للمتصفح."},"useCases":{"en":["Monitoring daily trending Python repositories","Automating topic-based repository discovery","Debugging web scraping scripts for GitHub trending pages"],"zh":["监控每日趋势的Python仓库","自动化基于主题的仓库发现","调试GitHub趋势页面的网页抓取脚本"],"ja":["毎日のトレンドのPythonリポジトリの監視","トピックベースのリポジトリの自動発見","GitHubのトレンドページのWebスクレイピングスクリプトのデバッグ"],"ko":["매일 트렌드하는 Python 저장소 모니터링","주제 기반 저장소 자동 발견","GitHub 트렌드 페이지 웹 스크레이핑 스크립트 디버깅"],"es":["Monitoreo diario de repositorios de Python de tendencias","Automatización del descubrimiento de repositorios basados en temas","Depuración de scripts de web scraping para páginas de tendencias de GitHub"],"fr":["Surveillance quotidienne des référentiels tendances Python","Automatisation de la découverte de référentiels basés sur des sujets","Débogage de scripts de web scraping pour les pages tendances GitHub"],"de":["Tägliches Monitoring von trending Python-Repositorys","Automatisierung der Entdeckung von themenbasierten Repositorys","Fehlerbehebung von Web-Scraping-Skripten für GitHub-Trending-Seiten"],"pt":["Monitoramento diário de repositórios Python em tendência","Automação da descoberta de repositórios com base em tópicos","Depuração de scripts de web scraping para páginas de tendência do GitHub"],"ru":["Ежедневный мониторинг репозиториев Python, находящихся в тренде","Автоматизация открытия репозиториев на основе тем","Отладка скриптов веб-скраппинга для страниц GitHub, находящихся в тренде"],"ar":["مراقبة يومية للمستودعات التي تُعَدّ من أحدث المستودعات التي تستخدم لغة بايثون","تأتميم اكتشاف المستودعات بناءً على المواضيع","تصحيح أخطاء في برامج حصر المعلومات من الويب الخاصة بصفحات المستودعات التي تُعَدّ من أحدث المستودعات على منصة GitHub"]},"limitations":{"en":["Requires web scraping or GitHub CLI authentication","Limited to GitHub repositories only","Dependent on GitHub''s trending page structure and availability"],"zh":["需要网页抓取或 GitHub CLI 身份验证","仅限 GitHub 仓库","依赖于 GitHub 的趋势页面结构和可用性"],"ja":["WebスクレイピングまたはGitHub CLIの認証が必要","GitHubリポジトリのみに限定される","GitHubのトレンドページの構造と可用性に依存する"],"ko":["웹 스크레이핑 또는 GitHub CLI 인증이 필요","GitHub 저장소만 제한","GitHub의 트렌드 페이지 구조 및 가용성에 의존"],"es":["Requiere autenticación de web scraping o GitHub CLI","Limitado a repositorios de GitHub solamente","Dependiente de la estructura y disponibilidad de la página de tendencias de GitHub"],"fr":["Nécessite une authentification de web scraping ou de GitHub CLI","Limité aux référentiels GitHub uniquement","Dépend de la structure et de la disponibilité de la page tendances GitHub"],"de":["Benötigt Web-Scraping- oder GitHub-CLI-Authentifizierung","Begrenzt auf GitHub-Repositorys","Abhängig von der Struktur und Verfügbarkeit der GitHub-Trending-Seite"],"pt":["Exige autenticação por web scraping ou GitHub CLI","Limitado apenas a repositórios GitHub","Dependente da estrutura e disponibilidade da página de tendência do GitHub"],"ru":["Требует аутентификации по веб-скраппингу или GitHub CLI","Ограничен только репозиториями GitHub","Зависит от структуры и доступности страницы тренда GitHub"],"ar":["يتطلب مصادقة باستخدام تقنيات حصر المعلومات من الويب أو واجهة سطر الأوامر الخاصة بمنصة جيت هاب","محدود بالمستودعات المتوفرة على منصة جيت هاب فقط","يعتمد على هيكل ومتطلبات صفحة أحدث المستودعات على منصة جيت هاب"]},"version":4},"contentHash":"e66fac42b7b5f3f3d521d65380493c2ccd2e5271869b4c04da6f8a86fbeb85f5","qualityScore":57}');
