INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jawsbaek/openclaw-agent-configs/github-trending', 'github-trending', 'jawsbaek', 'openclaw-agent-configs', 'community', 'github-trending jawsbaek openclaw-agent-configs community The github-trending skill allows developers to discover trending repositories on GitHub, filtered by language, date range, or topic, enabling efficient monitoring and response. GitHub Trending 是一个多代理人编排系统，用于基础设施监控、事件响应和负载测试，支持 Web 抓取和 GitHub CLI 两种方法 GitHub Trending は、インフラストラクチャの 監視、インシデント対応、負荷テストを行うためのマルチエージェントオーケストレーションシステムであり、Web スクレイピングと GitHub CLI の 2 つの方法をサポートしています GitHub Trending은 인프라 모니터링, 인시던트 응답 및 부하 테스트를 위한 멀티 에이전트 오케스트레이션 시스템으로 웹 스크레이핑 및 GitHub CLI 두 가지 방법을 지원합니다 github-trending es un sistema de orquestación de agentes múltiples para monitorear la infraestructura y responder a incidentes con agentes AI autónomos github-trending est un système d''orchestration d''agents multiples pour surveiller l''infrastructure et répondre aux incidents avec des agents AI autonomes github-trending ist ein System zur Orchestrierung mehrerer Agenten für die Überwachung der Infrastruktur und die Reaktion auf Incidenten mit autonomen AI-Agents O GitHub Trending é um sistema de orquestração de multi-agentes para monitoramento de infraestrutura e resposta a incidentes com agentes AI autônomos GitHub Trending - это система оркестровки многоагентной системы для мониторинга инфраструктуры и реагирования на инциденты с помощью автономных ИИ Агентов GitHub Trending هو نظام أوركسترالية متعدد الوكلاء لمراقبة البنية التحتية واستجابة الحوادث مع وكلاء ذكاء اصطناعي مستقلين how to use github-trending github-trending alternative github-trending setup guide what is github-trending github-trending vs gitlab github-trending install github trending repositories github-trending ai agent github-trending web scraping github-trending cli commands GitHub Trending AI 工具 Web 抓取 GitHub CLI 仓库发现 语言筛选 日期范围筛选 主题筛选 Fetches trending page using web scraping via bash Parses trending repositories with browser tool for better extraction Supports GitHub CLI for searching trending repos with authentication Filters repositories by language, date range, or topic Utilizes gh search repos command for sorting and limiting results Enables autonomous AI agents for infrastructure monitoring and incident response github-trending is a multi-agent orchestration system for infrastructure monitoring, incident response, and load testing with autonomous AI agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('knoopx/pi/gh', 'community', 'knoopx', 'pi', 'knoopx/pi', 'gh', 0, 0, 57, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:47.468Z', 'af673f737e85f693e788dae6de5392dc55d56b568d375f1b31a4957a65946c16', '{"id":"knoopx/pi/gh","name":"gh","description":{"en":"The gh skill provides GitHub functionality in the terminal, allowing developers to manage repositories efficiently. It benefits developers who need to perform tasks such as viewing, cloning, and forking repositories.","zh":"GitHub CLI (gh) 提供了 GitHub 功能在终端中的实现，包括仓库管理和配置","ja":"GitHub CLI (gh) は、GitHub の機能を端末で実現します。リポジトリ管理と設定が可能です","ko":"GitHub CLI (gh) 는 GitHub 기능을 터미널에서 구현합니다. 리포지토리 관리 및 설정이 가능합니다","es":"gh es una herramienta de línea de comandos para GitHub que permite gestionar repositorios de manera eficiente","fr":"gh est un outil en ligne de commande pour GitHub qui permet de gérer des dépôts de manière efficace","de":"gh ist ein Kommandozeilen-Tool für GitHub, mit dem Sie Repositorys effizient verwalten können","pt":"O gh é uma ferramenta de linha de comando para GitHub que permite gerenciar repositórios de forma eficiente. Com ele, você pode clonar, bifurcar e criar repositórios com facilidade.","ru":"gh - это инструмент командной строки для GitHub, который позволяет управлять репозиториями эффективно. С его помощью вы можете клонировать, вилочный и создавать репозитории легко.","ar":"gh هو أداة سطر أوامر لجيت هاب التي تمكنك من إدارة المستودعات بفعالية. يمكنك استنساخ وإنشاء وتفرع المستودعات بسهولة."},"seo":{"title":{"en":"gh: GitHub CLI Setup Guide | AI Agent Skill","zh":"GitHub CLI (gh) 配置与设置指南","ja":"GitHub CLI (gh) 設定ガイド - AIエージェント","ko":"GitHub CLI (gh) 설정 및 사용 방법 - AI 도구","es":"Guía de configuración de gh para GitHub CLI","fr":"Guide de mise en route de gh pour GitHub CLI","de":"Einrichtungsleitfaden für gh mit GitHub CLI","pt":"Guia de Configuração do gh: Ferramentas de Linha de Coman...","ru":"Настройка gh: Инструменты командной строки для GitHub ИИ ...","ar":"دليل إعداد gh: أدوات سطر الأوامر لجيت هاب"},"description":{"en":"Unlock GitHub''s full potential with gh, the official CLI. Learn how to view, clone, and manage repositories with ease. Get started now!","zh":"了解 GitHub CLI (gh) 的功能和用法，包括仓库管理和配置","ja":"GitHub CLI (gh) の機能と使い方を学ぶ - リポジトリ管理と設定","ko":"GitHub CLI (gh) 기능과 사용법을 알아보세요 - 리포지토리 관리 및 설정","es":"Aprende a configurar gh para GitHub CLI y aprovecha al máximo sus funciones de gestión de repositorios","fr":"Découvrez comment configurer gh pour GitHub CLI et exploiter ses fonctionnalités de gestion de dépôts","de":"Erfahren Sie, wie Sie gh für GitHub CLI einrichten und seine Funktionen für die Repository-Verwaltung nutzen","pt":"Aprenda a configurar o gh para gerenciar repositórios GitHub na linha de comando. Veja como clonar, bifurcar e criar repositórios com facilidade.","ru":"Узнайте, как настроить gh для управления репозиториями GitHub в командной строке. Посмотрите, как клонировать, вилочный и создавать репозитории легко с помощ...","ar":"تعرف على كيفية إعداد gh لإدارة مستودعات جيت هاب في سطر الأوامر. انظر كيفية استنساخ وإنشاء وتفرع مستودعات بسهولة."},"definition":{"en":"gh is a command-line interface (CLI) that brings GitHub functionality to the terminal, enabling developers to interact with repositories using commands like gh repo view and gh repo clone.","zh":"GitHub CLI (gh) 是一种命令行工具，提供 GitHub 功能在终端中的实现","ja":"GitHub CLI (gh) は、GitHub の機能を端末で実現するコマンドラインツールです","ko":"GitHub CLI (gh) 는 GitHub 기능을 터미널에서 구현하는 명령줄 도구입니다","es":"gh es una herramienta de GitHub CLI que permite gestionar repositorios en la terminal","fr":"gh est un outil de GitHub CLI qui permet de gérer des dépôts dans le terminal","de":"gh ist ein Tool von GitHub CLI, mit dem Sie Repositorys im Terminal verwalten können","pt":"O gh é uma ferramenta de linha de comando que fornece funcionalidades de gerenciamento de repositórios GitHub.","ru":"gh - это инструмент командной строки, который предоставляет функции управления репозиториями GitHub.","ar":"gh هو أداة سطر أوامر تقدم وظائف إدارة المستودعات جيت هاب."},"features":{"en":["View current and specific repositories using gh repo view","Clone repositories with gh repo clone","Fork current repositories using gh repo fork","Create new public and private repositories with gh repo create","List repositories using gh repo list","Open repositories in the browser with gh repo view --web"],"zh":["仓库管理：查看、克隆、分叉和创建仓库","配置管理：设置和管理 GitHub 配置","命令行工具：使用 gh 命令实现 GitHub 功能","仓库查看：使用 gh repo view 查看仓库信息","仓库克隆：使用 gh repo clone 克隆仓库","仓库分叉：使用 gh repo fork 分叉仓库"],"ja":["リポジトリ管理：リポジトリの表示、クローン、フォーク、作成","設定管理：GitHub の設定を管理","コマンドラインツール：gh コマンドを使用して GitHub の機能を実現","リポジトリ表示：gh repo view を使用してリポジトリ情報を表示","リポジトリクローン：gh repo clone を使用してリポジトリをクローン","リポジトリフォーク：gh repo fork を使用してリポジトリをフォーク"],"ko":["리포지토리 관리：리포지토리 보기, 클론, 포크 및 생성","설정 관리：GitHub 설정을 관리","명령줄 도구：gh 명령을 사용하여 GitHub 기능을 구현","리포지토리 보기：gh repo view를 사용하여 리포지토리 정보를 보기","리포지토리 클론：gh repo clone을 사용하여 리포지토리를 클론","리포지토리 포크：gh repo fork를 사용하여 리포지토리를 포크"],"es":["Visualización de repositorios con gh repo view","Clonación de repositorios con gh repo clone","Creación de nuevos repositorios con gh repo create","Fork de repositorios con gh repo fork","Lista de repositorios con gh repo list","Apertura de repositorios en el navegador con gh repo view --web"],"fr":["Affichage de dépôts avec gh repo view","Clonage de dépôts avec gh repo clone","Création de nouveaux dépôts avec gh repo create","Fork de dépôts avec gh repo fork","Liste de dépôts avec gh repo list","Ouverture de dépôts dans le navigateur avec gh repo view --web"],"de":["Anzeige von Repositorys mit gh repo view","Klonen von Repositorys mit gh repo clone","Erstellung neuer Repositorys mit gh repo create","Fork von Repositorys mit gh repo fork","Liste von Repositorys mit gh repo list","Öffnen von Repositorys im Browser mit gh repo view --web"],"pt":["Gerenciamento de repositórios GitHub na linha de comando","Clonar repositórios com o comando ''gh repo clone''","Bifurcar repositórios com o comando ''gh repo fork''","Criar repositórios com o comando ''gh repo create''","Listar repositórios com o comando ''gh repo list''","Abrir repositórios no navegador com o comando ''gh repo view --web''"],"ru":["Управление репозиториями GitHub в командной строке","Клонирование репозиториев с помощью команды ''gh repo clone''","Вилочный репозиториев с помощью команды ''gh repo fork''","Создание репозиториев с помощью команды ''gh repo create''","Список репозиториев с помощью команды ''gh repo list''","Открытие репозиториев в браузере с помощью команды ''gh repo view --web''"],"ar":["إدارة المستودعات جيت هاب في سطر الأوامر","استنساخ المستودعات باستخدام الأمر ''gh repo clone''","تفرع المستودعات باستخدام الأمر ''gh repo fork''","إنشاء المستودعات باستخدام الأمر ''gh repo create''","قائمة المستودعات باستخدام الأمر ''gh repo list''","فتح المستودعات في المتصفح باستخدام الأمر ''gh repo view --web''"]},"keywords":{"en":["how to use gh","gh install","gh vs git","github cli tutorial","gh setup guide","what is gh","gh alternative","gh repo management"],"zh":["GitHub CLI","gh","仓库管理","配置管理","命令行工具","GitHub 设置","仓库查看","仓库克隆","仓库分叉","AI 工具"],"ja":["GitHub CLI","gh","リポジトリ管理","設定管理","コマンドラインツール","GitHub 設定","リポジトリ表示","リポジトリクローン","リポジトリフォーク","AI エージェント"],"ko":["GitHub CLI","gh","리포지토리 관리","설정 관리","명령줄 도구","GitHub 설정","리포지토리 보기","리포지토리 클론","리포지토리 포크","AI 도구"],"es":["gh github cli","gestión de repositorios","github cli tutorial","configuración de gh","herramientas de desarrollo","github cli commands","gh repo view","gh repo clone","gh repo create"],"fr":["gh github cli","gestion de dépôts","tutoriel github cli","configuration de gh","outils de développement","commandes github cli","gh repo view","gh repo clone","gh repo create"],"de":["gh github cli","repository-verwaltung","github cli tutorial","konfiguration von gh","entwicklertools","github cli befehle","gh repo view","gh repo clone","gh repo create"],"pt":["gh","github cli","gerenciamento de repositórios","clonar repositórios","bifurcar repositórios","criar repositórios","listar repositórios","abrir repositórios no navegador"],"ru":["gh","github cli","управление репозиториями","клонирование репозиториев","вилочный репозиториев","создание репозиториев","список репозиториев","открытие репозиториев в браузере","ИИ Агенты"],"ar":["gh","github cli","إدارة المستودعات","استنساخ المستودعات","تفرع المستودعات","إنشاء المستودعات","قائمة المستودعات","فتح المستودعات في المتصفح","أدوات الذكاء الاصطناعي"]}},"owner":"knoopx","repo":"pi","repoPath":"knoopx/pi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"gh","description":"Interacts with GitHub repositories, issues, pull requests, releases, and gists using the gh CLI. Use when managing GitHub resources, searching code/repos, creating PRs/issues, or making API requests.","bodyPreview":"# GitHub CLI (gh)\n\nGitHub functionality in the terminal.\n\n## Repository Management\n\n```bash\ngh repo view                      # View current repo\ngh repo view owner/repo           # View specific repo\ngh repo view --web                # Open in browser\ngh repo clone owner/repo          # Clone repository\ngh repo fork                      # Fork current repo\ngh repo create name               # Create new repo\ngh repo create name --private     # Create private repo\ngh repo list","body":"# GitHub CLI (gh)\n\nGitHub functionality in the terminal.\n\n## Repository Management\n\n```bash\ngh repo view                      # View current repo\ngh repo view owner/repo           # View specific repo\ngh repo view --web                # Open in browser\ngh repo clone owner/repo          # Clone repository\ngh repo fork                      # Fork current repo\ngh repo create name               # Create new repo\ngh repo create name --private     # Create private repo\ngh repo list                      # List your repos\ngh repo list owner                # List user/org repos\ngh repo sync                      # Sync fork with upstream\n```\n\n## Issues\n\n```bash\n# Listing\ngh issue list                     # List open issues\ngh issue list --state all         # All issues\ngh issue list --assignee @me      # Assigned to you\ngh issue list --label bug         # Filter by label\ngh issue list --json number,title,state\n\n# Viewing\ngh issue view 123                 # View issue\ngh issue view 123 --comments      # With comments\ngh issue view 123 --web           # Open in browser\n\n# Creating\ngh issue create                   # Interactive create\ngh issue create --title \"T\" --body \"B\"\ngh issue create --title \"T\" --label bug,high-priority\n\n# Managing\ngh issue close 123                # Close issue\ngh issue reopen 123               # Reopen issue\ngh issue comment 123 --body \"msg\" # Add comment\ngh issue edit 123 --add-label bug # Edit issue\n```\n\n## Pull Requests\n\n```bash\n# Listing\ngh pr list                        # List open PRs\ngh pr list --state merged         # Merged PRs\ngh pr list --author @me           # Your PRs\ngh pr list --json number,title,author\n\n# Viewing\ngh pr view 123                    # View PR\ngh pr view 123 --web              # Open in browser\ngh pr checks 123                  # View CI status\ngh pr diff 123                    # View PR diff\n\n# Creating\ngh pr create                      # Interactive create\ngh pr create --fill               # Auto-fill from commits\ngh pr create --draft              # Create as draft\ngh pr create --title \"feat: X\" --body \"Description\"\n\n# Reviewing\ngh pr review 123 --approve        # Approve PR\ngh pr review 123 --request-changes --body \"Fix X\"\ngh pr review 123 --comment -b \"m\" # Comment on PR\n\n# Merging\ngh pr merge 123                   # Merge PR\ngh pr merge 123 --squash          # Squash merge\ngh pr merge 123 --rebase          # Rebase merge\ngh pr merge 123 --delete-branch   # Delete branch after\n\n# Other\ngh pr checkout 123                # Checkout PR locally\ngh pr ready 123                   # Mark as ready\n```\n\n## Search\n\n```bash\n# Repositories\ngh search repos \"react language:typescript stars:>1000\"\ngh search repos \"owner:facebook\" --limit 20\n\n# Issues\ngh search issues \"repo:owner/repo is:open label:bug\"\ngh search issues \"author:@me is:open\"\n\n# PRs\ngh search prs \"repo:owner/repo is:open review:required\"\n\n# Code\ngh search code \"function main repo:owner/repo\"\ngh search code \"filename:config.json owner:org\"\n\n# Commits\ngh search commits \"fix bug repo:owner/repo\"\n```\n\n## Releases\n\n```bash\ngh release list                   # List releases\ngh release view v1.0.0            # View release\ngh release create v1.0.0          # Create release\ngh release create v1.0.0 --draft  # Draft release\ngh release create v1.0.0 ./dist/* # With assets\ngh release download v1.0.0        # Download assets\ngh release delete v1.0.0          # Delete release\n```\n\n## Gists\n\n```bash\ngh gist list                      # List your gists\ngh gist create file.txt           # Create from file\ngh gist create -p file.txt        # Public gist\ngh gist view <id>                 # View gist\ngh gist edit <id>                 # Edit gist\ngh gist clone <id>                # Clone gist\ngh gist delete <id>               # Delete gist\n```\n\n## API Requests\n\n```bash\n# REST API\ngh api repos/{owner}/{repo}\ngh api repos/{owner}/{repo}/issues\ngh api /user\n\n# POST request\ngh api -X POST repos/{owner}/{repo}/issues \\\n  -f title=\"Bug\" -f body=\"Description\"\n\n# With query parameters\ngh api -X GET search/issues -f q=''repo:cli/cli is:open''\n\n# With pagination\ngh api repos/{owner}/{repo}/issues --paginate\n\n# Filter with jq\ngh api repos/{owner}/{repo}/issues --jq ''.[].title''\n\n# GraphQL\ngh api graphql -f query=''{ viewer { login } }''\ngh api graphql -F owner=''{owner}'' -F name=''{repo}'' -f query=''\n  query($name: String!, $owner: String!) {\n    repository(owner: $owner, name: $name) {\n      stargazerCount\n    }\n  }\n''\n```\n\n## Workflows (GitHub Actions)\n\n```bash\ngh workflow list                  # List workflows\ngh workflow run <workflow>        # Trigger workflow\ngh run list                       # List workflow runs\ngh run view <run-id>              # View run details\ngh run download <run-id>          # Download artifacts\n\n# Watch run (use tmux)\ntmux new -d -s gh-watch ''gh run watch <run-id>''\n```\n\n## JSON Output\n\n```bash\ngh issue list --json number,title,state\ngh pr list --json number,title,author\n\n# Filter with jq\ngh issue list --json title --jq ''.[].title''\ngh pr list --json number,title --jq ''.[] | \"\\(.number): \\(.title)\"''\ngh issue list --json number,title,state --jq ''.[] | select(.state == \"open\")''\n```\n\n## Common Flags\n\n| Flag                      | Description                |\n| ------------------------- | -------------------------- |\n| `-R owner/repo`           | Target specific repository |\n| `--web`                   | Open in browser            |\n| `--json fields`           | Output as JSON             |\n| `--jq query`              | Filter JSON output         |\n| `--limit N`               | Limit results              |\n| `--state open/closed/all` | Filter by state            |\n\n## Tips\n\n- Use `{owner}` and `{repo}` placeholders in API calls (auto-filled)\n- Use `--web` to open any resource in browser\n- Use `--json` with `--jq` for scriptable output\n- `gh auth status` to check authentication\n- `gh config set editor vim` to set default editor\n- Use `gh alias set` to create shortcuts\n"},"lastSynced":"2026-03-08T01:59:47.468Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient GitHub repository management in the terminal.","zh":"非常适合需要在终端高效管理 GitHub 仓库的 Developer Agents。","ja":"Developer Agents がターミナルで GitHub リポジトリを効率的に管理する必要がある場合に最適です。","ko":"개발자 에이전트가 터미널에서 깃허브 저장소를 효율적으로 관리해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una gestión eficiente de repositorios de GitHub en la terminal.","fr":"Parfait pour les agents de développement qui ont besoin d''une gestion efficace des référentiels GitHub dans le terminal.","de":"Perfekt für Entwickleragenten, die eine effiziente GitHub-Repository-Verwaltung im Terminal benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de gerenciamento eficiente de repositórios GitHub no terminal.","ru":"Идеально подходит для агентов-разработчиков, которым требуется эффективное управление репозиториями GitHub в терминале.","ar":"مثالي لعميل المطور الذي يحتاج إلى إدارة مخازن GitHub بكفاءة في الطرفية."},"recommendation":{"en":"Empowers agents to manage repositories efficiently using GitHub CLI commands, such as viewing, cloning, and forking repositories, and creating new ones with options like --web and --private, utilizing protocols like HTTPS for secure interactions.","zh":"赋予代理管理仓库的能力，使用诸如 GitHub CLI 命令来高效管理仓库，例如查看、克隆和分叉仓库，并使用 --web 和 --private 选项创建新仓库，利用 HTTPS 等协议进行安全交互。","ja":"エージェントがリポジトリを効率的に管理できるようにし、GitHub CLI コマンドを使用して、リポジトリの表示、クローン、フォーク、および --web および --private オプションを使用した新しいリポジトリの作成などを行い、HTTPS などのプロトコルを使用してセキュアなやり取りを行う。","ko":"에이전트가 리포지토리를 효율적으로 관리할 수 있도록 하여 GitHub CLI 명령을 사용하여 리포지토리를 보거나 복제하거나 분기하고 --web 및 --private 옵션을 사용하여 새로운 리포지토리를 생성하며 HTTPS와 같은 프로토콜을 사용하여 보안 상호 작용을 수행합니다.","es":"Habilita a los agentes a gestionar los repositorios de forma eficiente utilizando comandos de GitHub CLI, como ver, clonar y bifurcar repositorios, y crear nuevos con opciones como --web y --private, utilizando protocolos como HTTPS para interacciones seguras.","fr":"Permet aux agents de gérer les référentiels de manière efficace en utilisant des commandes GitHub CLI, telles que la visualisation, le clonage et la création de fork de référentiels, et la création de nouveaux avec des options comme --web et --private, en utilisant des protocoles comme HTTPS pour des interactions sécurisées.","de":"Ermöglicht es Agenten, Repositorys effizient zu verwalten, indem sie GitHub-CLI-Befehle wie Anzeigen, Klonen und Forken von Repositorys sowie Erstellen neuer Repositorys mit Optionen wie --web und --private verwenden, und Protokolle wie HTTPS für sichere Interaktionen nutzen.","pt":"Habilita os agentes a gerenciar repositórios de forma eficiente usando comandos GitHub CLI, como visualizar, clonar e bifurcar repositórios, e criar novos com opções como --web e --private, utilizando protocolos como HTTPS para interações seguras.","ru":"Наделяет агентов возможностью эффективно управлять репозиториями, используя команды GitHub CLI, такие как просмотр, клонирование и создание форков репозиториев, а также создание новых с опциями, такими как --web и --private, используя протоколы, такие как HTTPS, для безопасного взаимодействия.","ar":"يمنح الوكلاء القدرة على إدارة المخازن بفعالية باستخدام أوامر GitHub CLI، مثل عرض و استنساخ و انقسام المخازن، وإنشاء مخازن جديدة مع خيارات مثل --web و --private، واستخدام بروتوكولات مثل HTTPS للتفاعلات الآمنة."},"useCases":{"en":["Cloning repositories for automated testing","Forking repositories for collaborative development","Creating new private repositories for secure project management"],"zh":["自动化测试用途的仓库克隆","协作开发用途的仓库分叉","使用 --private 选项创建新私有仓库以实现安全的项目管理"],"ja":["自動テスト用途のリポジトリのクローン","共同開発用途のリポジトリのフォーク","--private オプションを使用した新しいプライベートリポジトリの作成によるセキュアなプロジェクト管理"],"ko":["자동화 테스트를 위한 리포지토리 복제","공동 개발을 위한 리포지토리 분기","--private 옵션을 사용하여 새로운 사적인 리포지토리를 생성하여 보안 프로젝트 관리"],"es":["Clonar repositorios para pruebas automatizadas","Crear fork de repositorios para desarrollo colaborativo","Crear nuevos repositorios privados para una gestión de proyectos segura"],"fr":["Cloner des référentiels pour des tests automatisés","Créer des fork de référentiels pour le développement collaboratif","Créer de nouveaux référentiels privés pour une gestion de projet sécurisée"],"de":["Repositorys klonen für automatisierte Tests","Repositorys forkieren für kollaborative Entwicklung","Neue private Repositorys erstellen für sichere Projektverwaltung"],"pt":["Clonar repositórios para teste automatizado","Bifurcar repositórios para desenvolvimento colaborativo","Criar novos repositórios privados para gerenciamento de projeto seguro"],"ru":["Клонирование репозиториев для автоматизированного тестирования","Создание форков репозиториев для совместной разработки","Создание новых приватных репозиториев для безопасного управления проектами"],"ar":["استنساخ مخازن لاختبار آلي","انقسام مخازن لتطوير تعاوني","إنشاء مخازن خاصة جديدة لإدارة مشروع آمن"]},"limitations":{"en":["Requires GitHub CLI installation","Terminal access needed","Limited to GitHub repositories only"],"zh":["需要安装 GitHub CLI","需要终端访问","仅限 GitHub 仓库"],"ja":["GitHub CLI のインストールが必要","ターミナルへのアクセスが必要","GitHub リポジトリのみに限定"],"ko":["깃허브 CLI 설치 필요","터미널 액세스 필요","깃허브 리포지토리만 사용 가능"],"es":["Requiere la instalación de GitHub CLI","Se necesita acceso a la terminal","Limitado a repositorios de GitHub solo"],"fr":["Nécessite l''installation de GitHub CLI","L''accès à la terminal est nécessaire","Limité aux référentiels GitHub uniquement"],"de":["Benötigt die Installation von GitHub CLI","Terminal-Zugriff erforderlich","Begrenzt auf GitHub-Repositorys nur"],"pt":["Requer instalação do GitHub CLI","Acesso ao terminal necessário","Limitado a repositórios GitHub apenas"],"ru":["Требуется установка GitHub CLI","Необходим доступ к терминалу","Ограничен только репозиториями GitHub"],"ar":["يتطلب تثبيت GitHub CLI","مطلوب الوصول إلى الطرفية","محدود بمخازن GitHub فقط"]},"version":4},"contentHash":"af673f737e85f693e788dae6de5392dc55d56b568d375f1b31a4957a65946c16","qualityScore":57}');
