INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('knoopx/pi/gh', 'gh', 'knoopx', 'pi', 'community', 'gh knoopx pi community The gh skill provides GitHub functionality in the terminal, allowing developers to manage repositories efficiently. It benefits developers who need to perform tasks such as viewing, cloning, and forking repositories. GitHub CLI (gh) 提供了 GitHub 功能在终端中的实现，包括仓库管理和配置 GitHub CLI (gh) は、GitHub の機能を端末で実現します。リポジトリ管理と設定が可能です GitHub CLI (gh) 는 GitHub 기능을 터미널에서 구현합니다. 리포지토리 관리 및 설정이 가능합니다 gh es una herramienta de línea de comandos para GitHub que permite gestionar repositorios de manera eficiente gh est un outil en ligne de commande pour GitHub qui permet de gérer des dépôts de manière efficace gh ist ein Kommandozeilen-Tool für GitHub, mit dem Sie Repositorys effizient verwalten können O gh é uma ferramenta de linha de comando para GitHub que permite gerenciar repositórios de forma eficiente. Com ele, você pode clonar, bifurcar e criar repositórios com facilidade. gh - это инструмент командной строки для GitHub, который позволяет управлять репозиториями эффективно. С его помощью вы можете клонировать, вилочный и создавать репозитории легко. gh هو أداة سطر أوامر لجيت هاب التي تمكنك من إدارة المستودعات بفعالية. يمكنك استنساخ وإنشاء وتفرع المستودعات بسهولة. how to use gh gh install gh vs git github cli tutorial gh setup guide what is gh gh alternative gh repo management GitHub CLI gh 仓库管理 配置管理 命令行工具 GitHub 设置 仓库查看 仓库克隆 仓库分叉 AI 工具 View current and specific repositories using gh repo view Clone repositories with gh repo clone Fork current repositories using gh repo fork Create new public and private repositories with gh repo create List repositories using gh repo list Open repositories in the browser with gh repo view --web gh is a command-line interface (CLI) that brings GitHub functionality to the terminal, enabling developers to interact with repositories using commands like gh repo view and gh repo clone.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dseirz-rgb/worker/code-porter', 'community', 'dseirz-rgb', 'worker', 'dseirz-rgb/worker', 'code-porter', 0, 0, 57, '2026-03-08T01:57:15.268Z', '2026-03-08T01:59:59.005Z', 'b371f66bae95d39d1f405af92e39ad81168770b19188ef07c3df133b408d8845', '{"id":"dseirz-rgb/worker/code-porter","name":"code-porter","description":{"en":"The code-porter skill helps developers integrate open-source projects into their own, prioritizing existing solutions over custom code. It benefits developers by streamlining their development process.","zh":"代码搬运师是一种AI工具，帮助开发者优先使用开源库，减少重复造轮子的工作","ja":"Code Porter AIエージェントは、開発者がオープンソースライブラリを優先して使用することにより、開発効率を向上させます","ko":"코드 포터는 開源 라이브러리를 우선 사용하여 개발 효율을 높이는 AI 도구입니다","es":"Code Porter es una habilidad que prioriza la implementación de soluciones de código abierto para evitar reinventar la rueda, con un enfoque en la reutilización de código maduro","fr":"Code Porter est une compétence qui donne la priorité à la mise en œuvre de solutions de code ouvert pour éviter de réinventer la roue, avec un focus sur la réutilisation de code mature","de":"Code Porter ist eine Fähigkeit, die die Implementierung von Open-Source-Lösungen priorisiert, um das erneute Erfinden des Rades zu vermeiden, mit Fokus auf die Wiederverwendung von ausgereiftem Code","pt":"O Code Porter é uma ferramenta que ajuda a otimizar o desenvolvimento de software, utilizando ferramentas de código aberto para reduzir a necessidade de reescrever código. Com ele, você pode encontrar e integrar soluções de código aberto em seus projetos","ru":"Code Porter — это инструмент, который помогает оптимизировать процесс разработки программного обеспечения, используя инструменты с открытым исходным кодом для минимизации необходимости переписывать код. С его помощью вы можете найти и интегрировать решения с открытым исходным кодом в свои проекты","ar":"Code Porter هو أداة تساعد على تحسين كفاءة تطوير البرمجيات باستخدام أدوات الكود المفتوح لتقليل الحاجة إلى إعادة كتابة الكود. يمكنك استخدامها لfinding ودمج حلول الكود المفتوح في مشاريعك"},"seo":{"title":{"en":"code-porter: Open-Source Project Integration Guide | AI A...","zh":"代码搬运师Setup Guide：优先使用开源库","ja":"Code Porter AIエージェント：ベストプラクティス","ko":"코드 포터 Setup Guide：開源 라이브러리 우선 사용","es":"Guía de configuración de Code Porter para desarrolladores","fr":"Guide de mise en place de Code Porter pour les développeurs","de":"Einrichtungsleitfaden für Code Porter für Entwickler","pt":"Guia de Configuração do Code Porter: Otimizando o Desenvo...","ru":"Настройка Code Porter: Руководство по Использованию ИИ Аг...","ar":"دليل إعداد Code Porter: تحسين التطوير باستخدام أدوات الكو..."},"description":{"en":"Discover how code-porter prioritizes open-source solutions, reducing redundant code. Learn to integrate mature libraries and evaluate custom implementation n...","zh":"代码搬运师帮助您优先使用开源库，减少重复造轮子的工作，提高开发效率","ja":"Code Porter AIエージェントは、オープンソースライブラリを優先して使用し、開発効率を向上させます","ko":"코드 포터는 開源 라이브러리를 우선 사용하여 반복적인 작업을 줄이고 개발 효율을 높입니다","es":"Aprende a utilizar Code Porter para implementar funciones y módulos de manera eficiente, con prioridad a soluciones de código abierto","fr":"Découvrez comment utiliser Code Porter pour mettre en œuvre des fonctions et des modules de manière efficace, en donnant la priorité aux solutions de code ou...","de":"Erfahren Sie, wie Sie Code Porter verwenden können, um Funktionen und Module effizient zu implementieren, mit Priorität auf Open-Source-Lösungen","pt":"Aprenda a usar o Code Porter para melhorar a eficiência do desenvolvimento de software, utilizando ferramentas de código aberto e reduzindo a necessidade de ...","ru":"Узнайте, как использовать Code Porter для оптимизации процесса разработки программного обеспечения, используя инструменты с открытым исходным кодом и минимиз...","ar":"تعلم كيفية استخدام Code Porter لتحسين كفاءة تطوير البرمجيات باستخدام أدوات الكود المفتوح وتقليل الحاجة إلى إعادة كتابة الكود"},"definition":{"en":"code-porter is a skill that prioritizes the integration of mature open-source libraries into projects, promoting efficient development by reusing existing solutions.","zh":"代码搬运师是一种AI工具，优先使用开源库，减少重复造轮子的工作","ja":"Code Porter AIエージェントは、オープンソースライブラリを優先して使用するAIツールです","ko":"코드 포터는 開源 라이브러리를 우선 사용하는 AI 도구입니다","es":"Code Porter es una herramienta de desarrollo que promueve la reutilización de código abierto y maduro para implementar funciones y módulos de manera eficiente","fr":"Code Porter est un outil de développement qui promeut la réutilisation de code ouvert et mature pour mettre en œuvre des fonctions et des modules de manière efficace","de":"Code Porter ist ein Entwicklungstool, das die Wiederverwendung von Open-Source-Code und ausgereiftem Code für die effiziente Implementierung von Funktionen und Modulen fördert","pt":"O Code Porter é uma ferramenta de desenvolvimento de software que ajuda a encontrar e integrar soluções de código aberto em projetos","ru":"Code Porter — это инструмент разработки программного обеспечения, который помогает находить и интегрировать решения с открытым исходным кодом в проекты","ar":"Code Porter هو أداة تطوير برمجيات تساعد على العثور ودمج حلول الكود المفتوح في المشاريع"},"features":{"en":["Prioritizes open-source library integration over custom code","Evaluates project needs to determine the best implementation approach","Supports the use of forked and modified open-source projects","References existing implementations for inspiration","Helps developers avoid redundant code by leveraging mature libraries"],"zh":["优先使用成熟开源库","Fork修改和参考实现","评估是否需要自己编写代码","集成第三方服务或API","减少重复造轮子的工作"],"ja":["成熟したオープンソースライブラリを優先して使用","Fork修正と参考実装","自分でコードを書く必要性を評価","第三者サービスまたはAPIの統合","開発効率の向上"],"ko":["成熟한 開源 라이브러리를 우선 사용","Fork 수정과 참고 구현","自分で 코드를 작성해야 하는지 평가","第三자 서비스 또는 API의 통합","개발 효율의 향상"],"es":["Priorización de soluciones de código abierto","Implementación de funciones y módulos con código maduro","Evaluación de la necesidad de código personalizado","Integración de servicios y API de terceros","Reutilización de código para evitar la redundancia"],"fr":["Priorisation des solutions de code ouvert","Mise en œuvre de fonctions et de modules avec du code mature","Évaluation de la nécessité de code personnalisé","Intégration de services et d''API tiers","Réutilisation de code pour éviter la redondance"],"de":["Priorisierung von Open-Source-Lösungen","Implementierung von Funktionen und Modulen mit ausgereiftem Code","Bewertung der Notwendigkeit von benutzerdefiniertem Code","Integration von Drittanbieter-Services und APIs","Wiederverwendung von Code zur Vermeidung von Redundanz"],"pt":["Priorização de soluções de código aberto","Integração de bibliotecas e frameworks de código aberto","Otimização do desenvolvimento de software","Redução da necessidade de reescrever código","Suporte à avaliação de soluções de código aberto"],"ru":["Приоритезация решений с открытым исходным кодом","Интеграция библиотек и фреймворков с открытым исходным кодом","Оптимизация процесса разработки программного обеспечения","Минимизация необходимости переписывать код","Поддержка оценки решений с открытым исходным кодом"],"ar":["التحديد الأول للبرمجيات المفتوحة المصدر","دمج المكتبات والإطارات المفتوحة المصدر","تحسين تطوير البرمجيات","تقليل الحاجة إلى إعادة كتابة الكود","دعم تقييم البرمجيات المفتوحة المصدر"]},"keywords":{"en":["how to use code-porter","code-porter setup guide","open-source project integration","code-porter alternative","code-porter vs custom implementation","reducing redundant code with code-porter","code-porter install","code-porter for efficient development"],"zh":["代码搬运师","开源库","AI工具","开发效率","重复造轮子","Fork修改","参考实现","第三方服务","API集成"],"ja":["Code Porter AIエージェント","オープンソースライブラリ","AIツール","開発効率","開発時間の短縮","Fork修正","参考実装","第三者サービス","API統合"],"ko":["코드 포터","開源 라이브러리","AI 도구","개발 효율","개발 시간의 단축","Fork 수정","참고 구현","第三자 서비스","API 통합"],"es":["code porter","desarrollo de software","código abierto","reutilización de código","implementación de funciones","integración de servicios","API de terceros","herramientas de desarrollo","eficiencia en el desarrollo"],"fr":["code porter","développement de logiciels","code ouvert","réutilisation de code","mise en œuvre de fonctions","intégration de services","API de tiers","outils de développement","efficacité dans le développement"],"de":["code porter","Software-Entwicklung","Open-Source-Code","Wiederverwendung von Code","Implementierung von Funktionen","Integration von Drittanbieter-Services","API von Drittanbietern","Entwicklungstools","Effizienz in der Entwicklung"],"pt":["Code Porter","desenvolvimento de software","ferramentas de código aberto","otimização de desenvolvimento","redução de código","integração de bibliotecas","frameworks de código aberto","avaliação de soluções de código aberto"],"ru":["Code Porter","ИИ Агенты","разработка программного обеспечения","инструменты с открытым исходным кодом","оптимизация кодирования","минимизация кода","интеграция библиотек","фреймворки с открытым исходным кодом","оценка решений с открытым исходным кодом"],"ar":["Code Porter","أدوات الذكاء الاصطناعي","تطوير البرمجيات","أدوات الكود المفتوح","تحسين الكود","تقليل الكود","دمج المكتبات","إطارات الكود المفتوح","تقييم البرمجيات المفتوحة المصدر"]}},"owner":"dseirz-rgb","repo":"worker","repoPath":"dseirz-rgb/worker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.268Z","topics":[],"category":"community","skillMd":{"name":"code-porter","description":"|","bodyPreview":"# Code Porter (代码搬运师)\n\n> 🚚 **核心理念**: 我是代码搬运师，喜欢搬运优秀的开源项目到自己的项目里。非必要，禁止重复造轮子。\n\n## 🔴 第一原则：先搬运，再修改\n\n**无论什么代码，都要先找开源方案！**\n\n```\n❌ 错误思路: \"这是核心逻辑，我要自己写\"\n✅ 正确思路: \"这是核心逻辑，更要找成熟方案，先搬运再改\"\n\n❌ 错误思路: \"安全代码太重要了，必须自己实现\"  \n✅ 正确思路: \"安全代码太重要了，自己写更危险，用久经考验的开源库\"\n```\n\n**搬运优先级**: 成熟开源库 > Fork修改 > 参考实现 > 最后才自己写\n\n## When to Use This Skill\n\n使用此技能当你需要：\n- 实现一个新功能或模块\n- 选择技术方案或库\n- 评估是否需要自己编写代码\n- 寻找现有解决方案\n- 集成第三方服务或 API\n\n## Not For / Boundaries\n\n此技能不适用于：\n- 已有明确技术选型的项目（遵循现有架构）\n- 纯学习目的的练习项目（刻意练习除外）\n\n### ⚠️ 常见误区纠正\n\n**误区**: \"核心","body":"# Code Porter (代码搬运师)\n\n> 🚚 **核心理念**: 我是代码搬运师，喜欢搬运优秀的开源项目到自己的项目里。非必要，禁止重复造轮子。\n\n## 🔴 第一原则：先搬运，再修改\n\n**无论什么代码，都要先找开源方案！**\n\n```\n❌ 错误思路: \"这是核心逻辑，我要自己写\"\n✅ 正确思路: \"这是核心逻辑，更要找成熟方案，先搬运再改\"\n\n❌ 错误思路: \"安全代码太重要了，必须自己实现\"  \n✅ 正确思路: \"安全代码太重要了，自己写更危险，用久经考验的开源库\"\n```\n\n**搬运优先级**: 成熟开源库 > Fork修改 > 参考实现 > 最后才自己写\n\n## When to Use This Skill\n\n使用此技能当你需要：\n- 实现一个新功能或模块\n- 选择技术方案或库\n- 评估是否需要自己编写代码\n- 寻找现有解决方案\n- 集成第三方服务或 API\n\n## Not For / Boundaries\n\n此技能不适用于：\n- 已有明确技术选型的项目（遵循现有架构）\n- 纯学习目的的练习项目（刻意练习除外）\n\n### ⚠️ 常见误区纠正\n\n**误区**: \"核心业务逻辑必须自己写\"\n**正解**: 核心业务逻辑也要**先搬运再修改**！\n- 交易系统？先看 [ccxt](https://github.com/ccxt/ccxt)、[hummingbot](https://github.com/hummingbot/hummingbot)\n- 风控引擎？先看 [riskfolio-lib](https://github.com/dcajasn/Riskfolio-Lib)\n- 推荐系统？先看 [surprise](https://github.com/NicolasHug/Surprise)\n\n**误区**: \"安全代码必须自己实现\"\n**正解**: 安全代码**更要用成熟开源方案**！自己写反而更危险！\n- 认证？用 [passport](https://github.com/jaredhanson/passport)、[next-auth](https://github.com/nextauthjs/next-auth)\n- 加密？用 [crypto-js](https://github.com/brix/crypto-js)、[bcrypt](https://github.com/kelektiv/node.bcrypt.js)\n- JWT？用 [jose](https://github.com/panva/jose)、[jsonwebtoken](https://github.com/auth0/node-jsonwebtoken)\n\n---\n\n## Quick Reference\n\n### 🎯 搬运决策流程\n\n```\n需求 → 搜索开源方案 → 评估适配性 → 搬运/集成 → 适配调整\n         ↓\n    找不到合适的 → 最小化自己实现\n```\n\n### 📋 搬运前必问清单\n\n| 问题 | 目的 |\n|------|------|\n| 1. 有没有现成的库/包？ | npm/pip/cargo 搜索 |\n| 2. 有没有类似的开源项目？ | GitHub 搜索 |\n| 3. 官方文档有没有推荐方案？ | 查阅官方文档 |\n| 4. 社区有没有最佳实践？ | Stack Overflow / Reddit |\n| 5. 这个轮子值得自己造吗？ | 成本/收益分析 |\n\n### 🔍 搜索策略\n\n```bash\n# 1. 包管理器搜索\nnpm search <keyword>\npip search <keyword>  # 或 pip index versions <package>\n\n# 2. GitHub 搜索\n# 按 stars 排序: stars:>1000 <keyword>\n# 按语言过滤: language:typescript <keyword>\n# 按最近更新: pushed:>2024-01-01 <keyword>\n\n# 3. Awesome 列表\n# 搜索 \"awesome-<domain>\" 仓库\n```\n\n### ✅ 开源项目评估标准\n\n| 指标 | 合格线 | 优秀线 |\n|------|--------|--------|\n| Stars | >100 | >1000 |\n| 最近更新 | <6个月 | <1个月 |\n| Issues 响应 | 有回复 | 24h内回复 |\n| 文档质量 | 有 README | 有完整文档站 |\n| 测试覆盖 | 有测试 | >80% 覆盖 |\n| 许可证 | MIT/Apache | MIT |\n| 依赖数量 | <20 | <5 |\n\n### 🚫 禁止造轮子清单\n\n以下场景**必须**使用现有方案：\n\n| 领域 | 推荐方案 |\n|------|----------|\n| HTTP 请求 | axios, fetch, ky |\n| 状态管理 | zustand, jotai, redux-toolkit |\n| 表单验证 | zod, yup, joi |\n| 日期处理 | date-fns, dayjs |\n| UI 组件 | shadcn/ui, radix-ui, headless-ui |\n| 图表 | recharts, chart.js, echarts |\n| 动画 | framer-motion, react-spring |\n| 数据库 ORM | drizzle, prisma, typeorm |\n| API 客户端 | openapi-typescript, trpc |\n| 测试 | vitest, jest, playwright |\n| 构建工具 | vite, esbuild, turbopack |\n| 代码格式化 | prettier, eslint |\n| **认证授权** | next-auth, passport, lucia |\n| **加密哈希** | bcrypt, argon2, crypto-js |\n| **JWT 处理** | jose, jsonwebtoken |\n| **交易系统** | ccxt, hummingbot |\n| **风控引擎** | riskfolio-lib, pyfolio |\n| **量化分析** | qlib, backtrader, zipline |\n\n### 🔧 搬运集成模式\n\n**模式 1: 直接安装**\n```bash\nnpm install <package>\n# 或\npnpm add <package>\n```\n\n**模式 2: 复制代码片段**\n```typescript\n// 来源: https://github.com/xxx/yyy\n// 许可证: MIT\n// 原作者: @author\n// 修改说明: 适配本项目的 TypeScript 类型\n\n// ... 代码 ...\n```\n\n**模式 3: Fork + 定制**\n```bash\n# 1. Fork 仓库\n# 2. 修改适配\n# 3. 作为 git submodule 或私有包引入\n```\n\n**模式 4: 参考实现**\n```typescript\n// 参考: https://github.com/xxx/yyy/blob/main/src/utils.ts\n// 基于原实现重写，适配本项目架构\n```\n\n---\n\n## Examples\n\n### Example 1: 需要实现 WebSocket 实时通信\n\n**Input:** \"我需要在 React 项目中实现 WebSocket 实时通信\"\n\n**Steps:**\n1. 搜索现有方案: `npm search websocket react`\n2. 发现候选: `socket.io-client`, `@tanstack/react-query` + WebSocket, `use-websocket`\n3. 评估 `use-websocket`:\n   - Stars: 1.8k ✅\n   - 最近更新: 2024 ✅\n   - TypeScript 支持: 完整 ✅\n   - 文档: 清晰 ✅\n4. 决策: 使用 `use-websocket`\n\n**Expected Output:**\n```bash\npnpm add react-use-websocket\n```\n\n```typescript\nimport useWebSocket from ''react-use-websocket'';\n\nfunction MyComponent() {\n  const { sendMessage, lastMessage } = useWebSocket(''wss://api.example.com'');\n  // ...\n}\n```\n\n### Example 2: 需要实现 Markdown 渲染\n\n**Input:** \"需要在页面中渲染 Markdown 内容，支持代码高亮\"\n\n**Steps:**\n1. 搜索: `npm search markdown react`\n2. 候选: `react-markdown`, `marked`, `markdown-it`\n3. 评估 `react-markdown`:\n   - Stars: 12k+ ✅\n   - 生态: 支持 remark/rehype 插件 ✅\n   - 代码高亮: 配合 `react-syntax-highlighter` ✅\n4. 决策: 使用 `react-markdown` + `react-syntax-highlighter`\n\n**Expected Output:**\n```bash\npnpm add react-markdown react-syntax-highlighter @types/react-syntax-highlighter\n```\n\n### Example 3: 需要实现拖拽排序\n\n**Input:** \"列表需要支持拖拽排序功能\"\n\n**Steps:**\n1. 搜索: `npm search drag drop react`\n2. 候选: `@dnd-kit/core`, `react-beautiful-dnd`, `react-dnd`\n3. 评估 `@dnd-kit`:\n   - Stars: 11k+ ✅\n   - 维护: 活跃 ✅\n   - 性能: 优秀 ✅\n   - 无障碍: 支持 ✅\n4. 决策: 使用 `@dnd-kit`\n\n**Expected Output:**\n```bash\npnpm add @dnd-kit/core @dnd-kit/sortable @dnd-kit/utilities\n```\n\n---\n\n## 搬运工作流\n\n### Phase 1: 需求分析\n```\n1. 明确功能需求\n2. 确定技术约束（语言、框架、性能要求）\n3. 评估复杂度\n```\n\n### Phase 2: 方案搜索\n```\n1. 包管理器搜索\n2. GitHub 搜索 (stars:>500)\n3. Awesome 列表查找\n4. 官方文档推荐\n5. 社区讨论（Reddit, HN, Twitter）\n```\n\n### Phase 3: 方案评估\n```\n1. 活跃度检查（最近提交、Issue 响应）\n2. 质量检查（测试、文档、TypeScript）\n3. 兼容性检查（依赖冲突、版本要求）\n4. 许可证检查（MIT/Apache 优先）\n5. 安全检查（npm audit, snyk）\n```\n\n### Phase 4: 集成实施\n```\n1. 安装依赖\n2. 阅读文档/示例\n3. 编写适配代码\n4. 测试验证\n5. 文档记录（来源、版本、修改）\n```\n\n---\n\n## References\n\n- `references/index.md`: 导航索引\n- `references/awesome-lists.md`: 常用 Awesome 列表汇总\n- `references/license-guide.md`: 开源许可证选择指南\n\n---\n\n## Maintenance\n\n- **Sources**: vibe-coding-cn 方法论, 开源社区最佳实践\n- **Last Updated**: 2025-12-30\n- **Known Limits**: \n  - 评估标准为经验值，需根据具体场景调整\n  - 某些领域可能缺少成熟开源方案\n"},"lastSynced":"2026-03-08T01:59:59.005Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient open-source integration and code reuse capabilities.","zh":"非常适合需要高效开源集成和代码重用功能的开发者代理。","ja":"開発者エージェントが効率的なオープンソース統合とコードの再利用機能を必要とする場合に最適です。","ko":"개발자 에이전트가 효율적인 오픈소스 통합 및 코드 재사용 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una integración de código abierto eficiente y capacidades de reutilización de código.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une intégration de code ouvert efficace et de capacités de réutilisation de code.","de":"Perfekt für Entwickler-Agenten, die eine effiziente Open-Source-Integration und Code-Wiederverwendungs-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de integração de código de fonte aberta eficiente e capacidades de reutilização de código.","ru":"Идеально подходит для разработчиков агентов, которым необходима эффективная интеграция с открытым исходным кодом и возможности повторного использования кода.","ar":"مثالي لعميل المطور الذي يحتاج إلى إمكانية التكامل الفعّال مع المصدر المفتوح وإعادة استخدام الشفرة."},"recommendation":{"en":"Empowers agents to prioritize existing solutions over custom code, streamlining development by integrating mature open-source libraries and projects, following a strict porter priority of mature open-source libraries, forked modifications, referenced implementations, and lastly custom writing.","zh":"赋予代理优先使用现有解决方案而不是自定义代码的能力，通过集成成熟的开源库和项目，按照严格的porter优先级，成熟的开源库、分叉修改、引用实现和最后自定义编写，简化开发过程。","ja":"エージェントがカスタムコードよりも既存の解決策を優先し、成熟したオープンソースライブラリとプロジェクトを統合することで開発を合理化する能力を付与し、厳格なポーター優先順位、成熟したオープンソースライブラリ、フォークされた変更、参照実装、および最後にカスタムライティングに従う。","ko":"에이전트가 커스텀 코드보다 기존 솔루션을 우선하여 개발을 간소화할 수 있는 능력을 부여하며, 엄격한 포터 우선 순위를 따르며, 완성된 오픈소스 라이브러리, 포크된 수정, 참조 구현 및 마지막으로 커스텀 작성으로 개발을 단순화합니다.","es":"Permite a los agentes priorizar las soluciones existentes sobre el código personalizado, simplificando el desarrollo mediante la integración de bibliotecas y proyectos de código abierto maduros, siguiendo una estricta prioridad de bibliotecas de código abierto maduros, modificaciones bifurcadas, implementaciones de referencia y, por último, escritura personalizada.","fr":"Permet aux agents de donner la priorité aux solutions existantes plutôt qu''au code personnalisé, en simplifiant le développement en intégrant des bibliothèques et des projets open-source matures, en suivant une stricte priorité de bibliothèques open-source matures, de modifications forkées, d''implémentations de référence et, enfin, d''écriture personnalisée.","de":"Ermöglicht es Agenten, bestehende Lösungen gegenüber benutzerdefiniertem Code zu priorisieren, indem sie die Entwicklung durch die Integration von ausgereiften Open-Source-Bibliotheken und -Projekten vereinfachen, einer strengen Priorität von ausgereiften Open-Source-Bibliotheken, modifizierten Forks, Referenzimplementierungen und schließlich benutzerdefinierter Schreibweise folgen.","pt":"Habilita agentes a priorizar soluções existentes sobre código personalizado, racionalizando o desenvolvimento por meio da integração de bibliotecas e projetos de código aberto maduros, seguindo uma estrita prioridade do porteiro de bibliotecas de código aberto maduro, modificações bifurcadas, implementações referenciadas e, por fim, escrita personalizada.","ru":"Наделяет агентов возможностью отдавать предпочтение существующим решениям над пользовательским кодом, упрощая разработку путем интеграции зрелых библиотек и проектов с открытым исходным кодом, следуя строгой очередности портера зрелых библиотек с открытым исходным кодом, измененных форков, ссылочных реализаций и, наконец, пользовательской записи.","ar":"يُمكِّن الوكيل من الأولوية ل الحلول الموجودة على الكود المخصص، و يُبسّط التطوير من خلال دمج المكتبات و المشاريع مفتوحة المصدر الناضجة، و متابعة الأولوية الصارمة للبوّاب لمكتبات مفتوحة المصدر الناضجة، و التعديلات المنشقة، و التنفيذات المرجعية، و أخيراً الكتابة المخصصة."},"useCases":{"en":["Integrating third-party APIs and services","Evaluating the need for custom code versus open-source solutions","Implementing new functionalities or modules with existing open-source projects"],"zh":["集成第三方API和服务","评估自定义代码与开源解决方案的需求","使用现有的开源项目实现新的功能或模块"],"ja":["サードパーティAPIおよびサービスを統合する","カスタムコードとオープンソースソリューションのニーズを評価する","既存のオープンソースプロジェクトを使用して新しい機能またはモジュールを実装する"],"ko":["제3자 API 및 서비스 통합","커스텀 코드와 오픈소스 솔루션의 필요성 평가","기존 오픈소스 프로젝트를 사용하여 새로운 기능 또는 모듈 구현"],"es":["Integración de API y servicios de terceros","Evaluación de la necesidad de código personalizado versus soluciones de código abierto","Implementación de nuevas funcionalidades o módulos con proyectos de código abierto existentes"],"fr":["Intégration d''API et de services tiers","Évaluation de la nécessité de code personnalisé par rapport aux solutions open-source","Implémentation de nouvelles fonctionnalités ou de modules avec des projets open-source existants"],"de":["Integration von Drittanbieter-APIs und -Diensten","Bewertung der Notwendigkeit von benutzerdefiniertem Code im Vergleich zu Open-Source-Lösungen","Implementierung neuer Funktionalitäten oder Module mit bestehenden Open-Source-Projekten"],"pt":["Integrando APIs e serviços de terceiros","Avaliando a necessidade de código personalizado versus soluções de código aberto","Implementando novas funcionalidades ou módulos com projetos de código aberto existentes"],"ru":["Интеграция с внешними API и сервисами","Оценка необходимости пользовательского кода по сравнению с открытым исходным кодом","Реализация новых функциональностей или модулей с использованием существующих проектов с открытым исходным кодом"],"ar":["دمج واجهات برمجة التطبيقات و الخدمات الخارجية","تقييم الحاجة إلى الكود المخصص مقابل حلول مفتوحة المصدر","تنفيذ وظائف أو وحدات جديدة مع مشاريع مفتوحة المصدر موجودة"]},"limitations":{"en":["Not suitable for projects with predefined technical selections or pure learning exercises","Requires careful evaluation of open-source solutions for security and compatibility"],"zh":["不适合具有预定义技术选择或纯学习练习的项目","需要仔细评估开源解决方案的安全性和兼容性"],"ja":["技術的選択が既に決定されているプロジェクトや純粋な学習演習には適していない","セキュリティと互換性の観点からオープンソースソリューションを慎重に評価する必要がある"],"ko":["이미 기술적 선택이 결정된 프로젝트나 순수한 학습 연습에는 적합하지 않음","보안 및 호환성 측면에서 오픈소스 솔루션을 신중하게 평가해야 함"],"es":["No es adecuado para proyectos con selecciones técnicas predefinidas o ejercicios de aprendizaje puro","Requiere una evaluación cuidadosa de las soluciones de código abierto para la seguridad y la compatibilidad"],"fr":["N''est pas adapté aux projets avec des sélections techniques prédéfinies ou des exercices d''apprentissage pur","Nécessite une évaluation soigneuse des solutions open-source pour la sécurité et la compatibilité"],"de":["Nicht geeignet für Projekte mit vordefinierten technischen Auswahlmöglichkeiten oder reinen Lernübungen","Erfordert eine sorgfältige Bewertung von Open-Source-Lösungen hinsichtlich Sicherheit und Kompatibilität"],"pt":["Não é adequado para projetos com seleções técnicas pré-definidas ou exercícios de aprendizado puro","Exige uma avaliação cuidadosa das soluções de código aberto para segurança e compatibilidade"],"ru":["Не подходит для проектов с предопределенными техническими выборами или чистыми упражнениями для обучения","Требует тщательной оценки решений с открытым исходным кодом для безопасности и совместимости"],"ar":["لا يناسب المشاريع التي لديها اختيارات تقنية محددة مسبقا أو تمارين تعليمية نقية","يتطلب تقييما دقيقا للحلول مفتوحة المصدر من أجل الأمان و التوافق"]},"version":4},"contentHash":"b371f66bae95d39d1f405af92e39ad81168770b19188ef07c3df133b408d8845","qualityScore":57}');
