INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dseirz-rgb/worker/code-porter', 'code-porter', 'dseirz-rgb', 'worker', 'community', 'code-porter dseirz-rgb worker community The code-porter skill helps developers integrate open-source projects into their own, prioritizing existing solutions over custom code. It benefits developers by streamlining their development process. 代码搬运师是一种AI工具，帮助开发者优先使用开源库，减少重复造轮子的工作 Code Porter AIエージェントは、開発者がオープンソースライブラリを優先して使用することにより、開発効率を向上させます 코드 포터는 開源 라이브러리를 우선 사용하여 개발 효율을 높이는 AI 도구입니다 Code Porter es una habilidad que prioriza la implementación de soluciones de código abierto para evitar reinventar la rueda, con un enfoque en la reutilización de código maduro Code Porter est une compétence qui donne la priorité à la mise en œuvre de solutions de code ouvert pour éviter de réinventer la roue, avec un focus sur la réutilisation de code mature Code Porter ist eine Fähigkeit, die die Implementierung von Open-Source-Lösungen priorisiert, um das erneute Erfinden des Rades zu vermeiden, mit Fokus auf die Wiederverwendung von ausgereiftem Code O Code Porter é uma ferramenta que ajuda a otimizar o desenvolvimento de software, utilizando ferramentas de código aberto para reduzir a necessidade de reescrever código. Com ele, você pode encontrar e integrar soluções de código aberto em seus projetos Code Porter — это инструмент, который помогает оптимизировать процесс разработки программного обеспечения, используя инструменты с открытым исходным кодом для минимизации необходимости переписывать код. С его помощью вы можете найти и интегрировать решения с открытым исходным кодом в свои проекты Code Porter هو أداة تساعد على تحسين كفاءة تطوير البرمجيات باستخدام أدوات الكود المفتوح لتقليل الحاجة إلى إعادة كتابة الكود. يمكنك استخدامها لfinding ودمج حلول الكود المفتوح في مشاريعك how to use code-porter code-porter setup guide open-source project integration code-porter alternative code-porter vs custom implementation reducing redundant code with code-porter code-porter install code-porter for efficient development 代码搬运师 开源库 AI工具 开发效率 重复造轮子 Fork修改 参考实现 第三方服务 API集成 Prioritizes open-source library integration over custom code Evaluates project needs to determine the best implementation approach Supports the use of forked and modified open-source projects References existing implementations for inspiration Helps developers avoid redundant code by leveraging mature libraries code-porter is a skill that prioritizes the integration of mature open-source libraries into projects, promoting efficient development by reusing existing solutions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jovermier/claude-code-plugins-ip-labs/best-practices-researcher', 'community', 'jovermier', 'claude-code-plugins-ip-labs', 'jovermier/claude-code-plugins-ip-labs', 'best-practices-researcher', 0, 0, 57, '2026-03-08T01:57:15.268Z', '2026-03-08T01:59:59.618Z', '73f12052ccc9ff4695c4a85270dea49a97a6af6015f40da1db36c0ecf76cdc83', '{"id":"jovermier/claude-code-plugins-ip-labs/best-practices-researcher","name":"best-practices-researcher","description":{"en":"The best-practices-researcher skill gathers comprehensive information from external sources, synthesizing expert knowledge for developers. It benefits developers by providing context for recommendations.","zh":"最佳实践研究员是一种专门从外部来源寻找和综合最佳实践的研究专家，涵盖官方文档、社区标准和开源项目","ja":"ベストプラクティス研究者は、公式ドキュメント、コミュニティ標準、オープンソースプロジェクトを含む外部ソースからのベストプラクティスを探し、統合する研究専門家です","ko":"베스트 프랙티스 리서처는 공식 문서, 커뮤니티 표준, 오픈소스 프로젝트를 포함한 외부 소스에서 베스트 프랙티스를 찾고 종합하는 연구 전문가입니다","es":"El Best Practices Researcher es un experto en investigación que ayuda a los desarrolladores a encontrar y sintetizar las mejores prácticas desde fuentes externas, como documentación oficial y proyectos de código abierto","fr":"Le Best Practices Researcher est un expert en recherche qui aide les développeurs à trouver et à synthétiser les meilleures pratiques à partir de sources externes, telles que la documentation officielle et les projets open source","de":"Der Best Practices Researcher ist ein Forschungsexperte, der Entwicklern hilft, die besten Praktiken aus externen Quellen wie offizieller Dokumentation und Open-Source-Projekten zu finden und zu synthetisieren","pt":"O Best Practices Researcher é um especialista em pesquisa que encontra e sintetiza as melhores práticas de fontes externas, incluindo documentação oficial e projetos de código aberto","ru":"Best Practices Researcher - это исследовательский эксперт, который 