INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nice-Wolf-Studio/agent-github-skills/search-operations', 'search-operations', 'Nice-Wolf-Studio', 'agent-github-skills', 'community', 'search-operations Nice-Wolf-Studio agent-github-skills community The search-operations skill provides comprehensive search capabilities across GitHub, including code, issues, and users. It benefits developers by replicating GitHub MCP server functionality using gh CLI search-operations skill 提供 GitHub 代码、问题、拉取请求、仓库和用户的综合搜索功能 search-operations スキルは、GitHub のコード、問題、プルリクエスト、リポジトリ、ユーザーの包括的な検索機能を提供します search-operations 스킬은 GitHub 코드, 문제, 풀 리퀘스트, 저장소 및 사용자의 포괄적인 검색 기능을 제공합니다 El skill de búsqueda de operaciones proporciona capacidades de búsqueda avanzadas en GitHub, incluyendo búsqueda de código, problemas y solicitudes de extracción Le skill d''opérations de recherche fournit des capacités de recherche avancées sur GitHub, notamment la recherche de code, de problèmes et de demandes d''extraction Das Suchoperationen-Skill bietet erweiterte Suchfunktionen in GitHub, einschließlich Code-, Problemm- und Pull-Request-Suche O search-operations é uma coleção de habilidades do Claude Code que replicam a funcionalidade do servidor MCP do GitHub usando o gh CLI, permitindo buscas avançadas por código, problemas e repositórios. ИИ Агенты search-operations - это коллекция навыков Claude Code, которые реплицируют функциональность сервера MCP GitHub, используя gh CLI, для расширенного поиска кода, проблем и репозиториев. وكلاء الذكاء الاصطناعي search-operations هي مجموعة من مهارات كلود كود التي تتكرر وظيفة خادم MCP على جيت هاب باستخدام غه CLI، مما يسمح بالبحث المتقدم عن الكود والمشاكل والمستودعات. how to use search-operations search-operations alternative search-operations setup guide what is search-operations search-operations vs GitHub MCP search-operations install GitHub 搜索 代码搜索 问题搜索 拉取请求搜索 仓库搜索 用户搜索 gh CLI search-operations AIエージェント GitHub搜索操作 Search code across GitHub repositories using gh CLI Search issues and pull requests with advanced filters Find repositories matching specific criteria Search for GitHub users and organizations Replicate GitHub MCP server functionality search-operations is a collection of Claude Code skills that enable advanced search capabilities across GitHub repositories, issues, and users');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ElliotJLT/Claude-Skill-Potions/eta', 'community', 'ElliotJLT', 'Claude-Skill-Potions', 'ElliotJLT/Claude-Skill-Potions', 'eta', 0, 0, 57, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:10.393Z', '2ac9d2f5606746f4e09271f19995e5a226be24f4d36d6e5494ae96264e814339', '{"id":"ElliotJLT/Claude-Skill-Potions/eta","name":"eta","description":{"en":"eta provides realistic time estimates for coding tasks by analyzing codebase scope, categorizing task complexity, and identifying risk factors. This skill benefits developers and teams by enabling better planning and preventing delays.","zh":"ETA 技术通过分析代码库范围、任务复杂性和风险因素，提供代码任务的真实时间估计","ja":"ETA はコードベースのスコープ、タスクの複雑さ、リスク要因を分析してコーディングタスクの時間見積もりを提供します","ko":"ETA는 코드베이스의 범위, 태스크의 복잡성 및 위험 요인을 분석하여 코드 작성 태스크의 시간을 추정합니다","es":"ETA es una herramienta de inteligencia artificial que proporciona estimaciones de tiempo realistas para tareas de codificación, analizando el alcance de la base de código y identificando factores de riesgo","fr":"ETA est un outil d''intelligence artificielle qui fournit des estimations de temps réalistes pour les tâches de codage, en analysant la portée de la base de code et en identifiant les facteurs de risque","de":"ETA ist ein KI-Tool, das realistische Zeitenschätzungen für Codierungsaufgaben liefert, indem es den Umfang der Codebasis analysiert und Risikofaktoren identifiziert","pt":"A habilidade ETA fornece estimativas de tempo de codificação realistas, analisando o escopo da base de código e identificando fatores de risco","ru":"Навык ETA предоставляет реалистичные оценки времени кодирования, анализируя объем кодовой базы и выявляя факторы риска","ar":"المهارة ETA توفر تقييمات زمن الترميز الواقعية، من خلال تحليل نطاق قاعدة الشفرة والتعرف على عوامل الخطر"},"seo":{"title":{"en":"eta: Realistic Time Estimates for Coding Tasks | AI Agent...","zh":"ETA 代码任务估时指南","ja":"ETA: コーディングタスクの時間見積もりセットアップガイド","ko":"ETA:コード작성 태스크 시간 추정하기","es":"Guía de configuración de ETA para estimaciones de codific...","fr":"Guide d''installation d''ETA pour les estimations de codage","de":"Einrichtungsleitfaden für ETA zur Codierungszeitenschätzung","pt":"ETA: Guia de Configuração para Estimativas de Tempo de Co...","ru":"ETA: Руководство по настройке для реалистичных оценок вре...","ar":"ETA: دليل الإعداد لتقييمات زمن الترميز الواقعية"},"description":{"en":"Get accurate coding time estimates with eta. Learn how to prevent surprise delays and improve your planning. Try eta today!","zh":"ETA 技术提供代码任务的真实时间估计，帮助开发者避免意外延迟","ja":"ETA を使用してコーディングタスクの時間見積もりを正確に行い、計画性を高めましょう","ko":"ETA를 사용하여 코드 작성 태스크의 시간을 정확히 추정하고, 계획을 수립하세요","es":"Optimice sus flujos de trabajo de Ops/Product con ETA, una herramienta de inteligencia artificial para estimar tiempos de codificación realistas","fr":"Optimisez vos flux de travail Ops/Product avec ETA, un outil d''intelligence artificielle pour estimer les temps de codage réalistes","de":"Optimieren Sie Ihre Ops/Product-Workflows mit ETA, einem KI-Tool zur Schätzung realistischer Codierungszeiten","pt":"Aprenda a configurar a habilidade ETA para obter estimativas de tempo de codificação realistas e otimizar seus fluxos de trabalho de operações e produtos","ru":"Узнайте, как настроить навык ETA для получения реалистичных оценок времени кодирования и оптимизации ваших операционных и продуктовых потоков","ar":"تعلم كيفية تكوين مهارة ETA للحصول على تقييمات زمن الترميز الواقعية وتحسين تدفقات العمل التشغيلية والمنتجات"},"definition":{"en":"eta is a collection of Claude skills that optimize Ops/Product workflows by providing realistic time estimates for coding tasks before work begins.","zh":"ETA 是一种代码任务时间估计技术，通过分析代码库和任务复杂性提供真实的时间预测","ja":"ETA は、コードベースとタスクの複雑さを分析して時間見積もりを提供するコーディングタスクの時間見積もり技術です","ko":"ETA는 코드베이스와 태스크의 복잡성을 분석하여 시간을 추정하는 코드 작성 태스크의 시간 추정 기술입니다","es":"ETA es una herramienta de inteligencia artificial que analiza la complejidad de las tareas de codificación y proporciona estimaciones de tiempo realistas","fr":"ETA est un outil d''intelligence artificielle qui analyse la complexité des tâches de codage et fournit des estimations de temps réalistes","de":"ETA ist ein KI-Tool, das die Komplexität von Codierungsaufgaben analysiert und realistische Zeitenschätzungen liefert","pt":"ETA é uma habilidade que fornece estimativas de tempo de codificação realistas, ajudando a prevenir atrasos e melhorar a planejamento","ru":"ETA - это навык, который предоставляет реалистичные оценки времени кодирования, помогая предотвратить задержки и улучшить планирование","ar":"ETA هي مهارة توفر تقييمات زمن الترميز الواقعية، مما يساعد في منع التأخيرات وتحسين التخطيط"},"features":{"en":["Analyzes codebase scope to estimate task complexity","Categorizes tasks based on complexity and risk factors","Calculates estimates using measured Claude Code performance baselines","Collects task description and relevant codebase path for accurate estimates","Prevents surprise delays by providing realistic time estimates"],"zh":["代码库范围分析","任务复杂性分类","风险因素识别","基于 Claude Code 性能基线的时间估计"],"ja":["コードベースのスコープ分析","タスクの複雑さの分类","リスク要因の識別","Claude Code のパフォーマンス基準に基づく時間見積もり"],"ko":["코드베이스의 범위 분석","태스크의 복잡성 분류","위험 요인의 식별","Claude Code의 성능 기준에 따른 시간 추정"],"es":["Análisis de la complejidad de la tarea de codificación","Identificación de factores de riesgo","Cálculo de estimaciones de tiempo basadas en mediciones de rendimiento de Claude Code","Prevención de retrasos sorpresa","Mejora de la planificación"],"fr":["Analyse de la complexité de la tâche de codage","Identification des facteurs de risque","Calcul des estimations de temps basées sur les mesures de performances de Claude Code","Prévention des retards inattendus","Amélioration de la planification"],"de":["Analyse der Komplexität von Codierungsaufgaben","Identifizierung von Risikofaktoren","Berechnung von Zeitenschätzungen basierend auf Leistungsmessungen von Claude Code","Vermeidung von unerwarteten Verzögerungen","Verbesserung der Planung"],"pt":["Análise do escopo da base de código","Identificação de fatores de risco","Cálculo de estimativas com base em linhas de base de desempenho do Claude Code","Prevenção de atrasos","Melhoria da planejamento"],"ru":["Анализ объема кодовой базы","Выявление факторов риска","Расчет оценок на основе линий базового性能 Claude Code","Предотвращение задержек","Улучшение планирования"],"ar":["تحليل نطاق قاعدة الشفرة","التعرف على عوامل الخطر","حساب التقييمات على أساس معايير أداء Claude Code","منع التأخيرات","تحسين التخطيط"]},"keywords":{"en":["how to use eta for coding tasks","eta alternative for time estimation","eta vs traditional time estimation methods","eta install guide for developers","eta setup for AI agents","what is eta and its benefits"],"zh":["代码任务估时","ETA 技术","代码库分析","任务复杂性","风险因素","Claude Code","AI 工具","代码开发"],"ja":["コーディングタスクの時間見積もり","ETA 技術","コードベース分析","タスクの複雑さ","リスク要因","Claude Code","AI エージェント","コード開発"],"ko":["코드 작성 태스크 시간 추정","ETA 기술","코드베이스 분석","태스크의 복잡성","위험 요인","Claude Code","AI 에이전트","코드 개발"],"es":["herramientas de inteligencia artificial para desarrolladores","estimaciones de tiempo de codificación","análisis de complejidad de tareas","identificación de factores de riesgo","planificación de proyectos de software","optimización de flujos de trabajo de Ops/Product"],"fr":["outils d''intelligence artificielle pour les développeurs","estimations de temps de codage","analyse de complexité des tâches","identification des facteurs de risque","planification de projets de logiciel","optimisation des flux de travail Ops/Product"],"de":["KI-Tools für Entwickler","Zeitenschätzungen für Codierungsaufgaben","Analyse der Komplexität von Aufgaben","Identifizierung von Risikofaktoren","Projektplanung für Softwareentwicklung","Optimierung von Ops/Product-Workflows"],"pt":["ETA","estimativas de tempo de codificação","análise de código","fatores de risco","planejamento de projetos","otimização de fluxos de trabalho","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ETA","оценки времени кодирования","анализ кода","факторы риска","планирование проектов","оптимизация рабочих процессов","разработка программного обеспечения","инструменты разработки"],"ar":["ETA","تقييمات زمن الترميز","تحليل الشفرة","عوامل الخطر","تخطيط المشاريع","تحسين تدفقات العمل","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ElliotJLT","repo":"Claude-Skill-Potions","repoPath":"ElliotJLT/Claude-Skill-Potions","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"eta","description":"|","bodyPreview":"# ETA\n\n<purpose>\nProvides realistic time estimates for coding tasks before work begins. Users often\nunderestimate task complexity. This skill analyzes codebase scope, categorizes task\ncomplexity, identifies risk factors, and calculates estimates based on measured\nClaude Code performance baselines. Prevents surprise delays and enables better planning.\n</purpose>\n\n## Instructions\n\n### Step 1: Gather Task Context\n\nWhen triggered, collect:\n- Task description from the user\n- Path to relevant codebase","body":"# ETA\n\n<purpose>\nProvides realistic time estimates for coding tasks before work begins. Users often\nunderestimate task complexity. This skill analyzes codebase scope, categorizes task\ncomplexity, identifies risk factors, and calculates estimates based on measured\nClaude Code performance baselines. Prevents surprise delays and enables better planning.\n</purpose>\n\n## Instructions\n\n### Step 1: Gather Task Context\n\nWhen triggered, collect:\n- Task description from the user\n- Path to relevant codebase (default: current directory)\n- Number of files likely in scope (if known)\n\n### Step 2: Run Estimation\n\n```bash\npython scripts/estimate_task.py --task \"<task_description>\" --path \"<codebase_path>\"\n```\n\nOptional flags:\n- `--files <n>`: Override estimated files in scope\n- `--json`: Output structured JSON for programmatic use\n\n### Step 3: Present Estimate\n\nReturn the formatted estimate showing:\n- Task category (trivial/simple/medium/complex/major)\n- Scope analysis (files, lines, test coverage)\n- Time range (low-high estimate)\n- Breakdown by phase (analysis, implementation, testing, verification)\n- Risk factors with explanations\n- Checkpoint recommendations for long tasks\n\n### Step 4: Adjust Based on Feedback\n\nIf user provides more context:\n- Re-run with `--files` override if scope is clearer\n- Adjust category interpretation based on domain knowledge\n\n## NEVER\n\n- Start a complex task without providing an estimate first\n- Give single-point estimates (always provide ranges)\n- Ignore risk factors when they''re detected\n- Skip the estimate for tasks over 15 minutes\n- Promise exact completion times\n\n## ALWAYS\n\n- Run the estimate script before non-trivial tasks\n- Show the breakdown so users understand where time goes\n- Flag risk factors visibly with explanations\n- Recommend checkpoints for tasks over 30 minutes\n- Update estimates if scope changes mid-task\n\n## Examples\n\n### Example 1: User asks about task duration\n\n**Input:** \"How long will it take to add user authentication?\"\n\n**Workflow:**\n1. Run `scripts/estimate_task.py --task \"Add user authentication\" --path .`\n2. Output shows:\n   - Category: Complex\n   - Estimated time: 24-53 minutes\n   - Risk factors: High-risk changes, External dependencies\n   - Recommendation: Break into phases with commits between each\n\n### Example 2: Before starting a feature\n\n**Input:** \"Add a dark mode toggle to settings\"\n\n**Workflow:**\n1. Detect this is a non-trivial task (feature keyword)\n2. Run `scripts/estimate_task.py --task \"Add dark mode toggle to settings\" --path ./src`\n3. Present estimate: 10-22 minutes (Medium complexity)\n4. Begin implementation with checkpoint plan\n\n### Example 3: Quick fix request\n\n**Input:** \"Fix the typo in the README\"\n\n**Workflow:**\n1. Detect trivial task (typo keyword)\n2. Run quick estimate: 3-6 minutes\n3. Proceed immediately (no detailed breakdown needed for trivial tasks)\n"},"lastSynced":"2026-03-08T02:00:10.393Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing accurate coding task time estimates and complexity analysis.","zh":"非常适合需要准确的编码任务时间估计和复杂性分析的开发代理。","ja":"開発エージェントが正確なコーディングタスク時間の見積もりと複雑性分析を必要とする場合に最適です。","ko":"정확한 코딩 작업 시간 추정 및 복잡성 분석이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan estimaciones de tiempo de tareas de codificación precisas y análisis de complejidad.","fr":"Parfait pour les agents de développement ayant besoin d''estimations de temps de tâches de codage précises et d''analyse de complexité.","de":"Perfekt für Entwicklungsmittel benötigende genaue Schätzungen der Codierungszeit und Komplexitätsanalyse.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de estimativas precisas de tempo de tarefas de codificação e análise de complexidade.","ru":"Идеально подходит для агентов разработки, которым необходимы точные оценки времени выполнения задач по кодированию и анализ сложности.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تقديرات دقيقة لزمن المهام البرمجية وتحليل التعقيد."},"recommendation":{"en":"Empowers agents to provide realistic time estimates for coding tasks by analyzing codebase scope, categorizing task complexity, and identifying risk factors using measured performance baselines, thus preventing surprise delays and enabling better planning with protocols like Claude Code performance metrics.","zh":"通过分析代码库范围、分类任务复杂性和使用测量性能基准识别风险因素，使代理能够提供编码任务的现实时间估计，从而防止意外延迟并通过类似Claude Code性能指标的协议实现更好的规划。","ja":"コードベースの範囲を分析し、タスクの複雑性を分類し、測定されたパフォーマンスベースラインを使用してリスク要因を識別することで、エージェントがコーディングタスクの現実的な時間見積もりを提供できるようにし、サプライズの遅延を防ぎ、Claude Codeパフォーマンスメトリクスなどのプロトコルでより良い計画を可能にします。","ko":"코드베이스 범위를 분석하고 작업 복잡성을 분류하고 측정된 성능 기준선을 사용하여 위험 요인을 식별하여 에이전트가 코딩 작업에 대한 현실적인 시간 추정을 제공할 수 있도록 하여 예상치 못한 지연을 방지하고 Claude Code 성능 메트릭스와 같은 프로토콜로 더 나은 계획을 가능하게 합니다.","es":"Habilita a los agentes a proporcionar estimaciones de tiempo realistas para tareas de codificación analizando el alcance de la base de código, categorizando la complejidad de la tarea e identificando factores de riesgo utilizando líneas de base de rendimiento medidas, lo que evita retrasos sorpresa y permite una mejor planificación con protocolos como las métricas de rendimiento de Claude Code.","fr":"Permet aux agents de fournir des estimations de temps réalistes pour les tâches de codage en analysant la portée de la base de code, en catégorisant la complexité de la tâche et en identifiant les facteurs de risque à l''aide de références de performances mesurées, ce qui prévient les retards inattendus et permet une meilleure planification avec des protocoles tels que les métriques de performance de Claude Code.","de":"Ermächtigt die Agenten, realistische Zeitabschätzungen für Codieraufgaben zu liefern, indem sie den Umfang der Codebasis analysieren, die Aufgabenkomplexität kategorisieren und Risikofaktoren unter Verwendung gemessener Leistungsgrundlagen identifizieren, was unerwartete Verzögerungen verhindert und eine bessere Planung mit Protokollen wie Claude Code-Leistungsmetriken ermöglicht.","pt":"Habilita os agentes a fornecer estimativas realistas de tempo para tarefas de codificação, analisando o escopo da base de código, categorizando a complexidade da tarefa e identificando fatores de risco usando linhas de base de desempenho medidas, prevenindo assim atrasos surpresa e permitindo um planejamento melhor com protocolos como métricas de desempenho do Claude Code.","ru":"Наделяет агентов возможностью предоставлять реалистичные оценки времени для задач по кодированию, анализируя объем кодовой базы, категоризируя сложность задачи и определяя факторы риска с использованием измеренных базовых показателей производительности, тем самым предотвращая неожиданные задержки и позволяя лучше планировать с протоколами, такими как метрики производительности Claude Code.","ar":"يمكن للعميل تقديم تقديرات زمنية واقعية للمهام البرمجية من خلال تحليل نطاق قاعدة الشفرة وتصنيف تعقيد المهمة وتحديد عوامل الخطر باستخدام معايير أداء قياسية، مما يمنع التأخيرات المفاجئة وتمكين التخطيط الأفضل مع بروتوكولات مثل مقاييس أداء Claude Code."},"useCases":{"en":["Estimating task completion times for agile project planning","Analyzing codebase complexity for risk assessment","Identifying potential bottlenecks in coding tasks"],"zh":["为敏捷项目规划估计任务完成时间","分析代码库复杂性以进行风险评估","识别编码任务中的潜在瓶颈"],"ja":["アジャイルプロジェクトプランニングのためにタスク完了時間を推定する","リスク評価のためにコードベースの複雑性を分析する","コーディングタスクの潜在的なボトルネックを特定する"],"ko":["敏捷 프로젝트 계획을 위한 작업 완료 시간 추정","리스크 평가를 위한 코드베이스 복잡성 분석","코딩 작업의 잠재적인 병목 현상을 식별하는 것"],"es":["Estimación del tiempo de finalización de tareas para la planificación de proyectos ágiles","Análisis de la complejidad de la base de código para la evaluación de riesgos","Identificación de posibles cuellos de botella en tareas de codificación"],"fr":["Estimation du temps de réalisation des tâches pour la planification de projets agiles","Analyse de la complexité de la base de code pour l''évaluation des risques","Identification des goulets d''étranglement potentiels dans les tâches de codage"],"de":["Schätzung der Aufgabenabschlusszeit für die agile Projektplanung","Analyse der Codebasis-Komplexität für die Risikobewertung","Identifizierung potenzieller Engpässe in Codieraufgaben"],"pt":["Estimativa do tempo de conclusão das tarefas para planejamento de projetos ágeis","Análise da complexidade da base de código para avaliação de riscos","Identificação de gargalos potenciais em tarefas de codificação"],"ru":["Оценка времени выполнения задач для планирования гибких проектов","Анализ сложности кодовой базы для оценки рисков","Определение потенциальных узких мест в задачах по кодированию"],"ar":["تقدير زمن انتهاء المهام للخطط المشروعة المرنة","تحليل تعقيد قاعدة الشفرة لتقييم المخاطر","تحديد العوائق المحتملة في المهام البرمجية"]},"limitations":{"en":["Requires access to relevant codebase","Dependent on Claude Code performance baselines"],"zh":["需要访问相关代码库","依赖于Claude Code性能基准"],"ja":["関連するコードベースへのアクセスが必要","Claude Codeパフォーマンスベースラインに依存する"],"ko":["관련 코드베이스에 대한 액세스가 필요함","Claude Code 성능 기준에 의존"],"es":["Requiere acceso a la base de código relevante","Dependiente de las líneas de base de rendimiento de Claude Code"],"fr":["Nécessite un accès à la base de code pertinente","Dépendante des références de performances de Claude Code"],"de":["Erfordert Zugriff auf die relevante Codebasis","Abhängig von den Leistungsgrundlagen von Claude Code"],"pt":["Requer acesso à base de código relevante","Dependente das linhas de base de desempenho do Claude Code"],"ru":["Требует доступа к соответствующей кодовой базе","Зависит от базовых показателей производительности Claude Code"],"ar":["يتطلب الوصول إلى قاعدة الشفرة ذات الصلة","يعتمد على معايير أداء Claude Code"]},"version":4},"contentHash":"2ac9d2f5606746f4e09271f19995e5a226be24f4d36d6e5494ae96264e814339","qualityScore":57}');
