INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ElliotJLT/Claude-Skill-Potions/eta', 'eta', 'ElliotJLT', 'Claude-Skill-Potions', 'community', 'eta ElliotJLT Claude-Skill-Potions community eta provides realistic time estimates for coding tasks by analyzing codebase scope, categorizing task complexity, and identifying risk factors. This skill benefits developers and teams by enabling better planning and preventing delays. ETA 技术通过分析代码库范围、任务复杂性和风险因素，提供代码任务的真实时间估计 ETA はコードベースのスコープ、タスクの複雑さ、リスク要因を分析してコーディングタスクの時間見積もりを提供します ETA는 코드베이스의 범위, 태스크의 복잡성 및 위험 요인을 분석하여 코드 작성 태스크의 시간을 추정합니다 ETA es una herramienta de inteligencia artificial que proporciona estimaciones de tiempo realistas para tareas de codificación, analizando el alcance de la base de código y identificando factores de riesgo ETA est un outil d''intelligence artificielle qui fournit des estimations de temps réalistes pour les tâches de codage, en analysant la portée de la base de code et en identifiant les facteurs de risque ETA ist ein KI-Tool, das realistische Zeitenschätzungen für Codierungsaufgaben liefert, indem es den Umfang der Codebasis analysiert und Risikofaktoren identifiziert A habilidade ETA fornece estimativas de tempo de codificação realistas, analisando o escopo da base de código e identificando fatores de risco Навык ETA предоставляет реалистичные оценки времени кодирования, анализируя объем кодовой базы и выявляя факторы риска المهارة ETA توفر تقييمات زمن الترميز الواقعية، من خلال تحليل نطاق قاعدة الشفرة والتعرف على عوامل الخطر how to use eta for coding tasks eta alternative for time estimation eta vs traditional time estimation methods eta install guide for developers eta setup for AI agents what is eta and its benefits 代码任务估时 ETA 技术 代码库分析 任务复杂性 风险因素 Claude Code AI 工具 代码开发 Analyzes codebase scope to estimate task complexity Categorizes tasks based on complexity and risk factors Calculates estimates using measured Claude Code performance baselines Collects task description and relevant codebase path for accurate estimates Prevents surprise delays by providing realistic time estimates eta is a collection of Claude skills that optimize Ops/Product workflows by providing realistic time estimates for coding tasks before work begins.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iagocavalcante/claude-turbo-search/qmd', 'community', 'iagocavalcante', 'claude-turbo-search', 'iagocavalcante/claude-turbo-search', 'qmd', 0, 0, 57, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:20.062Z', '3497c012572f55f285d54d808f5801fefc2d03621022e49ad422d69906111586', '{"id":"iagocavalcante/claude-turbo-search/qmd","name":"qmd","description":{"en":"qmd is a local search engine for Markdown notes, docs, and knowledge bases, helping developers find relevant files before reading them. It''s ideal for exploring codebases, looking for specific functionality, or finding related files.","zh":"qmd 是一个快速的 Markdown 搜索引擎，用于优化大型代码库的文件搜索和语义索引","ja":"qmd は、大規模なコードベースのファイル検索とセマンティックインデックスを最適化するクイックマークダウン検索エンジンです","ko":"qmd는 대형 코드베이스의 파일 검색과 의미적 색인을 최적화하는 빠른 Markdown 검색 엔진입니다","es":"qmd es una herramienta de búsqueda de archivos optimizados para grandes bases de código, que utiliza una búsqueda local y una indexación semántica para reducir el uso de tokens","fr":"qmd est un outil de recherche de fichiers optimisés pour les grandes bases de code, qui utilise une recherche locale et une indexation sémantique pour réduire l''utilisation de jetons","de":"qmd ist ein Tool für die optimierte Dateisuche in großen Codebasen, das eine lokale Suche und eine semantische Indizierung verwendet, um den Tokenverbrauch zu reduzieren","pt":"O qmd é uma ferramenta de pesquisa de arquivos otimizada para grandes bases de código em Claude Code","ru":"qmd - это ускоренный поиск файлов для больших кодовых баз в Claude Code для ИИ Агентов","ar":"qmd هي أداة بحث سريع عن الملفات لمجموعات الكود الكبيرة في Claude Code للآلات الذكية"},"seo":{"title":{"en":"qmd: Optimized File Search for AI Agents | Setup Guide","zh":"qmd 快速 Markdown 搜索引擎设置指南","ja":"qmd クイックマークダウン検索エンジンのベストプラクティス","ko":"qmd 빠른 Markdown 검색 엔진 사용법","es":"Guía de configuración de qmd para búsqueda de archivos op...","fr":"Mise en place de qmd pour une recherche de fichiers optim...","de":"Einrichtungsleitfaden für qmd zur optimierten Dateisuche","pt":"Guia de Configuração do qmd - Pesquisa de Arquivos Otimizada","ru":"Настройка qmd - Ускоренный Поиск Файлов для ИИ Агентов","ar":"دليل إعداد qmd - بحث سريع عن الملفات للآلات الذكية"},"description":{"en":"Discover how qmd reduces token usage by 80% with semantic indexing for large codebases in Claude Code. Get started with qmd today!","zh":"使用 qmd 快速 Markdown 搜索引擎减少令牌使用，提高代码库搜索效率","ja":"qmd クイックマークダウン検索エンジンを使用してトークンの使用を削減し、コードベースの検索効率を向上させる","ko":"qmd 빠른 Markdown 검색 엔진을 사용하여 토큰 사용량 줄이고 코드베이스 검색 효율성 높이기","es":"Descubre cómo qmd mejora la búsqueda de archivos en grandes bases de código con su función de búsqueda local y indexación semántica","fr":"Découvrez comment qmd améliore la recherche de fichiers dans les grandes bases de code avec sa fonction de recherche locale et d''indexation sémantique","de":"Erfahren Sie, wie qmd die Dateisuche in großen Codebasen mit seiner lokalen Suchfunktion und semantischer Indizierung verbessert","pt":"Aprenda a configurar o qmd para pesquisas de arquivos rápidas e índices semânticos em Claude Code","ru":"Узнайте, как настроить qmd для быстрого поиска файлов и семантического индексирования в Claude Code для ИИ Агентов","ar":"تعلم كيفية تكوين qmd للبحث السريع عن الملفات والفهرسة الدلالية في Claude Code للآلات الذكية"},"definition":{"en":"qmd is a quick Markdown search tool that enables optimized file search and semantic indexing for large codebases in Claude Code.","zh":"qmd 是一个用于快速搜索和索引 Markdown 文件的工具","ja":"qmd は、マークダウンファイルを迅速に検索してインデックスするためのツールです","ko":"qmd는 빠르게 Markdown 파일을 검색하고 색인하는 도구입니다","es":"qmd es un agente de búsqueda de archivos que utiliza algoritmos de búsqueda local y indexación semántica para mejorar la eficiencia en la búsqueda de documentos","fr":"qmd est un agent de recherche de fichiers qui utilise des algorithmes de recherche locale et d''indexation sémantique pour améliorer l''efficacité dans la recherche de documents","de":"qmd ist ein Dateisuchagent, der Algorithmen für die lokale Suche und semantische Indizierung verwendet, um die Effizienz bei der Suche nach Dokumenten zu verbessern","pt":"O qmd é uma ferramenta de pesquisa de arquivos que utiliza índices semânticos para encontrar arquivos relevantes","ru":"qmd - это инструмент поиска файлов, использующий семантическое индексирование для нахождения релевантных файлов","ar":"qmd هي أداة بحث عن الملفات التي تستخدم الفهارس الدلالية للعثور على الملفات ذات الصلة"},"features":{"en":["Local search engine for Markdown notes and documentation","Semantic indexing for large codebases in Claude Code","Reduces token usage by searching for relevant files before reading them","Supports exploration of codebases and documentation","Finds specific functionality or concepts within codebases","Identifies related files to a topic or question"],"zh":["快速 Markdown 搜索","语义索引","大型代码库支持","减少令牌使用","提高代码库搜索效率","支持 Claude Code"],"ja":["クイックマークダウン検索","セマンティックインデックス","大規模なコードベース対応","トークンの使用削減","コードベースの検索効率向上","Claude Code 対応"],"ko":["빠른 Markdown 검색","의미적 색인","대형 코드베이스 지원","토큰 사용량 줄이기","코드베이스 검색 효율성 향상","Claude Code 지원"],"es":["Búsqueda local de archivos en grandes bases de código","Indexación semántica para una búsqueda más precisa","Reducción del uso de tokens al encontrar archivos relevantes antes de leerlos","Integración con Claude Code para una búsqueda más eficiente","Compatibilidad con Markdown para una mejor organización de documentos"],"fr":["Recherche locale de fichiers dans les grandes bases de code","Indexation sémantique pour une recherche plus précise","Réduction de l''utilisation de jetons en trouvant des fichiers pertinents avant de les lire","Intégration avec Claude Code pour une recherche plus efficace","Compatibilité avec Markdown pour une meilleure organisation des documents"],"de":["Lokale Dateisuche in großen Codebasen","Semantische Indizierung für eine präzisere Suche","Reduzierung des Tokenverbrauchs durch das Finden relevanter Dateien vor dem Lesen","Integration mit Claude Code für eine effizientere Suche","Kompatibilität mit Markdown für eine bessere Dokumentenorganisation"],"pt":["Pesquisa de arquivos otimizada para grandes bases de código","Índices semânticos para encontrar arquivos relevantes","Redução do uso de tokens ao encontrar arquivos antes de lê-los","Suporte à busca por funcionalidades ou conceitos específicos","Capacidade de encontrar arquivos relacionados a um tópico"],"ru":["Ускоренный поиск файлов для больших кодовых баз","Семантическое индексирование для нахождения релевантных файлов","Снижение использования токенов при поиске файлов до их прочтения","Поддержка поиска по конкретным функциям или понятиям","Возможность найти файлы, связанные с определенной темой"],"ar":["بحث سريع عن الملفات لمجموعات الكود الكبيرة","الفهرسة الدلالية للعثور على الملفات ذات الصلة","تقليل استخدام الرموز عند العثور على الملفات قبل قراءتها","دعم البحث عن وظائف أو مفاهيم محددة","القدرة على العثور على الملفات المرتبطة بموضوع معين"]},"keywords":{"en":["how to use qmd","qmd alternative","qmd setup guide","what is qmd","qmd vs other search tools","qmd install for Claude Code","optimized file search for AI agents","semantic indexing for codebases","reducing token usage with qmd"],"zh":["qmd","快速 Markdown 搜索","语义索引","代码库搜索","AI エージェント","Markdown 搜索引擎","代码库优化","Claude Code","令牌使用减少"],"ja":["qmd","クイックマークダウン検索","セマンティックインデックス","コードベース検索","AIエージェント","マークダウン検索エンジン","コードベース最適化","Claude Code","トークンの使用削減"],"ko":["qmd","빠른 Markdown 검색","의미적 색인","코드베이스 검색","AI 에이전트","마크다운 검색 엔진","코드베이스 최적화","Claude Code","토큰 사용량 줄이기"],"es":["qmd","búsqueda de archivos","indexación semántica"," Claude Code","Markdown","optimización de búsqueda","reducción de tokens","herramientas de desarrollo","agentes de búsqueda"],"fr":["qmd","recherche de fichiers","indexation sémantique","Claude Code","Markdown","optimisation de recherche","réduction de jetons","outils de développement","agents de recherche"],"de":["qmd","Dateisuche","semantische Indizierung","Claude Code","Markdown","Suchoptimierung","Tokenreduzierung","Entwicklungstools","Suchagenten"],"pt":["qmd","pesquisa de arquivos","índices semânticos"," Claude Code","otimização de busca","redução de tokens","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["qmd","поиск файлов","семантическое индексирование","Claude Code","оптимизация поиска","снижение токенов","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["qmd","بحث عن الملفات","الفهرسة الدلالية","Claude Code","تحسين البحث","تقليل الرموز","تطوير البرمجيات","أدوات التطوير","الآلات الذكية"]}},"owner":"iagocavalcante","repo":"claude-turbo-search","repoPath":"iagocavalcante/claude-turbo-search","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"qmd","description":"Local hybrid search for markdown notes and docs. Use BEFORE reading files to save tokens - search first, read only whats relevant. Provides 90% token savings on exploration tasks.","bodyPreview":"# qmd - Quick Markdown Search\n\nLocal search engine for Markdown notes, docs, and knowledge bases. **Use this to find relevant files BEFORE reading them** to dramatically reduce token usage.\n\n## When to Use (IMPORTANT)\n\n**ALWAYS prefer qmd search over reading files directly when:**\n- Exploring a codebase or documentation\n- Looking for specific functionality or concepts\n- Finding related files to a topic\n- Answering questions about the codebase\n\n**Token savings:** Instead of reading 5 files (5000+","body":"# qmd - Quick Markdown Search\n\nLocal search engine for Markdown notes, docs, and knowledge bases. **Use this to find relevant files BEFORE reading them** to dramatically reduce token usage.\n\n## When to Use (IMPORTANT)\n\n**ALWAYS prefer qmd search over reading files directly when:**\n- Exploring a codebase or documentation\n- Looking for specific functionality or concepts\n- Finding related files to a topic\n- Answering questions about the codebase\n\n**Token savings:** Instead of reading 5 files (5000+ tokens), search first (50 tokens) and read only the relevant sections (200 tokens).\n\n## Search Priority (follow this order)\n\n1. **`qmd search \"query\"`** - Fast BM25 keyword search. Use this first, it''s instant.\n2. **`qmd vsearch \"query\"`** - Semantic similarity. Use only if keyword search fails.\n3. **`qmd query \"query\"`** - Hybrid + reranking. Avoid unless user explicitly requests highest quality.\n\n## Common Commands\n\n```bash\n# Fast keyword search (DEFAULT - use this first)\nqmd search \"authentication\" -n 10\n\n# Search specific collection\nqmd search \"api routes\" -c my-project\n\n# Get file paths only (for deciding what to read)\nqmd search \"database schema\" --files\n\n# JSON output for parsing\nqmd search \"error handling\" --json\n\n# Semantic search (slower, use as fallback)\nqmd vsearch \"how does the login flow work\"\n```\n\n## Retrieve Documents\n\n```bash\n# Get specific file\nqmd get \"path/to/file.md\"\n\n# Get by document ID from search results\nqmd get \"#docid\"\n\n# Get multiple files\nqmd multi-get \"docs/*.md\" --json\n```\n\n## Workflow Example\n\n**Bad (token expensive):**\n```\n1. Read src/auth/login.ts (800 tokens)\n2. Read src/auth/session.ts (600 tokens)\n3. Read src/auth/middleware.ts (500 tokens)\n4. Read src/auth/types.ts (400 tokens)\n→ Found answer in middleware.ts\nTotal: 2300 tokens\n```\n\n**Good (token efficient):**\n```\n1. qmd search \"authentication middleware\" --files (response: 50 tokens)\n   → Returns: src/auth/middleware.ts:45-62\n2. Read only the relevant section (150 tokens)\nTotal: 200 tokens (90% savings!)\n```\n\n## Tips for Claude\n\n- **Search before reading**: Always try qmd search first\n- **Use --files flag**: Get paths without content to decide what to read\n- **Be specific**: More specific queries = better results\n- **Check collections**: Use `qmd status` to see indexed collections\n- **Combine with cartographer**: CODEBASE_MAP.md gives structure, qmd gives content\n\n## Maintenance\n\n```bash\nqmd status          # Check index health and collections\nqmd update          # Re-index changed files (fast)\nqmd embed           # Update vector embeddings (slower)\n```\n"},"lastSynced":"2026-03-08T02:00:20.062Z","agentAnalysis":{"suitability":{"en":"Perfect for Knowledge Retrieval Agents needing rapid Markdown search capabilities for codebases and documentation.","zh":"非常适合需要快速Markdown搜索功能的知识检索代理，以便在代码库和文档中进行搜索。","ja":"Knowledge Retrieval Agentsがコードベースとドキュメントで迅速なMarkdown検索機能を必要とする場合に最適です。","ko":"코드베이스와 문서에서 빠른 Markdown 검색 기능이 필요한 지식 검색 에이전트에게 적합합니다.","es":"Perfecto para agentes de recuperación de conocimiento que necesitan capacidades de búsqueda de Markdown rápidas para codebases y documentación.","fr":"Parfait pour les agents de récupération de connaissances nécessitant des capacités de recherche Markdown rapides pour les codebases et la documentation.","de":"Perfekt für Wissensabrufagenten, die eine schnelle Markdown-Suchfunktion für Codebases und Dokumentation benötigen.","pt":"Perfeito para Agentes de Recuperação de Conhecimento que necessitam de capacidades de pesquisa Markdown rápidas para codebases e documentação.","ru":"Идеально подходит для агентов поиска знаний, которым требуются быстрые возможности поиска Markdown для кодовых баз и документации.","ar":"مثالي لعميل استرجاع المعرفة الذي يحتاج إلى قدرات بحث Markdown سريعة لتقصير الشفرة والتوثيق."},"recommendation":{"en":"Empowers agents to efficiently locate specific functionality or concepts within Markdown notes, docs, and knowledge bases using local search, dramatically reducing token usage and improving overall performance with Markdown file support.","zh":"能够让代理高效地在Markdown笔记、文档和知识库中定位特定的功能或概念，使用本地搜索，大大减少令牌使用并提高Markdown文件支持的整体性能。","ja":"エージェントがMarkdownノート、ドキュメント、ナレッジベース内で特定の機能または概念を効率的に検索できるようにし、ローカル検索を使用してトークンの使用を大幅に削減し、Markdownファイルのサポートによる全体的なパフォーマンスを向上させます。","ko":"에이전트가 Markdown 노트, 문서 및 지식 베이스 내에서 특정 기능 또는 개념을 효율적으로 찾을 수 있도록 하여 로컬 검색을 사용하여 토큰 사용을 크게 줄이고 Markdown 파일 지원에 의한 전반적인 성능을 향상시킵니다.","es":"Permite a los agentes localizar de manera eficiente una funcionalidad o conceptos específicos dentro de notas, documentos y bases de conocimiento de Markdown utilizando la búsqueda local, reduciendo dramáticamente el uso de tokens y mejorando el rendimiento general con soporte de archivos Markdown.","fr":"Permet aux agents de localiser efficacement une fonctionnalité ou des concepts spécifiques au sein de notes, de documents et de bases de connaissances Markdown en utilisant la recherche locale, réduisant ainsi de manière spectaculaire l''utilisation de jetons et améliorant les performances globales avec une prise en charge de fichiers Markdown.","de":"Ermöglicht es Agenten, bestimmte Funktionalitäten oder Konzepte innerhalb von Markdown-Notizen, -Dokumenten und -Wissensbasen mithilfe der lokalen Suche effizient zu finden, wodurch die Token-Nutzung dramatisch reduziert und die Gesamtleistung mit der Unterstützung von Markdown-Dateien verbessert wird.","pt":"Permite que os agentes localizem eficientemente funcionalidades ou conceitos específicos dentro de notas, docs e bases de conhecimento Markdown usando busca local, reduzindo drasticamente o uso de tokens e melhorando o desempenho geral com suporte a arquivos Markdown.","ru":"Позволяет агентам эффективно находить конкретную функциональность или концепции внутри заметок Markdown, документов и баз знаний с помощью локального поиска, что значительно снижает использование токенов и улучшает общую производительность с поддержкой файлов Markdown.","ar":"يسمح للعميل بالعثور بفعالية على وظائف أو مفاهيم محددة داخل الملاحظات و المستندات وقواعد المعرفة Markdown باستخدام البحث المحلي، مما يقلل بشكل كبير من استخدام الرموز وتحسين الأداء العام مع دعم ملفات Markdown."},"useCases":{"en":["Exploring codebases for specific functionality","Finding related Markdown files on a topic","Answering questions about codebases and documentation"],"zh":["探索代码库以查找特定功能","查找与特定主题相关的Markdown文件","回答关于代码库和文档的问题"],"ja":["特定機能を探すためにコードベースを探索する","特定のトピックに関するMarkdownファイルを検索する","コードベースとドキュメントに関する質問に答える"],"ko":["특정 기능을 찾기 위해 코드베이스를 탐색한다","특정 주제와 관련된 Markdown 파일을 찾는다","코드베이스 및 문서에 대한 질문에 답변한다"],"es":["Explorar codebases para funcionalidades específicas","Encontrar archivos de Markdown relacionados con un tema","Responder preguntas sobre codebases y documentación"],"fr":["Explorer des codebases pour des fonctionnalités spécifiques","Trouver des fichiers Markdown liés à un sujet","Répondre à des questions sur les codebases et la documentation"],"de":["Durchsuchen von Codebasen nach bestimmten Funktionalitäten","Finden von Markdown-Dateien zu einem bestimmten Thema","Beantworten von Fragen zu Codebasen und Dokumentation"],"pt":["Explorar codebases para funcionalidades específicas","Encontrar arquivos Markdown relacionados sobre um tópico","Responder perguntas sobre codebases e documentação"],"ru":["Изучение кодовых баз для конкретной функциональности","Поиск связанных файлов Markdown по теме","Ответы на вопросы о кодовых базах и документации"],"ar":["استكشاف قواعد الشفرة لمهام محددة","العثور على ملفات Markdown المتعلقة بموضوع","الإجابة على أسئلة حول قواعد الشفرة والتوثيق"]},"limitations":{"en":["Requires local Markdown files","Limited to Markdown file format"],"zh":["需要本地Markdown文件","仅限Markdown文件格式"],"ja":["ローカルのMarkdownファイルが必要","Markdownファイル形式のみ"],"ko":["로컬 Markdown 파일이 필요하다","Markdown 파일 형식만 해당"],"es":["Requiere archivos de Markdown locales","Limitado al formato de archivo Markdown"],"fr":["Nécessite des fichiers Markdown locaux","Limité au format de fichier Markdown"],"de":["Benötigt lokale Markdown-Dateien","Begrenzt auf das Markdown-Dateiformat"],"pt":["Requer arquivos Markdown locais","Limitado ao formato de arquivo Markdown"],"ru":["Требует локальных файлов Markdown","Ограничен форматом файла Markdown"],"ar":["يتطلب ملفات Markdown محلية","محدود بتنسيق ملف Markdown"]},"version":4},"contentHash":"3497c012572f55f285d54d808f5801fefc2d03621022e49ad422d69906111586","qualityScore":57}');
