INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iagocavalcante/claude-turbo-search/qmd', 'qmd', 'iagocavalcante', 'claude-turbo-search', 'community', 'qmd iagocavalcante claude-turbo-search community qmd is a local search engine for Markdown notes, docs, and knowledge bases, helping developers find relevant files before reading them. It''s ideal for exploring codebases, looking for specific functionality, or finding related files. qmd 是一个快速的 Markdown 搜索引擎，用于优化大型代码库的文件搜索和语义索引 qmd は、大規模なコードベースのファイル検索とセマンティックインデックスを最適化するクイックマークダウン検索エンジンです qmd는 대형 코드베이스의 파일 검색과 의미적 색인을 최적화하는 빠른 Markdown 검색 엔진입니다 qmd es una herramienta de búsqueda de archivos optimizados para grandes bases de código, que utiliza una búsqueda local y una indexación semántica para reducir el uso de tokens qmd est un outil de recherche de fichiers optimisés pour les grandes bases de code, qui utilise une recherche locale et une indexation sémantique pour réduire l''utilisation de jetons qmd ist ein Tool für die optimierte Dateisuche in großen Codebasen, das eine lokale Suche und eine semantische Indizierung verwendet, um den Tokenverbrauch zu reduzieren O qmd é uma ferramenta de pesquisa de arquivos otimizada para grandes bases de código em Claude Code qmd - это ускоренный поиск файлов для больших кодовых баз в Claude Code для ИИ Агентов qmd هي أداة بحث سريع عن الملفات لمجموعات الكود الكبيرة في Claude Code للآلات الذكية how to use qmd qmd alternative qmd setup guide what is qmd qmd vs other search tools qmd install for Claude Code optimized file search for AI agents semantic indexing for codebases reducing token usage with qmd qmd 快速 Markdown 搜索 语义索引 代码库搜索 AI エージェント Markdown 搜索引擎 代码库优化 Claude Code 令牌使用减少 Local search engine for Markdown notes and documentation Semantic indexing for large codebases in Claude Code Reduces token usage by searching for relevant files before reading them Supports exploration of codebases and documentation Finds specific functionality or concepts within codebases Identifies related files to a topic or question qmd is a quick Markdown search tool that enables optimized file search and semantic indexing for large codebases in Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('popup-studio-ai/bkit-claude-code/enterprise', 'community', 'popup-studio-ai', 'bkit-claude-code', 'popup-studio-ai/bkit-claude-code', 'enterprise', 0, 0, 57, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:41.757Z', '410690c330fffbd96ee9ebbacb9d24ecb17f434de24bcccf4f8f727f86cc2c87', '{"id":"popup-studio-ai/bkit-claude-code/enterprise","name":"enterprise","description":{"en":"The enterprise skill utilizes PDCA methodology and Claude Code mastery for AI-native development, benefiting developers with project initialization and development guides.","zh":"bkit Vibecoding Kit提供企业级AI开发解决方案，采用PDCA方法论和Claude Code掌握","ja":"bkit Vibecoding KitはエンタープライズAI開発ソリューションを提供し、PDCA方法論とClaude Codeのマスターを採用","ko":"bkit Vibecoding Kit는 엔터프라이즈 AI 개발 솔루션을 제공하며 PDCA 방법론과 Claude Code 마스터를采用","es":"La habilidad de enterprise utiliza la metodología PDCA y Claude Code para el desarrollo de AI nativo, permitiendo la inicialización de proyectos y la creación de estructuras de monorepo","fr":"La compétence de l''entreprise utilise la méthodologie PDCA et Claude Code pour le développement d''IA natif, permettant l''initialisation de projets et la création de structures de monorepo","de":"Die Enterprise-Fähigkeit verwendet die PDCA-Methodik und Claude Code für die native KI-Entwicklung, ermöglicht die Initialisierung von Projekten und die Erstellung von Monorepo-Strukturen","pt":"O kit de desenvolvimento Vibecoding combina PDCA e Claude Code para projetos de IA nativa, oferecendo inicialização de projeto e estrutura de monorepo com Turborepo","ru":"Набор разработки Vibecoding объединяет PDCA и Claude Code для проектов ИИ Агентов, предлагая инициализацию проекта и структуру монорепо с Turborepo","ar":"حزمة التطوير Vibecoding تجمع بين PDCA و Claude Code لمشاريع الذكاء الاصطناعي المحلية، وتقدم تهيئة المشروع وهيكل مونوريبو مع Turborepo"},"seo":{"title":{"en":"Enterprise: PDCA Methodology Setup Guide | AI Agent Skill","zh":"企业级AI开发设置指南 - bkit Vibecoding Kit","ja":"エンタープライズAI開発セットアップガイド - bkit Vibecoding Kit","ko":"엔터프라이즈 AI 개발 설정 가이드 - bkit Vibecoding Kit","es":"Configuración de Enterprise: Guía de inicio con PDCA y Cl...","fr":"Mise en place de l''entreprise : Guide de démarrage avec P...","de":"Enterprise-Setup: Leitfaden für den Einstieg mit PDCA und...","pt":"Guia de Configuração de Ferramentas de IA Enterprise","ru":"Настройка ИИ Агентов Enterprise: Лучшие Практики","ar":"دليل إعداد أدوات الذكاء الاصطناعي للمشاريع الكبيرة"},"description":{"en":"Unlock AI-native development with bkit Vibecoding Kit. Learn how to initialize projects with Turborepo and CLAUDE.md. Get started now!","zh":"使用bkit Vibecoding Kit实现企业级AI开发，包括PDCA方法论和Claude Code掌握","ja":"bkit Vibecoding Kitを使用してエンタープライズAI開発を実現する、PDCA方法論とClaude Codeのマスター","ko":"bkit Vibecoding Kit를 사용하여 엔터프라이즈 AI 개발을 구현하는 PDCA 방법론과 Claude Code 마스터","es":"Aprende a configurar tu proyecto de empresa con la metodología PDCA y Claude Code para un desarrollo de AI nativo","fr":"Découvrez comment configurer votre projet d''entreprise avec la méthodologie PDCA et Claude Code pour un développement d''IA natif","de":"Erfahren Sie, wie Sie Ihr Unternehmensprojekt mit der PDCA-Methodik und Claude Code für eine native KI-Entwicklung konfigurieren","pt":"Aprenda a configurar o kit de desenvolvimento Vibecoding com PDCA e Claude Code para projetos enterprise de IA nativa","ru":"Узнайте, как настроить набор разработки Vibecoding с PDCA и Claude Code для проектов ИИ Агентов enterprise","ar":"تعلم كيفية إعداد حزمة التطوير Vibecoding مع PDCA و Claude Code لمشاريع الذكاء الاصطناعي المحلية الكبيرة"},"definition":{"en":"Enterprise is a skill that combines PDCA methodology with Claude Code mastery for advanced AI-native development capabilities.","zh":"企业级AI开发是指使用AI技术和工具实现大规模企业级应用的开发","ja":"エンタープライズAI開発とは、AI技術とツールを使用して大規模なエンタープライズレベルのアプリケーション開発を実現すること","ko":"엔터프라이즈 AI 개발은 AI 기술과 도구를 사용하여 대규모 엔터프라이즈级 애플리케이션 개발을 구현하는 것","es":"La habilidad de enterprise es una herramienta de AI que utiliza PDCA y Claude Code para el desarrollo de aplicaciones de empresa","fr":"La compétence de l''entreprise est un outil d''IA qui utilise PDCA et Claude Code pour le développement d''applications d''entreprise","de":"Die Enterprise-Fähigkeit ist ein KI-Tool, das PDCA und Claude Code für die Entwicklung von Unternehmensanwendungen verwendet","pt":"O que é desenvolvimento de IA enterprise? É uma abordagem de desenvolvimento de software que combina PDCA e Claude Code para criar projetos de IA nativa","ru":"Что такое разработка ИИ Агентов enterprise? Это подход к разработке программного обеспечения, который объединяет PDCA и Claude Code для создания проектов ИИ Агентов","ar":"ما هو تطوير الذكاء الاصطناعي للمشاريع الكبيرة؟ إنه نهج لتطوير البرمجيات الذي يجمع بين PDCA و Claude Code لإنشاء مشاريع الذكاء الاصطناعي المحلية"},"features":{"en":["Initializes projects with Turborepo monorepo structure","Creates apps/, packages/, services/, and infra/ folder structure","Generates CLAUDE.md for enterprise-level documentation","Supports project initialization via `/enterprise init` command","Provides development guide via `/enterprise guide` command","Offers MSA/Infrastructure help via `/enterprise help` command"],"zh":["支持Turborepo monorepo结构","提供apps/、packages/、services/、infra/文件夹结构","创建CLAUDE.md文件","采用PDCA方法论","掌握Claude Code","支持init、guide、help等命令"],"ja":["Turborepo monorepo構造をサポート","apps/、packages/、services/、infra/フォルダ構造を提供","CLAUDE.mdファイルを作成","PDCA方法論を採用","Claude Codeのマスター","init、guide、helpなどのコマンドをサポート"],"ko":["Turborepo monorepo 구조 지원","apps/、packages/、services/、infra/ 폴더 구조 제공","CLAUDE.md 파일 생성","PDCA 방법론採用","Claude Code 마스터","init、guide、help 등의 명령어 지원"],"es":["Inicialización de proyectos con la función ''init''","Creación de estructuras de monorepo con Turborepo","Generación de carpetas ''apps/'', ''packages/'', ''services/'' y ''infra/''","Creación de archivos ''CLAUDE.md'' para la documentación de la empresa","Soporte para la metodología PDCA y Claude Code"],"fr":["Initialisation de projets avec la fonction ''init''","Création de structures de monorepo avec Turborepo","Génération de dossiers ''apps/'', ''packages/'', ''services/'' et ''infra/''","Création de fichiers ''CLAUDE.md'' pour la documentation de l''entreprise","Support de la méthodologie PDCA et Claude Code"],"de":["Initialisierung von Projekten mit der Funktion ''init''","Erstellung von Monorepo-Strukturen mit Turborepo","Generierung von Ordnern ''apps/'', ''packages/'', ''services/'' und ''infra/''","Erstellung von Dateien ''CLAUDE.md'' für die Dokumentation des Unternehmens","Unterstützung der PDCA-Methodik und Claude Code"],"pt":["Inicialização de projeto com Turborepo","Estrutura de monorepo com apps/, packages/, services/, infra/","Criação de CLAUDE.md para documentação de projeto","Suporte à PDCA e Claude Code para desenvolvimento de IA nativa","Guia de desenvolvimento para projetos enterprise"],"ru":["Инициализация проекта с Turborepo","Структура монорепо с apps/, packages/, services/, infra/","Создание CLAUDE.md для документации проекта","Поддержка PDCA и Claude Code для разработки ИИ Агентов","Руководство по разработке для проектов ИИ Агентов enterprise"],"ar":["تهيئة المشروع مع Turborepo","هيكل مونوريبو مع apps/, packages/, services/, infra/","إنشاء CLAUDE.md لتوثيق المشروع","دعم PDCA و Claude Code لتطوير الذكاء الاصطناعي المحلي","دليل التطوير لمشاريع الذكاء الاصطناعي المحلية الكبيرة"]},"keywords":{"en":["how to use enterprise skill","what is enterprise development","enterprise alternative to traditional development","enterprise vs agile methodology","enterprise setup guide","installing enterprise skill","enterprise PDCA methodology","Claude Code mastery","Turborepo monorepo structure"],"zh":["企业级AI开发","bkit Vibecoding Kit","PDCA方法论","Claude Code","Turborepo monorepo","AI开发工具","企业级应用开发","AIエージェント","AI开发设置"],"ja":["エンタープライズAI開発","bkit Vibecoding Kit","PDCA方法論","Claude Code","Turborepo monorepo","AI開発ツール","エンタープライズレベルのアプリケーション開発","AIエージェント","AI開発セットアップ"],"ko":["엔터프라이즈 AI 개발","bkit Vibecoding Kit","PDCA 방법론","Claude Code","Turborepo monorepo","AI 개발 도구","엔터프라이즈级 애플리케이션 개발","AI 에이전트","AI 개발 설정"],"es":["desarrollo de AI nativo","metodología PDCA","Claude Code","Turborepo","monorepo","inicialización de proyectos","documentación de empresa","herramientas de AI para empresas","desarrollo de aplicaciones de empresa"],"fr":["développement d''IA natif","méthodologie PDCA","Claude Code","Turborepo","monorepo","initialisation de projets","documentation de l''entreprise","outils d''IA pour les entreprises","développement d''applications d''entreprise"],"de":["native KI-Entwicklung","PDCA-Methodik","Claude Code","Turborepo","Monorepo","Initialisierung von Projekten","Dokumentation des Unternehmens","KI-Tools für Unternehmen","Entwicklung von Unternehmensanwendungen"],"pt":["desenvolvimento de IA enterprise","PDCA","Claude Code","Turborepo","monorepo","IA nativa","ferramentas de IA","desenvolvimento de software","projetos de IA"],"ru":["разработка ИИ Агентов enterprise","PDCA","Claude Code","Turborepo","монорепо","ИИ Агенты","инструменты ИИ","разработка программного обеспечения","проекты ИИ Агентов"],"ar":["تطوير الذكاء الاصطناعي للمشاريع الكبيرة","PDCA","Claude Code","Turborepo","مونوريبو","الذكاء الاصطناعي المحلي","أدوات الذكاء الاصطناعي","تطوير البرمجيات","مشاريع الذكاء الاصطناعي المحلية"]}},"owner":"popup-studio-ai","repo":"bkit-claude-code","repoPath":"popup-studio-ai/bkit-claude-code","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.276Z","topics":[],"category":"community","skillMd":{"name":"enterprise","description":"|","bodyPreview":"# Advanced (Enterprise) Skill\n\n## Actions\n\n| Action | Description | Example |\n|--------|-------------|---------|\n| `init` | Project initialization (/init-enterprise feature) | `/enterprise init my-platform` |\n| `guide` | Display development guide | `/enterprise guide` |\n| `help` | MSA/Infrastructure help | `/enterprise help` |\n\n### init (Project Initialization)\n1. Create Turborepo monorepo structure\n2. apps/, packages/, services/, infra/ folder structure\n3. Create CLAUDE.md (Level: Enterprise sp","body":"# Advanced (Enterprise) Skill\n\n## Actions\n\n| Action | Description | Example |\n|--------|-------------|---------|\n| `init` | Project initialization (/init-enterprise feature) | `/enterprise init my-platform` |\n| `guide` | Display development guide | `/enterprise guide` |\n| `help` | MSA/Infrastructure help | `/enterprise help` |\n\n### init (Project Initialization)\n1. Create Turborepo monorepo structure\n2. apps/, packages/, services/, infra/ folder structure\n3. Create CLAUDE.md (Level: Enterprise specified)\n4. docs/ 5-category structure\n5. infra/terraform/, infra/k8s/ base templates\n6. Initialize .bkit-memory.json\n\n### guide (Development Guide)\n- AI Native 10-Day development cycle\n- Microservices architecture patterns\n- Phase 1-9 full Pipeline (Enterprise version)\n\n### help (Infrastructure Help)\n- Kubernetes basic concepts\n- Terraform IaC patterns\n- AWS EKS, RDS configuration guide\n\n## Target Audience\n\n- Senior developers\n- CTOs / Architects\n- Large-scale system operators\n\n## Tech Stack\n\n```\nFrontend:\n- Next.js 14+ (Turborepo monorepo)\n- TypeScript\n- Tailwind CSS\n- TanStack Query\n- Zustand\n\nBackend:\n- Python FastAPI (microservices)\n- PostgreSQL (schema separation)\n- Redis (cache, Pub/Sub)\n- RabbitMQ / SQS (message queue)\n\nInfrastructure:\n- AWS (EKS, RDS, S3, CloudFront)\n- Kubernetes (Kustomize)\n- Terraform (IaC)\n- ArgoCD (GitOps)\n\nCI/CD:\n- GitHub Actions\n- Docker\n```\n\n### Language Tier Guidance (v1.3.0)\n\n> **Supported**: All Tiers\n>\n> Enterprise level handles complex requirements including legacy system integration.\n\n| Tier | Usage | Guidance |\n|------|-------|----------|\n| Tier 1 | Primary services | New development, core features |\n| Tier 2 | System/Cloud | Go (K8s), Rust (performance critical) |\n| Tier 3 | Platform native | iOS (Swift), Android (Kotlin), legacy Java |\n| Tier 4 | Legacy integration | Migration plan required |\n\n**Migration Path**:\n- PHP → TypeScript (Next.js API routes)\n- Ruby → Python (FastAPI)\n- Java → Kotlin or Go\n\n## Project Structure\n\n```\nproject/\n├── apps/                        # Frontend apps (Turborepo)\n│   ├── web/                    # Main web app\n│   ├── admin/                  # Admin\n│   └── docs/                   # Documentation site\n│\n├── packages/                    # Shared packages\n│   ├── ui/                     # UI components\n│   ├── api-client/             # API client\n│   └── config/                 # Shared config\n│\n├── services/                    # Backend microservices\n│   ├── auth/                   # Auth service\n│   ├── user/                   # User service\n│   ├── {domain}/               # Domain-specific services\n│   └── shared/                 # Shared modules\n│\n├── infra/                       # Infrastructure code\n│   ├── terraform/\n│   │   ├── modules/            # Reusable modules\n│   │   └── environments/       # Environment-specific config\n│   └── k8s/\n│       ├── base/               # Common manifests\n│       └── overlays/           # Environment-specific patches\n│\n├── docs/                        # PDCA documents\n│   ├── 00-requirement/\n│   ├── 01-development/         # Design documents (multiple)\n│   ├── 02-scenario/\n│   ├── 03-refactoring/\n│   └── 04-operation/\n│\n├── scripts/                     # Utility scripts\n├── .github/workflows/           # CI/CD\n├── docker-compose.yml\n├── turbo.json\n└── pnpm-workspace.yaml\n```\n\n## Clean Architecture (4-Layer)\n\n```\n┌─────────────────────────────────────────────────────────┐\n│                    API Layer                             │\n│  - FastAPI routers                                       │\n│  - Request/Response DTOs                                 │\n│  - Auth/authz middleware                                 │\n├─────────────────────────────────────────────────────────┤\n│                  Application Layer                       │\n│  - Service classes                                       │\n│  - Use Case implementation                               │\n│  - Transaction management                                │\n├─────────────────────────────────────────────────────────┤\n│                    Domain Layer                          │\n│  - Entity classes (pure Python)                          │\n│  - Repository interfaces (ABC)                           │\n│  - Business rules                                        │\n├─────────────────────────────────────────────────────────┤\n│                 Infrastructure Layer                     │\n│  - Repository implementations (SQLAlchemy)               │\n│  - External API clients                                  │\n│  - Cache, messaging                                      │\n└─────────────────────────────────────────────────────────┘\n\nDependency direction: Top → Bottom\nDomain Layer depends on nothing\n```\n\n## Core Patterns\n\n### Repository Pattern\n\n```python\n# domain/repositories/user_repository.py (interface)\nfrom abc import ABC, abstractmethod\n\nclass UserRepository(ABC):\n    @abstractmethod\n    async def find_by_id(self, id: str) -> User | None:\n        pass\n\n    @abstractmethod\n    async def save(self, user: User) -> User:\n        pass\n\n# infrastructure/repositories/user_repository_impl.py (implementation)\nclass UserRepositoryImpl(UserRepository):\n    def __init__(self, db: AsyncSession):\n        self.db = db\n\n    async def find_by_id(self, id: str) -> User | None:\n        result = await self.db.execute(\n            select(UserModel).where(UserModel.id == id)\n        )\n        return result.scalar_one_or_none()\n```\n\n### Inter-service Communication\n\n```python\n# Synchronous (Internal API)\nasync def get_user_info(user_id: str) -> dict:\n    async with httpx.AsyncClient() as client:\n        response = await client.get(\n            f\"{USER_SERVICE_URL}/internal/users/{user_id}\",\n            headers={\"X-Internal-Token\": INTERNAL_TOKEN}\n        )\n        return response.json()\n\n# Asynchronous (message queue)\nawait message_queue.publish(\n    topic=\"user.created\",\n    message={\"user_id\": user.id, \"email\": user.email}\n)\n```\n\n### Terraform Module\n\n```hcl\n# modules/eks/main.tf\nresource \"aws_eks_cluster\" \"this\" {\n  name     = \"${var.environment}-${var.project_name}-eks\"\n  role_arn = aws_iam_role.cluster.arn\n  version  = var.kubernetes_version\n\n  vpc_config {\n    subnet_ids = var.subnet_ids\n  }\n\n  tags = merge(var.tags, {\n    Environment = var.environment\n  })\n}\n```\n\n### Kubernetes Deployment\n\n```yaml\n# k8s/base/backend/deployment.yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: user-service\nspec:\n  replicas: 2\n  template:\n    spec:\n      containers:\n        - name: user-service\n          image: ${ECR_REGISTRY}/user-service:${TAG}\n          resources:\n            requests:\n              cpu: \"100m\"\n              memory: \"256Mi\"\n            limits:\n              cpu: \"500m\"\n              memory: \"512Mi\"\n          livenessProbe:\n            httpGet:\n              path: /health\n              port: 8000\n```\n\n## Environment Configuration\n\n| Environment | Infrastructure | Deployment Method |\n|-------------|---------------|-------------------|\n| Local | Docker Compose | Manual |\n| Staging | EKS | ArgoCD Auto Sync |\n| Production | EKS | ArgoCD Manual Sync |\n\n## Security Rules\n\n```\n✅ Allowed\n- Retrieve secrets from Secrets Manager\n- IAM role-based access\n- VPC internal communication\n- mTLS (inter-service)\n\n❌ Prohibited\n- Hardcoded secrets\n- DB in public subnet\n- Using root account\n- Excessive IAM permissions\n```\n\n## CI/CD Pipeline\n\n```\nPush to feature/*\n    ↓\nGitHub Actions (CI)\n    - Lint\n    - Test\n    - Build Docker image\n    - Push to ECR\n    ↓\nPR to staging\n    ↓\nArgoCD Auto Sync (Staging)\n    ↓\nPR to main\n    ↓\nArgoCD Manual Sync (Production)\n```\n\n## SoR Priority\n\n```\n1st Priority: Codebase\n  - scripts/init-db.sql (source of truth for DB schema)\n  - services/{service}/app/ (each service implementation)\n\n2nd Priority: CLAUDE.md / Convention docs\n  - services/CLAUDE.md\n  - frontend/CLAUDE.md\n  - infra/CLAUDE.md\n\n3rd Priority: docs/ design documents\n  - For understanding design intent\n  - If different from code, code is correct\n```\n\n---\n\n## AI Native Development\n\n### 3 Core Principles\n\n1. **Document-First Design**: Write design docs BEFORE code\n2. **Monorepo Context Control**: All code in one repo for AI context\n3. **PR-Based Collaboration**: Every change through PR\n\n### 10-Day Development Pattern\n\n| Day | Focus | Output |\n|-----|-------|--------|\n| 1 | Architecture | Market analysis + System architecture |\n| 2-3 | Core | Auth, User + Business services |\n| 4-5 | UX | PO feedback → Documentation → Implementation |\n| 6-7 | QA | Zero Script QA + bug fixes |\n| 8 | Infra | Terraform + GitOps |\n| 9-10 | Production | Security review + Deployment |\n\n---\n\n## Monorepo Benefits for AI\n\n```\nMono-repo:\n└─ project/\n    ├─ frontend/ ──────┐\n    ├─ services/ ──────┤  AI reads completely\n    ├─ infra/ ─────────┤  Context unified\n    └─ packages/ ──────┘\n\n✅ AI understands full context\n✅ Single source of truth for types\n✅ Atomic commits across layers\n✅ Consistent patterns enforced\n```\n\n### CLAUDE.md Hierarchy\n\n```\nproject/\n├── CLAUDE.md           # Project-wide context\n├── frontend/CLAUDE.md  # Frontend conventions\n├── services/CLAUDE.md  # Backend conventions\n└── infra/CLAUDE.md     # Infra conventions\n```\n\nRule: Area-specific CLAUDE.md overrides project-level rules\n\n---\n\n## bkit Features for Enterprise Level (v1.5.1)\n\n### Output Style: bkit-enterprise (Recommended)\n\nFor CTO-level architecture perspectives, activate the enterprise style:\n\n```\n/output-style bkit-enterprise\n```\n\nThis provides:\n- Architecture tradeoff analysis tables (Option/Pros/Cons/Recommendation)\n- Performance, security, and scalability perspectives for every decision\n- Cost impact estimates for infrastructure changes\n- Deployment strategy recommendations (Blue/Green, Canary, Rolling)\n- SOLID principles and Clean Architecture compliance checks\n\n### Agent Teams (4 Teammates)\n\nEnterprise projects support full Agent Teams for parallel PDCA execution:\n\n| Role | Agents | PDCA Phases |\n|------|--------|-------------|\n| architect | enterprise-expert, infra-architect | Design |\n| developer | bkend-expert | Do, Act |\n| qa | qa-monitor, gap-detector | Check |\n| reviewer | code-analyzer, design-validator | Check, Act |\n\n**To enable:**\n1. Set environment: `CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1`\n2. Start team mode: `/pdca team {feature}`\n3. Monitor progress: `/pdca team status`\n\n### Agent Memory (Auto-Active)\n\nAll bkit agents automatically remember project context across sessions.\nEnterprise agents use `project` scope memory, ensuring architecture decisions\nand infrastructure patterns persist across development sessions.\n"},"lastSynced":"2026-03-08T02:00:41.757Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced enterprise-level project initialization and development guides using PDCA methodology and Claude Code mastery.","zh":"非常适合需要高级企业级项目初始化和开发指南的 AI 代理，使用 PDCA 方法论和 Claude Code 掌握。","ja":"高度なエンタープライズレベルのプロジェクト初期化と開発ガイドが必要なAIエージェントに最適で、PDCA方法論とClaude Codeのマスターを使用しています。","ko":"고급 기업 수준의 프로젝트 초기화 및 개발 가이드가 필요한 AI 에이전트에게 적합하며 PDCA 방법론 및 Claude Code 마스터를 사용합니다.","es":"Perfecto para agentes de IA que necesitan guías de inicialización y desarrollo de proyectos de nivel empresarial avanzado utilizando la metodología PDCA y la maestría del código Claude.","fr":"Parfait pour les agents IA ayant besoin de guides de démarrage et de développement de projets d''entreprise de niveau avancé utilisant la méthodologie PDCA et la maîtrise du code Claude.","de":"Perfekt für AI-Agenten, die erweiterte Unternehmensprojekt-Initialisierungs- und Entwicklungsleitfäden unter Verwendung der PDCA-Methodik und der Meisterschaft im Claude-Code benötigen.","pt":"Perfeito para Agentes de IA que necessitam de guias avançados de inicialização e desenvolvimento de projetos de nível empresarial usando a metodologia PDCA e a mestria do Claude Code.","ru":"Идеально для агентов ИИ, которым требуются продвинутые руководства по инициализации и разработке проектов уровня предприятия с использованием методологии PDCA и освоения Claude Code.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى دلائل متقدمة لبدء مشاريع وتطوير مستوى المؤسسة باستخدام منهجية PDCA وسيطرة على Claude Code."},"recommendation":{"en":"Empowers agents to create Turborepo monorepo structures, initialize projects with apps/, packages/, services/, and infra/ folder organization, and generate CLAUDE.md files, leveraging PDCA and Claude Code for AI-native development.","zh":"赋予代理创建 Turborepo 单体仓库结构的能力，使用 apps/、packages/、services/ 和 infra/ 文件夹组织初始化项目，并生成 CLAUDE.md 文件，利用 PDCA 和 Claude Code 进行 AI 原生开发。","ja":"エージェントに Turborepo モノレポ構造を作成する能力を付与し、apps/、packages/、services/、infra/ フォルダの組織でプロジェクトを初期化し、CLAUDE.md ファイルを生成します。PDCA と Claude Code を使用して AI ネイティブ開発を行うことができます。","ko":"에이전트가 Turborepo 모노레포 구조를 생성하고 apps/, packages/, services/, infra/ 폴더 조직으로 프로젝트를 초기화하며 CLAUDE.md 파일을 생성할 수 있는 기능을 부여하여 PDCA 및 Claude Code를 사용한 AI 네이티브 개발을 가능하게 합니다.","es":"Permite a los agentes crear estructuras de monorepo Turborepo, inicializar proyectos con organización de carpetas apps/, packages/, services/ e infra/, y generar archivos CLAUDE.md, aprovechando PDCA y Claude Code para el desarrollo nativo de IA.","fr":"Permet aux agents de créer des structures de monorepo Turborepo, d''initialiser des projets avec une organisation de dossiers apps/, packages/, services/ et infra/, et de générer des fichiers CLAUDE.md, en exploitant PDCA et Claude Code pour le développement natif IA.","de":"Ermöglicht es Agenten, Turborepo-Monorepo-Strukturen zu erstellen, Projekte mit einer apps/-, packages/-, services/- und infra/-Ordnerorganisation zu initialisieren und CLAUDE.md-Dateien zu generieren, indem PDCA und Claude Code für die native AI-Entwicklung genutzt werden.","pt":"Habilita os agentes a criar estruturas de repositório monorepo do Turborepo, inicializar projetos com organização de pastas apps/, packages/, services/ e infra/, e gerar arquivos CLAUDE.md, aproveitando a PDCA e o Claude Code para o desenvolvimento nativo de IA.","ru":"Наделяет агентов возможностью создавать структуры монорепозитория Turborepo, инициализировать проекты с организацией папок apps/, packages/, services/ и infra/, и генерировать файлы CLAUDE.md, используя PDCA и Claude Code для разработки родной ИИ.","ar":"تمكين الوكلاء من إنشاء هياكل مستودع التوربو ريبوزيتوري، وتحديد مشاريع مع تنظيم مجلدات التطبيقات /، الحزم /، الخدمات / والبنية التحتية /، وتوليد ملفات CLAUDE.md، باستخدام PDCA و Claude Code للتنمية الأصلية للذكاء الاصطناعي."},"useCases":{"en":["Initializing enterprise-level projects with standardized folder structures","Generating development guides for complex software applications","Creating CLAUDE.md files for documenting project-specific Claude Code configurations"],"zh":["使用标准化的文件夹结构初始化企业级项目","为复杂的软件应用程序生成开发指南","为项目特定的 Claude Code 配置创建 CLAUDE.md 文件"],"ja":["標準化されたフォルダ構造を使用してエンタープライズレベルのプロジェクトを初期化する","複雑なソフトウェアアプリケーションの開発ガイドを生成する","プロジェクト固有の Claude Code 構成のドキュメント化のための CLAUDE.md ファイルを作成する"],"ko":["표준화된 폴더 구조를 사용하여 기업 수준의 프로젝트를 초기화하는 것","복잡한 소프트웨어 애플리케이션에 대한 개발 가이드를 생성하는 것","프로젝트 특정 Claude Code 구성에 대한 문서화용 CLAUDE.md 파일을 생성하는 것"],"es":["Inicialización de proyectos de nivel empresarial con estructuras de carpetas estandarizadas","Generación de guías de desarrollo para aplicaciones de software complejas","Creación de archivos CLAUDE.md para la documentación de configuraciones de código Claude específicas del proyecto"],"fr":["Initialisation de projets d''entreprise de niveau avec des structures de dossiers standardisées","Génération de guides de développement pour des applications logicielles complexes","Création de fichiers CLAUDE.md pour la documentation des configurations de code Claude spécifiques au projet"],"de":["Initialisierung von Unternehmensprojekten mit standardisierten Ordnerstrukturen","Generierung von Entwicklungsleitfäden für komplexe Softwareanwendungen","Erstellung von CLAUDE.md-Dateien für die Dokumentation von Projekt-spezifischen Claude-Code-Konfigurationen"],"pt":["Inicializar projetos de nível empresarial com estruturas de pastas padronizadas","Gerar guias de desenvolvimento para aplicações de software complexas","Criar arquivos CLAUDE.md para documentar configurações de Claude Code específicas do projeto"],"ru":["Инициализировать проекты уровня предприятия со стандартизированной структурой папок","Генерировать руководства по разработке для сложных программных приложений","Создавать файлы CLAUDE.md для документирования конфигураций Claude Code, специфичных для проекта"],"ar":["بدء مشاريع مستوى المؤسسة مع هياكل مجلدات معيارية","توليد دلائل التطوير للتطبيقات البرمجية المعقدة","إنشاء ملفات CLAUDE.md لتدوين تكوينات Claude Code الخاصة بمشروع معين"]},"limitations":{"en":["Requires Claude Code mastery","Limited to Turborepo monorepo structure","PDCA methodology expertise necessary"],"zh":["需要 Claude Code 的掌握","仅限 Turborepo 单体仓库结构","需要 PDCA 方法论的专家知识"],"ja":["Claude Code のマスターが必要","Turborepo モノレポ構造のみ","PDCA 方法論の専門知識が必要"],"ko":["Claude Code의 마스터가 필요합니다.","Turborepo 모노레포 구조만 해당됩니다.","PDCA 방법론에 대한 전문 지식이 필요합니다."],"es":["Requiere maestría en Claude Code","Limitado a la estructura de monorepo Turborepo","Se requiere experiencia en metodología PDCA"],"fr":["Nécessite une maîtrise du code Claude","Limité à la structure de monorepo Turborepo","L''expertise en méthodologie PDCA est nécessaire"],"de":["Erfordert Meisterschaft im Claude-Code","Begrenzt auf die Turborepo-Monorepo-Struktur","Erfahrung in der PDCA-Methodik ist erforderlich"],"pt":["Exige mestria do Claude Code","Limitado à estrutura de repositório monorepo do Turborepo","É necessária expertise em metodologia PDCA"],"ru":["Требует освоения Claude Code","Ограниченная структура монорепозитория Turborepo","Необходима экспертиза в методологии PDCA"],"ar":["يتطلب إتقان Claude Code","محدود ببنية مستودع التوربو ريبوزيتوري","يجب الخبرة في منهجية PDCA"]},"version":4},"contentHash":"410690c330fffbd96ee9ebbacb9d24ecb17f434de24bcccf4f8f727f86cc2c87","qualityScore":57}');
