INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('popup-studio-ai/bkit-claude-code/enterprise', 'enterprise', 'popup-studio-ai', 'bkit-claude-code', 'community', 'enterprise popup-studio-ai bkit-claude-code community The enterprise skill utilizes PDCA methodology and Claude Code mastery for AI-native development, benefiting developers with project initialization and development guides. bkit Vibecoding Kit提供企业级AI开发解决方案，采用PDCA方法论和Claude Code掌握 bkit Vibecoding KitはエンタープライズAI開発ソリューションを提供し、PDCA方法論とClaude Codeのマスターを採用 bkit Vibecoding Kit는 엔터프라이즈 AI 개발 솔루션을 제공하며 PDCA 방법론과 Claude Code 마스터를采用 La habilidad de enterprise utiliza la metodología PDCA y Claude Code para el desarrollo de AI nativo, permitiendo la inicialización de proyectos y la creación de estructuras de monorepo La compétence de l''entreprise utilise la méthodologie PDCA et Claude Code pour le développement d''IA natif, permettant l''initialisation de projets et la création de structures de monorepo Die Enterprise-Fähigkeit verwendet die PDCA-Methodik und Claude Code für die native KI-Entwicklung, ermöglicht die Initialisierung von Projekten und die Erstellung von Monorepo-Strukturen O kit de desenvolvimento Vibecoding combina PDCA e Claude Code para projetos de IA nativa, oferecendo inicialização de projeto e estrutura de monorepo com Turborepo Набор разработки Vibecoding объединяет PDCA и Claude Code для проектов ИИ Агентов, предлагая инициализацию проекта и структуру монорепо с Turborepo حزمة التطوير Vibecoding تجمع بين PDCA و Claude Code لمشاريع الذكاء الاصطناعي المحلية، وتقدم تهيئة المشروع وهيكل مونوريبو مع Turborepo how to use enterprise skill what is enterprise development enterprise alternative to traditional development enterprise vs agile methodology enterprise setup guide installing enterprise skill enterprise PDCA methodology Claude Code mastery Turborepo monorepo structure 企业级AI开发 bkit Vibecoding Kit PDCA方法论 Claude Code Turborepo monorepo AI开发工具 企业级应用开发 AIエージェント AI开发设置 Initializes projects with Turborepo monorepo structure Creates apps/, packages/, services/, and infra/ folder structure Generates CLAUDE.md for enterprise-level documentation Supports project initialization via `/enterprise init` command Provides development guide via `/enterprise guide` command Offers MSA/Infrastructure help via `/enterprise help` command Enterprise is a skill that combines PDCA methodology with Claude Code mastery for advanced AI-native development capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GoogleCloudPlatform/gke-mcp/gke-creation', 'community', 'GoogleCloudPlatform', 'gke-mcp', 'GoogleCloudPlatform/gke-mcp', 'gke-creation', 0, 0, 57, '2026-03-08T01:57:15.277Z', '2026-03-08T02:00:43.201Z', '9e72ce8028f0165a560fd0ba10ed0b722bf60ee0295d8685df197c35feb57299', '{"id":"GoogleCloudPlatform/gke-mcp/gke-creation","name":"gke-creation","description":{"en":"The gke-creation skill helps users create Google Kubernetes Engine clusters by providing best-practice templates and guiding them through customization. It benefits developers and DevOps teams.","zh":"GKE 集群创建 AI Agent Skill 提供模板选择和自定义功能，帮助用户实现 Google Kubernetes Engine 集群的最佳实践设置","ja":"GKE クラスター作成のための AI エージェントは、テンプレート選択とカスタマイズ機能を提供し、ユーザーが Google Kubernetes Engine クラスターのベストプラクティス設定を実現できるように支援","ko":"GKE 클러스터 생성을 위한 AI 에이전트는 템플릿 선택과 사용자 지정 기능을 제공하여 사용자가 Google Kubernetes Engine 클러스터의 최적의 설정을 구현할 수 있도록 지원","es":"El agente de AI para la creación de clústeres GKE ofrece plantillas de mejores prácticas y guía al usuario en el proceso de personalización","fr":"L''outil IA pour la création de clusters GKE propose des modèles de meilleures pratiques et guide l''utilisateur dans le processus de personnalisation","de":"Das KI-Tool für die Erstellung von GKE-Clustern bietet Vorlagen für bewährte Praktiken und führt den Benutzer durch den Anpassungsprozess","pt":"O skill de criação do GKE ajuda a criar clusters do Google Kubernetes Engine com modelos de configuração personalizados.","ru":"Навык создания GKE помогает создавать кластеры Google Kubernetes Engine с настраиваемыми шаблонами конфигурации.","ar":"مهارة إنشاء GKE تساعد على إنشاء مجموعات Google Kubernetes Engine مع نماذج تكوين مخصصة."},"seo":{"title":{"en":"gke-creation: GKE Cluster Setup Guide | AI Agent Skill","zh":"GKE 集群创建指南 - 使用 AI Agent 实现最佳实践","ja":"GKE クラスター作成のための AI エージェント - ベストプラクティス設定ガイド","ko":"GKE 클러스터 생성을 위한 AI 에이전트 - 최적의 설정 방법","es":"Guía de configuración de GKE: Creación de clústeres con A...","fr":"Guide de configuration GKE : Création de clusters avec Ou...","de":"GKE-Einrichtungsleitfaden: Erstellung von Clustern mit KI...","pt":"Guia de Configuração do GKE Creation - Melhores Práticas","ru":"ИИ Агенты для GKE Creation - Руководство по Настройке","ar":"دليل إعداد GKE Creation - أفضل الممارسات"},"description":{"en":"Streamline your GKE cluster creation with our AI agent skill, featuring template selection and customization for optimal Kubernetes deployment","zh":"使用 GKE 集群创建 AI Agent Skill，通过模板选择和自定义，实现 Google Kubernetes Engine 集群的最佳实践设置","ja":"GKE クラスター作成のための AI エージェントを使用して、テンプレート選択とカスタマイズを通じて、Google Kubernetes Engine クラスターのベストプラクティス設定を実現","ko":"GKE 클러스터 생성을 위한 AI 에이전트를 사용하여 템플릿 선택과 사용자 지정 통해 Google Kubernetes Engine 클러스터의 최적의 설정을 구현","es":"Aprende a crear clústeres de Google Kubernetes Engine con nuestro agente de AI y sigue las mejores prácticas para la configuración","fr":"Découvrez comment créer des clusters Google Kubernetes Engine avec notre outil IA et suivez les meilleures pratiques de configuration","de":"Erfahren Sie, wie Sie Google Kubernetes Engine-Cluster mit unserem KI-Tool erstellen und folgen Sie den besten Konfigurationspraktiken","pt":"Aprenda a criar clusters do Google Kubernetes Engine com o skill de criação do GKE. Confira as melhores práticas e modelos de configuração.","ru":"Создавайте кластеры Google Kubernetes Engine с помощью навыка создания GKE. Узнайте о лучших практиках и шаблонах конфигурации.","ar":"تعلم كيفية إنشاء مجموعات Google Kubernetes Engine باستخدام مهارة إنشاء GKE. استكشف أفضل الممارسات والنماذج التكوينية."},"definition":{"en":"gke-creation is a skill that facilitates the creation of Google Kubernetes Engine clusters using templates and customization options","zh":"GKE 集群创建 AI Agent Skill 是一种帮助用户创建 Google Kubernetes Engine 集群的工具，提供模板选择和自定义功能","ja":"GKE クラスター作成のための AI エージェントは、Google Kubernetes Engine クラスターを作成するためのツールであり、テンプレート選択とカスタマイズ機能を提供","ko":"GKE 클러스터 생성을 위한 AI 에이전트는 Google Kubernetes Engine 클러스터를 생성하기 위한 도구로 템플릿 선택과 사용자 지정 기능을 제공","es":"La creación de clústeres GKE es un proceso que utiliza un agente de AI para configurar y personalizar clusters de Google Kubernetes Engine","fr":"La création de clusters GKE est un processus qui utilise un outil IA pour configurer et personnaliser des clusters Google Kubernetes Engine","de":"Die Erstellung von GKE-Clustern ist ein Prozess, der ein KI-Tool verwendet, um Cluster von Google Kubernetes Engine zu konfigurieren und anzupassen","pt":"O que é GKE Creation? É um skill que fornece modelos de configuração para criar clusters do Google Kubernetes Engine.","ru":"Что такое GKE Creation? Это навык, который предоставляет шаблоны конфигурации для создания кластеров Google Kubernetes Engine.","ar":"ما هي مهارة إنشاء GKE؟ هي مهارة توفر نماذج تكوين لإنشاء مجموعات Google Kubernetes Engine."},"features":{"en":["Presents available templates for GKE cluster creation","Explains trade-offs between cost, availability, and Autopilot vs Standard configurations","Supports template selection and default configuration presentation","Guides users through customization of GKE cluster settings","Utilizes JavaScript for configuration customization","Provides a set of best-practice templates for GKE cluster deployment"],"zh":["模板选择功能，提供多种模板供用户选择","自定义功能，允许用户根据需要定制集群配置","支持 Google Kubernetes Engine 的 Autopilot 和 Standard 模式","提供 Cost vs. Availability 的权衡分析","支持 JavaScript 配置文件"],"ja":["テンプレート選択機能、複数のテンプレートを提供","カスタマイズ機能、ユーザーがクラスター構成を必要に応じてカスタマイズできる","Google Kubernetes Engine の Autopilot と Standard モードをサポート","Cost vs. Availability のトレードオフ分析を提供","JavaScript 構成ファイルをサポート"],"ko":["템플릿 선택 기능, 여러 가지 템플릿을 제공","사용자 지정 기능, 사용자가 클러스터 구성에 따라 필요에 맞게 설정할 수 있음","Google Kubernetes Engine의 Autopilot 및 Standard 모드를 지원","비용 대가용 분석을 제공","JavaScript 구성 파일을 지원"],"es":["Selección de plantillas de mejores prácticas para la creación de clústeres GKE","Personalización de la configuración con opciones de costo y disponibilidad","Compatibilidad con Autopilot y clusters estándar","Configuración de clústeres con JavaScript","Guía paso a paso para la creación de clústeres"],"fr":["Sélection de modèles de meilleures pratiques pour la création de clusters GKE","Personnalisation de la configuration avec des options de coût et de disponibilité","Compatibilité avec Autopilot et les clusters standard","Configuration de clusters avec JavaScript","Guide étape par étape pour la création de clusters"],"de":["Auswahl von Vorlagen für bewährte Praktiken zur Erstellung von GKE-Clustern","Anpassung der Konfiguration mit Kosten- und Verfügbarkeitsoptionen","Kompatibilität mit Autopilot und Standard-Clustern","Konfiguration von Clustern mit JavaScript","Schritt-für-Schritt-Anleitung zur Erstellung von Clustern"],"pt":["Seleção de modelos de configuração personalizados","Customização de clusters com opções de Autopilot e Standard","Explicação de trade-offs, como Custo vs. Disponibilidade","Integração com o Google Kubernetes Engine","Suporte a configuração em JavaScript"],"ru":["Выбор настраиваемых шаблонов конфигурации","Настройка кластеров с опциями Autopilot и Standard","Объяснение компромиссов, таких как Стоимость vs. Доступность","Интеграция с Google Kubernetes Engine","Поддержка конфигурации на JavaScript"],"ar":["اختيار نماذج تكوين مخصصة","تخصيص المجموعات بخيارات التحكم الآلي والمعيار","شرح التضحيات، مثل التكلفة مقابل التوفر","التكامل مع محرك كوبرنيتس جوجل","دعم التكوين بلغة جافا سكريبت"]},"keywords":{"en":["how to use gke-creation","gke-creation setup guide","gke-creation vs kubernetes","gke-creation install","what is gke-creation","gke-creation alternative","gke-creation template selection","gke-creation customization options","gke-creation for AI agents","gke-creation for developers"],"zh":["GKE 集群创建","AI Agent Skill","Google Kubernetes Engine","模板选择","自定义","Autopilot","Standard","Cost vs. Availability"],"ja":["GKE クラスター作成","AI エージェント","Google Kubernetes Engine","テンプレート選択","カスタマイズ","Autopilot","Standard","Cost vs. Availability"],"ko":["GKE 클러스터 생성","AI 에이전트","Google Kubernetes Engine","템플릿 선택","사용자 지정","Autopilot","Standard","비용 대가용"],"es":["creación de clústeres GKE","agente de AI para GKE","mejores prácticas para GKE","configuración de clústeres GKE","Autopilot GKE","clusters estándar GKE","JavaScript para GKE","guía de configuración GKE"],"fr":["création de clusters GKE","outil IA pour GKE","meilleures pratiques pour GKE","configuration de clusters GKE","Autopilot GKE","clusters standard GKE","JavaScript pour GKE","guide de configuration GKE"],"de":["Erstellung von GKE-Clustern","KI-Tool für GKE","bewährte Praktiken für GKE","Konfiguration von GKE-Clustern","Autopilot GKE","Standard-Cluster GKE","JavaScript für GKE","Konfigurationsleitfaden GKE"],"pt":["GKE Creation","criação de clusters","Google Kubernetes Engine","modelos de configuração","Autopilot vs Standard","Custo vs Disponibilidade","JavaScript","configuração de cluster"],"ru":["GKE Creation","создание кластеров","Google Kubernetes Engine","шаблоны конфигурации","Autopilot vs Standard","Стоимость vs Доступность","JavaScript","конфигурация кластера"],"ar":["إنشاء GKE","إنشاء المجموعات","محرك كوبرنيتس جوجل","نماذج التكوين","التحكم الآلي مقابل المعيار","التكلفة مقابل التوفر","جافا سكريبت","تكوين المجموعة"]}},"owner":"GoogleCloudPlatform","repo":"gke-mcp","repoPath":"GoogleCloudPlatform/gke-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.277Z","topics":[],"category":"community","skillMd":{"name":"gke-creation","description":"Guides the user through creating GKE clusters using pre-defined templates (Standard, Autopilot, GPU/AI).","bodyPreview":"# GKE Cluster Creation Skill\n\nThis skill helps users create Google Kubernetes Engine (GKE) clusters by providing a set of best-practice templates and guiding them through the customization process.\n\n## core_behavior\n\n1. **Template Selection**:\n   - Present the available templates to the user if they haven''t specified one.\n   - Explain the trade-offs (e.g., Cost vs. Availability, Autopilot vs. Standard).\n2. **Customization**:\n   - Once a template is selected, present the default configuration (JS","body":"# GKE Cluster Creation Skill\n\nThis skill helps users create Google Kubernetes Engine (GKE) clusters by providing a set of best-practice templates and guiding them through the customization process.\n\n## core_behavior\n\n1. **Template Selection**:\n   - Present the available templates to the user if they haven''t specified one.\n   - Explain the trade-offs (e.g., Cost vs. Availability, Autopilot vs. Standard).\n2. **Customization**:\n   - Once a template is selected, present the default configuration (JSON/YAML).\n   - Ask the user for essential missing information: `project_id`, `location`, `cluster_name`.\n   - Ask if they want to modify optional fields (e.g., `machineType`, `nodeCount`, `network`).\n3. **Validation**:\n   - Ensure `project_id`, `location`, and `cluster_name` are set.\n   - Ensure the configuration matches the `create_cluster` MCP tool schema.\n4. **Execution**:\n   - Call the `create_cluster` MCP tool with the final configuration.\n\n## best_practices\n\nWhen guiding the user or generating configurations, adhere to the following GKE cluster creation best practices:\n\n### Security\n\n1. **Private Clusters**: Default to private clusters with a private control plane and restricted public endpoints to minimize attack surface.\n2. **VPC-Native Networking**: Use VPC-native clusters to enable alias IP ranges, which allows pod-level firewall rules and better network security.\n3. **Workload Identity**: Prefer Workload Identity for securely granting GKE workloads access to Google Cloud services instead of using static service account keys.\n4. **Shielded GKE Nodes**: Enable Shielded GKE Nodes to protect against rootkits and bootkits.\n5. **Least Privilege (RBAC)**: Institute strict Role-Based Access Control limits granting minimal privilege to users and workloads.\n\n### Cost Optimization\n\n1. **Autoscaling**: Enable Cluster Autoscaler and Horizontal Pod Autoscaler to adjust resources based on demand.\n2. **Right-Sizing**: Choose the appropriate machine types and node counts. Consider Spot VMs for fault-tolerant, non-critical workloads.\n\n### High Availability & Reliability\n\n1. **Regional Clusters**: Use Regional Clusters for production environments to ensure control plane replication across multiple zones. (Note: standard regional creates nodes across 3 zones by default).\n2. **Pod Disruption Budgets**: Recommend setting Pod Disruption Budgets for application stability during node maintenance.\n3. **Release Channels**: Subscribe to a release channel (e.g., Regular or Stable) for automated and safer cluster upgrades.\n\n## templates\n\n### 1. Standard Zonal (Cost-Effective Dev/Test)\n\nBest for: Development, testing, non-critical workloads.\n\n```json\n{\n  \"name\": \"projects/{PROJECT_ID}/locations/{ZONE}/clusters/{CLUSTER_NAME}\",\n  \"initialNodeCount\": 1,\n  \"nodeConfig\": {\n    \"machineType\": \"e2-medium\",\n    \"diskSizeGb\": 50,\n    \"oauthScopes\": [\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\",\n      \"https://www.googleapis.com/auth/service.management.readonly\",\n      \"https://www.googleapis.com/auth/servicecontrol\",\n      \"https://www.googleapis.com/auth/trace.append\"\n    ]\n  }\n}\n```\n\n### 2. Standard Regional (High Availability)\n\nBest for: Production workloads requiring high availability.\n_Note: Creates 3 nodes (one per zone in the region) by default._\n\n```json\n{\n  \"name\": \"projects/{PROJECT_ID}/locations/{REGION}/clusters/{CLUSTER_NAME}\",\n  \"initialNodeCount\": 1,\n  \"nodeConfig\": {\n    \"machineType\": \"e2-standard-4\",\n    \"diskSizeGb\": 100,\n    \"oauthScopes\": [\"https://www.googleapis.com/auth/cloud-platform\"]\n  }\n}\n```\n\n### 3. Autopilot (Operations-Free)\n\nBest for: Most workloads where you don''t want to manage nodes.\n\n```json\n{\n  \"name\": \"projects/{PROJECT_ID}/locations/{REGION}/clusters/{CLUSTER_NAME}\",\n  \"autopilot\": {\n    \"enabled\": true\n  }\n}\n```\n\n### 4. GPU Inference (L4)\n\nBest for: AI/ML Inference, small model serving.\n_Note: Requires `g2-standard-4` quota._\n\n```json\n{\n  \"name\": \"projects/{PROJECT_ID}/locations/{REGION}/clusters/{CLUSTER_NAME}\",\n  \"initialNodeCount\": 1,\n  \"nodeConfig\": {\n    \"machineType\": \"g2-standard-4\",\n    \"accelerators\": [\n      {\n        \"acceleratorCount\": \"1\",\n        \"acceleratorType\": \"nvidia-l4\"\n      }\n    ],\n    \"diskSizeGb\": 100,\n    \"oauthScopes\": [\"https://www.googleapis.com/auth/cloud-platform\"]\n  }\n}\n```\n\n### 5. AI Hypercompute (A3 HighGPU)\n\nBest for: Large Model Training/Inference.\n_Note: High cost and strict quota requirements._\n\n```json\n{\n  \"name\": \"projects/{PROJECT_ID}/locations/{REGION}/clusters/{CLUSTER_NAME}\",\n  \"initialNodeCount\": 1,\n  \"nodeConfig\": {\n    \"machineType\": \"a3-highgpu-8g\",\n    \"accelerators\": [\n      {\n        \"acceleratorCount\": \"8\",\n        \"acceleratorType\": \"nvidia-h100-80gb-hbm3\"\n      }\n    ],\n    \"diskSizeGb\": 200,\n    \"oauthScopes\": [\"https://www.googleapis.com/auth/cloud-platform\"]\n  }\n}\n```\n\n## instructions\n\n- **ALWAYS** ask for the `project_id` if it is not in the context.\n- **ALWAYS** ask for the `location` (Region or Zone).\n- **ALWAYS** ask for a unique `cluster_name`.\n- **CHECK** if the user wants `Access to Google Cloud APIs` (default `cloud-platform` scope is usually best for modern GKE).\n- **WARN** the user about cost if they select GPU or Reginal clusters.\n- **USE** `create_cluster` MCP tool to create the cluster. The `parent` argument is `projects/{PROJECT_ID}/locations/{LOCATION}` and the `cluster` argument is the JSON object. The `cluster.name` is just the short name (e.g. \"my-cluster\").\n- **IMPORTANT**: When calling `create_cluster`, the `cluster.name` should be the **short name** (e.g., `my-cluster`), NOT the full resource path, because the `parent` argument defines the scope.\n\n## example_usage\n\n**User**: \"I want to create a GKE cluster.\"\n**Model**: \"I can help with that. What kind of cluster do you need?\n\n1. **Standard Zonal**: Good for dev/test.\n2. **Standard Regional**: High availability.\n3. **Autopilot**: Fully managed.\n4. **GPU Enabled**: For AI/ML workloads.\"\n\n**User**: \"Standard Zonal, please.\"\n**Model**: \"Great. I''ll need a few details:\n\n- Project ID\n- Zone (e.g., us-central1-a)\n- Cluster Name\"\n\n**User**: \"Project `my-proj`, zone `us-west1-b`, name `dev-cluster`.\"\n**Model**: \"Here is the configuration I will use:\n[JSON view]\nDo you want to proceed?\"\n"},"lastSynced":"2026-03-08T02:00:43.201Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Infrastructure Agents needing streamlined Google Kubernetes Engine cluster creation and customization.","zh":"适合需要简化Google Kubernetes Engine集群创建和自定义的云基础架构代理。","ja":"Google Kubernetes Engineクラスタの作成とカスタマイズをストリームライン化する必要があるクラウドインフラストラクチャエージェントに最適です。","ko":"구글 쿠버네티스 엔진 클러스터 생성과 사용자 정의를 간소화해야 하는 클라우드 인프라 에이전트에 적합합니다.","es":"Ideal para agentes de infraestructura en la nube que necesitan la creación y personalización de clústeres de Google Kubernetes Engine de forma optimizada.","fr":"Idéal pour les agents d''infrastructure cloud qui ont besoin de créer et de personnaliser des clusters Google Kubernetes Engine de manière optimale.","de":"Ideal für Cloud-Infrastruktur-Agents, die eine optimierte Erstellung und Anpassung von Google Kubernetes Engine-Clustern benötigen.","pt":"Ideal para agentes de infraestrutura em nuvem que precisam de criação e personalização de cluster do Google Kubernetes Engine de forma simplificada.","ru":"Идеально подходит для агентов инфраструктуры облачных вычислений, которым необходима упрощенная создание и настройка кластеров Google Kubernetes Engine.","ar":"مثالي لعميل بروتوكولインターネット لتقنيات السحابة التي تحتاج إلى إنشاء وتخصيص кластер محرك كوبرنيتس جوجل بسهولة."},"recommendation":{"en":"Empowers agents to create and customize GKE clusters using best-practice templates, guiding them through trade-offs such as Cost vs. Availability and Autopilot vs. Standard configurations, all while leveraging Google Cloud''s robust infrastructure.","zh":"赋予代理创建和自定义GKE集群的能力，使用最佳实践模板来指导它们进行权衡，例如成本与可用性和自动驾驶与标准配置之间的权衡，同时利用Google Cloud的强大基础架构。","ja":"ベストプラクティステンプレートを使用してGKEクラスタを作成およびカスタマイズできるエージェントをEmpowerし、コストvs可用性やオートパイロットvs標準構成などのトレードオフを案内し、Google Cloudの強力なインフラストラクチャを活用します。","ko":"베스트 프랙티스 템플릿을 사용하여 GKE 클러스터를 생성 및 사용자 정의할 수 있는 에이전트를 강화하고, 비용 대 가용성 및 오토파일럿 대 표준 구성과 같은 트레이드 오프를 안내하며, 구글 클라우드의 강력한 인프라를 활용합니다.","es":"Habilita a los agentes a crear y personalizar clústeres de GKE utilizando plantillas de mejores prácticas, guiándolos a través de compensaciones como Costo vs. Disponibilidad y Autopilot vs. configuraciones estándar, todo mientras aprovecha la robusta infraestructura de Google Cloud.","fr":"Permet aux agents de créer et de personnaliser des clusters GKE en utilisant des modèles de meilleures pratiques, en les guidant à travers des compromis tels que Coût vs. Disponibilité et Autopilot vs. configurations standard, le tout en exploitant l''infrastructure robuste de Google Cloud.","de":"Ermöglicht es Agenten, GKE-Cluster zu erstellen und anzupassen, indem sie Vorlagen für Best Practices verwenden, und führt sie durch Kompromisse wie Kosten vs. Verfügbarkeit und Autopilot vs. Standardkonfigurationen, während sie die robuste Infrastruktur von Google Cloud nutzen.","pt":"Permite que os agentes criem e personalizem clusters do GKE usando modelos de melhores práticas, guiando-os por meio de trade-offs, como Custo vs. Disponibilidade e Autopilot vs. Configurações Padrão, aproveitando toda a infraestrutura robusta do Google Cloud.","ru":"Наделяет агентов возможностью создавать и настраивать кластеры GKE с помощью шаблонов лучших практик, руководя ими через компромиссы, такие как Стоимость vs. Доступность и Автопилот vs. Стандартные конфигурации, используя все возможности robustной инфраструктуры Google Cloud.","ar":"تمكّن الوكيل من إنشاء وتخصيص клаستر GKE باستخدام قوالب أفضل الممارسات، وتوجيههم خلال التبادلات مثل التكلفة مقابل التوفر وتشغيل الطيار الآلي مقابل الإعدادات القياسية، مع الاستفادة الكاملة من بنية تحتية قوية من جوجل كلاود."},"useCases":{"en":["Automating GKE cluster deployments with predefined templates","Customizing cluster configurations for optimal performance and cost","Guiding users through the selection of appropriate GKE cluster templates based on specific needs"],"zh":["使用预定义模板自动化GKE集群部署","为最佳性能和成本自定义集群配置","根据特定需求指导用户选择适当的GKE集群模板"],"ja":["事前定義されたテンプレートを使用したGKEクラスタの自動化されたデプロイ","最適なパフォーマンスとコストのクラスタ構成のカスタマイズ","特定のニーズに基づいて適切なGKEクラスタテンプレートの選択をユーザーに案内する"],"ko":["사전 정의된 템플릿을 사용하여 GKE 클러스터 자동 배포","최적의 성능과 비용에 대한 클러스터 구성 사용자 정의","특정 요구 사항에 따라 적절한 GKE 클러스터 템플릿 선택을 사용자에게 안내"],"es":["Automatizar las implementaciones de clústeres de GKE con plantillas predefinidas","Personalizar las configuraciones de clúster para un rendimiento y costo óptimos","Guía a los usuarios en la selección de plantillas de clústeres de GKE adecuadas según necesidades específicas"],"fr":["Automatiser les déploiements de clusters GKE avec des modèles prédéfinis","Personnaliser les configurations de cluster pour des performances et un coût optimaux","Guider les utilisateurs dans la sélection de modèles de clusters GKE appropriés en fonction de besoins spécifiques"],"de":["Automatisieren von GKE-Cluster-Bereitstellungen mit vordefinierten Vorlagen","Anpassen von Cluster-Konfigurationen für optimale Leistung und Kosten","Benutzer bei der Auswahl geeigneter GKE-Cluster-Vorlagen nach spezifischen Anforderungen führen"],"pt":["Automatizar implantações de cluster do GKE com modelos predefinidos","Personalizar configurações de cluster para desempenho e custo ótimos","Orientar os usuários na seleção de modelos de cluster do GKE adequados com base em necessidades específicas"],"ru":["Автоматизировать развертывание кластеров GKE с помощью预определенных шаблонов","Настроить конфигурации кластера для оптимальной производительности и стоимости","Направлять пользователей в выборе подходящих шаблонов кластера GKE на основе конкретных потребностей"],"ar":["تأتمتة نشر клаستر GKE باستخدام قوالب محددة مسبقا","تخصيص إعدادات الكلستر من أجل الأداء والتكلفة الأمثل","توجيه المستخدمين في اختيار قوالب клаستر GKE المناسبة بناءً على الاحتياجات المحددة"]},"limitations":{"en":["Requires Google Cloud account and credentials","Limited to Google Kubernetes Engine (GKE) cluster creation"],"zh":["需要Google Cloud账户和凭证","仅限Google Kubernetes Engine (GKE)集群创建"],"ja":["Google Cloudアカウントと資格情報が必要","Google Kubernetes Engine (GKE)クラスタの作成のみ"],"ko":["구글 클라우드 계정 및 자격 증명이 필요","구글 쿠버네티스 엔진 (GKE) 클러스터 생성만"],"es":["Requiere una cuenta y credenciales de Google Cloud","Limitado a la creación de clústeres de Google Kubernetes Engine (GKE)"],"fr":["Nécessite un compte et des informations d''identification Google Cloud","Limité à la création de clusters Google Kubernetes Engine (GKE)"],"de":["Benötigt ein Google Cloud-Konto und -Anmeldeinformationen","Begrenzt auf die Erstellung von Google Kubernetes Engine-Clustern (GKE)"],"pt":["Exige conta e credenciais do Google Cloud","Limitado à criação de cluster do Google Kubernetes Engine (GKE)"],"ru":["Требует учетной записи и учетных данных Google Cloud","Ограничен созданием кластера Google Kubernetes Engine (GKE)"],"ar":["يتطلب حسابًا وأرصدة جوجل كلاود","محدود بإنشاء клаستر محرك كوبرنيتس جوجل (GKE)"]},"version":4},"contentHash":"9e72ce8028f0165a560fd0ba10ed0b722bf60ee0295d8685df197c35feb57299","qualityScore":57}');
