INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GoogleCloudPlatform/gke-mcp/gke-creation', 'gke-creation', 'GoogleCloudPlatform', 'gke-mcp', 'community', 'gke-creation GoogleCloudPlatform gke-mcp community The gke-creation skill helps users create Google Kubernetes Engine clusters by providing best-practice templates and guiding them through customization. It benefits developers and DevOps teams. GKE 集群创建 AI Agent Skill 提供模板选择和自定义功能，帮助用户实现 Google Kubernetes Engine 集群的最佳实践设置 GKE クラスター作成のための AI エージェントは、テンプレート選択とカスタマイズ機能を提供し、ユーザーが Google Kubernetes Engine クラスターのベストプラクティス設定を実現できるように支援 GKE 클러스터 생성을 위한 AI 에이전트는 템플릿 선택과 사용자 지정 기능을 제공하여 사용자가 Google Kubernetes Engine 클러스터의 최적의 설정을 구현할 수 있도록 지원 El agente de AI para la creación de clústeres GKE ofrece plantillas de mejores prácticas y guía al usuario en el proceso de personalización L''outil IA pour la création de clusters GKE propose des modèles de meilleures pratiques et guide l''utilisateur dans le processus de personnalisation Das KI-Tool für die Erstellung von GKE-Clustern bietet Vorlagen für bewährte Praktiken und führt den Benutzer durch den Anpassungsprozess O skill de criação do GKE ajuda a criar clusters do Google Kubernetes Engine com modelos de configuração personalizados. Навык создания GKE помогает создавать кластеры Google Kubernetes Engine с настраиваемыми шаблонами конфигурации. مهارة إنشاء GKE تساعد على إنشاء مجموعات Google Kubernetes Engine مع نماذج تكوين مخصصة. how to use gke-creation gke-creation setup guide gke-creation vs kubernetes gke-creation install what is gke-creation gke-creation alternative gke-creation template selection gke-creation customization options gke-creation for AI agents gke-creation for developers GKE 集群创建 AI Agent Skill Google Kubernetes Engine 模板选择 自定义 Autopilot Standard Cost vs. Availability Presents available templates for GKE cluster creation Explains trade-offs between cost, availability, and Autopilot vs Standard configurations Supports template selection and default configuration presentation Guides users through customization of GKE cluster settings Utilizes JavaScript for configuration customization Provides a set of best-practice templates for GKE cluster deployment gke-creation is a skill that facilitates the creation of Google Kubernetes Engine clusters using templates and customization options');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dojoengine/book/dojo-deploy', 'community', 'dojoengine', 'book', 'dojoengine/book', 'dojo-deploy', 0, 0, 57, '2026-03-08T01:57:15.277Z', '2026-03-08T02:00:44.342Z', '25220d2ca9734c53ca61183142f5a7554224905da3bd014ca0354f958d3991f3', '{"id":"dojoengine/book/dojo-deploy","name":"dojo-deploy","description":{"en":"The dojo-deploy skill handles deployment workflows for Dojo worlds, benefiting developers who need to deploy to Katana, Sepolia testnet, or Starknet mainnet. It streamlines the deployment process using sozo migrate and manages world addresses.","zh":"Dojo Deploy 是一个处理部署工作流的工具，支持 Katana sequencer、Sepolia testnet 和 Starknet mainnet 的部署","ja":"Dojo Deploy はデプロイメントワークフローを処理するツールで、Katana sequencer、Sepolia testnet、Starknet mainnet へのデプロイをサポートします","ko":"Dojo Deploy 는 배포 워크플로우를 처리하는 도구로 Katana sequencer, Sepolia testnet, Starknet mainnet 에 대한 배포를 지원합니다","es":"dojo-deploy es una habilidad que permite desplegar mundos en Katana, Sepolia o Starknet mainnet. Maneja flujos de trabajo de despliegue y configura redes","fr":"dojo-deploy est une compétence qui permet de déployer des mondes sur Katana, Sepolia ou Starknet mainnet. Elle gère les flux de travail de déploiement et configure les réseaux","de":"dojo-deploy ist eine Fähigkeit, die es ermöglicht, Welten auf Katana, Sepolia oder Starknet mainnet bereitzustellen. Sie verwaltet Bereitstellungsworkflows und konfiguriert Netze","pt":"O Dojo-Deploy é uma ferramenta para implantar mundos no Katana sequencer, Sepolia testnet ou Starknet mainnet","ru":"Dojo-Deploy - это инструмент для развертывания миров в Katana sequencer, Sepolia testnet или Starknet mainnet","ar":"Dojo-Deploy هو أداة لنشر العوالم في Katana sequencer أو Sepolia testnet أو Starknet mainnet"},"seo":{"title":{"en":"dojo-deploy: Deployment Setup Guide | AI Agent Skill","zh":"Dojo Deploy 设置指南 - AI 工具","ja":"Dojo Deploy のベストプラクティス - AI エージェント","ko":"Dojo Deploy 설정 가이드 - AI 에이전트","es":"Guía de configuración de dojo-deploy para despliegue de m...","fr":"Guide de déploiement de dojo-deploy pour les mondes","de":"Einrichtungsleitfaden für dojo-deploy zur Bereitstellung ...","pt":"Guia de Configuração do Dojo-Deploy: Implantação de Mundos","ru":"Настройка Dojo-Deploy: Руководство по развертыванию ИИ Аг...","ar":"دليل تثبيت Dojo-Deploy: نشر العوالم باستخدام أدوات الذكاء..."},"description":{"en":"Discover how to deploy your Dojo world to local Katana sequencer, Sepolia testnet, or Starknet mainnet with dojo-deploy - get started now!","zh":"了解 Dojo Deploy 的功能和用途，实现 Katana sequencer、Sepolia testnet 和 Starknet mainnet 的部署","ja":"Dojo Deploy の機能と使い方を学び、Katana sequencer、Sepolia testnet、Starknet mainnet へのデプロイを実現する","ko":"Dojo Deploy 의 기능과 용도를 알아보고 Katana sequencer, Sepolia testnet, Starknet mainnet 에 대한 배포를 구현하세요","es":"Aprende a desplegar tus mundos con dojo-deploy en Katana, Sepolia o Starknet mainnet. Configura y verifica tus despliegues con facilidad","fr":"Découvrez comment déployer vos mondes avec dojo-deploy sur Katana, Sepolia ou Starknet mainnet. Configurez et vérifiez vos déploiements avec facilité","de":"Erfahren Sie, wie Sie Ihre Welten mit dojo-deploy auf Katana, Sepolia oder Starknet mainnet bereitstellen. Konfigurieren und überprüfen Sie Ihre Bereitstellu...","pt":"Aprenda a implantar seus mundos no Katana sequencer, Sepolia testnet ou Starknet mainnet com o Dojo-Deploy","ru":"Развертывайте свои миры в Katana sequencer, Sepolia testnet или Starknet mainnet с помощью Dojo-Deploy и ИИ Агентов","ar":"تعلم نشر عوالمك في Katana sequencer أو Sepolia testnet أو Starknet mainnet باستخدام Dojo-Deploy وأدوات الذكاء الاصطناعي"},"definition":{"en":"dojo-deploy is a skill that enables deployment of Dojo worlds to various networks, including local Katana sequencer, Sepolia testnet, and Starknet mainnet.","zh":"Dojo Deploy 是一个 AI 工具，用于处理 Dojo 世界的部署工作流","ja":"Dojo Deploy は AI エージェントの一種で、Dojo ワールドのデプロイメントワークフローを処理する","ko":"Dojo Deploy 는 AI 에이전트의 일종으로 Dojo 세계의 배포 워크플로우를 처리합니다","es":"dojo-deploy es una herramienta de despliegue de mundos que permite configurar y verificar despliegues en diferentes redes","fr":"dojo-deploy est un outil de déploiement de mondes qui permet de configurer et de vérifier les déploiements sur différentes réseaux","de":"dojo-deploy ist ein Werkzeug zur Bereitstellung von Welten, das die Konfiguration und Überprüfung von Bereitstellungen auf verschiedenen Netzen ermöglicht","pt":"O que é Dojo-Deploy? Uma ferramenta de implantação de mundos para desenvolvedores","ru":"Что такое Dojo-Deploy? Инструмент для развертывания миров для разработчиков и ИИ Агентов","ar":"ما هو Dojo-Deploy؟ أداة لنشر العوالم لمطوري الذكاء الاصطناعي"},"features":{"en":["Starts and configures Katana sequencer","Deploys worlds using sozo migrate command","Verifies deployments and manages world addresses","Configures network settings for seamless deployment","Supports deployment to Sepolia testnet and Starknet mainnet"],"zh":["支持 Katana sequencer 的启动和配置","支持 Sepolia testnet 和 Starknet mainnet 的部署","支持 sozo migrate 命令的执行","支持部署验证和世界地址管理","支持网络设置的配置"],"ja":["Katana sequencer の起動と設定をサポート","Sepolia testnet と Starknet mainnet へのデプロイをサポート","sozo migrate コマンドの実行をサポート","デプロイの検証とワールドアドレスの管理をサポート","ネットワーク設定の構成をサポート"],"ko":["Katana sequencer 의 시작과 설정을 지원","Sepolia testnet 과 Starknet mainnet 에 대한 배포를 지원","sozo migrate 명령의 실행을 지원","배포의 검증과 세계 주소의 관리를 지원","네트워크 설정의 구성을 지원"],"es":["Despliegue de mundos en Katana","Despliegue en Sepolia testnet","Despliegue en Starknet mainnet","Configuración de redes","Verificación de despliegues","Uso de sozo migrate para despliegues"],"fr":["Déploiement de mondes sur Katana","Déploiement sur Sepolia testnet","Déploiement sur Starknet mainnet","Configuration de réseaux","Vérification de déploiements","Utilisation de sozo migrate pour les déploiements"],"de":["Bereitstellung von Welten auf Katana","Bereitstellung auf Sepolia testnet","Bereitstellung auf Starknet mainnet","Netzwerkkonfiguration","Überprüfung von Bereitstellungen","Verwendung von sozo migrate für Bereitstellungen"],"pt":["Inicia e configura o Katana sequencer","Implanta mundos com `sozo migrate`","Verifica implantações","Gerencia endereços de mundos","Configura configurações de rede"],"ru":["Запускает и настраивает Katana sequencer","Развертывает миры с помощью `sozo migrate`","Проверяет развертывания","Управляет адресами миров","Настраивает сетевые настройки"],"ar":["يبدأ وتكوين Katana sequencer","ينشر العوالم باستخدام `sozo migrate`","يتحقق من النشر","يدير عناوين العوالم","يتحكم في إعدادات الشبكة"]},"keywords":{"en":["how to use dojo-deploy","dojo-deploy setup guide","dojo-deploy alternative","dojo-deploy vs Starknet","deploy Dojo world to Katana","dojo-deploy installation","what is dojo-deploy","dojo-deploy tutorial","dojo-deploy Sepolia testnet deployment"],"zh":["Dojo Deploy","Katana sequencer","Sepolia testnet","Starknet mainnet","AI 工具","部署工作流","sozo migrate","网络设置"],"ja":["Dojo Deploy","Katana sequencer","Sepolia testnet","Starknet mainnet","AI エージェント","デプロイメントワークフロー","sozo migrate","ネットワーク設定"],"ko":["Dojo Deploy","Katana sequencer","Sepolia testnet","Starknet mainnet","AI 에이전트","배포 워크플로우","sozo migrate","네트워크 설정"],"es":["dojo-deploy","despliegue de mundos","Katana","Sepolia testnet","Starknet mainnet","configuración de redes","verificación de despliegues","sozo migrate","herramientas de despliegue","Agentes de Inteligencia Artificial"],"fr":["dojo-deploy","déploiement de mondes","Katana","Sepolia testnet","Starknet mainnet","configuration de réseaux","vérification de déploiements","sozo migrate","outils de déploiement","Agents d''Intelligence Artificielle"],"de":["dojo-deploy","Bereitstellung von Welten","Katana","Sepolia testnet","Starknet mainnet","Netzwerkkonfiguration","Überprüfung von Bereitstellungen","sozo migrate","Werkzeuge zur Bereitstellung","Künstliche Intelligenz Agenten"],"pt":["Dojo-Deploy","implantação de mundos","Katana sequencer","Sepolia testnet","Starknet mainnet","desenvolvimento de mundos","ferramentas de desenvolvimento","implantação de aplicativos"],"ru":["Dojo-Deploy","развертывание миров","Katana sequencer","Sepolia testnet","Starknet mainnet","разработка миров","инструменты разработки","ИИ Агенты","развертывание приложений"],"ar":["Dojo-Deploy","نشر العوالم","Katana sequencer","Sepolia testnet","Starknet mainnet","تطوير العوالم","أدوات التطوير","أدوات الذكاء الاصطناعي","نشر التطبيقات"]}},"owner":"dojoengine","repo":"book","repoPath":"dojoengine/book","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.277Z","topics":[],"category":"community","skillMd":{"name":"dojo-deploy","description":"Deploy Dojo worlds to local Katana, testnet, or mainnet. Configure Katana sequencer and manage deployments with sozo. Use when deploying your game or starting local development environment.","bodyPreview":"# Dojo Deployment\n\nDeploy your Dojo world to local Katana sequencer, Sepolia testnet, or Starknet mainnet.\n\n## When to Use This Skill\n\n- \"Deploy my world to Katana\"\n- \"Start Katana sequencer\"\n- \"Deploy to Sepolia testnet\"\n- \"Deploy to mainnet\"\n\n## What This Skill Does\n\nHandles deployment workflows:\n- Start and configure Katana sequencer\n- Deploy worlds with `sozo migrate`\n- Verify deployments\n- Manage world addresses\n- Configure network settings\n\n## Quick Start\n\n**Local development:**\n```\n\"Start","body":"# Dojo Deployment\n\nDeploy your Dojo world to local Katana sequencer, Sepolia testnet, or Starknet mainnet.\n\n## When to Use This Skill\n\n- \"Deploy my world to Katana\"\n- \"Start Katana sequencer\"\n- \"Deploy to Sepolia testnet\"\n- \"Deploy to mainnet\"\n\n## What This Skill Does\n\nHandles deployment workflows:\n- Start and configure Katana sequencer\n- Deploy worlds with `sozo migrate`\n- Verify deployments\n- Manage world addresses\n- Configure network settings\n\n## Quick Start\n\n**Local development:**\n```\n\"Start Katana and deploy my world\"\n```\n\n**Testnet deployment:**\n```\n\"Deploy my world to Sepolia\"\n```\n\n**Mainnet deployment:**\n```\n\"Deploy to Starknet mainnet\"\n```\n\n## Deployment Workflow\n\n### 1. Local Development (Katana)\n\n**Start Katana:**\n```bash\nkatana --dev --dev.no-fee\n```\n\nThis launches Katana with:\n- RPC server at `http://localhost:5050`\n- 10 pre-funded accounts\n- Instant block mining\n- Gas fees disabled\n\n**Build and deploy:**\n```bash\nsozo build && sozo migrate\n```\n\n**Verify:**\n```bash\n# Preview deployment\nsozo inspect\n\n# Execute a system\nsozo execute dojo_starter-actions spawn\n```\n\n### 2. Testnet Deployment (Sepolia)\n\n**Configure profile:**\n```toml\n# dojo_sepolia.toml\n[world]\nname = \"My Game\"\nseed = \"my-game-sepolia\"\n\n[env]\nrpc_url = \"https://api.cartridge.gg/x/starknet/sepolia\"\naccount_address = \"YOUR_ACCOUNT\"\nprivate_key = \"YOUR_KEY\"\n\n[namespace]\ndefault = \"my_game\"\n\n[writers]\n\"my_game\" = [\"my_game-actions\"]\n```\n\n**Deploy:**\n```bash\nsozo build --profile sepolia\nsozo migrate --profile sepolia\n```\n\n### 3. Mainnet Deployment\n\n**Configure profile:**\n```toml\n# dojo_mainnet.toml\n[world]\nname = \"My Game\"\nseed = \"my-game-mainnet\"\n\n[env]\nrpc_url = \"https://api.cartridge.gg/x/starknet/mainnet\"\naccount_address = \"YOUR_ACCOUNT\"\nkeystore_path = \"~/.starknet_accounts/mainnet.json\"\n\n[namespace]\ndefault = \"my_game\"\n\n[writers]\n\"my_game\" = [\"my_game-actions\"]\n```\n\n**Deploy:**\n```bash\nsozo build --profile mainnet\nsozo migrate --profile mainnet\n```\n\n## Katana Configuration\n\nSee the [Katana configuration guide](/toolchain/katana/configuration) for all available TOML options.\n\n### TOML Configuration\n\nMost Dojo projects use a `katana.toml` config file rather than CLI flags.\nRecommended starter config:\n\n```toml\n[dev]\ndev = true\nno_fee = true\n\n[cartridge]\ncontrollers = true\n\n[server]\nhttp_cors_origins = \"*\"\n```\n\nStart with config file:\n\n```bash\nkatana --config katana.toml\n```\n\n### Cartridge Controller on Katana\n\nWhen using [Cartridge Controller](https://docs.cartridge.gg/controller/getting-started) locally, Katana must deploy Controller contracts at genesis.\nWithout this, Controller transactions fail with \"Requested contract address ... is not deployed\".\n\n```toml\n# katana.toml\n[cartridge]\npaymaster = true  # Enables paymaster AND deploys Controller contracts at genesis\n```\n\nNote: `paymaster = true` implicitly enables `controllers = true`.\nSee the [Controller setup docs](https://docs.cartridge.gg/controller/getting-started) for client-side configuration.\n\n### Quick Start (CLI flags)\n\n```bash\nkatana --dev --dev.no-fee\n```\n\n### Mining Modes\n\n**Instant (default):**\n```bash\nkatana --dev --dev.no-fee\n```\nMines block immediately on transaction.\n\n**Interval:**\n```bash\nkatana --block-time 10000\n```\nMines block every 10 seconds.\n\n### Persistent Storage\n\n```bash\nkatana --db-dir ./katana-db\n```\n\n### Network Forking\n\n**Fork Starknet mainnet:**\n```bash\nkatana --fork.provider https://api.cartridge.gg/x/starknet/mainnet\n```\n\n**Fork at specific block:**\n```bash\nkatana --fork.provider https://api.cartridge.gg/x/starknet/mainnet --fork.block 1000000\n```\n\n## Sozo Commands\n\n### Build\n```bash\nsozo build\n```\n\n### Inspect (Preview Deployment)\n```bash\n# See what will be deployed/changed\nsozo inspect\n```\n\n### Migrate (Deploy)\n```bash\n# Deploy with default dev profile\nsozo migrate\n\n# Deploy with specific profile\nsozo migrate --profile sepolia\n```\n\n### Execute System\n```bash\n# Call a system function\nsozo execute <CONTRACT_TAG> <FUNCTION> [ARGS...]\n\n# Example: spawn\nsozo execute dojo_starter-actions spawn\n\n# Example: move with argument\nsozo execute dojo_starter-actions move 1\n```\n\n## Deployment Checklist\n\n### Pre-Deployment\n- [ ] All tests passing (`sozo test`)\n- [ ] Code reviewed (`dojo-review` skill)\n- [ ] Configuration set (`dojo-config` skill)\n- [ ] Target network funded (for gas)\n- [ ] Private key secured (not committed)\n\n### Deployment\n- [ ] Build succeeds (`sozo build`)\n- [ ] Inspect looks correct (`sozo inspect`)\n- [ ] Migration succeeds (`sozo migrate`)\n- [ ] Manifest generated (check `manifest_<profile>.json`)\n- [ ] World address recorded\n\n### Post-Deployment\n- [ ] Deployment verified (execute systems, query models)\n- [ ] Torii indexer configured (`dojo-indexer` skill)\n- [ ] Client connected (`dojo-client` skill)\n- [ ] World permissions verified (`dojo-world` skill)\n\n## Development Workflow\n\n**Terminal 1: Start Katana**\n```bash\nkatana --dev --dev.no-fee\n```\n\n**Terminal 2: Build and deploy**\n```bash\nsozo build && sozo migrate\n```\n\n**Terminal 3: Start Torii**\n```bash\ntorii --world <WORLD_ADDRESS> --indexing.controllers\n```\n\n## Sample Deploy Script\n\nThis skill includes `deploy_local.sh`, a template script for automated local development.\nCopy it into your project''s `scripts/` directory and customize it for your needs.\n\n**Setup:**\n1. Copy the script to your project: `cp deploy_local.sh your-project/scripts/`\n2. Adjust configuration variables (profile name, URLs) as needed\n3. Make executable: `chmod +x scripts/deploy_local.sh`\n\n**Run:**\n```bash\n# Default dev profile\n./scripts/deploy_local.sh\n\n# Specific profile\nPROFILE=staging ./scripts/deploy_local.sh\n```\n\n**What it does:**\n1. Checks for required tools (katana, sozo, torii, jq)\n2. Starts Katana with health checking\n3. Builds and deploys contracts\n4. Extracts addresses from the manifest\n5. Starts Torii indexer\n6. Cleans up all services on exit (Ctrl+C)\n\n**Customization points:**\n- `PROFILE`: Default build/deploy profile\n- `RPC_URL`: Katana endpoint (default: `http://localhost:5050`)\n- `TORII_URL`: Torii endpoint (default: `http://localhost:8080`)\n- Add project-specific post-deploy steps (e.g., seeding data, running migrations)\n\n## Slot Deployment (Remote)\n\n[Slot](https://docs.cartridge.gg/slot) provides hosted Katana and Torii instances.\n\n### Authentication\n\n```bash\nslot auth login\n```\n\n### Katana on Slot\n\n**Optimistic mode (simplest):**\n```bash\nslot deployments create <PROJECT_NAME> katana --optimistic\n```\n\n**With configuration file:**\n```bash\nslot deployments create <PROJECT_NAME> katana --config katana.toml\n```\n\nSee the [Katana configuration guide](/toolchain/katana/configuration) for TOML options.\n\n### Torii on Slot\n\nCreate a `torii.toml` with your world address and RPC endpoint, then deploy:\n\n```bash\nslot deployments create <PROJECT_NAME> torii --config torii.toml --version <DOJO_VERSION>\n```\n\nSee the `dojo-indexer` skill for full Torii configuration details.\n\n### Useful Commands\n\n```bash\n# Stream logs\nslot deployments logs <PROJECT_NAME> katana -f\nslot deployments logs <PROJECT_NAME> torii -f\n\n# Delete a deployment\nslot deployments delete <PROJECT_NAME> katana\nslot deployments delete <PROJECT_NAME> torii\n```\n\n## Manifest File\n\nAfter deployment, `manifest_<profile>.json` contains:\n- World address\n- Model addresses and class hashes\n- System/contract addresses\n- ABI information\n\n**Example:**\n```json\n{\n  \"world\": {\n    \"address\": \"0x...\",\n    \"class_hash\": \"0x...\"\n  },\n  \"models\": [\n    {\n      \"tag\": \"dojo_starter-Position\",\n      \"address\": \"0x...\"\n    }\n  ],\n  \"contracts\": [\n    {\n      \"tag\": \"dojo_starter-actions\",\n      \"address\": \"0x...\"\n    }\n  ]\n}\n```\n\n## Troubleshooting\n\n### \"Account not found\"\n- Ensure account is deployed on target network\n- Check account address in profile config\n- Verify account has funds for gas\n\n### \"Class hash mismatch\"\n- Run `sozo build` before migrating\n- Check Scarb.toml for correct Dojo version\n- Clear `target/` and rebuild\n\n### \"Insufficient funds\"\n- Fund account with ETH/STRK for gas\n- Use Sepolia faucet: https://faucet.starknet.io\n\n### \"Profile not found\"\n- Ensure `dojo_<profile>.toml` exists\n- Check spelling matches the `--profile` flag\n\n## Network Information\n\n### Katana (Local)\n- RPC: `http://localhost:5050`\n- Pre-funded accounts printed on startup\n\n### Sepolia (Testnet)\n- RPC: `https://api.cartridge.gg/x/starknet/sepolia`\n- Faucet: https://faucet.starknet.io\n- Explorer: https://sepolia.voyager.online\n\n### Mainnet\n- RPC: `https://api.cartridge.gg/x/starknet/mainnet`\n- Explorer: https://voyager.online\n\n## Next Steps\n\nAfter deployment:\n1. Use `dojo-indexer` skill to set up Torii\n2. Use `dojo-client` skill to connect frontend\n3. Use `dojo-world` skill to configure permissions\n4. Use `dojo-migrate` skill for updates\n\n## Related Skills\n\n- **dojo-config**: Configure deployment profiles\n- **dojo-migrate**: Update deployments\n- **dojo-indexer**: Index deployed world\n- **dojo-client**: Connect clients to deployment\n- **dojo-world**: Manage world permissions\n"},"lastSynced":"2026-03-08T02:00:44.342Z","agentAnalysis":{"suitability":{"en":"Perfect for Blockchain Agents needing streamlined deployment workflows for Dojo worlds on Katana, Sepolia testnet, or Starknet mainnet.","zh":"非常适合需要为Dojo世界在Katana、Sepolia测试网或Starknet主网上实现简化部署工作流的区块链代理。","ja":"Katana、Sepoliaテストネット、またはStarknetメインネット上のDojo世界に対してストリームライン化されたデプロイワークフローを必要とするブロックチェーンエージェントに最適です。","ko":"Katana, Sepolia 테스트 네트워크 또는 Starknet 메인 네트워크에서 Dojo 세계를 위한 스트림 라인화된 배포 워크 플로우가 필요한 블록 체인 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Blockchain que necesitan flujos de trabajo de implementación simplificados para mundos de Dojo en Katana, Sepolia testnet o Starknet mainnet.","fr":"Parfait pour les agents de blockchain ayant besoin de flux de travail de déploiement simplifiés pour les mondes de Dojo sur Katana, Sepolia testnet ou Starknet mainnet.","de":"Perfekt für Blockchain-Agents, die vereinfachte Bereitstellungs-Workflows für Dojo-Welten auf Katana, Sepolia-Testnet oder Starknet-Mainnet benötigen.","pt":"Perfeito para Agentes de Blockchain que precisam de fluxos de implantação simplificados para mundos Dojo em Katana, testnet Sepolia ou mainnet Starknet.","ru":"Идеально подходит для агентов блокчейна, которым необходимы упрощенные рабочие процессы развертывания для миров Dojo в Katana, тестовой сети Sepolia или основной сети Starknet.","ar":"مثالي لعميل Blockchain الذي يحتاج إلى عمليات نشر مبسطة لمundos Dojo في Katana أو شبكة اختبار Sepolia أو شبكة Starknet الرئيسية."},"recommendation":{"en":"Empowers agents to automate deployment processes using sozo migrate, manage world addresses, and configure network settings for seamless interaction with blockchain testnets and mainnets, including Sepolia and Starknet.","zh":"赋予代理自动化部署流程的能力，使用sozo migrate，管理世界地址，并为与区块链测试网和主网（包括Sepolia和Starknet）进行无缝交互配置网络设置。","ja":"sozo migrateを使用してデプロイプロセスを自動化し、ワールドアドレスを管理し、SepoliaおよびStarknetを含むブロックチェーンテストネットおよびメインネットとのシームレスなやり取りに対するネットワーク設定を構成することでエージェントに力を与えます。","ko":"에이전트에게 sozo migrate를 사용하여 배포 프로세스를 자동화하고, 세계 주소를 관리하고, Sepolia 및 Starknet를 포함한 블록 체인 테스트 네트워크 및 메인 네트워크와의 무결점 상호 작용을 위한 네트워크 설정을 구성할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a automatizar los procesos de implementación utilizando sozo migrate, gestionar direcciones de mundo y configurar la configuración de red para una interacción sin problemas con testnets y mainnets de blockchain, incluyendo Sepolia y Starknet.","fr":"Permet aux agents d''automatiser les processus de déploiement en utilisant sozo migrate, de gérer les adresses de monde et de configurer les paramètres de réseau pour une interaction transparente avec les testnets et les mainnets de blockchain, notamment Sepolia et Starknet.","de":"Ermöglicht es den Agents, die Bereitstellungsprozesse mithilfe von sozo migrate zu automatisieren, Weltadressen zu verwalten und Netzwerkeinstellungen für eine nahtlose Interaktion mit Blockchain-Testnets und -Mainnets, einschließlich Sepolia und Starknet, zu konfigurieren.","pt":"Habilita os agentes a automatizar os processos de implantação usando sozo migrate, gerenciar endereços de mundo e configurar configurações de rede para interação sem problemas com testnets e mainnets de blockchain, incluindo Sepolia e Starknet.","ru":"Предоставляет агентам возможность автоматизировать процессы развертывания с использованием sozo migrate, управлять адресами миров и настраивать сетевые параметры для бесперебойного взаимодействия с тестовыми сетями и основными сетями блокчейна, включая Sepolia и Starknet.","ar":"يمنح الوكلاء القدرة على توفير عمليات النشر باستخدام sozo migrate، وإدارة عناوين العالم، وتكوين إعدادات الشبكة للتفاعل السلس مع شبكات الاختبار والشبكات الرئيسية للبلوكشين، بما في ذلك Sepolia وStarknet."},"useCases":{"en":["Deploying Dojo worlds to local Katana sequencer","Automating deployments to Sepolia testnet","Configuring Starknet mainnet deployments","Verifying world deployments"],"zh":["将Dojo世界部署到本地Katana序列器","自动化部署到Sepolia测试网","配置Starknet主网部署","验证世界部署"],"ja":["Dojo世界をローカルのKatanaシーケンサーにデプロイする","Sepoliaテストネットへのデプロイを自動化する","Starknetメインネットのデプロイを構成する","ワールドのデプロイを検証する"],"ko":["Dojo 세계를 로컬 Katana 시퀀서에 배포하기","Sepolia 테스트 네트워크에 대한 배포 자동화","Starknet 메인 네트워크 배포 구성","세계 배포 확인"],"es":["Implementar mundos de Dojo en el secuenciador local de Katana","Automatizar implementaciones en Sepolia testnet","Configurar implementaciones de Starknet mainnet","Verificar implementaciones de mundo"],"fr":["Déployer des mondes de Dojo sur le séquenceur local Katana","Automatiser les déploiements sur Sepolia testnet","Configurer les déploiements de Starknet mainnet","Vérifier les déploiements de monde"],"de":["Dojo-Welten auf dem lokalen Katana-Sequenzer bereitstellen","Bereitstellungen auf Sepolia-Testnet automatisieren","Starknet-Mainnet-Bereitstellungen konfigurieren","Weltbereitstellungen überprüfen"],"pt":["Implantação de mundos Dojo no sequenciador local Katana","Automatização de implantações na testnet Sepolia","Configuração de implantações de mainnet Starknet","Verificação de implantações de mundo"],"ru":["Развертывание миров Dojo в локальном секвенсоре Katana","Автоматизация развертывания в тестовой сети Sepolia","Настройка развертывания основной сети Starknet","Проверка развертывания миров"],"ar":["نشر عوالم Dojo على متسلسل Katana المحلي","توفير عمليات النشر على شبكة اختبار Sepolia","تكوين عمليات نشر شبكة Starknet الرئيسية","تحقق من عمليات النشر العالمية"]},"limitations":{"en":["Requires sozo migrate setup","Limited to Katana, Sepolia testnet, and Starknet mainnet deployments"],"zh":["需要sozo migrate设置","仅限Katana、Sepolia测试网和Starknet主网部署"],"ja":["sozo migrateのセットアップが必要","Katana、Sepoliaテストネット、Starknetメインネットへのデプロイのみ"],"ko":["sozo migrate 설정이 필요","Katana, Sepolia 테스트 네트워크 및 Starknet 메인 네트워크 배포에만 제한"],"es":["Requiere configuración de sozo migrate","Limitado a implementaciones de Katana, Sepolia testnet y Starknet mainnet"],"fr":["Nécessite une configuration de sozo migrate","Limité aux déploiements de Katana, Sepolia testnet et Starknet mainnet"],"de":["Benötigt sozo migrate-Setup","Begrenzt auf Katana-, Sepolia-Testnet- und Starknet-Mainnet-Bereitstellungen"],"pt":["Requer configuração do sozo migrate","Limitado a implantações em Katana, testnet Sepolia e mainnet Starknet"],"ru":["Требуется настройка sozo migrate","Ограничен развертыванием в Katana, тестовой сети Sepolia и основной сети Starknet"],"ar":["يتطلب إعداد sozo migrate","محدود بنشر في Katana وشبكة اختبار Sepolia وشبكة Starknet الرئيسية"]},"version":4},"contentHash":"25220d2ca9734c53ca61183142f5a7554224905da3bd014ca0354f958d3991f3","qualityScore":57}');
