INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dojoengine/book/dojo-deploy', 'dojo-deploy', 'dojoengine', 'book', 'community', 'dojo-deploy dojoengine book community The dojo-deploy skill handles deployment workflows for Dojo worlds, benefiting developers who need to deploy to Katana, Sepolia testnet, or Starknet mainnet. It streamlines the deployment process using sozo migrate and manages world addresses. Dojo Deploy 是一个处理部署工作流的工具，支持 Katana sequencer、Sepolia testnet 和 Starknet mainnet 的部署 Dojo Deploy はデプロイメントワークフローを処理するツールで、Katana sequencer、Sepolia testnet、Starknet mainnet へのデプロイをサポートします Dojo Deploy 는 배포 워크플로우를 처리하는 도구로 Katana sequencer, Sepolia testnet, Starknet mainnet 에 대한 배포를 지원합니다 dojo-deploy es una habilidad que permite desplegar mundos en Katana, Sepolia o Starknet mainnet. Maneja flujos de trabajo de despliegue y configura redes dojo-deploy est une compétence qui permet de déployer des mondes sur Katana, Sepolia ou Starknet mainnet. Elle gère les flux de travail de déploiement et configure les réseaux dojo-deploy ist eine Fähigkeit, die es ermöglicht, Welten auf Katana, Sepolia oder Starknet mainnet bereitzustellen. Sie verwaltet Bereitstellungsworkflows und konfiguriert Netze O Dojo-Deploy é uma ferramenta para implantar mundos no Katana sequencer, Sepolia testnet ou Starknet mainnet Dojo-Deploy - это инструмент для развертывания миров в Katana sequencer, Sepolia testnet или Starknet mainnet Dojo-Deploy هو أداة لنشر العوالم في Katana sequencer أو Sepolia testnet أو Starknet mainnet how to use dojo-deploy dojo-deploy setup guide dojo-deploy alternative dojo-deploy vs Starknet deploy Dojo world to Katana dojo-deploy installation what is dojo-deploy dojo-deploy tutorial dojo-deploy Sepolia testnet deployment Dojo Deploy Katana sequencer Sepolia testnet Starknet mainnet AI 工具 部署工作流 sozo migrate 网络设置 Starts and configures Katana sequencer Deploys worlds using sozo migrate command Verifies deployments and manages world addresses Configures network settings for seamless deployment Supports deployment to Sepolia testnet and Starknet mainnet dojo-deploy is a skill that enables deployment of Dojo worlds to various networks, including local Katana sequencer, Sepolia testnet, and Starknet mainnet.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alirezarezvani/claude-code-tresor/readme-updater', 'community', 'alirezarezvani', 'claude-code-tresor', 'alirezarezvani/claude-code-tresor', 'readme-updater', 0, 0, 57, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:54.869Z', '173a3ffbb6684b7c19e2203915b91c51724abc9aca007f05d2c72f31a16299f7', '{"id":"alirezarezvani/claude-code-tresor/readme-updater","name":"readme-updater","description":{"en":"The readme-updater skill keeps your project''s README file current with changes, including new features, dependencies, and setup instructions. It benefits developers by ensuring their project documentation is always up-to-date.","zh":"README更新器是一种自动化工具，用于保持项目README当前状态，包括新功能、依赖项和设置说明","ja":"READMEアップデーターは、プロジェクトのREADMEを最新の状態に保つために、新機能、依存関係、設定手順などを自動的に更新するツールです","ko":"README 업데이터는 프로젝트 README를 최신 상태로 유지하기 위한 자동화 도구로, 새로운 기능, 의존성 및 설정 지침 등을 포함합니다","es":"readme-updater es una herramienta que mantiene tus archivos README actualizados con cambios de proyecto, incluyendo nuevas características y dependencias","fr":"readme-updater est un outil qui garde vos fichiers README à jour avec les modifications de projet, notamment les nouvelles fonctionnalités et les dépendances","de":"readme-updater ist ein Tool, das Ihre README-Dateien auf dem neuesten Stand hält, einschließlich neuer Funktionen und Abhängigkeiten","pt":"O README Updater é uma ferramenta que atualiza automaticamente o arquivo README com alterações de projeto, incluindo novas funcionalidades e dependências","ru":"README Updater - это инструмент, который автоматически обновляет файл README с изменениями проекта, включая новые функции и зависимости","ar":"README Updater هو أداة تحديث ملف README تلقائيًا مع تحديثات المشروع، بما في ذلك الميزات الجديدة والاعتماديات"},"seo":{"title":{"en":"readme-updater: Automated README Updates for AI Agents | ...","zh":"README 更新器设置指南 - 自动化项目文档","ja":"README アップデーターのベストプラクティス - AIエージェントによるプロジェクト管理","ko":"README 업데이터 설정 가이드 - 프로젝트 문서 자동화 도구","es":"Guía de configuración de readme-updater para desarrolladores","fr":"Meilleures pratiques pour mettre à jour les fichiers READ...","de":"Einrichtungsanleitung für readme-updater: Automatisieren ...","pt":"Guia de Configuração do README Updater: Ferramentas de De...","ru":"Настройка README Updater: ИИ Агенты для Автоматизации Раз...","ar":"دليل إعداد README Updater: أدوات ذكاء اصطناعي لتحسين المنتج"},"description":{"en":"Discover how readme-updater streamlines your development workflow by automatically updating README files. Learn how to install and setup this essential AI ag...","zh":"使用README更新器自动化项目文档，保持项目README当前状态，包括新功能、依赖项和设置说明","ja":"READMEアップデーターを使ってプロジェクトドキュメントを自動化し、プロジェクトのREADMEを最新の状態に保つ","ko":"README 업데이터를 사용하여 프로젝트 문서를 자동화하고 프로젝트 README를 최신 상태로 유지합니다","es":"Mantenga sus archivos README actualizados con cambios de proyecto utilizando readme-updater, una herramienta de desarrollo de código abierto","fr":"Découvrez comment utiliser readme-updater pour garder vos fichiers README à jour avec les modifications de projet, une solution pour les développeurs","de":"Halten Sie Ihre README-Dateien mit readme-updater auf dem neuesten Stand, einer Weltklasse-Sammlung von Claude Code-Utilities für Entwickler","pt":"Mantenha seu README atualizado com alterações de projeto usando o README Updater, uma coleção de utilitários de desenvolvimento inteligentes","ru":"Сохраняйте свой README в актуальном состоянии с помощью README Updater, коллекции умных инструментов разработки","ar":"احتفظ بملف README محدثًا مع تحديثات المشروع باستخدام README Updater، مجموعة من أدوات التطوير الذكية"},"definition":{"en":"readme-updater is a utility that automatically updates README sections, including installation, features, and usage, to reflect project changes and ensure accurate documentation.","zh":"README更新器是一种自动化工具，用于更新项目的README文件","ja":"READMEアップデーターは、プロジェクトのREADMEファイルを自動的に更新するツールです","ko":"README 업데이터는 프로젝트의 README 파일을 자동으로 업데이트하는 도구입니다","es":"readme-updater es una herramienta de desarrollo que actualiza automáticamente los archivos README con cambios de proyecto","fr":"readme-updater est un outil de développement qui met à jour automatiquement les fichiers README avec les modifications de projet","de":"readme-updater ist ein Entwicklungstool, das README-Dateien automatisch mit Projektänderungen aktualisiert","pt":"O que é README Updater? É uma ferramenta de desenvolvimento que atualiza o arquivo README com alterações de projeto","ru":"Что такое README Updater? Это инструмент разработки, который обновляет файл README с изменениями проекта","ar":"ما هو README Updater؟ إنه أداة تطوير تحديث ملف README مع تحديثات المشروع"},"features":{"en":["Updates README installation sections with new dependencies and setup steps","Modifies features sections to reflect new capabilities, functionality changes, and feature deprecation","Automatically updates usage sections to ensure accurate documentation","Tracks project structure changes and updates README accordingly","Monitors configuration files and updates README when modifications are made"],"zh":["自动更新README文件","支持新功能和依赖项的添加","设置说明和环境变量的更新","用户提及README或文档时的自动更新","配置文件的修改"],"ja":["READMEファイルの自動更新","新機能と依存関係の追加のサポート","設定手順と環境変数の更新","ユーザーがREADMEまたはドキュメントに言及したときの自動更新","設定ファイルの変更"],"ko":["README 파일 자동 업데이트","새로운 기능 및 의존성 추가 지원","설정 지침 및 환경 변수 업데이트","사용자가 README 또는 문서에 언급할 때 자동 업데이트","설정 파일의 변경"],"es":["Actualiza secciones de instalación con nuevas dependencias y pasos de configuración","Mantiene la sección de características actualizada con nuevas capacidades y cambios de funcionalidad","Actualiza la sección de uso con instrucciones de configuración y variables de entorno","Soporta la actualización de la estructura del proyecto y la configuración de archivos","Notifica a los usuarios cuando se actualiza la documentación o el archivo README","Actualiza la sección de características con la información de depreciación de funcionalidades"],"fr":["Mise à jour des sections d''installation avec de nouvelles dépendances et étapes de configuration","Maintien de la section des fonctionnalités à jour avec de nouvelles capacités et des modifications de fonctionnalité","Mise à jour de la section d''utilisation avec des instructions de configuration et des variables d''environnement","Prise en charge de la mise à jour de la structure du projet et de la configuration des fichiers","Notification des utilisateurs lors de la mise à jour de la documentation ou du fichier README","Mise à jour de la section des fonctionnalités avec des informations de dépréciation de fonctionnalités"],"de":["Aktualisiert Installationsabschnitte mit neuen Abhängigkeiten und Konfigurationsschritten","Hält den Funktionsabschnitt auf dem neuesten Stand mit neuen Fähigkeiten und Funktionsänderungen","Aktualisiert den Nutzungsabschnitt mit Konfigurationsanweisungen und Umgebungsvariablen","Unterstützt die Aktualisierung der Projektstruktur und der Dateikonfiguration","Benachrichtigt Benutzer, wenn die Dokumentation oder die README-Datei aktualisiert wird","Aktualisiert den Funktionsabschnitt mit Informationen zur Funktionsveraltung"],"pt":["Atualização automática do arquivo README","Inclusão de novas dependências e configurações","Atualização de seções de instalação e uso","Suporte a alterações de estrutura de projeto","Integração com configurações de ambiente"],"ru":["Автоматическое обновление файла README","Добавление новых зависимостей и настроек","Обновление разделов установки и использования","Поддержка изменений структуры проекта","Интеграция с настройками окружения"],"ar":["تحديث تلقائي لملف README","إضافة зависимости جديدة وتكوين","تحديث أقسام التثبيت والاستخدام","دعم تحديثات هيكل المشروع","التكامل مع إعدادات البيئة"]},"keywords":{"en":["how to use readme-updater","readme-updater setup guide","automated README updates","readme-updater alternative","readme-updater vs competing tools","readme-updater install","what is readme-updater","readme-updater for AI agents","README file management"],"zh":["README更新器","自动化项目文档","AI工具","项目管理","README文件更新","依赖项管理","设置说明更新"],"ja":["READMEアップデーター","AIエージェント","プロジェクト管理","READMEファイル更新","依存関係管理","設定手順更新","自動化ツール"],"ko":["README 업데이터","프로젝트 문서 자동화","AI 도구","프로젝트 관리","README 파일 업데이트","의존성 관리","설정 지침 업데이트"],"es":["herramientas de desarrollo de código abierto","actualización de archivos README","automatización de documentación","desarrollo de software","gestión de proyectos","readme-updater","herramientas de desarrollo para programadores","mejores prácticas para desarrolladores","guía de configuración de readme-updater"],"fr":["outils de développement de code ouvert","mise à jour de fichiers README","automatisation de la documentation","développement de logiciels","gestion de projets","readme-updater","outils de développement pour programmeurs","meilleures pratiques pour les développeurs","guide de configuration de readme-updater"],"de":["Entwicklungstools für offenen Code","Aktualisierung von README-Dateien","Automatisierung von Dokumentation","Software-Entwicklung","Projektmanagement","readme-updater","Entwicklungstools für Programmierer","Best Practices für Entwickler","Einrichtungsanleitung für readme-updater"],"pt":["README Updater","ferramentas de desenvolvimento","desenvolvimento inteligente","automatização de tarefas","gerenciamento de projetos","documentação de código","desenvolvedores de software"],"ru":["README Updater","инструменты разработки","умное развитие","автоматизация задач","управление проектами","документация кода","разработчики программного обеспечения","ИИ Агенты"],"ar":["README Updater","أدوات التطوير","التطوير الذكي","آليّة المهام","إدارة المشاريع","توثيق الشفرة","مطوّرو البرمجيات","أدوات ذكاء اصطناعي"]}},"owner":"alirezarezvani","repo":"claude-code-tresor","repoPath":"alirezarezvani/claude-code-tresor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.283Z","topics":[],"category":"community","skillMd":{"name":"readme-updater","description":"Keep README files current with project changes. Use when project structure changes, features added, or setup instructions modified. Suggests README updates based on code changes. Triggers on significant project changes, new features, dependency changes.","bodyPreview":"# README Updater Skill\n\nKeep your README current with project changes.\n\n## When I Activate\n\n- ✅ New features added\n- ✅ Project structure changes\n- ✅ Dependencies added/removed\n- ✅ Setup instructions change\n- ✅ User mentions README or documentation\n- ✅ Configuration files modified\n\n## What I Update\n\n### README Sections\n\n**Installation:**\n- New dependencies\n- Setup steps\n- Prerequisites\n- Environment variables\n\n**Features:**\n- New capabilities\n- Functionality changes\n- Feature deprecation\n\n**Usage","body":"# README Updater Skill\n\nKeep your README current with project changes.\n\n## When I Activate\n\n- ✅ New features added\n- ✅ Project structure changes\n- ✅ Dependencies added/removed\n- ✅ Setup instructions change\n- ✅ User mentions README or documentation\n- ✅ Configuration files modified\n\n## What I Update\n\n### README Sections\n\n**Installation:**\n- New dependencies\n- Setup steps\n- Prerequisites\n- Environment variables\n\n**Features:**\n- New capabilities\n- Functionality changes\n- Feature deprecation\n\n**Usage:**\n- API changes\n- New examples\n- Updated screenshots\n\n**Configuration:**\n- New options\n- Environment variables\n- Config file changes\n\n## Examples\n\n### New Feature Addition\n\n```bash\n# You add authentication:\ngit diff\n# + auth.service.ts\n# + login.component.tsx\n# + JWT middleware\n\n# I suggest README update:\n## Features\n- ✨ User authentication with JWT  # NEW\n- 🔐 Role-based access control    # NEW\n- User management\n- Dashboard\n```\n\n### New Dependency\n\n```bash\n# You add: npm install stripe\n\n# I suggest:\n## Installation\n\n```bash\nnpm install\nnpm install stripe  # Added for payment processing\n```\n\n## Environment Variables\n```bash\nSTRIPE_SECRET_KEY=your_stripe_key  # Required for payments\n```\n```\n\n### Setup Instructions\n\n```bash\n# You modify docker-compose.yml\n\n# I update README:\n## Development Setup\n\n```bash\n# 1. Clone repository\ngit clone [url]\n\n# 2. Install dependencies\nnpm install\n\n# 3. Start services (UPDATED)\ndocker-compose up -d  # Now includes Redis cache\n\n# 4. Run migrations\nnpm run migrate\n```\n```\n\n## Detection Logic\n\n### Change Analysis\n\nI detect these changes automatically:\n- **package.json** → Update dependencies section\n- **New routes** → Update API documentation\n- **.env.example** → Update environment variables\n- **docker-compose.yml** → Update setup instructions\n- **New features** → Update features list\n\n### Section Mapping\n\n```yaml\nCode Change → README Section:\n  - New API endpoint → Usage / API Reference\n  - New dependency → Installation\n  - New env var → Configuration\n  - New feature → Features list\n  - Architecture change → Architecture section\n```\n\n## Intelligent Updates\n\n### Keep Structure\n\nI maintain your README structure:\n- Preserve emoji style\n- Keep formatting consistent\n- Maintain tone and voice\n- Respect existing organization\n\n### Add Missing Sections\n\n```markdown\n# Suggested additions:\n\n## Prerequisites\n- Node.js 18+\n- Docker (for development)\n- PostgreSQL 14+\n\n## Environment Variables\n```bash\nDATABASE_URL=postgresql://localhost/mydb\nAPI_KEY=your_api_key\n```\n\n## Testing\n```bash\nnpm test\n```\n```\n\n### Update Examples\n\n```markdown\n# Before:\n```javascript\nconst result = api.getUsers();\n```\n\n# After (API changed):\n```javascript\nconst result = await api.getUsers({ page: 1, limit: 10 });\n```\n```\n\n## Version Compatibility\n\nI track version-specific documentation:\n\n```markdown\n## Requirements\n\n- Node.js 18+ (updated from 16+)\n- TypeScript 5.0+ (new requirement)\n- React 18+ (unchanged)\n```\n\n## Changelog Integration\n\nI can sync with CHANGELOG.md:\n\n```markdown\n## Recent Changes\n\nSee [CHANGELOG.md](CHANGELOG.md) for detailed version history.\n\n### Latest (v2.1.0)\n- ✨ Added user authentication\n- 🔧 Fixed memory leak in data processing\n- 📝 Updated API documentation\n```\n\n## Screenshot Management\n\n```markdown\n# I suggest when UI changes:\n## Screenshots\n\n![Dashboard](screenshots/dashboard.png)\n*Updated: 2025-10-24 - New authentication panel*\n\n![User Profile](screenshots/profile.png)\n*New feature - user profile management*\n```\n\n## Relationship with @docs-writer\n\n**Me (Skill):** Keep README current with code changes\n**@docs-writer (Sub-Agent):** Comprehensive documentation strategy\n\n### Workflow\n1. I detect changes\n2. I suggest README updates\n3. For full docs → Invoke **@docs-writer** sub-agent\n4. Sub-agent creates complete documentation\n\n## Sandboxing Compatibility\n\n**Works without sandboxing:** ✅ Yes\n**Works with sandboxing:** ✅ Yes\n\n- **Filesystem**: Writes to README.md\n- **Network**: None required\n- **Configuration**: None required\n\n## Best Practices\n\n1. **Keep it current** - Update README with every feature\n2. **Be specific** - Include version numbers, prerequisites\n3. **Add examples** - Show actual usage, not just API\n4. **Include troubleshooting** - Common issues and solutions\n5. **Badge status** - Keep build/coverage badges current\n\n## README Templates\n\n### Basic Structure\n\n```markdown\n# Project Name\n\nBrief description\n\n## Features\n- Feature 1\n- Feature 2\n\n## Installation\n```bash\nnpm install\n```\n\n## Usage\n```javascript\n// Example\n```\n\n## Configuration\nEnvironment variables needed\n\n## Contributing\nHow to contribute\n\n## License\nMIT\n```\n\n### Comprehensive Structure\n\n```markdown\n# Project Name\n> Tagline\n\n[Badges]\n\n## Table of Contents\n- Features\n- Installation\n- Usage\n- API Reference\n- Configuration\n- Development\n- Testing\n- Deployment\n- Contributing\n- License\n\n[Sections with detailed content]\n```\n\n## Integration\n\n### With /docs-gen Command\n\n```bash\n/docs-gen --format markdown\n\n# Generates:\n# 1. README.md (via me)\n# 2. Full documentation site (via @docs-writer)\n# 3. API reference (via api-documenter)\n```\n\n### With CI/CD\n\n```yaml\n# .github/workflows/docs.yml\n- name: Update README\n  run: |\n    # Skill suggests updates based on changes\n    # Review and commit\n```\n\n## Customization\n\nAdd company-specific README standards:\n\n```bash\ncp -r ~/.claude/skills/documentation/readme-updater \\\n      ~/.claude/skills/documentation/company-readme-updater\n\n# Edit to add:\n# - Company README template\n# - Required sections\n# - Badge standards\n```\n\n## Related Tools\n\n- **api-documenter skill**: API documentation\n- **@docs-writer sub-agent**: Comprehensive docs\n- **git-commit-helper skill**: Commit messages for updates\n- **/docs-gen command**: Full documentation generation\n"},"lastSynced":"2026-03-08T02:00:54.869Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents needing automated documentation updates for project README files","zh":"适用于需要自动更新项目 README 文件文档的开发者代理","ja":"プロジェクトのREADMEファイルの自動ドキュメント更新が必要なデベロッパーエージェントに適しています","ko":"프로젝트 README 파일의 자동 문서 업데이트가 필요한 개발자 에이전트에게 적합합니다","es":"Ideal para Agentes de Desarrollador que necesitan actualizaciones de documentación automatizadas para archivos README de proyectos","fr":"Idéal pour les agents de développement nécessitant des mises à jour de documentation automatiques pour les fichiers README de projet","de":"Ideal für Entwickleragenten, die automatisierte Dokumentenaktualisierungen für Projekt-README-Dateien benötigen","pt":"Ideal para Agentes de Desenvolvedores que precisam de atualizações de documentação automatizadas para arquivos README de projetos","ru":"Идеально для агентов разработчиков, которым необходимы автоматические обновления документации для файлов README проектов","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى تحديثات وثائقية آلية لملفات README للمشاريع"},"recommendation":{"en":"Empowers agents to maintain up-to-date project documentation by automatically updating README sections such as Installation, Features, and Usage, ensuring consistency with project changes, including new dependencies, setup instructions, and feature deprecations","zh":"赋予代理维护项目文档的能力，通过自动更新README文件的安装、功能和使用等部分，使其与项目更改保持一致，包括新的依赖项、设置说明和功能废弃","ja":"エージェントにプロジェクト文書を最新の状態に保つ能力を与え、READMEファイルのインストール、機能、使用などのセクションを自動的に更新し、プロジェクトの変更、包括して新しい依存関係、セットアップ手順、機能廃止などと一致させる","ko":"에이전트가 프로젝트 문서를 최신 상태로 유지할 수 있도록 하며, README 파일의 설치, 기능, 사용 등 섹션을 자동으로 업데이트하여 프로젝트 변경 사항과 일치시키며, 새로운 의존성, 설정 지침, 기능 폐지 등도 포함합니다","es":"Habilita a los agentes a mantener la documentación del proyecto actualizada mediante la actualización automática de secciones de README como Instalación, Características y Uso, garantizando la coherencia con los cambios del proyecto, incluidas nuevas dependencias, instrucciones de configuración y deprecaciones de características","fr":"Permet aux agents de maintenir une documentation de projet à jour en mettant à jour automatiquement les sections de README telles que Installation, Fonctionnalités et Utilisation, en garantissant la cohérence avec les modifications du projet, y compris les nouvelles dépendances, les instructions de configuration et les dépréciations de fonctionnalités","de":"Ermächtigt die Agenten, die Projekt-Dokumentation auf dem neuesten Stand zu halten, indem sie Abschnitte wie Installation, Funktionen und Verwendung in der README-Datei automatisch aktualisieren, um die Konsistenz mit Projektänderungen sicherzustellen, einschließlich neuer Abhängigkeiten, Einrichtungsanweisungen und Funktionsveraltungen","pt":"Habilita os agentes a manter a documentação do projeto atualizada, atualizando automaticamente seções do README, como Instalação, Recursos e Uso, garantindo a consistência com as alterações do projeto, incluindo novas dependências, instruções de configuração e depreciações de recursos","ru":"Наделяет агентов возможностью поддерживать актуальную документацию проекта, автоматически обновляя разделы файла README, такие как Установка, Возможности и Использование, обеспечивая согласованность с изменениями проекта, включая новые зависимости, инструкции по настройке и устаревшие функции","ar":"يمنح الوكلاء القدرة على الحفاظ على توثيق المشروع محدثًا، من خلال تحديث أقسام ملف README تلقائيًا، مثل التثبيت والميزات والاستخدام، وضمان الاتساق مع تغييرات المشروع، بما في ذلك الإعتماديات الجديدة وإرشادات الإعداد وإلغاء الميزات"},"useCases":{"en":["Automating README updates after adding new dependencies","Generating documentation for new project features","Updating setup instructions in response to project structure changes"],"zh":["在添加新依赖项后自动更新 README","为新项目功能生成文档","响应项目结构更改时更新设置说明"],"ja":["新しい依存関係を追加した後、READMEを自動的に更新する","新しいプロジェクト機能のドキュメントを生成する","プロジェクト構造の変更に応じてセットアップ手順を更新する"],"ko":["새로운 의존성을 추가한 후 README를 자동으로 업데이트합니다","새 프로젝트 기능에 대한 문서를 생성합니다","프로젝트 구조 변경에 따라 설정 지침을 업데이트합니다"],"es":["Automatizar las actualizaciones de README después de agregar nuevas dependencias","Generar documentación para nuevas características del proyecto","Actualizar las instrucciones de configuración en respuesta a cambios en la estructura del proyecto"],"fr":["Automatiser les mises à jour de README après avoir ajouté de nouvelles dépendances","Générer la documentation pour les nouvelles fonctionnalités du projet","Mettre à jour les instructions de configuration en réponse aux modifications de la structure du projet"],"de":["Automatisieren von README-Aktualisierungen nach dem Hinzufügen neuer Abhängigkeiten","Generieren von Dokumentationen für neue Projektfunktionen","Aktualisieren der Einrichtungsanweisungen als Reaktion auf Änderungen der Projektstruktur"],"pt":["Automatizar atualizações do README após adicionar novas dependências","Gerar documentação para recursos de projeto novos","Atualizar instruções de configuração em resposta a alterações na estrutura do projeto"],"ru":["Автоматизировать обновления файла README после добавления новых зависимостей","Генерировать документацию для новых функций проекта","Обновлять инструкции по настройке в ответ на изменения структуры проекта"],"ar":["تحديث ملف README تلقائيًا بعد إضافة اعتماديات جديدة","توليد توثيق لميزات مشروع جديدة","تحديث إرشادات الإعداد استجابة لتغييرات في هيكل المشروع"]},"limitations":{"en":["Requires access to project repository and README file","Limited to updating specific sections of the README file","May require manual review for complex project changes"],"zh":["需要访问项目仓库和 README 文件","仅限更新 README 文件的特定部分","可能需要手动审查复杂的项目更改"],"ja":["プロジェクトリポジトリとREADMEファイルへのアクセスが必要","READMEファイルの特定のセクションのみを更新可能","複雑なプロジェクト変更の場合、手動レビューが必要になる可能性がある"],"ko":["프로젝트 저장소와 README 파일에 액세스해야 합니다","README 파일의 특정 섹션만 업데이트할 수 있습니다","복잡한 프로젝트 변경의 경우 수동 검토가 필요할 수 있습니다"],"es":["Requiere acceso al repositorio del proyecto y al archivo README","Limitado a la actualización de secciones específicas del archivo README","Puede requerir una revisión manual para cambios complejos del proyecto"],"fr":["Nécessite un accès au référentiel de projet et au fichier README","Limité à la mise à jour de sections spécifiques du fichier README","Peut nécessiter une révision manuelle pour des modifications complexes du projet"],"de":["Erfordert Zugriff auf das Projekt-Repository und die README-Datei","Begrenzt auf die Aktualisierung bestimmter Abschnitte der README-Datei","Kann eine manuelle Überprüfung für komplexe Projektänderungen erfordern"],"pt":["Exige acesso ao repositório do projeto e ao arquivo README","Limitado à atualização de seções específicas do arquivo README","Pode exigir revisão manual para alterações complexas do projeto"],"ru":["Требует доступа к репозиторию проекта и файлу README","Ограничен обновлением конкретных разделов файла README","Может потребовать ручного рассмотрения для сложных изменений проекта"],"ar":["يتطلب الوصول إلى مستودع المشروع وملف README","محدود بالتحديثات الخاصة بأقسام معينة من ملف README","يمكن أن يتطلب مراجعة يدوية لتغييرات معقدة في المشروع"]},"version":4},"contentHash":"173a3ffbb6684b7c19e2203915b91c51724abc9aca007f05d2c72f31a16299f7","qualityScore":57}');
