INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iamzhihuix/happy-claude-skills/docx-format-replicator', 'docx-format-replicator', 'iamzhihuix', 'happy-claude-skills', 'community', 'docx-format-replicator iamzhihuix happy-claude-skills community The docx-format-replicator skill enables developers to extract formatting from existing Word documents and generate new documents with identical formatting. This benefits developers who need to maintain consistent formatting across multiple documents. DOCX格式复制器是一个强大的工具，能够从现有Word文档中提取格式信息，并创建具有相同格式但不同内容的新文档 DOCX Format Replicatorは、既存のWord文書からフォーマット情報を抽出し、同等のフォーマットを持つ新しい文書を生成する強力なツールです DOCX 형식 복제기는 기존 워드 문서에서 형식 정보를 추출하고 동일한 형식但 다른 내용의 새로운 문서를 생성하는 강력한 도구입니다 La habilidad de replicar formatos DOCX permite extraer información de formato de documentos Word existentes y generar nuevos documentos con formato idéntico pero contenido diferente La compétence de réplication de formats DOCX permet d''extraire les informations de format à partir de documents Word existants et de générer de nouveaux documents avec un format identique mais un contenu différent Die Fähigkeit zum Replicieren von DOCX-Formaten ermöglicht das Extrahieren von Formatinformationen aus bestehenden Word-Dokumenten und das Erstellen neuer Dokumente mit identischem Format aber unterschiedlichem Inhalt O replicador de formato DOCX é uma habilidade que extrai informações de formatação de documentos Word existentes e gera novos documentos com formatação idêntica Репликатор формата DOCX — это навык, который извлекает информацию о форматировании из существующих документов Word и генерирует новые документы с идентичным форматированием مكرر تنسيق DOCX هو مهارة تقوم باستخراج معلومات التنسيق من المستندات Word الحالية وتوليد مستندات جديدة بنفس التنسيق how to use docx-format-replicator docx-format-replicator alternative docx-format-replicator setup guide what is docx-format-replicator docx-format-replicator vs template generators docx-format-replicator install for AI agents DOCX格式复制器 AI工具 Word文档格式 文档模板 格式一致性 文档结构复制 AIエージェント 文档处理 Extracts formatting information from existing Word documents (.docx) Generates new documents with identical formatting but different content Enables creating document templates with consistent formatting Replicates complex Word document structures Maintains consistent formatting across multiple documents docx-format-replicator is a skill that extracts formatting information from existing Word documents (.docx) to generate new documents with identical formatting but different content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stacklok/toolhive/split-pr', 'community', 'stacklok', 'toolhive', 'stacklok/toolhive', 'split-pr', 0, 0, 57, '2026-03-08T01:57:15.291Z', '2026-03-08T02:01:02.605Z', '2dea7c48dbba05891c4b1e544b55515afd407a7b2b49d39265fbcc1ec1314111', '{"id":"stacklok/toolhive/split-pr","name":"split-pr","description":{"en":"split-pr helps developers break down large changesets into logical, reviewable pull requests. It analyzes the current diff and proposes a splitting strategy.","zh":"Split-PR工具帮助开发者将大型更改集分解为逻辑、可审查的拉取请求，提高代码审查效率","ja":"Split-PRツールは、開発者が大きな変更セットを論理的かつレビュー可能なプルリクエストに分割するのに役立ちます","ko":"Split-PR 도구는 개발자가 대형 변경 세트를 논리적이고 검토 가능한 풀 요청으로 분할하는 것을 도와줍니다","es":"Split-pr es una herramienta que ayuda a los desarrolladores a dividir grandes conjuntos de cambios en solicitudes de extracción lógicas y revisables","fr":"Split-pr est un outil qui aide les développeurs à diviser de grands ensembles de modifications en demandes d''extraction logiques et révisables","de":"Split-pr ist ein Tool, das Entwicklern hilft, große Änderungssätze in logische und überprüfbare Pull-Requests aufzuteilen","pt":"O split-pr é uma ferramenta que ajuda a dividir alterações em pedidos de revisão menores e mais gerenciáveis, melhorando a colaboração e a qualidade do código","ru":"Split-pr - это инструмент, который помогает разделить изменения на меньшие запросы на проверку, повышая сотрудничество и качество кода","ar":"Split-PR هو أداة تساعد في تقسيم التغييرات إلى طلبات مراجعة أصغر وأكثر إدارة، مع تحسين التعاون وجودة الكود"},"seo":{"title":{"en":"split-pr: Git Workflow Optimization for AI Agents | AI Ag...","zh":"Split-PR 分支合并工具指南","ja":"Split-PRブランチマージツールのベストプラクティス","ko":"Split-PR 분기 병합 도구 설정 가이드","es":"Guía de configuración para split-pr: Divide cambios en so...","fr":"Guide de configuration pour split-pr : Diviser les modifi...","de":"Konfigu