INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stacklok/toolhive/split-pr', 'split-pr', 'stacklok', 'toolhive', 'community', 'split-pr stacklok toolhive community split-pr helps developers break down large changesets into logical, reviewable pull requests. It analyzes the current diff and proposes a splitting strategy. Split-PR工具帮助开发者将大型更改集分解为逻辑、可审查的拉取请求，提高代码审查效率 Split-PRツールは、開発者が大きな変更セットを論理的かつレビュー可能なプルリクエストに分割するのに役立ちます Split-PR 도구는 개발자가 대형 변경 세트를 논리적이고 검토 가능한 풀 요청으로 분할하는 것을 도와줍니다 Split-pr es una herramienta que ayuda a los desarrolladores a dividir grandes conjuntos de cambios en solicitudes de extracción lógicas y revisables Split-pr est un outil qui aide les développeurs à diviser de grands ensembles de modifications en demandes d''extraction logiques et révisables Split-pr ist ein Tool, das Entwicklern hilft, große Änderungssätze in logische und überprüfbare Pull-Requests aufzuteilen O split-pr é uma ferramenta que ajuda a dividir alterações em pedidos de revisão menores e mais gerenciáveis, melhorando a colaboração e a qualidade do código Split-pr - это инструмент, который помогает разделить изменения на меньшие запросы на проверку, повышая сотрудничество и качество кода Split-PR هو أداة تساعد في تقسيم التغييرات إلى طلبات مراجعة أصغر وأكثر إدارة، مع تحسين التعاون وجودة الكود how to use split-pr what is split-pr split-pr alternative split-pr vs GitFlow split-pr install split-pr setup guide Git workflow optimization reviewable pull requests large changeset management Split-PR工具 AI工具 代码审查 Git diff 拉取请求 代码合并 开发工具 版本控制 Analyzes current Git diffs using `git diff main...HEAD --stat` Lists all changed files with `git diff main...HEAD --name-only` Shows commit history for context Proposes a splitting strategy for reviewable pull requests Helps keep changes atomic and reviewable Integrates with Git workflow for easy deployment split-pr is a tool that analyzes Git diffs and proposes a strategy to split large changes into smaller, reviewable changesets');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mckinsey/agents-at-scale-ark/ark-documentation', 'community', 'mckinsey', 'agents-at-scale-ark', 'mckinsey/agents-at-scale-ark', 'ark-documentation', 0, 0, 57, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.268Z', '5a2c976292466c897e033207e079345c86466ea624cb378bf0029f594d712fab', '{"id":"mckinsey/agents-at-scale-ark/ark-documentation","name":"ark-documentation","description":{"en":"The ark-documentation skill provides guidance for structuring documentation using Diataxis, helping developers create, review, and restructure content for agentic resources.","zh":"Ark 文档提供了 provider-agnostic 操作和资源的结构化指南，使用 Diataxis 适配 Ark 的需求","ja":"Ark ドキュメントはプロバイダー非依存の操作とリソースの構造化ガイドを提供し、Diataxis を使用して Ark のニーズに合わせた文書化を行う","ko":"Ark 문서는 provider-agnostic操作과 리소스의 구조화된 가이드를 제공하며 Diataxis를 사용하여 Ark의需求에 맞는 문서화를 수행","es":"Ark-documentation proporciona operaciones agnósticas de proveedor para recursos agenticos, utilizando Diataxis para estructurar documentación","fr":"Ark-documentation offre des opérations agnostiques de fournisseur pour les ressources agenticas, en utilisant Diataxis pour structurer la documentation","de":"Ark-documentation bietet anbieterunabhängige Operationen für agentic-Ressourcen, mit Diataxis für die Strukturierung von Dokumentationen","pt":"O Ark-Documentation é um recurso para operações de agente, que codifica padrões e práticas de desenvolvimento de aplicações","ru":"ARK Документация - это провайдер-агностические операции для агентских ресурсов, кодифицирующие закономерности и методы разработки агентских приложений","ar":"وثائق Ark هي عمليات وثائقية لمنصات الإيمان الإلكتروني، التي توحد أنماط وممارسات تطوير التطبيقات الإلكترونية"},"seo":{"title":{"en":"ark-documentation: Structuring Guidance for AI Agents | A...","zh":"Ark 文档最佳实践指南 - AIエージェント文档结构","ja":"Ark ドキュメント設定ガイド - AIエージェントの文書化","ko":"Ark 문서 구조 가이드 - AI 에이전트 개발자를 위한 문서화","es":"Guía de configuración de ark-documentation para agentes d...","fr":"Guide de mise en place d''ark-documentation pour les outil...","de":"Einrichtungsleitfaden für ark-documentation und künstlich...","pt":"Guia de Configuração do Ark-Documentation para Desenvolve...","ru":"Настройка ARK Документации: Руководство для разработчиков...","ar":"دليل إعداد وثائق Ark-Documentation لمنصة الإيمان الإلكتروني"},"description":{"en":"Discover how to effectively structure your documentation with ark-documentation. Learn how to create, review, and restructure content using Diataxis framework","zh":"学习 Ark 文档的最佳实践和结构指南，了解如何使用 Diataxis 适配 Ark 的需求","ja":"Ark ドキュメントの構造と best practice を学ぶ、Diataxis を使用して Ark のニーズに合わせた文書化を行う","ko":"Ark 문서 구조와最佳实践을 익히고 Diataxis를 사용하여 Ark의需求에 맞는 문서화를 수행하는 방법","es":"Aprende a estructurar documentación con ark-documentation y Diataxis para proyectos de aplicaciones agenticas","fr":"Découvrez comment structurer votre documentation avec ark-documentation et Diataxis pour les projets d''applications agenticas","de":"Erfahren Sie, wie Sie mit ark-documentation und Diataxis Dokumentationen für agentic-Anwendungsprojekte strukturieren","pt":"Aprenda a estruturar documentação do Ark com Diataxis e melhore a produtividade dos desenvolvedores","ru":"Откройте для себя, как использовать Diataxis для создания документации ARK и повысьте эффективность разработки ИИ Агентов","ar":"اكتشف كيفية تنظيم وثائق Ark باستخدام Diataxis وتحسين إنتاجية المطورين"},"definition":{"en":"ark-documentation is a provider-agnostic operations framework for structuring documentation, codifying patterns and practices for agentic application projects","zh":"Ark 文档是 provider-agnostic 操作和资源的结构化指南，使用 Diataxis 适配 Ark 的需求","ja":"Ark ドキュメントはプロバイダー非依存の操作とリソースの構造化ガイドを提供するもの","ko":"Ark 문서는 provider-agnostic操作과 리소스의 구조화된 가이드","es":"Ark-documentation es un conjunto de patrones y prácticas para la documentación de proyectos de aplicaciones agenticas","fr":"Ark-documentation est un ensemble de modèles et de pratiques pour la documentation des projets d''applications agenticas","de":"Ark-documentation ist eine Sammlung von Mustern und Praktiken für die Dokumentation von agentic-Anwendungsprojekten","pt":"O que é Ark-Documentation? É um recurso de documentação para operações de agente","ru":"Что такое ARK Документация? Это провайдер-агностические операции для агентских ресурсов","ar":"ما هي وثائق Ark؟ هي عمليات وثائقية لمنصات الإيمان الإلكتروني"},"features":{"en":["Uses Diataxis framework for structuring documentation","Supports linear learning paths through Tutorials","Provides task-oriented guides with How-to Guides","Offers understanding of core concepts and their implementation","Enables effective content review and restructuring"],"zh":["使用 Diataxis 适配 Ark 的需求","提供 provider-agnostic 操作","结构化的文档指南","支持创建新文档","支持文档 PR 审查","支持现有文档重构"],"ja":["Diataxis を使用して Ark のニーズに合わせた文書化","プロバイダー非依存の操作を提供","構造化された文書ガイド","新しい文書の作成をサポート","文書 PR のレビューをサポート","既存の文書のリファクタリングをサポート"],"ko":["Diataxis를 사용하여 Ark의需求에 맞는 문서화","provider-agnostic操作을 제공","구조화된 문서 가이드","새 문서의 생성을 지원","문서 PR의 리뷰를 지원","既存의 문서의 리팩토링을 지원"],"es":["Estructura de documentación Diataxis","Rutas de aprendizaje lineales con tutoriales","Guías de tareas orientadas a personas","Conceptos básicos para entender el porqué y el cómo","Reestructuración de documentación existente"],"fr":["Structure de documentation Diataxis","Parcours d''apprentissage linéaires avec tutoriels","Guides de tâches orientées vers les personnes","Concepts de base pour comprendre le pourquoi et le comment","Réorganisation de la documentation existante"],"de":["Diataxis-Dokumentenstruktur","Lineare Lernpfade mit Tutorien","Aufgabenorientierte Anleitungen für Personen","Grundkonzepte zum Verständnis von Warum und Wie","Umstrukturierung bestehender Dokumentationen"],"pt":["Estrutura de documentação Diataxis","Caminhos de aprendizado lineares com Tutorials","Guias de tarefas orientadas por persona com How-to Guides","Conceitos centrais para compreender o ''porquê'' e o ''como''","Reestruturação de documentação existente"],"ru":["Структура документации Diataxis","Линейные пути обучения с помощью Tutorials","Задачи, ориентированные на персону, с помощью How-to Guides","Центральные понятия для понимания ''почему'' и ''как''","Переструктуризация существующей документации"],"ar":["هيكل وثائق Diataxis","مسارات تعلم خطية مع التutorials","دليل المهام الموجهة بالشخصية مع How-to Guides","مفاهيم مركزية لفهم ''لماذا'' و ''كيف''","إعادة هيكلة الوثائق الحالية"]},"keywords":{"en":["how to use ark-documentation","what is ark-documentation","ark-documentation setup guide","ark-documentation alternative","Diataxis framework for documentation","agentic resource documentation","ark-documentation install","structuring documentation with ark-documentation"],"zh":["Ark 文档","AIエージェント文档结构","Diataxis","provider-agnostic","文档最佳实践","文档结构指南","Ark 开发者"],"ja":["Ark ドキュメント","AIエージェントの文書化","Diataxis","プロバイダー非依存","文書の best practice","文書構造ガイド","Ark 開発者"],"ko":["Ark 문서","AI 에이전트 문서 구조","Diataxis","provider-agnostic","문서 최고의實踐","문서 구조 가이드","Ark 개발자"],"es":["ark-documentation","documentación de aplicaciones agenticas","Diataxis","estructura de documentación","tutoriales","guías de tareas","conceptos básicos","reestructuración de documentación","herramientas de inteligencia artificial"],"fr":["ark-documentation","documentation d''applications agenticas","Diataxis","structure de documentation","tutoriels","guides de tâches","concepts de base","réorganisation de documentation","outils d''intelligence artificielle"],"de":["ark-documentation","Dokumentation von agentic-Anwendungen","Diataxis","Dokumentenstruktur","Tutorien","Aufgabenorientierte Anleitungen","Grundkonzepte","Umstrukturierung von Dokumentationen","künstliche Intelligenz-Tools"],"pt":["ark-documentation","diataxis","documentação de agente","desenvolvimento de aplicações","tutorials","how-to guides","conceitos centrais","reestruturação de documentação"],"ru":["ark-документация","diataxis","документация агента","разработка приложений","tutorials","how-to guides","центральные понятия","переструктуризация документации","ИИ Агенты"],"ar":["وثائق ark","diataxis","وثائق الإيمان الإلكتروني","تطوير التطبيقات","تutorials","دليل المهام","مفاهيم مركزية","إعادة هيكلة الوثائق","منصات الإيمان الإلكتروني"]}},"owner":"mckinsey","repo":"agents-at-scale-ark","repoPath":"mckinsey/agents-at-scale-ark","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"ark-documentation","description":"Guidance for structuring Ark documentation using the Diataxis framework. Use this skill when creating new docs, deciding where content belongs, reviewing documentation PRs, or restructuring existing documentation.","bodyPreview":"# Ark Documentation\n\nGuidance for structuring Ark documentation using Diataxis adapted for Ark''s needs.\n\n## When to use this skill\n\n- Creating new documentation\n- Deciding where content belongs\n- Reviewing documentation PRs\n- Restructuring existing documentation\n\n## ARK''s Diataxis structure\n\n```\ndocs/content/\n├── Introduction\n├── Quickstart\n├── Tutorials          → Linear learning paths\n├── How-to Guides      → Task-oriented, by persona\n├── Core Concepts      → Understanding \"why\" and \"how\"\n├──","body":"# Ark Documentation\n\nGuidance for structuring Ark documentation using Diataxis adapted for Ark''s needs.\n\n## When to use this skill\n\n- Creating new documentation\n- Deciding where content belongs\n- Reviewing documentation PRs\n- Restructuring existing documentation\n\n## ARK''s Diataxis structure\n\n```\ndocs/content/\n├── Introduction\n├── Quickstart\n├── Tutorials          → Linear learning paths\n├── How-to Guides      → Task-oriented, by persona\n├── Core Concepts      → Understanding \"why\" and \"how\"\n├── Reference          → Factual lookup material\n├── Marketplace        → External link\n└── Disclaimer\n```\n\n### Terminology\n\n| Diataxis | Ark Term | Why |\n|----------|----------|-----|\n| Explanation | **Core Concepts** | More accessible |\n\n## The four quadrants\n\n### 1. Tutorials (learning-oriented)\n\n**Purpose**: Hands-on lessons for newcomers.\n\n**Characteristics**:\n- Linear, numbered paths (1, 2, 3...)\n- Single prescribed path - no choices\n- Frequent visible results\n- Ends with \"Next step\" → How-to Guides\n\n**Writing style**:\n- Use \"we\" language\n- Don''t explain - link to Core Concepts\n\n**Content belongs here if**:\n- It teaches a skill through doing\n- Reader is studying, not working\n- Success requires following steps in order\n\n**Examples**: Quickstart, Running the Dashboard, Starting a New Project, Complete Worked Example\n\n---\n\n### 2. How-to guides (task-oriented)\n\n**Purpose**: Help competent users complete specific tasks.\n\n**Organized by persona**:\n\n#### Build with ARK (application developers)\n- Configure models, create agents, coordinate teams, run queries, add tools.\n\n#### Extend ARK (contributors)\n- Build services locally, implement APIs, build A2A servers, add tests.\n\n#### Operate ARK (operators / SRE / security)\n- **Platform operations**: Provisioning, deploying\n- **CI/CD and supply chain**: Build pipelines\n- **Security & assurance**: Pen testing, code analysis\n\n**Writing style**:\n- Goal-oriented: \"If you want X, do Y\"\n- Assumes competence\n- Don''t teach - link to Tutorials or Core Concepts\n\n**Content belongs here if**:\n- Reader has a specific task to complete\n- Reader is working, not studying\n\n---\n\n### 3. Core concepts (understanding-oriented)\n\n**Purpose**: Explain what ARK is, how it''s designed, and why.\n\n**Topics**:\n- What ARK is and how it works.\n- Design effective agentic systems.\n- Platform architecture concepts.\n- Extensibility concepts.\n- Security and identity concepts.\n\n**Writing style**:\n- Discursive: \"The reason for X is...\"\n- Make connections between concepts\n- Provide design decision context\n\n**Content belongs here if**:\n- It answers \"why\" or \"how does this work\"\n- Reader is deciding how to design/extend/operate\n- Content provides context, not procedures\n\n---\n\n### 4. Reference (information-oriented)\n\n**Purpose**: Factual lookup material.\n\n**Organized by type**:\n- **Interfaces**: ARK APIs.\n- **Kubernetes API**: CRDs, resources.\n- **Evaluations**: Guides, event-based evaluations.\n- **System behavior**: Query execution, relationships.\n- **Operations**: Upgrading, troubleshooting.\n- **Project**: Contributors.\n\n**Writing style**:\n- Austere, factual, neutral\n- Structure mirrors product\n- No instruction, explanation, or opinion\n\n**Content belongs here if**:\n- It describes what something IS\n- Reader needs to look up specific details\n- Content is consulted, not read cover-to-cover\n\n---\n\n## Decision guide\n\n```\nIs the reader LEARNING or WORKING?\n│\n├─ LEARNING (studying)\n│   ├─ Hands-on, step-by-step? → TUTORIALS\n│   └─ Understanding concepts? → CORE CONCEPTS\n│\n└─ WORKING (applying)\n    ├─ Completing a task? → HOW-TO GUIDES\n    └─ Looking up facts? → REFERENCE\n```\n\n## Hub pages\n\nHub pages link to content without moving files:\n\n- `tutorials.mdx` - Lists tutorials in order.\n- `how-to-guides.mdx` - Groups by persona.\n- `core-concepts.mdx` - Groups by topic.\n- `reference/index.mdx` - Groups by type.\n\nHub pages should:\n- Explain purpose in one sentence.\n- Group links logically.\n- Not duplicate content.\n\n## Personas\n\n| Persona | Sections |\n|---------|----------|\n| End users | Quickstart, Tutorials |\n| Agent builders | Tutorials, How-to (Build) |\n| Platform engineers | How-to (Operate), Reference |\n| Contributors | How-to (Extend), Core Concepts |\n\n## Writing guidelines\n\n### Lexicon\n- The product is known as ARK rather than Ark.\n\n\n### General style\n- Be concise and direct.\n- Use simple language.\n- Keep descriptions to 1-2 sentences.\n- Use active voice: \"Creates agent\" not \"Agent is created\".\n- Write \"ARK\" not \"Ark\".\n- Use US English.\n- Use Oxford commas in lists.\n\n### Bullets\n- Capitalize the first word and end with a period.\n- Use numbered lists only for sequences of instructions or when referencing items later.\n\n### Capitalization\n- Capitalize only proper nouns (product names, tools, services).\n- Use sentence case for titles: \"An introduction to data visualization\" not \"An Introduction to Data Visualization\".\n- Don''t capitalize: cloud, internet, machine learning, advanced analytics.\n\n### Headings\n- Avoid gerunds: \"Get started\" not \"Getting started,\" \"Customize a layout\" not \"Customizing a layout\".\n- Keep titles short and descriptive for search discoverability.\n\n### Instructions\n- Use imperatives: \"Complete the configuration steps\".\n- Don''t use \"please\".\n- Don''t use passive tense: \"Complete the steps\" not \"The steps should be completed\".\n\n### Links\n- Make hyperlinks descriptive: `Learn how to [contribute to ARK](url)`.\n- Don''t write: `To contribute, see [here](url)`.\n\n### Avoid\n- Gerunds in headings.\n- Colloquialisms (may not translate across regions/languages).\n- Business speak: \"leverage\", \"utilize\", \"facilitate\".\n\n### What not to mix\n\n| Don''t put in... | This content... |\n|-----------------|-----------------|\n| Tutorials | Explanations, choices. |\n| How-to guides | Teaching, complete reference. |\n| Core concepts | Instructions, reference. |\n| Reference | Instructions, explanations. |\n\n## References\n\n- [Diataxis Framework](https://diataxis.fr/)\n- [Issue #338](https://github.com/mckinsey/agents-at-scale-ark/issues/338)\n- [PR #620](https://github.com/mckinsey/agents-at-scale-ark/pull/620)\n"},"lastSynced":"2026-03-08T02:01:03.268Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing structured documentation guidance using Diataxis framework.","zh":"非常适合需要利用Diataxis框架进行结构化文档指导的Developer Agents。","ja":"Diataxisフレームワークを使用した構造化されたドキュメントガイダンスを必要とするDeveloper Agentsに最適です。","ko":"Diataxis 프레임워크를 사용하여 구조화된 문서 가이드가 필요한 Developer Agents에 완벽합니다.","es":"Perfecto para agentes de desarrollo que necesitan orientación estructurada para documentación utilizando el framework Diataxis.","fr":"Parfait pour les agents développeurs ayant besoin d''un guidage structuré pour la documentation en utilisant le framework Diataxis.","de":"Perfekt für Entwickler-Agents, die eine strukturierte Dokumentationsanleitung unter Verwendung des Diataxis-Frameworks benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de orientação estruturada para documentação utilizando o framework Diataxis.","ru":"Идеально подходит для Агентов-разработчиков, которым требуется структурированное руководство по документации с использованием фреймворка Diataxis.","ar":"مثالي لوكلاء المطورين الذين يحتاجون إلى توجيه منظم للتوثيق باستخدام إطار عمل Diataxis."},"recommendation":{"en":"Empowers agents to create, review, and restructure content for agentic resources using a standardized documentation structure, incorporating elements like tutorials, how-to guides, and core concepts, all adapted for Ark''s specific needs and utilizing the Diataxis methodology.","zh":"使Agent能够使用标准化的文档结构来创建、审查和重组Agentic资源的内容，其中包含教程、操作指南和核心概念等元素，所有这些都根据Ark的特定需求进行了调整，并利用了Diataxis方法。","ja":"チュートリアル、ハウツーガイド、コアコンセプトなどの要素を組み込み、Arkの特定のニーズに合わせて調整され、Diataxis方法論を利用した標準化されたドキュメント構造を使用して、Agenticリソースのコンテンツを作成、レビュー、再構築するAgentを強化します。","ko":"자습서, 방법 가이드 및 핵심 개념과 같은 요소를 통합하고, Ark의 특정 요구 사항에 맞게 조정되며 Diataxis 방법론을 활용하는 표준화된 문서 구조를 사용하여 Agentic 리소스에 대한 콘텐츠를 생성, 검토 및 재구성하는 Agent의 능력을 강화합니다.","es":"Empodera a los agentes para crear, revisar y reestructurar contenido para recursos agenticos utilizando una estructura de documentación estandarizada, incorporando elementos como tutoriales, guías prácticas y conceptos básicos, todo adaptado para las necesidades específicas de Ark y utilizando la metodología Diataxis.","fr":"Permet aux agents de créer, examiner et restructurer du contenu pour des ressources agentiques en utilisant une structure de documentation standardisée, incorporant des éléments tels que des tutoriels, des guides pratiques et des concepts de base, le tout adapté aux besoins spécifiques d''Ark et utilisant la méthodologie Diataxis.","de":"Ermächtigt Agents dazu, Inhalte für agentische Ressourcen zu erstellen, zu überprüfen und umzustrukturieren, indem eine standardisierte Dokumentationsstruktur verwendet wird, die Elemente wie Tutorials, How-to-Guides und Kernkonzepte einbezieht, alles angepasst an die spezifischen Anforderungen von Ark und unter Nutzung der Diataxis-Methodologie.","pt":"Capacita os agentes a criar, revisar e reestruturar conteúdo para recursos agentivos usando uma estrutura de documentação padronizada, incorporando elementos como tutoriais, guias de como fazer e conceitos principais, todos adaptados para as necessidades específicas da Ark e utilizando a metodologia Diataxis.","ru":"Позволяет агентам создавать, проверять и реструктурировать контент для агентских ресурсов, используя стандартизированную структуру документации, включая такие элементы, как учебные пособия, руководства и основные концепции, все адаптировано для конкретных потребностей Ark и с использованием методологии Diataxis.","ar":"يمكّن الوكلاء من إنشاء ومراجعة وإعادة هيكلة المحتوى للموارد الوكلية باستخدام هيكل توثيق قياسي، يتضمن عناصر مثل البرامج التعليمية وأدلة الإرشادات والمفاهيم الأساسية، كلها مكيفة لاحتياجات Ark المحددة وباستخدام منهجية Diataxis."},"useCases":{"en":["Creating new documentation with clear introduction and quickstart guides","Reviewing and restructuring existing documentation for better clarity and accessibility","Deciding where content belongs within the Diataxis structure for optimal user experience"],"zh":["创建包含清晰介绍和快速入门指南的新文档","审查和重组现有文档以提高清晰度和可访问性","决定内容在Diataxis结构中的位置以获得最佳用户体验"],"ja":["明確な紹介とクイックスタートガイドを含む新しいドキュメントの作成","明確さとアクセシビリティを向上させるための既存ドキュメントのレビューと再構築","最適なユーザーエクスペリエンスのためのDiataxis構造内でのコンテンツの配置決定"],"ko":["명확한 소개 및 빠른 시작 가이드가 포함된 새로운 문서 생성","명확성과 접근성을 높이기 위한 기존 문서 검토 및 재구성","최적의 사용자 경험을 위한 Diataxis 구조 내 콘텐츠 위치 결정"],"es":["Crear nueva documentación con una introducción clara y guías de inicio rápido","Revisar y reestructurar la documentación existente para una mejor claridad y accesibilidad","Decidir dónde debe ir el contenido dentro de la estructura Diataxis para una experiencia de usuario óptima"],"fr":["Créer une nouvelle documentation avec une introduction claire et des guides de démarrage rapide","Examiner et restructurer la documentation existante pour une meilleure clarté et accessibilité","Décider où le contenu doit se situer dans la structure Diataxis pour une expérience utilisateur optimale"],"de":["Erstellen neuer Dokumentation mit klarer Einführung und Schnellstart-Anleitungen","Überprüfen und Umstrukturieren vorhandener Dokumentation für bessere Klarheit und Zugänglichkeit","Entscheiden, wo Inhalte innerhalb der Diataxis-Struktur für ein optimales Benutzererlebnis hingehören"],"pt":["Criar nova documentação com introdução clara e guias de início rápido","Revisar e reestruturar a documentação existente para melhor clareza e acessibilidade","Decidir onde o conteúdo se encaixa dentro da estrutura Diataxis para uma experiência do usuário ideal"],"ru":["Создание новой документации с четким введением и руководствами по быстрому старту","Проверка и реструктуризация существующей документации для лучшей ясности и доступности","Определение места контента в структуре Diataxis для оптимального пользовательского опыта"],"ar":["إنشاء توثيق جديد بمقدمة واضحة وأدلة بدء سريع","مراجعة وإعادة هيكلة التوثيق الحالي لمزيد من الوضوح وسهولة الوصول","تحديد المكان المناسب للمحتوى داخل هيكل Diataxis لتجربة مستخدم مثالية"]},"limitations":{"en":["Requires understanding of Diataxis framework","Specifically designed for Ark''s documentation needs, may require adaptation for other use cases"],"zh":["需要理解Diataxis框架","专为Ark的文档需求设计，可能需要进行调整才能用于其他用例"],"ja":["Diataxisフレームワークの理解が必要","Arkのドキュメントニーズに特化して設計されているため、他のユースケースには調整が必要な場合がある"],"ko":["Diataxis 프레임워크에 대한 이해 필요","Ark의 문서 요구 사항에 맞게 특별히 설계되어 다른 사용 사례에는 조정이 필요할 수 있음"],"es":["Requiere comprensión del framework Diataxis","Diseñado específicamente para las necesidades de documentación de Ark, puede requerir adaptación para otros casos de uso"],"fr":["Nécessite une compréhension du framework Diataxis","Conçu spécifiquement pour les besoins de documentation d''Ark, peut nécessiter une adaptation pour d''autres cas d''utilisation"],"de":["Erfordert ein Verständnis des Diataxis-Frameworks","Speziell für die Dokumentationsanforderungen von Ark entwickelt, kann für andere Anwendungsfälle Anpassungen erfordern"],"pt":["Requer compreensão do framework Diataxis","Projetado especificamente para as necessidades de documentação da Ark, pode exigir adaptação para outros casos de uso"],"ru":["Требует понимания фреймворка Diataxis","Специально разработан для потребностей документации Ark, может потребовать адаптации для других случаев использования"],"ar":["يتطلب فهم إطار عمل Diataxis","مصمم خصيصًا لاحتياجات توثيق Ark، وقد يحتاج إلى تكييف لحالات استخدام أخرى"]},"version":4},"contentHash":"5a2c976292466c897e033207e079345c86466ea624cb378bf0029f594d712fab","qualityScore":57}');
