INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mckinsey/agents-at-scale-ark/ark-documentation', 'ark-documentation', 'mckinsey', 'agents-at-scale-ark', 'community', 'ark-documentation mckinsey agents-at-scale-ark community The ark-documentation skill provides guidance for structuring documentation using Diataxis, helping developers create, review, and restructure content for agentic resources. Ark 文档提供了 provider-agnostic 操作和资源的结构化指南，使用 Diataxis 适配 Ark 的需求 Ark ドキュメントはプロバイダー非依存の操作とリソースの構造化ガイドを提供し、Diataxis を使用して Ark のニーズに合わせた文書化を行う Ark 문서는 provider-agnostic操作과 리소스의 구조화된 가이드를 제공하며 Diataxis를 사용하여 Ark의需求에 맞는 문서화를 수행 Ark-documentation proporciona operaciones agnósticas de proveedor para recursos agenticos, utilizando Diataxis para estructurar documentación Ark-documentation offre des opérations agnostiques de fournisseur pour les ressources agenticas, en utilisant Diataxis pour structurer la documentation Ark-documentation bietet anbieterunabhängige Operationen für agentic-Ressourcen, mit Diataxis für die Strukturierung von Dokumentationen O Ark-Documentation é um recurso para operações de agente, que codifica padrões e práticas de desenvolvimento de aplicações ARK Документация - это провайдер-агностические операции для агентских ресурсов, кодифицирующие закономерности и методы разработки агентских приложений وثائق Ark هي عمليات وثائقية لمنصات الإيمان الإلكتروني، التي توحد أنماط وممارسات تطوير التطبيقات الإلكترونية how to use ark-documentation what is ark-documentation ark-documentation setup guide ark-documentation alternative Diataxis framework for documentation agentic resource documentation ark-documentation install structuring documentation with ark-documentation Ark 文档 AIエージェント文档结构 Diataxis provider-agnostic 文档最佳实践 文档结构指南 Ark 开发者 Uses Diataxis framework for structuring documentation Supports linear learning paths through Tutorials Provides task-oriented guides with How-to Guides Offers understanding of core concepts and their implementation Enables effective content review and restructuring ark-documentation is a provider-agnostic operations framework for structuring documentation, codifying patterns and practices for agentic application projects');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Yorick-Ryu/deep-share/md2docx', 'community', 'Yorick-Ryu', 'deep-share', 'Yorick-Ryu/deep-share', 'md2docx', 0, 0, 57, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.603Z', 'c04d36aefba9d7d16d477ad972d3955d7954cf10c80da3be6ec8de873d1afdbb', '{"id":"Yorick-Ryu/deep-share/md2docx","name":"md2docx","description":{"en":"md2docx is a browser extension that converts Markdown text to professionally formatted Word documents, supporting AI conversations from ChatGPT, DeepSeek, and more. It benefits AI users by simplifying document creation.","zh":"md2docx是一种轻量级的浏览器扩展，支持将Markdown文本转换为Word文档，包括公式和长对话截图","ja":"md2docxは、MarkdownテキストをWord文書に変換する軽量ブラウザ拡張機能です。数式や長い会話のスクリーンショットもサポートしています","ko":"md2docx는 마크다운 텍스트를 워드 문서로 변환하는 경량 브라우저 확장機能입니다. 수식과 긴 대화 스크린샷도 지원합니다","es":"md2docx es una extensión de navegador ligera que convierte texto Markdown en documentos Word profesionales","fr":"md2docx est une extension de navigateur légère qui convertit du texte Markdown en documents Word professionnels","de":"md2docx ist eine leichte Browser-Erweiterung, die Markdown-Text in professionell formatierte Word-Dokumente umwandelt","pt":"O md2docx é uma extensão leve que converte texto Markdown em documentos Word formatados, ideal para usuários de AI","ru":"md2docx - это легкое расширение, которое преобразует текст Markdown в профессионально оформленные документы Word, подходящее для ИИ Агентов","ar":"md2docx هو امتداد خفيف يتحول نص Markdown إلى مستندات Word معدة بشكل محترف، مثالي لمستخدمي أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"md2docx: Markdown to DOCX Converter for AI Agents | AI Ag...","zh":"md2docx设置指南：Markdown转Word文档","ja":"md2docxのベストプラクティス：AIエージェントのMarkdownからWordへの変換","ko":"md2docx 설정 가이드: 마크다운을 워드 문서로 변환하는 방법","es":"Guía de configuración de md2docx: Conversión de Markdown ...","fr":"Guide d''installation de md2docx: Conversion Markdown en Word","de":"Einrichtungsleitfaden für md2docx: Markdown in Word umwan...","pt":"Guia de Configuração md2docx: Conversor de Markdown para ...","ru":"Руководство по настройке md2docx: Преобразователь Markdow...","ar":"دليل إعداد md2docx: محول Markdown إلى Word لأدوات الذكاء ..."},"description":{"en":"Discover how to export AI conversation formulas to Word documents with md2docx. Learn how to use this lightweight browser extension and convert Markdown text...","zh":"使用md2docx轻松将Markdown文本转换为专业格式的Word文档，支持云环境和本地环境","ja":"md2docxを使用して、MarkdownテキストをプロフェッショナルなフォーマットのWord文書に変換する方法","ko":"md2docx를 사용하여 마크다운 텍스트를 전문가처럼 포맷된 워드 문서로 변환하는 방법","es":"Descubre cómo utilizar md2docx para convertir texto Markdown en documentos Word profesionales con facilidad","fr":"Découvrez comment utiliser md2docx pour convertir du texte Markdown en documents Word professionnels avec facilité","de":"Erfahren Sie, wie Sie md2docx verwenden, um Markdown-Text in professionell formatierte Word-Dokumente umzuwandeln","pt":"Aprenda a usar o md2docx para converter texto Markdown em documentos Word formatados com facilidade e eficiência","ru":"Узнайте, как использовать md2docx для преобразования текста Markdown в профессионально оформленные документы Word для ИИ Агентов","ar":"تعلم كيفية استخدام md2docx لتحويل نص Markdown إلى مستندات Word معدة بشكل محترف لأدوات الذكاء الاصطناعي"},"definition":{"en":"md2docx is a lightweight browser extension that converts Markdown text to Word documents, supporting long conversation screenshot sharing and export of beautifully formatted DOCX files.","zh":"md2docx是一种Markdown到Word转换工具","ja":"md2docxは、MarkdownからWordへの変換ツールです","ko":"md2docx는 마크다운을 워드로 변환하는 도구입니다","es":"md2docx es una herramienta de conversión de Markdown a Word que utiliza Python y CLI","fr":"md2docx est un outil de conversion de Markdown en Word qui utilise Python et CLI","de":"md2docx ist ein Werkzeug zur Umwandlung von Markdown in Word, das Python und CLI verwendet","pt":"O md2docx é um conversor de Markdown para Word que permite a exportação de documentos formatados","ru":"md2docx - это преобразователь Markdown в Word, который позволяет экспортировать профессионально оформленные документы","ar":"md2docx هو محول Markdown إلى Word الذي يسمح bằng استيراد مستندات معدة بشكل محترف"},"features":{"en":["Converts Markdown text to professionally formatted Word (DOCX) documents","Supports export of formulas from AI conversations, including ChatGPT and DeepSeek","Allows long conversation screenshot sharing for DeepSeek","Operates in two modes: URL mode for cloud environments and file mode for local environments","Utilizes Python scripts, such as convert.py, for conversion processes","Supports command-line interface for flexible usage, including --url and --file options"],"zh":["支持Markdown文本转换为Word文档","支持公式转换","支持长对话截图","提供URL模式和文件模式","支持Python脚本执行"],"ja":["MarkdownテキストをWord文書に変換する機能","数式の変換をサポート","長い会話のスクリーンショットをサポート","URLモードとファイルモードを提供","Pythonスクリプトの実行をサポート"],"ko":["마크다운 텍스트를 워드 문서로 변환하는 기능","수식 변환을 지원","긴 대화 스크린샷을 지원","URL 모드와 파일 모드를 제공","Python 스크립트 실행을 지원"],"es":["Conversión de Markdown a Word utilizando Python","Compatibilidad con entornos en la nube y locales","Modos de URL y archivo para la conversión","Soporte para la compartición de capturas de pantalla de conversaciones largas","Integración con ChatGPT, DeepSeek, Grok y otros 10+ agentes de IA"],"fr":["Conversion de Markdown en Word à l''aide de Python","Compatibilité avec les environnements cloud et locaux","Modes URL et fichier pour la conversion","Prise en charge du partage d''écran de conversations longues","Intégration avec ChatGPT, DeepSeek, Grok et 10+ autres agents IA"],"de":["Umwandlung von Markdown in Word mit Python","Unterstützung für Cloud- und lokale Umgebungen","URL- und Dateimodi für die Umwandlung","Unterstützung für das Teilen von Screenshots von langen Konversationen","Integration mit ChatGPT, DeepSeek, Grok und 10+ anderen KI-Agents"],"pt":["Conversão de texto Markdown em documentos Word formatados","Modo URL para ambientes em nuvem/remotos","Modo arquivo para ambientes locais","Comando Python para conversão de Markdown em Word","Compatibilidade com ChatGPT, DeepSeek, Grok e outros"],"ru":["Преобразование текста Markdown в профессионально оформленные документы Word","Режим URL для облачных/удаленных сред","Режим файла для локальных сред","Команда Python для преобразования Markdown в Word","Совместимость с ChatGPT, DeepSeek, Grok и другими ИИ Агентами"],"ar":["تحويل نص Markdown إلى مستندات Word معدة بشكل محترف","الوضع URL للبيئات السحابية/النائية","الوضع الملف للبيئات المحلية","أمر Python لتحويل Markdown إلى Word","التوافق مع ChatGPT و DeepSeek و Grok وأدوات الذكاء الاصطناعي الأخرى"]},"keywords":{"en":["how to use md2docx","md2docx setup guide","md2docx alternative","md2docx vs other converters","markdown to docx conversion","ai conversation export","deepseek screenshot sharing","chatgpt formula export","md2docx install","python markdown converter"],"zh":["md2docx","Markdown转Word","AI工具","浏览器扩展","Python脚本","公式转换","长对话截图"],"ja":["md2docx","MarkdownからWord","AIエージェント","ブラウザ拡張","Pythonスクリプト","数式変換","長い会話のスクリーンショット"],"ko":["md2docx","마크다운을 워드로","AI도구","브라우저 확장","Python 스크립트","수식 변환","긴 대화 스크린샷"],"es":["md2docx","conversión de Markdown a Word","herramientas de IA","agentes de IA","Python","CLI","entornos en la nube","entornos locales","compatibilidad con ChatGPT"],"fr":["md2docx","conversion de Markdown en Word","outils d''IA","agents d''IA","Python","CLI","environnements cloud","environnements locaux","compatibilité avec ChatGPT"],"de":["md2docx","Umwandlung von Markdown in Word","KI-Tools","KI-Agents","Python","CLI","Cloud-Umgebungen","lokale Umgebungen","Kompatibilität mit ChatGPT"],"pt":["md2docx","conversor de Markdown","documento Word formatado","extensão leve","usuários de AI","ChatGPT","DeepSeek","Grok","Python","CLI"],"ru":["md2docx","преобразователь Markdown","документ Word","легкое расширение","ИИ Агенты","ChatGPT","DeepSeek","Grok","Python","CLI","ИИ инструменты"],"ar":["md2docx","محول Markdown","مستند Word","امتداد خفيف","مستخدمي أدوات الذكاء الاصطناعي","ChatGPT","DeepSeek","Grok","Python","CLI","أدوات الذكاء الاصطناعي"]}},"owner":"Yorick-Ryu","repo":"deep-share","repoPath":"Yorick-Ryu/deep-share","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"md2docx","description":"Convert Markdown to Word (DOCX) documents. Use when user wants to export, convert, or create Word documents from Markdown content.","bodyPreview":"# md2docx - Markdown to Word Converter\n\nConvert Markdown text to professionally formatted Word (DOCX) documents.\n\n## Quick Start\n\n**Choose the right mode based on your environment**:\n\n```bash\n# URL mode: Returns download URL (for cloud/remote environments)\npython scripts/convert.py input.md --url\n\n# File mode: Saves file directly (for local environments)\npython scripts/convert.py input.md --file\n```\n\n## Choosing the Right Mode\n\n| Scenario | Mode | Command |\n|----------|------|---------|\n| Skill","body":"# md2docx - Markdown to Word Converter\n\nConvert Markdown text to professionally formatted Word (DOCX) documents.\n\n## Quick Start\n\n**Choose the right mode based on your environment**:\n\n```bash\n# URL mode: Returns download URL (for cloud/remote environments)\npython scripts/convert.py input.md --url\n\n# File mode: Saves file directly (for local environments)\npython scripts/convert.py input.md --file\n```\n\n## Choosing the Right Mode\n\n| Scenario | Mode | Command |\n|----------|------|---------|\n| Skill runs in cloud, user needs to download | `--url` | `python scripts/convert.py input.md --url` |\n| Skill runs locally, user wants file saved | `--file` | `python scripts/convert.py input.md --file` |\n| Remote execution (MCP, API, cloud agent) | `--url` | Returns URL for user to download |\n| Local execution (user''s machine) | `--file` | Saves .docx directly to disk |\n\n**Decision Rule**:\n- **Use `--url`** when the skill runs in a different environment than the user (cloud, remote server, MCP server)\n- **Use `--file`** when the skill runs on the same machine where the user wants the output file\n\n## How It Works\n\n1. **Prepare Markdown**: Ensure content is in standard Markdown format\n2. **Run Script**: Execute `scripts/convert.py` with appropriate mode\n3. **Get Result**: \n   - URL mode: Receive download URL\n   - File mode: File saved to specified location\n\n## API Details\n\n**Endpoints**:\n- URL mode: `https://api.deepshare.app/convert-text-to-url` → Returns `{\"url\": \"...\"}`\n- File mode: `https://api.deepshare.app/convert-text` → Returns DOCX file directly\n\n**Authentication**: Include header `X-API-Key: {api_key}`\n\n### API Key Configuration\n\nYou can configure the API key in three ways:\n\n1. **Environment Variable** (Highest Priority)\n   ```bash\n   export DEEP_SHARE_API_KEY=\"your_api_key_here\"\n   ```\n\n2. **Skill Variable** (Medium Priority)\n   Edit the `api_key` field in the YAML frontmatter of this Skill file:\n   ```yaml\n   ---\n   name: md2docx\n   api_key: \"your_api_key_here\"\n   ---\n   ```\n\n3. **Trial Key** (Fallback): `f4e8fe6f-e39e-486f-b7e7-e037d2ec216f`\n\n**Priority Order**:\n1. Environment variable `DEEP_SHARE_API_KEY` (if set)\n2. Skill''s `api_key` variable (if not empty)\n3. Trial key (limited quota)\n\n⚠️ **Trial Mode**: Limited quota. For stable production use, purchase at: https://ds.rick216.cn/purchase\n\n## Request Format\n\n```json\n{\n  \"content\": \"markdown text here\",\n  \"filename\": \"output\",\n  \"template_name\": \"templates\",\n  \"language\": \"zh\",\n  \"hard_line_breaks\": false,\n  \"remove_hr\": false\n}\n```\n\n## Parameters\n\n| Parameter | Default | Description |\n|-----------|---------|-------------|\n| `content` | required | Markdown text to convert |\n| `filename` | `\"output\"` | Output filename (without .docx) |\n| `template_name` | `\"templates\"` | Template: `templates`, `论文`, `article`, `thesis`, etc. |\n| `language` | `\"zh\"` | Template language: `zh` or `en` |\n| `hard_line_breaks` | `false` | Preserve single line breaks |\n| `remove_hr` | `false` | Remove horizontal rules |\n\n## Common Templates\n\n**Chinese** (`language: \"zh\"`):\n- `templates` - General purpose\n- `论文` - Academic paper\n- `论文-首行不缩进` - Paper without indent\n- `论文-标题加粗` - Paper with bold headings\n\n**English** (`language: \"en\"`):\n- `templates` - General purpose\n- `article` - Article/report style\n- `thesis` - Academic thesis\n\n## Conversion Script Usage\n\n### Command Line Options\n\n```bash\npython scripts/convert.py <input.md> [options]\n\nOptions:\n  --url              Return download URL (default if no mode specified)\n  --file             Save file directly to disk\n  --template, -t     Template name (default: templates)\n  --language, -l     Language: zh or en (default: zh)\n  --output, -o       Output directory for file mode\n  --api-key, -k      API key (optional)\n```\n\n### Examples\n\n```bash\n# URL mode (cloud/remote environments)\npython scripts/convert.py document.md --url\npython scripts/convert.py paper.md --url --template 论文 --language zh\n\n# File mode (local environments)\npython scripts/convert.py document.md --file\npython scripts/convert.py paper.md --file --output ./docs --template thesis --language en\n\n# With custom API key\npython scripts/convert.py doc.md --url --api-key your_key\n```\n\n## Validation Before Conversion\n\nEnsure Markdown content:\n- Headers use `#` syntax\n- Lists use `-` or `1.` syntax\n- Code blocks use triple backticks\n- Math formulas use `$...$` (inline) or `$$...$$` (block)\n- Images use publicly accessible URLs\n\n## Response Handling\n\n### URL Mode Response\n\n**Success** (200 OK):\n```json\n{\n  \"url\": \"https://flies.deepshare.app/mcp/hash/document_xxx.docx\"\n}\n```\n\n### File Mode Response\n\n**Success**: File saved to disk, path printed to stdout\n\n### Error Responses (Both Modes)\n\n- `401 Unauthorized` - Invalid API key\n- `403 Forbidden` - Quota exceeded → Purchase at https://ds.rick216.cn/purchase\n- `413 Payload Too Large` - Content exceeds 10MB\n- `500 Internal Server Error` - Service unavailable, retry\n\n## User Communication\n\n### On Success\n\nTell user:\n1. Conversion completed successfully\n2. **URL mode**: Provide the download URL\n3. **File mode**: Provide the file path where document was saved\n4. Check which API key was used:\n   - **If using environment variable or Skill variable**: No reminder needed\n   - **If using trial key**: Remind: \"⚠️ You''re using trial mode (limited quota). For stable production use, get your API key at: https://ds.rick216.cn/purchase\"\n\n### On Quota Exceeded\n\nTell user:\n1. Conversion failed: quota exceeded\n2. Purchase more credits at: https://ds.rick216.cn/purchase\n3. Or use another API key\n\n### On Other Errors\n\nTell user:\n1. What went wrong (based on error message)\n2. How to fix it\n3. Offer to retry\n\n## Tips\n\n- **API Key Configuration**:\n  - **Option 1 (Recommended)**: Set environment variable `DEEP_SHARE_API_KEY`\n    ```bash\n    export DEEP_SHARE_API_KEY=\"your_api_key_here\"\n    ```\n  - **Option 2**: Edit `api_key` in this Skill''s YAML frontmatter\n  - **Option 3**: Use trial key (limited quota)\n- **File Size**: Keep Markdown under 10MB\n- **Images**: Use `https://` URLs, not local paths\n- **Math**: Use LaTeX syntax: `$E=mc^2$` or `$$\\int_0^\\infty$$`\n- **Line Breaks**: Use `hard_line_breaks: true` for addresses, poetry\n- **Templates**: Choose based on document type (paper, article, etc.)\n\n## Example Workflows\n\n### Workflow 1: Cloud Environment (URL Mode)\n\n**User asks**: \"Convert this to Word\" (skill running in cloud)\n\n1. Save the Markdown content to a temporary file (e.g., `temp.md`)\n\n2. Run the conversion script with URL mode:\n   ```bash\n   python scripts/convert.py temp.md --url\n   ```\n\n3. The script will:\n   - Select API key by priority (env → skill → trial)\n   - Call the conversion API\n   - Return download URL\n\n4. Provide the download URL to user\n\n5. Clean up temporary file\n\n### Workflow 2: Local Environment (File Mode)\n\n**User asks**: \"Convert my notes.md to Word\" (skill running locally)\n\n1. Run the conversion script with file mode:\n   ```bash\n   python scripts/convert.py notes.md --file --output ./output\n   ```\n\n2. The script will:\n   - Select API key by priority (env → skill → trial)\n   - Call the conversion API\n   - Save the DOCX file directly\n\n3. Tell user where the file was saved\n\n4. No cleanup needed - file is the output\n"},"lastSynced":"2026-03-08T02:01:04.603Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing Markdown to DOCX conversion capabilities.","zh":"非常适合需要 Markdown 到 DOCX 转换能力的文档分析代理。","ja":"Markdown を DOCX に変換する機能が必要なドキュメント分析エージェントに最適です。","ko":"Markdown를 DOCX로 변환하는 기능이 필요한 문서 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de conversión de Markdown a DOCX.","fr":"Parfait pour les Agents d''Analyse de Documents ayant besoin de capacités de conversion de Markdown en DOCX.","de":"Perfekt für Dokumentenanalyse-Agents, die Markdown-zu-DOCX-Konvertierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que precisam de capacidades de conversão de Markdown para DOCX.","ru":"Идеально подходит для агентов анализа документов, которым необходимы возможности преобразования Markdown в DOCX.","ar":"مثالي للوكلاء تحليل الوثائق الذين يحتاجون إلى قدرات تحويل Markdown إلى DOCX."},"recommendation":{"en":"Empowers agents to convert Markdown text to professionally formatted Word documents using Python scripts, supporting both URL and file modes for cloud and local environments, and leveraging Markdown formatting for AI-generated content from ChatGPT and DeepSeek.","zh":"使代理能够使用 Python 脚本将 Markdown 文本转换为专业格式的 Word 文档，支持云环境和本地环境的 URL 和文件模式，并利用 ChatGPT 和 DeepSeek 生成的 AI 内容的 Markdown 格式。","ja":"Python スクリプトを使用して、エージェントが Markdown テキストをプロフェッショナルなフォーマットの Word 文書に変換できるようにし、クラウドおよびローカル環境の URL およびファイル モードをサポートし、ChatGPT および DeepSeek によって生成された AI コンテンツの Markdown フォーマットを利用します。","ko":"에이전트가 Python 스크립트를 사용하여 Markdown 텍스트를 전문가급 형식의 워드 문서로 변환할 수 있도록 하며, 클라우드 및 로컬 환경의 URL 및 파일 모드를 지원하며, ChatGPT 및 DeepSeek에서 생성한 AI 콘텐츠의 Markdown 형식을 활용합니다.","es":"Habilita a los agentes a convertir texto Markdown a documentos Word profesionalmente formateados utilizando scripts de Python, admitiendo tanto modos de URL como de archivo para entornos en la nube y locales, y aprovechando el formato Markdown para contenido generado por AI desde ChatGPT y DeepSeek.","fr":"Permet aux agents de convertir du texte Markdown en des documents Word professionnellement formatés en utilisant des scripts Python, en prenant en charge les modes URL et fichier pour les environnements cloud et locaux, et en exploitant le formatage Markdown pour le contenu généré par l''IA à partir de ChatGPT et DeepSeek.","de":"Ermächtigt Agents, Markdown-Text in professionell formatierte Word-Dokumente mithilfe von Python-Skripten zu konvertieren, und unterstützt sowohl URL- als auch Dateimodi für Cloud- und lokale Umgebungen, und nutzt das Markdown-Format für von KI generierte Inhalte von ChatGPT und DeepSeek.","pt":"Habilita os agentes a converter texto Markdown em documentos do Word profissionalmente formatados usando scripts Python, suportando ambos os modos de URL e arquivo para ambientes em nuvem e locais, e aproveitando a formatação Markdown para conteúdo gerado por IA do ChatGPT e DeepSeek.","ru":"Наделяет агентов возможностью конвертировать текст Markdown в профессионально оформленные документы Word с помощью скриптов Python, поддерживая как режим URL, так и режим файла для облачных и локальных сред, и использует форматирование Markdown для контента, сгенерированного ИИ из ChatGPT и DeepSeek.","ar":"يتمكن الوكلاء من تحويل نص Markdown إلى مستندات Word معدة بشكل محترف باستخدام سكريبتات Python، ودعم كل من وضع URL ووضع الملف للبيئات السحابية والمحلية، و الاستفادة من تنسيق Markdown لمحتوى مولد بواسطة الذكاء الاصطناعي من ChatGPT و DeepSeek."},"useCases":{"en":["Converting AI-generated Markdown text to DOCX files","Automating document creation from Markdown sources","Generating professionally formatted reports from Markdown data"],"zh":["将 AI 生成的 Markdown 文本转换为 DOCX 文件","自动从 Markdown 源创建文档","从 Markdown 数据生成专业格式的报告"],"ja":["AI によって生成された Markdown テキストを DOCX ファイルに変換する","Markdown ソースからドキュメントを作成を自動化する","Markdown データからプロフェッショナルなフォーマットのレポートを生成する"],"ko":["AI가 생성한 Markdown 텍스트를 DOCX 파일로 변환하는 것","Markdown 소스에서 문서 생성을 자동화하는 것","Markdown 데이터에서 전문가급 형식의 보고서를 생성하는 것"],"es":["Conversión de texto Markdown generado por IA a archivos DOCX","Automatización de la creación de documentos a partir de fuentes Markdown","Generación de informes profesionalmente formateados a partir de datos Markdown"],"fr":["Conversion de texte Markdown généré par l''IA en fichiers DOCX","Automatisation de la création de documents à partir de sources Markdown","Génération de rapports professionnellement formatés à partir de données Markdown"],"de":["Konvertierung von KI-generiertem Markdown-Text in DOCX-Dateien","Automatisierung der Dokumentenerstellung aus Markdown-Quellen","Generierung von professionell formatierten Berichten aus Markdown-Daten"],"pt":["Conversão de texto Markdown gerado por IA em arquivos DOCX","Automação da criação de documentos a partir de fontes Markdown","Geração de relatórios profissionalmente formatados a partir de dados Markdown"],"ru":["Преобразование текста Markdown, сгенерированного ИИ, в файлы DOCX","Автоматизация создания документов из источников Markdown","Генерация профессионально оформленных отчетов из данных Markdown"],"ar":["تحويل نص Markdown المولّد بواسطة الذكاء الاصطناعي إلى ملفات DOCX","أتمتة إنشاء المستندات من مصادر Markdown","توليد تقارير معدة بشكل محترف من بيانات Markdown"]},"limitations":{"en":["Requires Python environment","Limited to Markdown and DOCX file formats"],"zh":["需要 Python 环境","仅限 Markdown 和 DOCX 文件格式"],"ja":["Python 環境が必要","Markdown および DOCX ファイル形式のみ"],"ko":["Python 환경이 필요함","Markdown 및 DOCX 파일 형식만 해당"],"es":["Requiere entorno de Python","Limitado a formatos de archivo Markdown y DOCX"],"fr":["Nécessite un environnement Python","Limité aux formats de fichiers Markdown et DOCX"],"de":["Benötigt Python-Umgebung","Begrenzt auf Markdown- und DOCX-Dateiformate"],"pt":["Requer ambiente Python","Limitado a formatos de arquivo Markdown e DOCX"],"ru":["Требуется среда Python","Ограничен форматами файлов Markdown и DOCX"],"ar":["يتطلب بيئة Python","محدود بصيغ ملفات Markdown و DOCX"]},"version":4},"contentHash":"c04d36aefba9d7d16d477ad972d3955d7954cf10c80da3be6ec8de873d1afdbb","qualityScore":57}');
