INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Yorick-Ryu/deep-share/md2docx', 'md2docx', 'Yorick-Ryu', 'deep-share', 'community', 'md2docx Yorick-Ryu deep-share community md2docx is a browser extension that converts Markdown text to professionally formatted Word documents, supporting AI conversations from ChatGPT, DeepSeek, and more. It benefits AI users by simplifying document creation. md2docx是一种轻量级的浏览器扩展，支持将Markdown文本转换为Word文档，包括公式和长对话截图 md2docxは、MarkdownテキストをWord文書に変換する軽量ブラウザ拡張機能です。数式や長い会話のスクリーンショットもサポートしています md2docx는 마크다운 텍스트를 워드 문서로 변환하는 경량 브라우저 확장機能입니다. 수식과 긴 대화 스크린샷도 지원합니다 md2docx es una extensión de navegador ligera que convierte texto Markdown en documentos Word profesionales md2docx est une extension de navigateur légère qui convertit du texte Markdown en documents Word professionnels md2docx ist eine leichte Browser-Erweiterung, die Markdown-Text in professionell formatierte Word-Dokumente umwandelt O md2docx é uma extensão leve que converte texto Markdown em documentos Word formatados, ideal para usuários de AI md2docx - это легкое расширение, которое преобразует текст Markdown в профессионально оформленные документы Word, подходящее для ИИ Агентов md2docx هو امتداد خفيف يتحول نص Markdown إلى مستندات Word معدة بشكل محترف، مثالي لمستخدمي أدوات الذكاء الاصطناعي how to use md2docx md2docx setup guide md2docx alternative md2docx vs other converters markdown to docx conversion ai conversation export deepseek screenshot sharing chatgpt formula export md2docx install python markdown converter md2docx Markdown转Word AI工具 浏览器扩展 Python脚本 公式转换 长对话截图 Converts Markdown text to professionally formatted Word (DOCX) documents Supports export of formulas from AI conversations, including ChatGPT and DeepSeek Allows long conversation screenshot sharing for DeepSeek Operates in two modes: URL mode for cloud environments and file mode for local environments Utilizes Python scripts, such as convert.py, for conversion processes Supports command-line interface for flexible usage, including --url and --file options md2docx is a lightweight browser extension that converts Markdown text to Word documents, supporting long conversation screenshot sharing and export of beautifully formatted DOCX files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SpookyPirate/spookys-automod-toolkit/skyrim-mcm', 'community', 'SpookyPirate', 'spookys-automod-toolkit', 'SpookyPirate/spookys-automod-toolkit', 'skyrim-mcm', 0, 0, 57, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.603Z', '4016153533ab400da404d4e59036b2ff4fb628159e046a30092ad72f9e076cd2', '{"id":"SpookyPirate/spookys-automod-toolkit/skyrim-mcm","name":"skyrim-mcm","description":{"en":"The skyrim-mcm skill assists LLMs in creating and editing Skyrim mods by generating JSON configuration files compatible with MCM Helper. This benefits developers and modders working with Skyrim mods.","zh":"Skyrim MCM是一个用于创建和编辑游戏模组配置文件的工具，支持Spooky''s AutoMod Toolkit","ja":"Skyrim MCMは、ゲームモッドの設定ファイルを作成、編集するために使用されるツールです","ko":"Skyrim MCM은 게임 모드 설정 파일을 생성하고 편집하는 데 사용되는 도구입니다","es":"Skyrim-mcm es una herramienta para crear y editar configuraciones de MCM Helper para mods de Skyrim. Utiliza Spooky''s AutoMod Toolkit para generar archivos de configuración JSON","fr":"Skyrim-mcm est un outil pour créer et éditer des configurations MCM Helper pour les mods Skyrim. Il utilise Spooky''s AutoMod Toolkit pour générer des fichiers de configuration JSON","de":"Skyrim-mcm ist ein Tool zum Erstellen und Bearbeiten von MCM-Helper-Konfigurationen für Skyrim-Mods. Es verwendet Spooky''s AutoMod Toolkit, um JSON-Konfigurationsdateien zu generieren","pt":"O módulo Skyrim MCM é uma ferramenta para criar e editar mods para o jogo, utilizando o Spooky''s AutoMod Toolkit para gerar arquivos de configuração JSON.","ru":"Модуль Skyrim MCM — это инструмент для создания и редактирования модов для игры, использующий Spooky''s AutoMod Toolkit для генерации файлов конфигурации JSON.","ar":"وحدة سكاي ريم إم سي إم هي أداة لإنشاء وتحرير المودات الخاصة بلعبة، وتستخدم أداة أوتومود من سبوكي لإنشاء ملفات تكوين جيسون."},"seo":{"title":{"en":"skyrim-mcm: MCM Helper Configuration Setup Guide | AI Age...","zh":"Skyrim MCM 配置指南 - AI工具","ja":"Skyrim MCM セットアップガイド - AIエージェント","ko":"Skyrim MCM 설정 가이드 - AI 에이전트","es":"Guía de configuración de skyrim-mcm para mods de Skyrim","fr":"Configurer skyrim-mcm pour les mods Skyrim - Guide étape ...","de":"Skyrim-MCM-Setup-Anleitung für Mod-Entwickler","pt":"Guia de Configuração do Skyrim MCM para Desenvolvedores","ru":"Настройка ИИ Агентов для Skyrim MCM: Руководство","ar":"دليل إعداد آي آي للعبة سكاي ريم إم سي إم"},"description":{"en":"Unlock Skyrim modding with skyrim-mcm! Learn how to create and edit MCM Helper configuration files using Spooky''s AutoMod Toolkit and take your mods to the n...","zh":"使用Skyrim MCM AI工具创建和编辑游戏模组配置文件，支持Spooky''s AutoMod Toolkit","ja":"Skyrim MCM AIエージェントを使用してゲームモッドの設定ファイルを作成、編集します","ko":"Skyrim MCM AI 에이전트를 사용하여 게임 모드 설정 파일을 생성하고 편집합니다","es":"Descubre cómo crear y editar mods de Skyrim con skyrim-mcm y Spooky''s AutoMod Toolkit. Obtén la guía paso a paso para dominar MCM Helper","fr":"Découvrez comment créer et éditer des mods Skyrim avec skyrim-mcm et Spooky''s AutoMod Toolkit. Obtenez le guide étape par étape pour maîtriser MCM Helper","de":"Erfahren Sie, wie Sie Skyrim-Mods mit skyrim-mcm und Spooky''s AutoMod Toolkit erstellen und bearbeiten. Holen Sie sich die Schritt-für-Schritt-Anleitung für ...","pt":"Aprenda a criar e editar mods para Skyrim com o módulo MCM. Descubra como usar o Spooky''s AutoMod Toolkit para gerar arquivos de configuração JSON.","ru":"Мастерская по созданию и редактированию модов для Skyrim с помощью модуля MCM. Узнайте, как использовать Spooky''s AutoMod Toolkit для генерации файлов конфиг...","ar":"تعلم كيفية إنشاء وتحرير المودات الخاصة بلعبة سكاي ريم باستخدام وحدة إم سي إم. اكتشف كيفية استخدام أداة أوتومود من سبوكي لإنشاء ملفات تكوين جيسون."},"definition":{"en":"skyrim-mcm is a module for creating and editing MCM Helper configuration files for in-game mod settings menus using Spooky''s AutoMod Toolkit","zh":"Skyrim MCM是一种用于创建和编辑游戏模组配置文件的AI工具","ja":"Skyrim MCMは、ゲームモッドの設定ファイルを作成、編集するためのAIエージェントです","ko":"Skyrim MCM은 게임 모드 설정 파일을 생성하고 편집하는 데 사용되는 AI 에이전트입니다","es":"Skyrim-mcm es un módulo que genera archivos de configuración JSON para MCM Helper, permitiendo a los mods de Skyrim tener menús de configuración en el juego","fr":"Skyrim-mcm est un module qui génère des fichiers de configuration JSON pour MCM Helper, permettant aux mods Skyrim d''avoir des menus de configuration en jeu","de":"Skyrim-mcm ist ein Modul, das JSON-Konfigurationsdateien für MCM Helper generiert, damit Skyrim-Mods Spiel-Configurationsmenüs haben können","pt":"O Skyrim MCM é um módulo que permite criar e editar mods para o jogo Skyrim, utilizando arquivos de configuração JSON.","ru":"Skyrim MCM — это модуль, который позволяет создавать и редактировать моды для игры Skyrim, используя файлы конфигурации JSON.","ar":"سكاي ريم إم سي إم هو وحدة تمكن من إنشاء وتحرير المودات الخاصة بلعبة سكاي ريم، باستخدام ملفات تكوين جيسون."},"features":{"en":["Generates JSON configuration files compatible with MCM Helper","Utilizes Spooky''s AutoMod Toolkit for mod settings menus","Creates MCM Helper configuration files for in-game mod settings","Requires running commands from the toolkit directory","Supports MCM (Mod Configuration Menu) for in-game settings menus","Compatible with Skyrim Special Edition mods"],"zh":["支持Spooky''s AutoMod Toolkit","创建和编辑MCM Helper配置文件","生成JSON配置文件","兼容MCM Helper","命令行界面","工具包目录支持"],"ja":["Spooky''s AutoMod Toolkitをサポート","MCM Helper設定ファイルの作成と編集","JSON設定ファイルの生成","MCM Helperと互換性がある","コマンドラインインターフェース","ツールキットディレクトリのサポート"],"ko":["Spooky''s AutoMod Toolkit 지원","MCM Helper 설정 파일 생성 및 편집","JSON 설정 파일 생성","MCM Helper와 호환","명령줄 인터페이스","도구 키트 디렉토리 지원"],"es":["Generación de archivos de configuración JSON para MCM Helper","Compatibilidad con Spooky''s AutoMod Toolkit","Creación y edición de configuraciones de MCM Helper para mods de Skyrim","Uso de comandos de línea de comandos (CLI) para ejecutar herramientas","Generación de menús de configuración en el juego para mods de Skyrim","Compatibilidad con la versión especial de Skyrim"],"fr":["Génération de fichiers de configuration JSON pour MCM Helper","Compatibilité avec Spooky''s AutoMod Toolkit","Création et édition de configurations MCM Helper pour les mods Skyrim","Utilisation de commandes de ligne de commande (CLI) pour exécuter des outils","Génération de menus de configuration en jeu pour les mods Skyrim","Compatibilité avec la version spéciale de Skyrim"],"de":["Generierung von JSON-Konfigurationsdateien für MCM Helper","Kompatibilität mit Spooky''s AutoMod Toolkit","Erstellen und Bearbeiten von MCM-Helper-Konfigurationen für Skyrim-Mods","Verwendung von Kommandozeilenbefehlen (CLI) zum Ausführen von Tools","Generierung von Spiel-Configurationsmenüs für Skyrim-Mods","Kompatibilität mit der Spezialversion von Skyrim"],"pt":["Criação de arquivos de configuração JSON para mods de Skyrim","Uso do Spooky''s AutoMod Toolkit para gerar arquivos de configuração","Compatibilidade com o MCM Helper","Edição de mods para o jogo Skyrim","Geração de arquivos de configuração para menus de configuração de mods"],"ru":["Создание файлов конфигурации JSON для модов Skyrim","Использование Spooky''s AutoMod Toolkit для генерации файлов конфигурации","Совместимость с MCM Helper","Редактирование модов для игры Skyrim","Генерация файлов конфигурации для меню настроек модов"],"ar":["إنشاء ملفات تكوين جيسون للمودات الخاصة بلعبة سكاي ريم","استخدام أداة أوتومود من سبوكي لإنشاء ملفات تكوين","التوافق مع مساعد إم سي إم","تحرير المودات الخاصة بلعبة سكاي ريم","إنشاء ملفات تكوين لمنús إعدادات المودات"]},"keywords":{"en":["how to use skyrim-mcm","skyrim-mcm setup guide","MCM Helper configuration","Spooky''s AutoMod Toolkit","skyrim modding tools","skyrim-mcm alternative","skyrim-mcm install","MCM Helper tutorial","Skyrim Special Edition modding"],"zh":["Skyrim MCM","AI工具","游戏模组","Spooky''s AutoMod Toolkit","MCM Helper","JSON配置文件","游戏开发","模组开发"],"ja":["Skyrim MCM","AIエージェント","ゲームモッド","Spooky''s AutoMod Toolkit","MCM Helper","JSON設定ファイル","ゲーム開発","モッド開発"],"ko":["Skyrim MCM","AI 에이전트","게임 모드","Spooky''s AutoMod Toolkit","MCM Helper","JSON 설정 파일","게임 개발","모드 개발"],"es":["skyrim-mcm","MCM Helper","Spooky''s AutoMod Toolkit","mods de Skyrim","configuración de mods","generación de archivos JSON","herramientas de línea de comandos","desarrollo de mods","Skyrim especial"],"fr":["skyrim-mcm","MCM Helper","Spooky''s AutoMod Toolkit","mods Skyrim","configuration de mods","génération de fichiers JSON","outils de ligne de commande","développement de mods","Skyrim spéciale"],"de":["skyrim-mcm","MCM Helper","Spooky''s AutoMod Toolkit","Skyrim-Mods","Mod-Konfiguration","Generierung von JSON-Dateien","Kommandozeilen-Tools","Mod-Entwicklung","Skyrim Spezialversion"],"pt":["skyrim mcm","mods de skyrim","spooky''s automod toolkit","mcm helper","arquivos de configuração json","criação de mods","edição de mods","jogo skyrim","desenvolvimento de mods"],"ru":["skyrim mcm","моды для skyrim","spooky''s automod toolkit","mcm helper","файлы конфигурации json","создание модов","редактирование модов","игра skyrim","разработка модов"],"ar":["سكاي ريم إم سي إم","مودات سكاي ريم","أداة أوتومود من سبوكي","مساعد إم سي إم","ملفات تكوين جيسون","إنشاء مودات","تحرير مودات","لعبة سكاي ريم","تطوير المودات"]}},"owner":"SpookyPirate","repo":"spookys-automod-toolkit","repoPath":"SpookyPirate/spookys-automod-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"skyrim-mcm","description":"Create and edit MCM Helper configuration files for mod settings menus. Use when the user wants to add in-game settings, configuration options, toggles, sliders, or dropdowns to their mod.","bodyPreview":"# Skyrim MCM Module\n\nCreate and edit MCM Helper configuration files for in-game mod settings menus using Spooky''s AutoMod Toolkit.\n\n## Prerequisites\n\nRun all commands from the toolkit directory:\n```bash\ncd \"<TOOLKIT_PATH>\"\n# Example: cd \"C:\\Tools\\spookys-automod-toolkit\"\n```\n\n## Overview\n\nMCM (Mod Configuration Menu) allows mods to have in-game settings menus. This module generates JSON configuration files compatible with [MCM Helper](https://www.nexusmods.com/skyrimspecialedition/mods/53000).","body":"# Skyrim MCM Module\n\nCreate and edit MCM Helper configuration files for in-game mod settings menus using Spooky''s AutoMod Toolkit.\n\n## Prerequisites\n\nRun all commands from the toolkit directory:\n```bash\ncd \"<TOOLKIT_PATH>\"\n# Example: cd \"C:\\Tools\\spookys-automod-toolkit\"\n```\n\n## Overview\n\nMCM (Mod Configuration Menu) allows mods to have in-game settings menus. This module generates JSON configuration files compatible with [MCM Helper](https://www.nexusmods.com/skyrimspecialedition/mods/53000).\n\n## Command Reference\n\n### Create MCM Configuration\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm create \"<modName>\" \"<displayName>\" --output \"<file>\"\n```\n| Option | Description |\n|--------|-------------|\n| `<modName>` | Internal mod name (no spaces, used for file paths) |\n| `<displayName>` | Display name shown in MCM menu |\n| `--output`, `-o` | Output file path |\n\n### Get MCM Info\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm info \"<config>\"\n```\n\n### Validate MCM Configuration\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm validate \"<config>\"\n```\n\n### Add Toggle (Checkbox)\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"<config>\" \"<id>\" \"<text>\" [options]\n```\n| Option | Description |\n|--------|-------------|\n| `<config>` | Path to config.json |\n| `<id>` | Control identifier (e.g., `bEnabled`) |\n| `<text>` | Display text |\n| `--help-text` | Help text shown on hover |\n| `--page` | Target page name |\n\n### Add Slider\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"<config>\" \"<id>\" \"<text>\" --min <n> --max <n> [options]\n```\n| Option | Default | Description |\n|--------|---------|-------------|\n| `<config>` | Required | Path to config.json |\n| `<id>` | Required | Control identifier (e.g., `fDamage`) |\n| `<text>` | Required | Display text |\n| `--min` | 0 | Minimum value |\n| `--max` | 100 | Maximum value |\n| `--step` | 1 | Step increment |\n\n## Common Workflows\n\n### Create Basic Mod Settings\n```bash\n# 1. Create the MCM config\ndotnet run --project src/SpookysAutomod.Cli -- mcm create \"MyMod\" \"My Awesome Mod\" --output \"./MCM/config/MyMod/config.json\"\n\n# 2. Add an enable toggle\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config/MyMod/config.json\" \"bEnabled\" \"Enable Mod\" --help-text \"Turn the mod on or off\"\n\n# 3. Add a debug toggle\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config/MyMod/config.json\" \"bDebugMode\" \"Debug Mode\" --help-text \"Show debug messages\"\n\n# 4. Add a damage multiplier slider\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"./MCM/config/MyMod/config.json\" \"fDamageMultiplier\" \"Damage Multiplier\" --min 0.5 --max 3.0 --step 0.1\n\n# 5. Validate the configuration\ndotnet run --project src/SpookysAutomod.Cli -- mcm validate \"./MCM/config/MyMod/config.json\"\n```\n\n### Create Multi-Page Settings\n```bash\n# Create config\ndotnet run --project src/SpookysAutomod.Cli -- mcm create \"MyMod\" \"My Mod\" --output \"./MCM/config.json\"\n\n# Add controls to \"General\" page (default)\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config.json\" \"bEnabled\" \"Enable Mod\"\n\n# Add controls to \"Combat\" page\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"./MCM/config.json\" \"fDamage\" \"Damage Bonus\" --min 0 --max 100 --page \"Combat\"\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config.json\" \"bCritical\" \"Enable Criticals\" --page \"Combat\"\n\n# Add controls to \"Magic\" page\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"./MCM/config.json\" \"fSpellCost\" \"Spell Cost Reduction\" --min 0 --max 50 --page \"Magic\"\n```\n\n### Validate and Check Existing MCM\n```bash\n# Check MCM structure\ndotnet run --project src/SpookysAutomod.Cli -- mcm info \"./MCM/config/SomeMod/config.json\"\n\n# Validate for errors\ndotnet run --project src/SpookysAutomod.Cli -- mcm validate \"./MCM/config/SomeMod/config.json\"\n```\n\n## MCM Helper Integration\n\n### Required File Structure\nMCM Helper expects files in specific locations:\n```\nData/\n  MCM/\n    config/\n      MyMod/\n        config.json     # Main config (required)\n        settings.ini    # Default values (optional)\n    translations/\n      MyMod_english.txt # Translations (optional)\n```\n\n### Config JSON Format\nGenerated config.json structure:\n```json\n{\n  \"modName\": \"MyMod\",\n  \"displayName\": \"My Awesome Mod\",\n  \"minMcmVersion\": 7,\n  \"pages\": [\n    {\n      \"pageDisplayName\": \"Main\",\n      \"content\": [\n        {\n          \"type\": \"toggle\",\n          \"id\": \"bEnabled\",\n          \"text\": \"Enable Mod\"\n        },\n        {\n          \"type\": \"slider\",\n          \"id\": \"fDamage\",\n          \"text\": \"Damage Multiplier\",\n          \"min\": 0.5,\n          \"max\": 2.0,\n          \"step\": 0.1\n        }\n      ]\n    }\n  ]\n}\n```\n\n### Control Types\n\n| Type | Description | Properties |\n|------|-------------|------------|\n| toggle | Checkbox | id, text, help |\n| slider | Value slider | id, text, min, max, step |\n| dropdown | Dropdown list | id, text, options |\n| keymap | Key binding | id, text |\n| text | Text input | id, text |\n\n### Linking MCM to Scripts\n\nMCM values are stored as GlobalVariables in your plugin:\n```papyrus\nScriptName MyMod_ConfigScript extends Quest\n\n; These must match the MCM control IDs\nGlobalVariable Property bEnabled Auto\nGlobalVariable Property fDamageMultiplier Auto\n\nFunction ApplySettings()\n    If bEnabled.GetValue() == 1\n        float damage = fDamageMultiplier.GetValue()\n        ; Apply settings...\n    EndIf\nEndFunction\n```\n\n## Naming Conventions\n\n### Control IDs\nFollow Hungarian notation for clarity:\n- `bSomething` - Boolean toggles\n- `fSomething` - Float sliders\n- `iSomething` - Integer values\n- `sSomething` - String values\n\n### Examples\n- `bEnabled` - Main enable toggle\n- `bDebugMode` - Debug mode toggle\n- `fDamageMultiplier` - Damage multiplier (float)\n- `iItemCount` - Item count (integer)\n- `fSpellCostReduction` - Spell cost reduction percentage\n\n## Important Notes\n\n1. **MCM Helper required** - Users must have MCM Helper installed\n2. **GlobalVariables must exist** - Create matching globals in your plugin\n3. **File location matters** - Place config in `Data/MCM/config/ModName/`\n4. **Validate before release** - Always run validate command\n5. **Use `--json` flag** for machine-readable output when scripting\n\n## Complete MCM + Plugin Workflow (Basic)\n\n```bash\n# 1. Create the plugin\ndotnet run --project src/SpookysAutomod.Cli -- esp create \"MyConfigMod.esp\" --light\n\n# 2. Add globals that match MCM controls\ndotnet run --project src/SpookysAutomod.Cli -- esp add-global \"MyConfigMod.esp\" \"bEnabled\" --type long --value 1\ndotnet run --project src/SpookysAutomod.Cli -- esp add-global \"MyConfigMod.esp\" \"fDamageMultiplier\" --type float --value 1.0\n\n# 3. Create MCM config\ndotnet run --project src/SpookysAutomod.Cli -- mcm create \"MyConfigMod\" \"My Config Mod\" --output \"./MCM/config/MyConfigMod/config.json\"\n\n# 4. Add matching controls\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config/MyConfigMod/config.json\" \"bEnabled\" \"Enable Mod\"\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"./MCM/config/MyConfigMod/config.json\" \"fDamageMultiplier\" \"Damage Multiplier\" --min 0.5 --max 2.0 --step 0.1\n\n# 5. Validate\ndotnet run --project src/SpookysAutomod.Cli -- mcm validate \"./MCM/config/MyConfigMod/config.json\"\n```\n\n## Complete MCM + Script Workflow with Auto-Fill\n```bash\n# 1. Create the plugin and quest\ndotnet run --project src/SpookysAutomod.Cli -- esp create \"MyConfigMod.esp\" --light\ndotnet run --project src/SpookysAutomod.Cli -- esp add-quest \"MyConfigMod.esp\" \"MyConfigQuest\" --start-enabled\n\n# 2. Add globals that match MCM controls\ndotnet run --project src/SpookysAutomod.Cli -- esp add-global \"MyConfigMod.esp\" \"bEnabled\" --type long --value 1\ndotnet run --project src/SpookysAutomod.Cli -- esp add-global \"MyConfigMod.esp\" \"fDamageMultiplier\" --type float --value 1.0\ndotnet run --project src/SpookysAutomod.Cli -- esp add-global \"MyConfigMod.esp\" \"bDebugMode\" --type long --value 0\n\n# 3. Create script that references these globals\ncat > \"./Scripts/Source/MyConfigScript.psc\" << ''EOF''\nScriptName MyConfigScript extends Quest\n\nGlobalVariable Property bEnabled Auto\nGlobalVariable Property fDamageMultiplier Auto\nGlobalVariable Property bDebugMode Auto\n\nEvent OnInit()\n    RegisterForSingleUpdate(1.0)\nEndEvent\n\nEvent OnUpdate()\n    If bEnabled.GetValue() == 1\n        float mult = fDamageMultiplier.GetValue()\n        If bDebugMode.GetValue() == 1\n            Debug.Notification(\"Damage multiplier: \" + mult)\n        EndIf\n    EndIf\n    RegisterForSingleUpdate(5.0)\nEndEvent\nEOF\n\n# 4. Compile script\ndotnet run --project src/SpookysAutomod.Cli -- papyrus compile \"./Scripts/Source/MyConfigScript.psc\" --output \"./Scripts\" --headers \"./skyrim-script-headers\"\n\n# 5. Attach script to quest\ndotnet run --project src/SpookysAutomod.Cli -- esp attach-script \"MyConfigMod.esp\" --quest \"MyConfigQuest\" --script \"MyConfigScript\"\n\n# 6. Auto-fill script properties from PSC (links globals automatically!)\ndotnet run --project src/SpookysAutomod.Cli -- esp auto-fill \"MyConfigMod.esp\" --quest \"MyConfigQuest\" --script \"MyConfigScript\" --psc-file \"./Scripts/Source/MyConfigScript.psc\" --data-folder \"C:/Skyrim/Data\"\n\n# Output:\n# Filled property ''bEnabled'' with MyConfigMod.esp:0x000800\n# Filled property ''fDamageMultiplier'' with MyConfigMod.esp:0x000801\n# Filled property ''bDebugMode'' with MyConfigMod.esp:0x000802\n\n# 7. Create MCM config\ndotnet run --project src/SpookysAutomod.Cli -- mcm create \"MyConfigMod\" \"My Config Mod\" --output \"./MCM/config/MyConfigMod/config.json\"\n\n# 8. Add matching MCM controls\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config/MyConfigMod/config.json\" \"bEnabled\" \"Enable Mod\"\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-slider \"./MCM/config/MyConfigMod/config.json\" \"fDamageMultiplier\" \"Damage Multiplier\" --min 0.5 --max 2.0 --step 0.1\ndotnet run --project src/SpookysAutomod.Cli -- mcm add-toggle \"./MCM/config/MyConfigMod/config.json\" \"bDebugMode\" \"Debug Mode\"\n\n# 9. Validate MCM\ndotnet run --project src/SpookysAutomod.Cli -- mcm validate \"./MCM/config/MyConfigMod/config.json\"\n\n# 10. Generate SEQ file (required for start-enabled quest)\ndotnet run --project src/SpookysAutomod.Cli -- esp generate-seq \"MyConfigMod.esp\" --output \"./SEQ\"\n```\n\n**Why This Workflow Matters:**\n- Auto-fill automatically links the GlobalVariable properties in your script to the actual globals in your plugin\n- No manual property filling in Creation Kit required\n- Type-safe matching ensures correct globals are linked\n- Works with your own plugin''s globals, not just vanilla Skyrim records\n\n## JSON Output\n\nAll commands support `--json` for structured output:\n```bash\ndotnet run --project src/SpookysAutomod.Cli -- mcm info \"./config.json\" --json\n```\n"},"lastSynced":"2026-03-08T02:01:04.603Z","agentAnalysis":{"suitability":{"en":"Perfect for Gaming Agents specializing in Skyrim mod development, requiring advanced JSON configuration file generation for MCM Helper compatibility.","zh":"非常适合专门从事上古卷轴模组开发的游戏代理，需要高级JSON配置文件生成以兼容MCM Helper。","ja":"Skyrimモッド開発を専門とするゲームエージェントに最適で、MCM Helperとの互換性を確保するために高度なJSON設定ファイルの生成が必要です。","ko":"스카이림 모드 개발을 전문으로 하는 게임 에이전트에게 적합하며, MCM Helper와의 호환성을 위해 고급 JSON 구성 파일 생성이 필요합니다.","es":"Perfecto para Agentes de Juegos especializados en desarrollo de mods de Skyrim, que requieren la generación avanzada de archivos de configuración JSON para la compatibilidad con MCM Helper.","fr":"Parfait pour les Agents de Jeu spécialisés dans le développement de mods Skyrim, nécessitant la génération avancée de fichiers de configuration JSON pour la compatibilité avec MCM Helper.","de":"Perfekt für Gaming-Agenten, die auf Skyrim-Mod-Entwicklung spezialisiert sind und erweiterte JSON-Konfigurationsdatei-Generierung für MCM-Helper-Kompatibilität erfordern.","pt":"Perfeito para Agentes de Jogos especializados em desenvolvimento de mods do Skyrim, que exigem geração avançada de arquivos de configuração JSON para compatibilidade com o MCM Helper.","ru":"Идеально подходит для Игровых Агентов, специализирующихся на разработке модов для Skyrim, требующих продвинутой генерации файлов конфигурации JSON для совместимости с MCM Helper.","ar":"مثالي لعميل الألعاب المتخصص في تطوير mods.skyrim الذي يتطلب توليد ملفات تكوين JSON متقدمة لتوافق MCM Helper."},"recommendation":{"en":"Empowers agents to create and edit Skyrim mods by generating JSON configuration files compatible with MCM Helper, utilizing Spooky''s AutoMod Toolkit for in-game mod settings menus, and leveraging JSON file formats for seamless integration.","zh":"赋予代理创建和编辑上古卷轴模组的能力，通过生成兼容MCM Helper的JSON配置文件，利用Spooky''s AutoMod Toolkit进行游戏内模组设置菜单，并利用JSON文件格式实现无缝集成。","ja":"エージェントがSkyrimモッドを作成および編集できるようにし、MCM Helperと互換性のあるJSON設定ファイルを生成し、Spooky''s AutoMod Toolkitを使用してゲーム内のモッド設定メニューを作成し、JSONファイル形式を使用してシームレスに統合します。","ko":"에이전트가 스카이림 모드를 생성하고 편집할 수 있도록 하며, MCM Helper와 호환되는 JSON 구성 파일을 생성하고, Spooky''s AutoMod Toolkit을 사용하여 게임 내 모드 설정 메뉴를 생성하며, JSON 파일 형식을 사용하여 무중단 통합을 구현합니다.","es":"Habilita a los agentes a crear y editar mods de Skyrim mediante la generación de archivos de configuración JSON compatibles con MCM Helper, utilizando Spooky''s AutoMod Toolkit para menús de configuración de mods en el juego y aprovechando los formatos de archivo JSON para una integración fluida.","fr":"Permet aux agents de créer et de modifier des mods Skyrim en générant des fichiers de configuration JSON compatibles avec MCM Helper, en utilisant Spooky''s AutoMod Toolkit pour les menus de configuration de mods dans le jeu et en exploitant les formats de fichier JSON pour une intégration fluide.","de":"Ermächtigt Agenten, Skyrim-Mods zu erstellen und zu bearbeiten, indem sie JSON-Konfigurationsdateien generieren, die mit MCM Helper kompatibel sind, Spooky''s AutoMod Toolkit für Mod-Settings-Menüs im Spiel verwenden und JSON-Dateiformate für eine nahtlose Integration nutzen.","pt":"Habilita os agentes a criar e editar mods do Skyrim, gerando arquivos de configuração JSON compatíveis com o MCM Helper, utilizando o Spooky''s AutoMod Toolkit para menus de configuração de mods dentro do jogo e aproveitando formatos de arquivo JSON para integração sem problemas.","ru":"Наделяет агентов возможностью создавать и редактировать моды для Skyrim, генерируя файлы конфигурации JSON, совместимые с MCM Helper, используя Spooky''s AutoMod Toolkit для меню настроек модов внутри игры и использует форматы файлов JSON для бесшовной интеграции.","ar":"يُمكن العميل من إنشاء وتحرير mods.skyrim من خلال توليد ملفات تكوين JSON متوافقة مع MCM Helper، واستخدام Spooky''s AutoMod Toolkit من أجل قوائم إعدادات المودات داخل اللعبة، وتحقيق التكامل السلس باستخدام صيغ ملفات JSON."},"useCases":{"en":["Generating MCM Helper configuration files","Editing Skyrim mod settings menus","Creating in-game mod settings using Spooky''s AutoMod Toolkit"],"zh":["生成MCM Helper配置文件","编辑上古卷轴模组设置菜单","使用Spooky''s AutoMod Toolkit创建游戏内模组设置"],"ja":["MCM Helper設定ファイルの生成","Skyrimモッド設定メニューの編集","Spooky''s AutoMod Toolkitを使用したゲーム内のモッド設定の作成"],"ko":["MCM Helper 구성 파일 생성","스카이림 모드 설정 메뉴 편집","Spooky''s AutoMod Toolkit을 사용한 게임 내 모드 설정 생성"],"es":["Generación de archivos de configuración de MCM Helper","Edición de menús de configuración de mods de Skyrim","Creación de configuraciones de mods en el juego mediante Spooky''s AutoMod Toolkit"],"fr":["Génération de fichiers de configuration MCM Helper","Édition de menus de configuration de mods Skyrim","Création de configurations de mods dans le jeu à l''aide de Spooky''s AutoMod Toolkit"],"de":["Generierung von MCM-Helper-Konfigurationsdateien","Bearbeitung von Skyrim-Mod-Settings-Menüs","Erstellung von Mod-Settings im Spiel mithilfe von Spooky''s AutoMod Toolkit"],"pt":["Geração de arquivos de configuração do MCM Helper","Edição de menus de configuração de mods do Skyrim","Criação de configurações de mods dentro do jogo usando o Spooky''s AutoMod Toolkit"],"ru":["Генерация файлов конфигурации MCM Helper","Редактирование меню настроек модов Skyrim","Создание настроек модов внутри игры с помощью Spooky''s AutoMod Toolkit"],"ar":["توليد ملفات تكوين MCM Helper","تحرير قوائم إعدادات mods.skyrim","إنشاء إعدادات المودات داخل اللعبة باستخدام Spooky''s AutoMod Toolkit"]},"limitations":{"en":["Requires Spooky''s AutoMod Toolkit","MCM Helper compatibility only","JSON configuration file generation limited to Skyrim mods"],"zh":["需要Spooky''s AutoMod Toolkit","仅兼容MCM Helper","JSON配置文件生成仅限于上古卷轴模组"],"ja":["Spooky''s AutoMod Toolkitが必要","MCM Helperのみと互換性がある","JSON設定ファイルの生成はSkyrimモッドのみに制限される"],"ko":["Spooky''s AutoMod Toolkit 필요","MCM Helper만 호환","JSON 구성 파일 생성은 스카이림 모드에만 제한됨"],"es":["Requiere Spooky''s AutoMod Toolkit","Compatibilidad solo con MCM Helper","Generación de archivos de configuración JSON limitada a mods de Skyrim"],"fr":["Nécessite Spooky''s AutoMod Toolkit","Compatibilité uniquement avec MCM Helper","Génération de fichiers de configuration JSON limitée aux mods Skyrim"],"de":["Benötigt Spooky''s AutoMod Toolkit","Kompatibilität nur mit MCM Helper","Generierung von JSON-Konfigurationsdateien auf Skyrim-Mods beschränkt"],"pt":["Exige o Spooky''s AutoMod Toolkit","Compatibilidade apenas com o MCM Helper","Geração de arquivos de configuração JSON limitada a mods do Skyrim"],"ru":["Требует Spooky''s AutoMod Toolkit","Совместимость только с MCM Helper","Генерация файлов конфигурации JSON ограничена модами для Skyrim"],"ar":["يتطلب Spooky''s AutoMod Toolkit","التوافق فقط مع MCM Helper","التوليد المحدود لملفات تكوين JSON لmods.skyrim"]},"version":4},"contentHash":"4016153533ab400da404d4e59036b2ff4fb628159e046a30092ad72f9e076cd2","qualityScore":57}');
