INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SpookyPirate/spookys-automod-toolkit/skyrim-mcm', 'skyrim-mcm', 'SpookyPirate', 'spookys-automod-toolkit', 'community', 'skyrim-mcm SpookyPirate spookys-automod-toolkit community The skyrim-mcm skill assists LLMs in creating and editing Skyrim mods by generating JSON configuration files compatible with MCM Helper. This benefits developers and modders working with Skyrim mods. Skyrim MCM是一个用于创建和编辑游戏模组配置文件的工具，支持Spooky''s AutoMod Toolkit Skyrim MCMは、ゲームモッドの設定ファイルを作成、編集するために使用されるツールです Skyrim MCM은 게임 모드 설정 파일을 생성하고 편집하는 데 사용되는 도구입니다 Skyrim-mcm es una herramienta para crear y editar configuraciones de MCM Helper para mods de Skyrim. Utiliza Spooky''s AutoMod Toolkit para generar archivos de configuración JSON Skyrim-mcm est un outil pour créer et éditer des configurations MCM Helper pour les mods Skyrim. Il utilise Spooky''s AutoMod Toolkit pour générer des fichiers de configuration JSON Skyrim-mcm ist ein Tool zum Erstellen und Bearbeiten von MCM-Helper-Konfigurationen für Skyrim-Mods. Es verwendet Spooky''s AutoMod Toolkit, um JSON-Konfigurationsdateien zu generieren O módulo Skyrim MCM é uma ferramenta para criar e editar mods para o jogo, utilizando o Spooky''s AutoMod Toolkit para gerar arquivos de configuração JSON. Модуль Skyrim MCM — это инструмент для создания и редактирования модов для игры, использующий Spooky''s AutoMod Toolkit для генерации файлов конфигурации JSON. وحدة سكاي ريم إم سي إم هي أداة لإنشاء وتحرير المودات الخاصة بلعبة، وتستخدم أداة أوتومود من سبوكي لإنشاء ملفات تكوين جيسون. how to use skyrim-mcm skyrim-mcm setup guide MCM Helper configuration Spooky''s AutoMod Toolkit skyrim modding tools skyrim-mcm alternative skyrim-mcm install MCM Helper tutorial Skyrim Special Edition modding Skyrim MCM AI工具 游戏模组 Spooky''s AutoMod Toolkit MCM Helper JSON配置文件 游戏开发 模组开发 Generates JSON configuration files compatible with MCM Helper Utilizes Spooky''s AutoMod Toolkit for mod settings menus Creates MCM Helper configuration files for in-game mod settings Requires running commands from the toolkit directory Supports MCM (Mod Configuration Menu) for in-game settings menus Compatible with Skyrim Special Edition mods skyrim-mcm is a module for creating and editing MCM Helper configuration files for in-game mod settings menus using Spooky''s AutoMod Toolkit');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Gerstep/cybos/gtd', 'community', 'Gerstep', 'cybos', 'Gerstep/cybos', 'gtd', 0, 0, 57, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.846Z', '61c7adb4a70f3e66197fdb3b747d860e475628ccba6c23519a94e5cd5a79c8c6', '{"id":"Gerstep/cybos/gtd","name":"gtd","description":{"en":"The gtd skill automates task execution from GTD.md items, benefiting developers who need to streamline their workflows. It classifies items and plans actions using specific commands like `/cyber-gtd`.","zh":"GTD Runner Skill 是一种自动任务执行工具，支持从 GTD.md 项中提取任务并自动执行","ja":"GTD Runner スキルは、GTD.md 項目からタスクを抽出し自動実行するツールです","ko":"GTD 태스크 자동 실행 스킬은 GTD.md 항목에서 태스크를 추출하여 자동으로 실행합니다","es":"GTD es una habilidad que permite la ejecución autónoma de tareas desde GTD.md. Lee y ejecuta tareas de forma secuencial","fr":"GTD est une compétence qui permet l''exécution autonome de tâches depuis GTD.md. Lit et exécute des tâches de manière séquentielle","de":"GTD ist eine Fähigkeit, die die autonome Ausführung von Aufgaben von GTD.md ermöglicht. Liest und führt Aufgaben sequenziell aus","pt":"O GTD Runner é uma habilidade que executa tarefas de forma autônoma a partir de itens do GTD.md. Ele classifica e planeja ações para cada item.","ru":"GTD Runner - это навык, который выполняет задачи автономно из элементов GTD.md. Он классифицирует и планирует действия для каждого элемента.","ar":"GTD Runner هو مهارة تقوم بتشغيل المهام تلقائيًا من عناصر GTD.md. وهي تصنف و تخطط الإجراءات لكل عنصر."},"seo":{"title":{"en":"gtd: Autonomous Task Execution Setup Guide | AI Agent Skill","zh":"GTD 自动任务执行设置指南","ja":"GTD Runner スキルの使い方とベストプラクティス","ko":"GTD 태스크 자동 실행 가이드","es":"Guía de configuración de GTD: Ejecución autónoma de tareas","fr":"Guide de configuration GTD : Exécution autonome de tâches","de":"GTD-Setup-Leitfaden: Autonome Aufgaben-Ausführung","pt":"Guia de Configuração do 