INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Gerstep/cybos/gtd', 'gtd', 'Gerstep', 'cybos', 'community', 'gtd Gerstep cybos community The gtd skill automates task execution from GTD.md items, benefiting developers who need to streamline their workflows. It classifies items and plans actions using specific commands like `/cyber-gtd`. GTD Runner Skill 是一种自动任务执行工具，支持从 GTD.md 项中提取任务并自动执行 GTD Runner スキルは、GTD.md 項目からタスクを抽出し自動実行するツールです GTD 태스크 자동 실행 스킬은 GTD.md 항목에서 태스크를 추출하여 자동으로 실행합니다 GTD es una habilidad que permite la ejecución autónoma de tareas desde GTD.md. Lee y ejecuta tareas de forma secuencial GTD est une compétence qui permet l''exécution autonome de tâches depuis GTD.md. Lit et exécute des tâches de manière séquentielle GTD ist eine Fähigkeit, die die autonome Ausführung von Aufgaben von GTD.md ermöglicht. Liest und führt Aufgaben sequenziell aus O GTD Runner é uma habilidade que executa tarefas de forma autônoma a partir de itens do GTD.md. Ele classifica e planeja ações para cada item. GTD Runner - это навык, который выполняет задачи автономно из элементов GTD.md. Он классифицирует и планирует действия для каждого элемента. GTD Runner هو مهارة تقوم بتشغيل المهام تلقائيًا من عناصر GTD.md. وهي تصنف و تخطط الإجراءات لكل عنصر. how to use gtd gtd setup guide gtd alternative gtd vs todo list autonomous task execution GTD.md file format bun scripts database integration cyber-gtd command GTD Runner Skill 自动任务执行 GTD.md 数据库查询 CLI 命令 任务自动化 生产力工具 AI エージェント Triggers workflow using the `/cyber-gtd` command Classifies items using pattern matching to workflow Looks up entities via database using `bun scripts/db/query.ts` Plans actions and shows plan before execution Executes approved items sequentially using `~/CybosVault/private/content/work/M` output gtd is an AI agent skill that enables autonomous task execution from GTD.md items, using a workflow that includes reading, classifying, and planning actions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Synthesys-Lab/assassyn/open-pr', 'community', 'Synthesys-Lab', 'assassyn', 'Synthesys-Lab/assassyn', 'open-pr', 0, 0, 57, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:05.109Z', '3f56e2d7106c7c47364c7a2db06366c392d1c7a0b097c45eb7834aa80a9990dd', '{"id":"Synthesys-Lab/assassyn/open-pr","name":"open-pr","description":{"en":"The open-pr skill enables AI agents to create GitHub pull requests with conversation context. It extracts PR details and confirms with users before creation.","zh":"Open PR 技术允许 AI 代理从对话上下文创建 GitHub Pull Request，具有有意义的标题、适当的格式和标签选择","ja":"Open PR 技術により、AI エージェントは会話のコンテキストから GitHub Pull Request を生成できます","ko":"Open PR 기술을 통해 AI 에이전트는 대화 문脈에서 GitHub Pull Request를 생성할 수 있습니다","es":"Open-pr es una habilidad que permite a los agentes de inteligencia artificial crear solicitudes de extracción en GitHub de forma asíncrona con títulos significativos y formato adecuado","fr":"Open-pr est une compétence qui permet aux outils d''intelligence artificielle de créer des demandes de tirage sur GitHub de manière asynchrone avec des titres significatifs et un format adapté","de":"Open-pr ist eine Fähigkeit, die es KI-Agents ermöglicht, Pull-Requests auf GitHub asynchron mit sinnvollen Titeln und geeigneter Formatierung zu erstellen","pt":"O open-pr é uma habilidade que permite criar solicitações de pull no GitHub de forma assíncrona com títulos significativos e formatação adequada","ru":"Открытый запрос - это навык, позволяющий создавать запросы на GitHub асинхронно с осмысленными заголовками и правильным форматированием","ar":"الطلب المفتوح هو مهارة تتيح إنشاء طلبات سحب على GitHub بشكل غير متزامن مع أسماء ذات معنى وتفاصيل مناسبة"},"seo":{"title":{"en":"open-pr: GitHub Pull Request Automation for AI Agents | A...","zh":"Open PR Setup Guide: GitHub Pull Request 自动化","ja":"Open PR ベストプラクティス: GitHub Pull Request の自動生成","ko":"Open PR 설정 가이드: GitHub Pull Request 자동화","es":"Guía de configuración de open-pr para agentes de intelige...","fr":"Guide de mise en place d''open-pr pour les outils d''intell...","de":"Einrichtungsleitfaden für open-pr in KI-Agents","pt":"Guia de Configuração do Open-PR para Agentes de IA","ru":"Настройка Открытых Запросов для ИИ Агентов","ar":"دليل إعداد_open-pr_لأدوات الذكاء الاصطناعي"},"description":{"en":"Automate GitHub pull requests with open-pr skill. Learn how to create PRs with meaningful titles and proper formatting. Get started now!","zh":"使用 Open PR 技术创建 GitHub Pull Request，实现自动化和高效的代码审查","ja":"Open PR 技術で GitHub Pull Request を自動生成し、コードレビューの効率化を実現","ko":"Open PR 기술을 사용하여 GitHub Pull Request를 자동화하고 코드 리뷰의 효율성을 높입니다","es":"Aprende a crear solicitudes de extracción en GitHub con open-pr y descubre cómo esta habilidad puede mejorar la colaboración en tu equipo de desarrollo","fr":"Découvrez comment créer des demandes de tirage sur GitHub avec open-pr et améliorez la collaboration au sein de votre équipe de développement","de":"Erfahren Sie, wie Sie mit open-pr Pull-Requests auf GitHub erstellen und die Zusammenarbeit in Ihrem Entwicklungsteam verbessern können","pt":"Aprenda a criar solicitações de pull no GitHub com títulos significativos e formatação adequada usando o open-pr","ru":"Мастер создания запросов на GitHub с осмысленными заголовками и правильным форматированием при помощи open-pr","ar":"تعلم كيفية إنشاء طلبات سحب على GitHub بأسماء ذات معنى وتفاصيل مناسبة باستخدام_open-pr"},"definition":{"en":"open-pr is a skill that instructs AI agents on asynchronous semantics for architectural simulation and synthesis, specifically for creating GitHub pull requests.","zh":"Open PR 是一种允许 AI 代理创建 GitHub Pull Request 的技术","ja":"Open PR は、AI エージェントが GitHub Pull Request を生成できる技術です","ko":"Open PR는 AI 에이전트가 GitHub Pull Request를 생성할 수 있는 기술입니다","es":"Open-pr es una habilidad de inteligencia artificial que permite la creación automática de solicitudes de extracción en GitHub","fr":"Open-pr est une compétence d''intelligence artificielle qui permet la création automatique de demandes de tirage sur GitHub","de":"Open-pr ist eine KI-Fähigkeit, die die automatische Erstellung von Pull-Requests auf GitHub ermöglicht","pt":"O que é open-pr? É uma habilidade de agentes de IA para criar solicitações de pull no GitHub de forma automatizada","ru":"Что такое открытый запрос? Это навык ИИ агентов для автоматического создания запросов на GitHub","ar":"ما هو_open-pr؟ إنه مهارة لأدوات الذكاء الاصطناعي لإنشاء طلبات سحب على GitHub بشكل آلي"},"features":{"en":["Creates GitHub pull requests with meaningful titles and proper formatting","Extracts PR details from conversation context","Confirms with users before creating pull requests","Follows a specific structure for PR creation, including tags and issue numbers","Uses Markdown formatting for PR descriptions","Supports tag selection and issue number inclusion"],"zh":["自动创建 GitHub Pull Request","从对话上下文提取 PR 详情","确认用户输入后创建 PR","支持特定格式的 PR 标题和描述","自动标签选择和添加"],"ja":["GitHub Pull Request の自動生成","会話のコンテキストから PR の詳細を抽出","ユーザーの入力確認後に PR を生成","特定の形式の PR タイトルと説明のサポート","自動的なラベル選択と追加"],"ko":["GitHub Pull Request 자동 생성","대화 문脈에서 PR 세부 정보 추출","사용자 입력 확인 후 PR 생성","특정 형식의 PR 제목 및 설명 지원","자동 라벨 선택 및 추가"],"es":["Creación asíncrona de solicitudes de extracción en GitHub","Títulos significativos y formato adecuado para las solicitudes de extracción","Selección adecuada de etiquetas para las solicitudes de extracción","Confirmación con el usuario antes de crear la solicitud de extracción","Compatibilidad con la estructura de solicitud de extracción de GitHub","Análisis del contexto de la conversación para extraer detalles de la solicitud de extracción"],"fr":["Création asynchrone de demandes de tirage sur GitHub","Titres significatifs et format adapté pour les demandes de tirage","Sélection appropriée d''étiquettes pour les demandes de tirage","Confirmation avec l''utilisateur avant de créer la demande de tirage","Compatibilité avec la structure de demande de tirage de GitHub","Analyse du contexte de la conversation pour extraire les détails de la demande de tirage"],"de":["Asynchrone Erstellung von Pull-Requests auf GitHub","Sinnvolle Titel und geeignete Formatierung für Pull-Requests","Adequate Auswahl von Tags für Pull-Requests","Bestätigung mit dem Benutzer vor der Erstellung des Pull-Requests","Kompatibilität mit der Pull-Request-Struktur von GitHub","Analyse des Konversationskontexts zur Extraktion von Pull-Request-Details"],"pt":["Criação de solicitações de pull no GitHub com títulos significativos","Formatação adequada de solicitações de pull","Seleção apropriada de etiquetas para solicitações de pull","Análise de contexto de conversa para extração de detalhes de solicitação de pull","Confirmação com o usuário antes de criar a solicitação de pull"],"ru":["Создание запросов на GitHub с осмысленными заголовками","Правильное форматирование запросов на GitHub","Умная выборка тегов для запросов на GitHub","Анализ контекста разговора для извлечения деталей запроса на GitHub","Подтверждение с пользователем перед созданием запроса на GitHub"],"ar":["إنشاء طلبات سحب على GitHub بأسماء ذات معنى","تنسيق طلبات سحب على GitHub بشكل مناسب","اختيار مناسب للعلامات لطلبات السحب","تحليل سياق المحادثة لاستخراج تفاصيل طلب السحب","التأكيد مع المستخدم قبل إنشاء طلب السحب"]},"keywords":{"en":["how to use open-pr","what is open-pr","open-pr alternative","open-pr vs GitHub API","open-pr install","open-pr setup guide","GitHub pull request automation","AI agent skills for GitHub","asynchronous semantics for architectural simulation"],"zh":["Open PR","GitHub Pull Request","AI 代理","代码审查","自动化","效率化","代码管理","版本控制","协作开发"],"ja":["Open PR","GitHub Pull Request","AI エージェント","コードレビュー","自動化","効率化","コード管理","バージョン管理","コラボレーション開発"],"ko":["Open PR","GitHub Pull Request","AI 에이전트","코드 리뷰","자동화","효율성","코드 관리","버전 관리","협업 개발"],"es":["open-pr","agentes de inteligencia artificial","solicitudes de extracción en GitHub","colaboración en equipo de desarrollo","automatización de procesos de desarrollo","integración con GitHub","desarrollo de software","herramientas de desarrollo","tecnologías de inteligencia artificial"],"fr":["open-pr","outils d''intelligence artificielle","demandes de tirage sur GitHub","collaboration dans l''équipe de développement","automatisation des processus de développement","intégration avec GitHub","développement de logiciels","outils de développement","technologies d''intelligence artificielle"],"de":["open-pr","KI-Agents","Pull-Requests auf GitHub","Zusammenarbeit im Entwicklungsteam","Automatisierung von Entwicklungsprozessen","Integration mit GitHub","Software-Entwicklung","Entwicklertools","Künstliche-Intelligenz-Technologien"],"pt":["open-pr","agentes de IA","solicitações de pull","GitHub","formatação de solicitações de pull","etiquetas para solicitações de pull","análise de contexto de conversa","confirmação de solicitações de pull"],"ru":["открытый запрос","ИИ агенты","запросы на GitHub","форматирование запросов на GitHub","теги для запросов на GitHub","анализ контекста разговора","подтверждение запросов на GitHub"],"ar":["الطلب المفتوح","أدوات الذكاء الاصطناعي","طلبات السحب على GitHub","تنسيق طلبات السحب","اختيار علامات لطلبات السحب","تحليل سياق المحادثة","تأكيد طلبات السحب"]}},"owner":"Synthesys-Lab","repo":"assassyn","repoPath":"Synthesys-Lab/assassyn","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"open-pr","description":"Create GitHub pull requests from conversation context with proper formatting and tag selection","bodyPreview":"# Open PR\n\nThis skill instructs AI agents on how to create GitHub pull requests from conversation context\nwith meaningful titles, proper formatting, and appropriate tag selection. The AI agent\nshould analyze the conversation, extract PR details, and confirm with the user before\ncreating the pull request.\n\n## PR Format\n\nGitHub pull requests created by this skill must follow this exact structure:\n\n```markdown\n# [tag][#issue-number] Brief description of what was achieved\n\n## Summary\n\nProvide a conc","body":"# Open PR\n\nThis skill instructs AI agents on how to create GitHub pull requests from conversation context\nwith meaningful titles, proper formatting, and appropriate tag selection. The AI agent\nshould analyze the conversation, extract PR details, and confirm with the user before\ncreating the pull request.\n\n## PR Format\n\nGitHub pull requests created by this skill must follow this exact structure:\n\n```markdown\n# [tag][#issue-number] Brief description of what was achieved\n\n## Summary\n\nProvide a concise summary of what has been achieved in this PR. Focus on the\ncompleted work and the value it delivers.\n\n## Changes\n\nProvide a detailed list of changes made in this PR:\n- Modified `file_path:line_range` to implement X\n- Added `new_file.py` for Y functionality\n- Updated `config.json` to support Z\n- Removed deprecated code from `old_file.py:line_range`\n\n## Testing\n\nDescribe what was tested and how:\n- Added `tests/test_feature.py` to verify behavior A\n- Modified `tests/test_existing.py:line_range` to cover edge case B\n- Manually tested scenario C with the following steps:\n  1. Step 1\n  2. Step 2\n  3. Expected result\n\n## Related Issue\n\nCloses #issue-number\n\n(Or \"Part of #issue-number\" if this PR partially addresses the issue)\n```\n\n## Tag Selection\n\nA `git-msg-tags.md` file should appear in `{ROOT_PROJ}/docs/git-msg-tags.md` which\ndefines the tags related to the corresponding modules or modifications. The AI agent\n**MUST** refer to this file to select the appropriate tag for the PR title.\n\nIf the file does not exist, reject the PR creation and ask the user to provide a\nlist of tags in `docs/git-msg-tags.md`.\n\n### Tag Logic\n\nThe AI agent must determine which tag to use based on the PR type by reading\n`docs/git-msg-tags.md` which contains the project''s tag definitions.\n\n**Selection guidelines:**\n- Read `docs/git-msg-tags.md` to understand available tags and their meanings\n- Choose the most specific tag that describes the primary change\n- If multiple tags could apply, choose the one that best represents the core purpose\n- If the tag is ambiguous, ask the user to select from 2-3 most relevant options\n\n## Workflow for AI Agents\n\nWhen this skill is invoked, the AI agent **MUST** follow these steps:\n\n### 1. Context Analysis Phase\n\nReview the entire conversation history and git changes to extract PR details:\n- Identify what work was completed during the conversation\n- Review git diff and git status to see actual changes made\n- Extract key details: what was changed, why, which files were affected\n- Determine the type of changes (feature, bugfix, refactor, etc.)\n- Check if there''s a related issue number mentioned in the conversation\n\nContext signals for PR type:\n- Feature signals: new functionality added, new files created, capabilities extended\n- Bugfix signals: fixed error, resolved issue, corrected behavior\n- Refactor signals: improved code structure, reorganized code, better patterns\n- Documentation signals: updated README, added comments, wrote guides\n- Test signals: added test coverage, modified test cases\n\n### 2. Git Changes Review\n\n**CRITICAL:** Before drafting the PR, the AI agent **MUST** review actual git changes:\n\n```bash\n# Check what files have changed\ngit status\n\n# Review the actual changes\ngit diff\n\n# Check commit history on current branch\ngit log origin/main..HEAD --oneline\n```\n\nThis ensures the PR description accurately reflects the actual code changes.\n\n### 3. Tag Selection Phase\n\n- Read `docs/git-msg-tags.md` to understand available tags\n- Analyze the changes and determine the primary purpose\n- Apply the tag logic described above\n- If multiple tags could apply, choose the most specific one\n- If the tag is ambiguous, ask the user to choose from 2-3 most relevant options\n\n### 4. Issue Number Extraction\n\n**CRITICAL:** The PR title **MUST** include an issue number in the format `[tag][#N]`.\n\n**How to find the issue number:**\n1. Search conversation history for explicit issue references:\n   - \"for issue #42\"\n   - \"closes #15\"\n   - \"related to #23\"\n   - GitHub issue URLs containing issue numbers\n\n2. If no issue number is found in conversation:\n   - Check if there are recent issues that match this work:\n     ```bash\n     gh issue list --limit 10\n     ```\n   - Ask the user: \"Which issue does this PR address? (Provide issue number)\"\n\n3. If user says there''s no related issue:\n   - **STOP** and inform the user:\n     ```\n     Cannot create PR without a related issue.\n     Please create an issue first using the open-issue skill, or provide an existing issue number.\n     ```\n\n**Never create a PR without an issue number.**\n\n### 5. PR Draft Construction\n\nBuild the PR following the format specification:\n\n**Title:**\n- Format: `[tag][#issue-number] Brief description`\n- The description should be in past tense (what was achieved)\n- Keep description concise (max 80 characters for the description portion)\n- Example: `[feat][#42] Add TypeScript SDK template support`\n- Example: `[bugfix][#15] Fix pre-commit hook test execution`\n\n**Summary section:**\n- Describe what has been achieved (past tense)\n- Focus on the value and purpose of the changes\n- Keep it concise but meaningful\n\n**Changes section:**\n- List specific files modified, added, or deleted\n- Include line ranges when relevant (e.g., `file.py:12-34`)\n- Describe what each change does\n- Order changes logically (not just alphabetically)\n- **DO NOT** include actual code snippets to save context length\n\n**Testing section:**\n- Describe what was tested\n- List new test files added with what they test\n- List modified test files with what new coverage was added\n- Include manual testing steps if applicable\n- Be specific about test scenarios and expected outcomes\n\n**Related Issue section:**\n- Use `Closes #N` if this PR fully resolves the issue\n- Use `Part of #N` if this PR partially addresses the issue\n- Use `Fixes #N` for bugfix PRs\n- GitHub will automatically link and close the issue when PR is merged\n\n### 6. User Confirmation Phase\n\n**CRITICAL:** The AI agent **MUST** display the complete PR draft to the user\nand wait for explicit confirmation before creating the PR.\n\nPresent the draft in a clear format:\n```\nI''ve prepared this pull request:\n\n---\n[Full PR content here]\n---\n\nShould I create this PR?\n```\n\n- Wait for explicit \"yes\", \"confirm\", \"create it\", or similar affirmative response\n- If the user requests modifications, update the draft and present again\n- If the user declines, abort PR creation gracefully\n\n### 6.5. Remote Branch Verification\n\n**CRITICAL:** Before creating the PR, verify the current branch exists on the remote repository.\n\nCheck if the current branch is tracking a remote branch:\n\n```bash\n# Check if current branch has an upstream branch\ngit rev-parse --abbrev-ref --symbolic-full-name @{u} 2>/dev/null\n```\n\n**If the command fails (no upstream branch):**\n1. Get the current branch name:\n   ```bash\n   git branch --show-current\n   ```\n2. Push the branch with tracking:\n   ```bash\n   git push -u origin <branch-name>\n   ```\n3. Confirm to user: \"Pushed branch to remote: origin/<branch-name>\"\n\n**If the command succeeds (upstream branch exists):**\n1. Check if local is ahead of remote:\n   ```bash\n   git status --porcelain --branch\n   ```\n2. If output contains `[ahead N]`, push changes:\n   ```bash\n   git push\n   ```\n3. If up-to-date, continue to PR creation\n\n**Error handling:**\n- If push fails due to authentication:\n  ```\n  Git push failed. Please check your Git credentials.\n  ```\n- If push fails due to conflicts:\n  ```\n  Cannot push: your branch has diverged from remote.\n  Please resolve conflicts manually with:\n    git pull --rebase origin <branch-name>\n  ```\n- For other push failures: Display the error and abort PR creation\n\n### 7. GitHub PR Creation\n\nOnce confirmed and the branch is on remote, create the PR using the GitHub CLI:\n\n```bash\ngh pr create --title \"TITLE_HERE\" --body \"$(cat <<''EOF''\nBODY_CONTENT_HERE\nEOF\n)\"\n```\n\n**Important:**\n- Use heredoc (`<<''EOF'' ... EOF`) to preserve markdown formatting\n- The body should include all sections from Summary onwards (not the title)\n- The PR will be created against the default branch (usually main/master)\n- After successful creation, display the PR URL to the user\n- Confirm: \"Pull request created successfully: [URL]\"\n\n**Optional flags:**\n- Add `--draft` if the user wants to create a draft PR\n- Add `--base BRANCH` if targeting a different base branch\n\n### 8. Error Handling\n\nHandle common error scenarios gracefully:\n\n**Missing git-msg-tags.md:**\n```\nCannot create PR: docs/git-msg-tags.md not found.\nPlease create this file with your project''s tag definitions.\n```\n\n**No issue number found:**\n```\nCannot create PR: No related issue number found.\n\nPlease either:\n1. Provide the issue number this PR addresses\n2. Create an issue first using the open-issue skill\n```\n\n**No git changes:**\n```\nCannot create PR: No changes detected in the working directory.\nPlease make and commit your changes first.\n```\n\n**GitHub CLI not authenticated:**\n```\nGitHub CLI is not authenticated. Please run:\n  gh auth login\n```\n\n**Not on a feature branch:**\n```\nWarning: You''re on the main/master branch.\nPRs should typically be created from feature branches.\n\nCreate a new branch with:\n  git checkout -b feature/your-feature-name\n\nOr confirm you want to create a PR from the current branch.\n```\n\n**No conversation context:**\n```\nI don''t have enough context to create a PR. Could you please provide:\n- What changes were made?\n- What issue does this PR address?\n- What was tested?\n```\n\n**PR creation failed:**\n```\nFailed to create pull request: [error message]\nPlease check your GitHub CLI configuration and try again.\n```\n\n## Ownership\n\nThe AI agent **SHALL NOT** claim authorship or co-authorship of the pull request.\nThe PR is created on behalf of the user, who is **FULLY** responsible for its content.\n\nDo not add any \"Created by AI\" or similar attributions to the PR body unless\nexplicitly requested by the user.\n\n## Examples\n\n**Note:** The following examples use tags like `[feat]`, `[bugfix]`, `[agent.skill]` etc.\nThese are illustrative only - actual tags must come from your project''s `docs/git-msg-tags.md`.\n\n### Example 1: Feature PR\n\n**Context:** User implemented TypeScript SDK template support to close issue #42.\n\n**PR:**\n```markdown\n# [feat][#42] Add TypeScript SDK template support\n\n## Summary\n\nAdded support for generating TypeScript SDK templates in the agentize project.\nDevelopers can now bootstrap TypeScript-based agent SDKs alongside existing\nPython templates.\n\n## Changes\n\n- Created `templates/typescript/` directory structure with standard layout\n- Added `templates/typescript/package.json` with default dependencies (typescript, @types/node)\n- Created `templates/typescript/tsconfig.json` with recommended compiler settings\n- Added `templates/typescript/src/index.ts` as the SDK entry point\n- Updated `claude/skills/sdk-init/SKILL.md` to include TypeScript as a language option\n- Modified `sdk-init` skill logic to handle TypeScript template generation\n\n## Testing\n\n- Added `tests/test_typescript_template.py` to verify:\n  - Template directory creation\n  - All required files are generated correctly\n  - package.json has correct dependencies\n  - tsconfig.json has proper compiler options\n- Manually tested TypeScript template generation:\n  1. Ran sdk-init skill and selected TypeScript\n  2. Verified generated files compile without errors\n  3. Confirmed npm install works correctly\n  4. Built sample TypeScript SDK successfully\n\n## Related Issue\n\nCloses #42\n```\n\n### Example 2: Bugfix PR\n\n**Context:** User fixed pre-commit hook not running tests (issue #15).\n\n**PR:**\n```markdown\n# [bugfix][#15] Fix pre-commit hook test execution\n\n## Summary\n\nFixed the pre-commit hook to properly execute the test suite before allowing commits.\nThe hook was not running tests due to incorrect path resolution.\n\n## Changes\n\n- Modified `.git/hooks/pre-commit:8-12` to use absolute path for test script\n- Updated hook to check exit code and block commit on test failure\n- Added error message output when tests fail\n\n## Testing\n\n- Modified `tests/test_hooks.py:23-45` to verify pre-commit hook behavior\n- Manually tested the fix:\n  1. Made changes to a Python file in `claude/skills/`\n  2. Ran `git add .` and `git commit -m \"test\"`\n  3. Confirmed tests executed and commit was blocked when tests failed\n  4. Fixed the test failure\n  5. Confirmed commit succeeded after tests passed\n\n## Related Issue\n\nFixes #15\n```\n\n### Example 3: Agent Skill PR\n\n**Context:** User created the open-pr skill (issue #67).\n\n**PR:**\n```markdown\n# [agent.skill][#67] Add open-pr skill for creating pull requests\n\n## Summary\n\nAdded the open-pr skill that guides AI agents through creating well-formatted\nGitHub pull requests with proper tag selection and mandatory issue references.\n\n## Changes\n\n- Created `claude/skills/open-pr/` directory\n- Added `claude/skills/open-pr/SKILL.md` with complete PR creation workflow\n- Skill enforces issue number requirement in PR titles\n- Includes comprehensive examples and error handling guidelines\n\n## Testing\n\n- Added `tests/test_open_pr_skill.py` to verify:\n  - Skill file structure and format\n  - Tag selection logic correctness\n  - Issue number extraction from various formats\n- Manually tested skill workflow:\n  1. Invoked open-pr skill in conversation\n  2. Verified it correctly extracted issue number from context\n  3. Confirmed it generated proper PR format\n  4. Tested error handling for missing issue numbers\n\n## Related Issue\n\nCloses #67\n```\n"},"lastSynced":"2026-03-08T02:01:05.109Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Integration Agents needing automated pull request creation with conversation context.","zh":"适合需要自动创建拉取请求并带有对话上下文的GitHub集成代理。","ja":"会話のコンテキストを使用した自動プルリクエストの作成を必要とするGitHub統合エージェントに適しています。","ko":"대화 문脈을 사용하여 자동으로 풀 리퀘스트를 생성해야 하는 GitHub 통합 에이전트에 적합합니다.","es":"Ideal para agentes de integración de GitHub que necesitan la creación automática de solicitudes de extracción con contexto de conversación.","fr":"Idéal pour les agents d''intégration GitHub nécessitant la création automatisée de demandes d''extraction avec contexte de conversation.","de":"Ideal für GitHub-Integration-Agents, die die automatisierte Erstellung von Pull-Anfragen mit Konversationskontext benötigen.","pt":"Ideal para Agentes de Integração do GitHub que necessitam de criação automática de solicitações de pull com contexto de conversa.","ru":"Идеально для агентов интеграции GitHub, которым требуется автоматизированное создание запросов на включение с контекстом разговора.","ar":"مثالي للوكلاء المتكاملون مع GitHub الذين يحتاجون إلى إنشاء طلبات سحب автомاتيكي مع سياق المحادثة."},"recommendation":{"en":"Empowers agents to create formatted GitHub pull requests with meaningful titles, proper markdown formatting, and appropriate tag selection, utilizing conversation context and confirming with users before creation via GitHub API protocols.","zh":"赋予代理创建格式化的GitHub拉取请求的能力，包括有意义的标题、正确的markdown格式和适当的标签选择，利用会话上下文，并在创建前通过GitHub API协议确认用户。","ja":"会話のコンテキストを利用し、意味のあるタイトル、適切なマークダウン形式、適切なタグの選択を使用して、フォーマットされたGitHubプルリクエストを作成するエージェントを可能にし、また、GitHub APIプロトコルを介して作成前にユーザーに確認します。","ko":"에이전트가 대화 문脈을 사용하여 의미 있는 제목, 올바른 마크다운 형식 및 적절한 태그 선택과 함께 형식화된 GitHub 풀 리퀘스트를 생성할 수 있도록 하며, GitHub API 프로토콜을 통해 생성 전에 사용자에게 확인합니다.","es":"Habilita a los agentes a crear solicitudes de extracción de GitHub formateadas con títulos significativos, formato de markdown adecuado y selección de etiquetas apropiada, utilizando el contexto de la conversación y confirmando con los usuarios antes de la creación a través de los protocolos de la API de GitHub.","fr":"Permet aux agents de créer des demandes d''extraction GitHub formatées avec des titres significatifs, un formatage markdown approprié et une sélection de balises appropriée, en utilisant le contexte de la conversation et en confirmant avec les utilisateurs avant la création via les protocoles de l''API GitHub.","de":"Ermächtigt Agents, formatierte GitHub-Pull-Anfragen mit sinnvollen Titeln, ordnungsgemäßer Markdown-Formatierung und geeigneter Tag-Auswahl zu erstellen, unter Verwendung des Konversationskontexts und durch Bestätigung mit den Benutzern vor der Erstellung über die GitHub-API-Protokolle.","pt":"Habilita os agentes a criar solicitações de pull do GitHub formatadas com títulos significativos, formatação de markdown adequada e seleção de tags apropriada, utilizando o contexto da conversa e confirmando com os usuários antes da criação via protocolos da API do GitHub.","ru":"Наделяет агентов возможностью создавать форматированные запросы на включение в GitHub с осмысленными названиями, правильной форматировкой markdown и подходящим выбором тегов, используя контекст разговора и подтверждая с пользователями перед созданием через протоколы API GitHub.","ar":"يمنح الوكلاء القدرة على إنشاء طلبات سحب GitHub مع تنسيق معني بالألقاب والتنسيق الصحيح لمرك다운 واختيار العلامات المناسبة، باستخدام سياق المحادثة والتحقق من المستخدمين قبل الإنشاء عبر بروتوكولات واجهة برمجة تطبيقات GitHub."},"useCases":{"en":["Automating pull request creation from conversation context","Generating properly formatted pull requests with tags and issue numbers","Streamlining GitHub workflow with automated PR creation and confirmation"],"zh":["从会话上下文自动创建拉取请求","生成带有标签和问题编号的正确格式化的拉取请求","通过自动化的PR创建和确认来简化GitHub工作流"],"ja":["会話のコンテキストから自動的にプルリクエストを作成する","タグや問題番号を付けた適切にフォーマットされたプルリクエストを生成する","自動化されたPRの作成と確認を通じてGitHubのワークフローを効率化する"],"ko":["대화 문脈에서 자동으로 풀 리퀘스트를 생성하는 것","태그와 이슈 번호가 있는 올바른 형식의 풀 리퀘스트를 생성하는 것","자동화된 PR 생성 및 확인을 통해 GitHub 워크플ロー简化"],"es":["Automatización de la creación de solicitudes de extracción a partir del contexto de la conversación","Generación de solicitudes de extracción formateadas con etiquetas y números de problema","Optimización del flujo de trabajo de GitHub con la creación automática de PR y confirmación"],"fr":["Automatisation de la création de demandes d''extraction à partir du contexte de la conversation","Génération de demandes d''extraction formatées avec des balises et des numéros de problème","Optimisation du flux de travail GitHub avec la création automatisée de PR et de confirmation"],"de":["Automatisierung der Erstellung von Pull-Anfragen aus dem Konversationskontext","Generierung ordnungsgemäß formatierter Pull-Anfragen mit Tags und Issues-Nummern","Optimierung des GitHub-Workflows mit automatisierter PR-Erstellung und -Bestätigung"],"pt":["Automatizar a criação de solicitações de pull a partir do contexto da conversa","Gerar solicitações de pull formatadas corretamente com tags e números de problemas","Otimizar o fluxo de trabalho do GitHub com criação automática de PR e confirmação"],"ru":["Автоматизировать создание запросов на включение из контекста разговора","Генерировать правильно форматированные запросы на включение с тегами и номерами задач","Оптимизировать рабочий процесс GitHub с автоматизированным созданием PR и подтверждением"],"ar":["تأتمتة إنشاء طلبات السحب من سياق المحادثة","توليد طلبات سحب مع تنسيق مناسب مع علامات وأرقام المشكلات","تحسين تدفق العمل في GitHub مع إنشاء طلبات سحب 자동اتيكي والتحقق منها"]},"limitations":{"en":["Requires GitHub API access","Limited to GitHub pull requests only","Needs user confirmation before PR creation"],"zh":["需要GitHub API访问","仅限于GitHub拉取请求","需要在PR创建前获得用户确认"],"ja":["GitHub APIへのアクセスが必要","GitHubのプルリクエストのみに限定されている","PRの作成前にユーザーの確認が必要"],"ko":["GitHub API 액세스가 필요함","GitHub 풀 리퀘스트에만 국한됨","PR 생성 이전에 사용자 확인이 필요함"],"es":["Requiere acceso a la API de GitHub","Limitado a solicitudes de extracción de GitHub solamente","Necesita confirmación del usuario antes de la creación de PR"],"fr":["Nécessite un accès à l''API GitHub","Limité aux demandes d''extraction GitHub uniquement","Nécessite une confirmation de l''utilisateur avant la création de PR"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf GitHub-Pull-Anfragen nur","Benötigt Benutzerbestätigung vor der Erstellung von PR"],"pt":["Requer acesso à API do GitHub","Limitado apenas às solicitações de pull do GitHub","Necessita de confirmação do usuário antes da criação da PR"],"ru":["Требует доступа к API GitHub","Ограничен только запросами на включение в GitHub","Требует подтверждения пользователя перед созданием PR"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub","محدود فقط بطلبات السحب في GitHub","يحتاج إلى التحقق من المستخدم قبل إنشاء طلب السحب"]},"version":4},"contentHash":"3f56e2d7106c7c47364c7a2db06366c392d1c7a0b097c45eb7834aa80a9990dd","qualityScore":57}');
