INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Synthesys-Lab/assassyn/open-pr', 'open-pr', 'Synthesys-Lab', 'assassyn', 'community', 'open-pr Synthesys-Lab assassyn community The open-pr skill enables AI agents to create GitHub pull requests with conversation context. It extracts PR details and confirms with users before creation. Open PR 技术允许 AI 代理从对话上下文创建 GitHub Pull Request，具有有意义的标题、适当的格式和标签选择 Open PR 技術により、AI エージェントは会話のコンテキストから GitHub Pull Request を生成できます Open PR 기술을 통해 AI 에이전트는 대화 문脈에서 GitHub Pull Request를 생성할 수 있습니다 Open-pr es una habilidad que permite a los agentes de inteligencia artificial crear solicitudes de extracción en GitHub de forma asíncrona con títulos significativos y formato adecuado Open-pr est une compétence qui permet aux outils d''intelligence artificielle de créer des demandes de tirage sur GitHub de manière asynchrone avec des titres significatifs et un format adapté Open-pr ist eine Fähigkeit, die es KI-Agents ermöglicht, Pull-Requests auf GitHub asynchron mit sinnvollen Titeln und geeigneter Formatierung zu erstellen O open-pr é uma habilidade que permite criar solicitações de pull no GitHub de forma assíncrona com títulos significativos e formatação adequada Открытый запрос - это навык, позволяющий создавать запросы на GitHub асинхронно с осмысленными заголовками и правильным форматированием الطلب المفتوح هو مهارة تتيح إنشاء طلبات سحب على GitHub بشكل غير متزامن مع أسماء ذات معنى وتفاصيل مناسبة how to use open-pr what is open-pr open-pr alternative open-pr vs GitHub API open-pr install open-pr setup guide GitHub pull request automation AI agent skills for GitHub asynchronous semantics for architectural simulation Open PR GitHub Pull Request AI 代理 代码审查 自动化 效率化 代码管理 版本控制 协作开发 Creates GitHub pull requests with meaningful titles and proper formatting Extracts PR details from conversation context Confirms with users before creating pull requests Follows a specific structure for PR creation, including tags and issue numbers Uses Markdown formatting for PR descriptions Supports tag selection and issue number inclusion open-pr is a skill that instructs AI agents on asynchronous semantics for architectural simulation and synthesis, specifically for creating GitHub pull requests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ArtemXTech/claude-code-obsidian-starter/granola', 'community', 'ArtemXTech', 'claude-code-obsidian-starter', 'ArtemXTech/claude-code-obsidian-starter', 'granola', 0, 0, 57, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:07.241Z', 'cead22e3f9c08b4787b92dbf9c849c42763952c83615c778e0ebe5ebf0b8e71d', '{"id":"ArtemXTech/claude-code-obsidian-starter/granola","name":"granola","description":{"en":"Granola is a free starter kit that stores meeting notes, transcripts, and updates locally. It benefits developers and teams by providing a pre-configured vault for projects and tasks.","zh":"Granola AI工具提供本地缓存集成，实现 Obsidian vault 数据的实时同步","ja":"Granola AIエージェントはローカルキャッシュを利用して Obsidian vault のデータを同期します","ko":"Granola AI 에이전트는 로컬 캐시를 통해 Obsidian vault 데이터를 동기화합니다","es":"Granola es una habilidad que sincroniza notas de reuniones de AI con Obsidian. Almacena documentos y transcripciones localmente","fr":"Granola est une compétence qui synchronise les notes de réunion d''IA avec Obsidian. Elle stocke les documents et les transcriptions localement","de":"Granola ist eine Fähigkeit, die AI-Meeting-Notizen mit Obsidian synchronisiert. Sie speichert Dokumente und Transkripte lokal","pt":"O Granola é uma habilidade que sincroniza notas de reunião com o Obsidian, permitindo uma gestão eficaz de projetos e tarefas. Com o Granola, você pode automatizar a organização de suas notas e melhorar a produtividade","ru":"Granola - это навык, который синхронизирует заметки о встречах с Obsidian, позволяя эффективно управлять проектами и задачами. С помощью Granola вы можете автоматизировать организацию заметок и повысить производительность для ИИ Агентов","ar":"Granola هو مهارة تدمج ملاحظات الاجتماعات مع Obsidian، مما يسمح بإدارة فعالة للمشاريع والمهام. باستخدام Granola، يمكنك توفير وقتك ورفع الإنتاجية باستخدام الآليين الذكيين"},"seo":{"title":{"en":"Granola: Setup Guide for AI Agents | AI Agent Skill","zh":"Granola AI工具：本地缓存集成指南","ja":"Granola AIエージェント：ローカルキャッシュ統合ガイド","ko":"Granola AI 에이전트: 로컬 캐시 통합 설정 가이드","es":"Guía de configuración de Granola: sincronización de notas...","fr":"Guide de configuration de Granola : synchronisation de no...","de":"Granola-Setup-Anleitung: Synchronisierung von AI-Meeting-...","pt":"Guia de Configuração do Granola: Integração de Notas de R...","ru":"Настройка Granola: Интеграция заметок о встречах с Obsidi...","ar":"دليل إعداد Granola: دمج ملاحظات الاجتماعات مع Obsidian لل..."},"description":{"en":"Unlock efficient meeting note management with Granola. Learn how to sync AI meeting notes to Obsidian vault and get started with our quick start guide.","zh":"Granola AI工具通过本地缓存实现 Obsidian vault 数据同步，提高开发效率","ja":"Granola AIエージェントはローカルキャッシュを利用して Obsidian vault のデータを同期します","ko":"Granola AI 에이전트는 로컬 캐시를 통해 Obsidian vault 데이터를 동기화하여 개발 효율성을 높입니다","es":"Aprende a configurar Granola para sincronizar notas de reuniones de AI con Obsidian. Descubre cómo funciona y cómo empezar","fr":"Découvrez comment configurer Granola pour synchroniser les notes de réunion d''IA avec Obsidian. Commencez dès maintenant","de":"Erfahren Sie, wie Sie Granola konfigurieren, um AI-Meeting-Notizen mit Obsidian zu synchronisieren. Los geht''s","pt":"Aprenda a configurar o Granola para sincronizar notas de reunião com o Obsidian, otimizando sua produtividade com ferramentas de código e automação","ru":"Узнайте, как настроить Granola для синхронизации заметок о встречах с Obsidian, повышая производительность с помощью инструментов кода и автоматизации для ИИ...","ar":"تعلم كيفية إعداد Granola لدمج ملاحظات الاجتماعات مع Obsidian، ورفع الإنتاجية باستخدام أدوات الكود والتحكم الآلي للآليين الذكيين"},"definition":{"en":"Granola is a skill that queries and syncs Granola AI meeting notes to Obsidian vault, storing data locally in a cache-v3.json file.","zh":"Granola AI工具是一种通过本地缓存实现数据同步的 AI 集成工具","ja":"Granola AIエージェントはローカルキャッシュを利用してデータを同期する AI 統合ツールです","ko":"Granola AI 에이전트는 로컬 캐시를 통해 데이터를 동기화하는 AI 통합 도구입니다","es":"Granola es una herramienta de AI que sincroniza notas de reuniones con Obsidian, almacenando datos localmente","fr":"Granola est un outil d''IA qui synchronise les notes de réunion avec Obsidian, stockant les données localement","de":"Granola ist ein AI-Tool, das Meeting-Notizen mit Obsidian synchronisiert und Daten lokal speichert","pt":"O Granola é uma habilidade de código que sincroniza notas de reunião com o Obsidian, utilizando cache local para armazenar documentos e transcrições","ru":"Granola - это навык кода, который синхронизирует заметки о встречах с Obsidian, используя локальный кэш для хранения документов и транскрипций для ИИ Агентов","ar":"Granola هو مهارة كود تدمج ملاحظات الاجتماعات مع Obsidian، باستخدام ذاكرة مؤقتة محلية لتخزين المستندات والنسخ"},"features":{"en":["Stores documents, transcripts, and updates locally at ~/Library/Application Support/Granola/cache-v3.json","Syncs Granola AI meeting notes to Obsidian vault","Updates in real-time as you record, without requiring API calls","Supports listing all meetings using the python3 .claude/skills/granola/scripts/granola.py list command","Allows retrieval of specific meeting notes using the granola.py script","Pre-configured vault for projects, tasks, clients, and daily routines"],"zh":["本地缓存集成","Obsidian vault 数据同步","实时更新","无需 API 调用","Python 脚本支持"],"ja":["ローカルキャッシュ統合","Obsidian vault データ同期","リアルタイム更新","API 呼び出し不要","Python スクリプト対応"],"ko":["로컬 캐시 통합","Obsidian vault 데이터 동기화","실시간 업데이트","API 호출 불필요","Python 스크립트 지원"],"es":["Almacenamiento local de documentos y transcripciones","Sincronización de notas de reuniones de AI con Obsidian","Actualizaciones en tiempo real sin llamadas a la API","Uso de Python para la sincronización de datos","Compatibilidad con la línea de comandos (CLI) para una configuración flexible"],"fr":["Stockage local de documents et de transcriptions","Synchronisation de notes de réunion d''IA avec Obsidian","Mises à jour en temps réel sans appel d''API","Utilisation de Python pour la synchronisation de données","Compatibilité avec la ligne de commande (CLI) pour une configuration flexible"],"de":["Lokales Speichern von Dokumenten und Transkripten","Synchronisierung von AI-Meeting-Notizen mit Obsidian","Echtzeit-Updates ohne API-Aufrufe","Verwendung von Python für die Datensynchronisation","Kompatibilität mit der Kommandozeile (CLI) für eine flexible Konfiguration"],"pt":["Sincronização de notas de reunião com o Obsidian","Armazenamento de documentos e transcrições em cache local","Atualização em tempo real das notas","Integração com Claude Code para automação de tarefas","Suporte a comandos CLI para gerenciamento de notas"],"ru":["Синхронизация заметок о встречах с Obsidian","Хранение документов и транскрипций в локальном кэше","Обновление заметок в режиме реального времени","Интеграция с Claude Code для автоматизации задач","Поддержка команд CLI для управления заметками для ИИ Агентов"],"ar":["دمج ملاحظات الاجتماعات مع Obsidian","تخزين المستندات والنسخ في ذاكرة مؤقتة محلية","تحديث الملاحظات في الوقت الفعلي","التكامل مع Claude Code للتحكم الآلي في المهام","دعم أوامر CLI لإدارة الملاحظات للآليين الذكيين"]},"keywords":{"en":["how to use granola","what is granola","granola alternative","granola vs obsidian","granola install","granola setup guide","granola meeting notes","obsidian vault integration","ai meeting notes sync"],"zh":["Granola AI工具","本地缓存集成","Obsidian vault","AI 集成","Python 脚本","数据同步","实时更新"],"ja":["Granola AIエージェント","ローカルキャッシュ統合","Obsidian vault","AI 統合","Python スクリプト","データ同期","リアルタイム更新"],"ko":["Granola AI 에이전트","로컬 캐시 통합","Obsidian vault","AI 통합","Python 스크립트","데이터 동기화","실시간 업데이트"],"es":["herramientas de AI","sincronización de notas","Obsidian","Python","CLI","almacenamiento local","Granola","meeting notes","IA","configuración de Granola"],"fr":["outils d''IA","synchronisation de notes","Obsidian","Python","CLI","stockage local","Granola","notes de réunion","IA","configuration de Granola"],"de":["AI-Tools","Synchronisierung von Notizen","Obsidian","Python","CLI","lokales Speichern","Granola","Meeting-Notizen","KI","Granola-Konfiguration"],"pt":["Granola setup","Obsidian integração","notas de reunião","cache local","Claude Code","automação de tarefas","gerenciamento de notas","produtividade","ferramentas de código"],"ru":["настройка Granola","Интеграция с Obsidian","заметки о встречах","локальный кэш","Claude Code","автоматизация задач","управление заметками","производительность","инструменты кода для ИИ Агентов"],"ar":["إعداد Granola","الدمج مع Obsidian","ملاحظات الاجتماعات","ذاكرة مؤقتة محلية","Claude Code","التحكم الآلي في المهام","إدارة الملاحظات","الإنتاجية","أدوات الكود للآليين الذكيين"]}},"owner":"ArtemXTech","repo":"claude-code-obsidian-starter","repoPath":"ArtemXTech/claude-code-obsidian-starter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"granola","description":"Query and sync Granola meetings to Obsidian vault. Use when user mentions Granola, meeting transcripts, or wants to sync meeting notes. Reads from local cache - no API needed.","bodyPreview":"# Granola Skill\n\nQuery and sync Granola AI meeting notes to Obsidian vault.\n\n## How It Works\n\nGranola stores everything locally at `~/Library/Application Support/Granola/cache-v3.json`:\n- Documents (meetings with title, notes, people)\n- Transcripts (real-time, with timestamps and source)\n- Updates in real-time as you record\n\nNo API calls needed - reads directly from local cache.\n\n## Quick Start\n\n```bash\n# List all meetings\npython3 .claude/skills/granola/scripts/granola.py list\n\n# Get specific me","body":"# Granola Skill\n\nQuery and sync Granola AI meeting notes to Obsidian vault.\n\n## How It Works\n\nGranola stores everything locally at `~/Library/Application Support/Granola/cache-v3.json`:\n- Documents (meetings with title, notes, people)\n- Transcripts (real-time, with timestamps and source)\n- Updates in real-time as you record\n\nNo API calls needed - reads directly from local cache.\n\n## Quick Start\n\n```bash\n# List all meetings\npython3 .claude/skills/granola/scripts/granola.py list\n\n# Get specific meeting with transcript\npython3 .claude/skills/granola/scripts/granola.py get <id>\n\n# Sync new meetings to vault\npython3 .claude/skills/granola/scripts/granola.py sync\n\n# Sync specific meeting\npython3 .claude/skills/granola/scripts/granola.py sync --id <id>\n```\n\n## Commands\n\n### list\n\nList all Granola meetings with sync status.\n\n```bash\npython3 .claude/skills/granola/scripts/granola.py list\npython3 .claude/skills/granola/scripts/granola.py list --limit 5\n```\n\nOutput:\n```\n[✓] 2026-01-09  Team Sync - Weekly\n    ID: abc123...\n    Transcript: 450 segments, ~86 min\n\n[ ] 2026-01-10  Team Standup\n    ID: def456...\n    Transcript: 120 segments, ~15 min\n```\n\n- `[✓]` = already synced to vault\n- `[ ]` = not synced yet\n\n### get\n\nView full meeting details and transcript.\n\n```bash\npython3 .claude/skills/granola/scripts/granola.py get <id>\npython3 .claude/skills/granola/scripts/granola.py get <id> --no-transcript\n```\n\n### sync\n\nSync meetings to `Meetings/` as structured Markdown.\n\n```bash\n# Sync new meetings only\npython3 .claude/skills/granola/scripts/granola.py sync\n\n# Sync specific meeting\npython3 .claude/skills/granola/scripts/granola.py sync --id <id>\n\n# Re-sync all (overwrites existing)\npython3 .claude/skills/granola/scripts/granola.py sync --all\n```\n\n## Output Format\n\nSynced meetings are saved to `Meetings/` with this structure:\n\n```markdown\n---\ntype: granola-meeting\ndate: 2026-01-09\ntime: \"19:30\"\nduration_min: 86\ngranola_id: abc123...\npeople:\n  - \"[[Sarah Chen]]\"\ntopics: []\nstatus: raw\n---\n\n# Meeting Title\n\n## Notes\n\n(Your notes from Granola)\n\n## Transcript\n\n[19:30:45] 🎤 Hey, how''s it going?\n[19:30:48] 🎤 Great to meet you...\n```\n\n**Transcript icons:**\n- 🎤 = microphone (you)\n- 🔊 = system audio (others on call)\n\n## Workflow\n\n1. **Record meeting** in Granola (real-time transcription)\n2. **Sync to vault**: `python3 .claude/skills/granola/scripts/granola.py sync`\n3. **Process meeting**: Extract action items, update people notes\n4. **Mark as processed**: Change `status: raw` to `status: processed`\n\n## Querying with Bases\n\nUse `Granola.base` to query synced meetings:\n\n| View | Filter |\n|------|--------|\n| Recent | Last 7 days |\n| Needs Processing | status = raw |\n| By Person | Grouped by people field |\n\n## Data Structure\n\n**Local cache:** `~/Library/Application Support/Granola/cache-v3.json`\n\n```\ncache (JSON string) → state →\n  ├── documents: {id: {title, notes_plain, notes_markdown, people, created_at}}\n  └── transcripts: {id: [{text, source, start_timestamp, end_timestamp}]}\n```\n\n**Transcript segment:**\n```json\n{\n  \"text\": \"Hey, how''s it going?\",\n  \"source\": \"microphone\",\n  \"start_timestamp\": \"2026-01-09T19:30:45.123Z\",\n  \"end_timestamp\": \"2026-01-09T19:30:48.456Z\"\n}\n```\n\n## Tips\n\n- **Real-time access**: Cache updates as you record - can query mid-meeting\n- **Free tier hack**: Sync hourly to bypass 7-day history limit\n- **No auth needed**: Uses local files, not API\n"},"lastSynced":"2026-03-08T02:01:07.241Z","agentAnalysis":{"suitability":{"en":"Perfect for Local Data Analysis Agents needing direct access to meeting notes and transcripts stored in JSON format.","zh":"非常适合需要直接访问存储在JSON格式的会议记录和转录的本地数据分析代理。","ja":"JSON形式で保存された会議ノートやトランスクリプトに直接アクセスする必要があるローカルデータ分析エージェントに最適です。","ko":"JSON 형식으로 저장된 회의록 및 전사본에 직접 액세스해야 하는 로컬 데이터 분석 에이전트에게 완벽합니다.","es":"Perfecto para agentes de análisis de datos locales que necesitan acceso directo a notas y transcripciones de reuniones almacenadas en formato JSON.","fr":"Parfait pour les agents d''analyse de données locales ayant besoin d''un accès direct aux notes et transcriptions de réunions stockées au format JSON.","de":"Perfekt für lokale Datenanalyse-Agenten, die direkten Zugriff auf in JSON-Format gespeicherte Besprechungsnotizen und Transkripte benötigen.","pt":"Perfeito para Agentes de Análise de Dados Locais que precisam de acesso direto a notas e transcrições de reuniões armazenadas no formato JSON.","ru":"Идеально подходит для агентов локального анализа данных, которым требуется прямой доступ к заметкам и транскриптом собраний, хранящимся в формате JSON.","ar":"مثالي لعمليات تحليل البيانات المحلية التي تحتاج إلى الوصول المباشر إلى ملاحظات ومحاضر الاجتماعات المخزنة بصيغة JSON."},"recommendation":{"en":"Empowers agents to sync and query Granola meeting notes, transcripts, and updates stored locally in cache-v3.json, using Python scripts to read and list meetings without requiring API calls, leveraging real-time data with timestamps and source information.","zh":"赋予代理同步和查询Granola会议记录、转录和更新到本地缓存cache-v3.json，使用Python脚本读取和列出会议而无需API调用，利用实时数据和时间戳、源信息。","ja":"Granolaの会議ノート、トランスクリプト、および更新をローカルキャッシュのcache-v3.jsonと同期およびクエリできるようにエージェントを有効にし、API呼び出しの必要なくPythonスクリプトを使用して会議を読み込みリスト化し、リアルタイムデータとタイムスタンプ、およびソース情報を活用します。","ko":"에이전트가 Granola 회의록, 전사본 및 업데이트를 로컬 캐시 cache-v3.json와 동기화 및 쿼리할 수 있도록 하며, API 호출 없이 Python 스크립트를 사용하여 회의를 읽고 목록화하며, 실시간 데이터 및 타임스탬프 및 소스 정보를 활용합니다.","es":"Habilita a los agentes a sincronizar y consultar notas y transcripciones de reuniones de Granola, así como actualizaciones almacenadas localmente en cache-v3.json, utilizando scripts de Python para leer y enumerar reuniones sin requerir llamadas a la API, aprovechando datos en tiempo real con marcas de tiempo y información de origen.","fr":"Permet aux agents de synchroniser et d''interroger les notes et transcriptions de réunions Granola, ainsi que les mises à jour stockées localement dans cache-v3.json, en utilisant des scripts Python pour lire et lister les réunions sans nécessiter d''appels d''API, en exploitant les données en temps réel avec des horodatages et des informations de source.","de":"Ermächtigt Agenten, Granola-Besprechungsnotizen, Transkripte und in cache-v3.json lokal gespeicherte Updates zu synchronisieren und abzufragen, indem Python-Skripte verwendet werden, um Besprechungen zu lesen und aufzulisten, ohne API-Aufrufe zu benötigen, und profitiert von Echtzeitdaten mit Zeitstempeln und Quellinformationen.","pt":"Permite que os agentes sincronizem e consultem notas e transcrições de reuniões do Granola, bem como atualizações armazenadas localmente no cache-v3.json, usando scripts Python para ler e listar reuniões sem necessidade de chamadas de API, aproveitando dados em tempo real com carimbos de data e hora e informações de origem.","ru":"Позволяет агентам синхронизировать и запрашивать заметки и транскрипты собраний Granola, а также обновления, хранящиеся локально в cache-v3.json, используя скрипты Python для чтения и перечисления собраний без необходимости вызовов API, используя данные в реальном времени с метками времени и информацией об источнике.","ar":"تمكن العميل من مزامنة واستعلام ملاحظات ومحاضر اجتماعات Granola والتحديثات المخزنة محلياً في cache-v3.json، باستخدام سكريبتات Python لقراءة وlisting الاجتماعات دون الحاجة إلى 呼び出し API، واستخدام البيانات في الوقت الحقيقي مع таймستامبز ومعلومات المصدر."},"useCases":{"en":["Syncing Granola meeting notes to Obsidian vaults","Querying local cache for specific meeting transcripts","Automating updates to project tasks based on real-time meeting notes"],"zh":["将Granola会议记录同步到Obsidian保险库","查询本地缓存以获取特定会议转录","根据实时会议记录自动更新项目任务"],"ja":["Granolaの会議ノートをObsidianのボールトに同期する","ローカルキャッシュを特定の会議トランスクリプトのためにクエリする","リアルタイムの会議ノートに基づいてプロジェクトタスクを自動的に更新する"],"ko":["Granola 회의록을 Obsidian 보관소에 동기화하는 것","로컬 캐시를 특정 회의 전사본에 대한 쿼리하는 것","실시간 회의록을 기반으로 프로젝트 작업을 자동으로 업데이트하는 것"],"es":["Sincronizar notas de reuniones de Granola con vaults de Obsidian","Consultar la caché local para transcripciones de reuniones específicas","Automatizar actualizaciones de tareas de proyecto en función de notas de reuniones en tiempo real"],"fr":["Synchroniser les notes de réunions Granola avec des vaults Obsidian","Interroger la cache locale pour des transcriptions de réunions spécifiques","Automatiser les mises à jour des tâches de projet en fonction des notes de réunions en temps réel"],"de":["Granola-Besprechungsnotizen mit Obsidian-Vaults synchronisieren","Lokale Cache für bestimmte Besprechungstranskripte abfragen","Projekt-Aufgaben auf Basis von Echtzeit-Besprechungsnotizen automatisch aktualisieren"],"pt":["Sincronização de notas de reuniões do Granola para cofres do Obsidian","Consulta de cache local para transcrições de reuniões específicas","Automatização de atualizações de tarefas de projeto com base em notas de reuniões em tempo real"],"ru":["Синхронизация заметок собраний Granola с хранилищами Obsidian","Запрос локального кэша для конкретных транскриптов собраний","Автоматизация обновлений задач проекта на основе заметок собраний в реальном времени"],"ar":["مزامنة ملاحظات اجتماعات Granola مع الخزائن Obsidian","استعلام 캐시 المحلي لمحاضر اجتماعات محددة","تحديث تلقائي لمهام المشروع بناءً على ملاحظات الاجتماعات في الوقت الفعلي"]},"limitations":{"en":["Requires local filesystem access to ~/Library/Application Support/Granola/cache-v3.json","Limited to reading from local cache, no external API calls supported","Python 3.x required for script execution"],"zh":["需要本地文件系统访问~/Library/Application Support/Granola/cache-v3.json","仅限于从本地缓存读取，不支持外部API调用","需要Python 3.x来执行脚本"],"ja":["~/Library/Application Support/Granola/cache-v3.jsonへのローカルファイルシステムアクセスが必要","ローカルキャッシュからの読み取りのみ、外部API呼び出しはサポートされない","スクリプトの実行にはPython 3.xが必要"],"ko":["~/Library/Application Support/Granola/cache-v3.json 로컬 파일 시스템 액세스가 필요합니다.","로컬 캐시에서 읽기만 가능하며, 외부 API 호출은 지원되지 않습니다.","스크립트 실행을 위해 Python 3.x가 필요합니다."],"es":["Requiere acceso al sistema de archivos local a ~/Library/Application Support/Granola/cache-v3.json","Limitado a la lectura de la caché local, no se admiten llamadas a la API externa","Se requiere Python 3.x para la ejecución de scripts"],"fr":["Nécessite un accès au système de fichiers local à ~/Library/Application Support/Granola/cache-v3.json","Limité à la lecture de la cache locale, les appels d''API externes ne sont pas pris en charge","Python 3.x est requis pour l''exécution de scripts"],"de":["Benötigt Zugriff auf das lokale Dateisystem unter ~/Library/Application Support/Granola/cache-v3.json","Begrenzt auf das Lesen der lokalen Cache, externe API-Aufrufe werden nicht unterstützt","Python 3.x wird für die Skriptausführung benötigt"],"pt":["Requer acesso ao sistema de arquivos local para ~/Library/Application Support/Granola/cache-v3.json","Limitado à leitura do cache local, sem suporte a chamadas de API externas","Python 3.x é necessário para execução de scripts"],"ru":["Требуется доступ к локальной файловой системе для ~/Library/Application Support/Granola/cache-v3.json","Ограничен чтением из локального кэша, не поддерживаются внешние вызовы API","Python 3.x необходим для выполнения скриптов"],"ar":["يتطلب الوصول إلى نظام الملفات المحلي إلى ~/Library/Application Support/Granola/cache-v3.json","محدود بالقراءة من ذاكرة التخزين المؤقت المحلية، ولا يدعم 呼び出し API الخارجية","Python 3.x مطلوب للتنفيذ سكريبتات"]},"version":4},"contentHash":"cead22e3f9c08b4787b92dbf9c849c42763952c83615c778e0ebe5ebf0b8e71d","qualityScore":57}');
