INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('az9713/ai-co-writing-claude-skills/voice-dna-creator', 'voice-dna-creator', 'az9713', 'ai-co-writing-claude-skills', 'community', 'voice-dna-creator az9713 ai-co-writing-claude-skills community The voice-dna-creator skill analyzes writing samples to extract a unique voice profile, enabling AI to replicate authentic writing styles. It benefits content creators and writers. Voice DNA Creator 是一个基于 Claude Code 的 AI 共同写作系统，用于分析写作样本并提取独特的语音配置文件 Voice DNA Creator は、Claude Code に基づく AI 共同作成システムであり、書き込みサンプルを分析して独自の声のプロファイルを抽出します Voice DNA Creator는 Claude Code 기반의 AI 공동 작성 시스템으로, 작문 샘플을 분석하여 고유한 음성 프로필을 추출합니다 El sistema voice-dna-creator es una herramienta de codificación de voz que utiliza principios de ingeniería de contexto para replicar estilos de escritura auténticos. Se basa en la clase magistral de Claude Code de Alex McFarland Le système voice-dna-creator est un outil de codage vocal qui utilise des principes d''ingénierie de contexte pour répliquer des styles d''écriture authentiques. Il est basé sur la classe magistrale de Claude Code d''Alex McFarland Das System voice-dna-creator ist ein Sprachcodierungstool, das Kontext-Engineering-Prinzipien verwendet, um authentische Schreibstile zu replizieren. Es basiert auf dem Claude-Code-Masterclass von Alex McFarland O Voice DNA Creator é um sistema de co-escrita de IA que analisa amostras de escrita para extrair e codificar um perfil de voz único Voice DNA Creator - это система совместного написания ИИ, которая анализирует образцы письма для извлечения и кодирования уникального голосового профиля Voice DNA Creator هو نظام الكتابة المشتركة بالذكاء الاصطناعي الذي يanalyzes عينات الكتابة لاستخراج وكود التوقيع الصوتي الفريد how to use voice-dna-creator what is voice-dna-creator voice-dna-creator alternative voice-dna-creator setup guide voice-dna-creator install Claude Code writing system AI co-writing systems content creation workflow Voice DNA Creator AI 共同写作系统 Claude Code 语音配置文件 写作样本分析 AI 工具 写作风格复制 设置新写作系统 创建客户语音配置文件 Analyzes writing samples to extract unique voice profiles Requires a minimum of 3 writing samples (500+ words each) Ideal for 5-10 samples across different content types Enables AI to replicate authentic writing styles Supports updating voice profiles after style evolution Integrates with content creation workflows voice-dna-creator is a Claude Code writing system that extracts and codifies a unique voice profile from writing samples to replicate authentic writing styles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('natea/fitfinder/threejs-game', 'community', 'natea', 'fitfinder', 'natea/fitfinder', 'threejs-game', 0, 0, 57, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:19.284Z', '19ca677f9a3a81a37677353d715a0a4d12817e9c23406ca82489471cc97cfe71', '{"id":"natea/fitfinder/threejs-game","name":"threejs-game","description":{"en":"The threejs-game skill provides comprehensive assistance with Three.js game development, helping developers build 3D web games with features like physics, animations, and user input handling. It benefits developers looking to create immersive browser-based games.","zh":"Three.js 游戏开发技能提供了使用 Three.js 和 WebGL 进行 3D 游戏开发的综合帮助，包括 3D 渲染、游戏机制、物理、动画和交互式浏览器游戏","ja":"Three.js ゲーム開発スキルは、Three.js と WebGL を使用した 3D ゲーム開発の包括的な支援を提供します。3D レンダリング、ゲームメカニクス、物理、アニメーション、インタラクティブ ブラウザ ゲーム","ko":"Three.js 게임 개발 스킬은 Three.js와 WebGL을 사용한 3D 게임 개발의 포괄적인 지원을 제공합니다. 3D 렌더링, 게임 메커니즘, 물리, 애니메이션, 인터랙티브 브라우저 게임","es":"El skill threejs-game ofrece asistencia integral para el desarrollo de juegos con Three.js, incluyendo renderizado 3D, mecánicas de juego y física","fr":"Le skill threejs-game offre une aide complète pour le développement de jeux avec Three.js, y compris le rendu 3D, la mécanique de jeu et la physique","de":"Der Skill threejs-game bietet umfassende Unterstützung für die Entwicklung von Spielen mit Three.js, einschließlich 3D-Rendering, Spielmechanik und Physik","pt":"Three.js Game é uma habilidade que fornece assistência abrangente para o desenvolvimento de jogos 3D no navegador","ru":"Three.js Game — это навык, который обеспечивает всестороннюю помощь в разработке 3D-игр в браузере","ar":"Three.js Game هو مهارة توفر مساعدة شاملة لإنشاء ألعاب 3D في المتصفح"},"seo":{"title":{"en":"threejs-game: Comprehensive Game Development Setup Guide ...","zh":"Three.js 游戏开发设置指南","ja":"Three.js ゲーム開発ベストプラクティス","ko":"Three.js 게임 개발 가이드","es":"Guía de configuración de Three.js para juegos","fr":"Configurer les jeux Three.js - Meilleures pratiques","de":"Three.js-Game-Setup-Anleitung","pt":"Guia de Configuração Three.js Game","ru":"Руководство по настройке ИИ Агентов Three.js Game","ar":"دليل إعداد لعبة Three.js مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of Three.js game development with our AI agent skill, covering WebGL, 3D rendering, and interactive browser-based games. Get starte...","zh":"使用 Three.js 和 WebGL 进行 3D 游戏开发，包括 3D 渲染、游戏机制、物理、动画和交互式浏览器游戏","ja":"Three.js と WebGL を使用した 3D ゲーム開発、3D レンダリング、ゲームメカニクス、物理、アニメーション、インタラクティブ ブラウザ ゲーム","ko":"Three.js와 WebGL을 사용한 3D 게임 개발, 3D 렌더링, 게임 메커니즘, 물리, 애니메이션, 인터랙티브 브라우저 게임","es":"Descubre cómo acelerar el desarrollo de juegos con Three.js y herramientas de AI. Aprende a crear juegos 3D en el navegador","fr":"Découvrez comment accélérer le développement de jeux avec Three.js et des outils d''IA. Créez des jeux 3D dans le navigateur","de":"Erfahren Sie, wie Sie die Entwicklung von Spielen mit Three.js und AI-Tools beschleunigen. Erstellen Sie 3D-Spiele im Browser","pt":"Aprenda a criar jogos 3D no navegador com Three.js e WebGL, incluindo mecânicas de jogo e física","ru":"Изучите разработку 3D-игр в браузере с помощью Three.js и WebGL, включая игровую механику и физику","ar":"تعلم كيفية إنشاء ألعاب 3D في المتصفح باستخدام Three.js و WebGL، بما في ذلك ميكانيكا اللعبة والفيزياء"},"definition":{"en":"threejs-game is a skill that assists with Three.js game development using WebGL, covering aspects like 3D rendering, game mechanics, and interactive browser-based games.","zh":"Three.js 游戏开发技能是一种 AI 工具，帮助开发者使用 Three.js 和 WebGL 进行 3D 游戏开发","ja":"Three.js ゲーム開発スキルは、Three.js と WebGL を使用した 3D ゲーム開発を支援する AI エージェントです","ko":"Three.js 게임 개발 스킬은 Three.js와 WebGL을 사용한 3D 게임 개발을 지원하는 AI 도구입니다","es":"Three.js es una biblioteca de JavaScript para crear juegos 3D en el navegador, utilizando WebGL","fr":"Three.js est une bibliothèque JavaScript pour créer des jeux 3D dans le navigateur, utilisant WebGL","de":"Three.js ist eine JavaScript-Bibliothek für die Erstellung von 3D-Spielen im Browser, die WebGL verwendet","pt":"Three.js Game é uma habilidade que permite criar jogos 3D no navegador com WebGL","ru":"Three.js Game — это навык, который позволяет создавать 3D-игры в браузере с помощью WebGL","ar":"Three.js Game هو مهارة تمكن من إنشاء ألعاب 3D في المتصفح باستخدام WebGL"},"features":{"en":["Building 3D web games with Three.js and WebGL","Implementing game mechanics like player movement, collisions, and scoring","Setting up cameras, lighting, and scene management for optimal rendering","Loading 3D models in GLTF, OBJ, and FBX formats","Handling user input from keyboard, mouse, touch, and other devices"],"zh":["使用 Three.js 和 WebGL 进行 3D 渲染","实现游戏机制（玩家移动、碰撞、计分）","设置摄像机、灯光和场景管理","加载 3D 模型（GLTF、OBJ、FBX）","处理用户输入（键盘、鼠标、触摸）"],"ja":["Three.js と WebGL を使用した 3D レンダリング","ゲームメカニクス（プレイヤー移動、衝突、スコアリング）の実装","カメラ、ライト、シーン管理の設定","3D モデルの読み込み（GLTF、OBJ、FBX）","ユーザー入力（キーボード、マウス、タッチ）の処理"],"ko":["Three.js와 WebGL을 사용한 3D 렌더링","게임 메커니즘（플레이어 이동, 충돌, 스코어링）的 구현","카메라, 라이트, 씬 관리의 설정","3D 모델의 로딩（GLTF, OBJ, FBX）","사용자 입력（키보드, 마우스, 터치）的 처리"],"es":["Renderizado 3D con WebGL","Implementación de mecánicas de juego","Carga de modelos 3D (GLTF, OBJ, FBX)","Manipulación de cámaras, iluminación y gestión de escenas","Control de entrada de usuario (teclado, mouse, touch)"],"fr":["Rendu 3D avec WebGL","Mise en œuvre de mécaniques de jeu","Chargement de modèles 3D (GLTF, OBJ, FBX)","Manipulation de caméras, d''éclairage et de gestion de scènes","Contrôle de l''entrée utilisateur (clavier, souris, tactile)"],"de":["3D-Rendering mit WebGL","Implementierung von Spielmechaniken","Laden von 3D-Modellen (GLTF, OBJ, FBX)","Manipulation von Kameras, Beleuchtung und Szenenverwaltung","Steuerung der Benutzereingabe (Tastatur, Maus, Touch)"],"pt":["Criação de jogos 3D no navegador com Three.js e WebGL","Implementação de mecânicas de jogo, como movimento do jogador e colisões","Configuração de câmeras, iluminação e gerenciamento de cenas","Carregamento de modelos 3D em formatos GLTF, OBJ e FBX","Tratamento de entrada do usuário, incluindo teclado, mouse e toque"],"ru":["Создание 3D-игр в браузере с помощью Three.js и WebGL","Реализация игровой механики, такой как движение игрока и столкновения","Настройка камер, освещения и управления сценами","Загрузка 3D-моделей в форматах GLTF, OBJ и FBX","Обработка пользовательского ввода, включая клавиатуру, мышь и сенсорный экран"],"ar":["إنشاء ألعاب 3D في المتصفح باستخدام Three.js و WebGL","تنفيذ ميكانيكا اللعبة، مثل حركة اللاعب والتصادمات","تكوين الكاميرات والإضاءة وإدارة المشاهد","تحميل نماذج 3D في صيغ GLTF و OBJ و FBX","معالجة إدخال المستخدم، بما في ذلك لوحة المفاتيح والفأرة واللمس"]},"keywords":{"en":["how to use threejs-game","threejs-game setup guide","threejs-game vs PlayCanvas","threejs-game install","what is threejs-game","threejs-game alternative","threejs-game game development","threejs-game WebGL tutorial","threejs-game 3D rendering"],"zh":["Three.js 游戏开发","WebGL 游戏开发","3D 游戏开发","游戏机制","物理引擎","动画","交互式浏览器游戏","AI 工具","Three.js 教程"],"ja":["Three.js ゲーム開発","WebGL ゲーム開発","3D ゲーム開発","ゲームメカニクス","物理エンジン","アニメーション","インタラクティブ ブラウザ ゲーム","AI エージェント","Three.js チュートリアル"],"ko":["Three.js 게임 개발","WebGL 게임 개발","3D 게임 개발","게임 메커니즘","물리 엔진","애니메이션","인터랙티브 브라우저 게임","AI 도구","Three.js 튜토리얼"],"es":["threejs-game","desarrollo de juegos 3D","WebGL","mecánicas de juego","carga de modelos 3D","control de entrada de usuario","AI para juegos","herramientas de IA para juegos"],"fr":["threejs-game","développement de jeux 3D","WebGL","mécaniques de jeu","chargement de modèles 3D","contrôle de l''entrée utilisateur","IA pour les jeux","outils d''IA pour les jeux"],"de":["threejs-game","Entwicklung von 3D-Spielen","WebGL","Spielmechaniken","Laden von 3D-Modellen","Steuerung der Benutzereingabe","KI für Spiele","KI-Tools für Spiele"],"pt":["Three.js Game","Desenvolvimento de jogos 3D","WebGL","Mecânicas de jogo","Física em jogos","Criação de jogos no navegador","Three.js tutorial","Jogos 3D no navegador"],"ru":["Three.js Game","Разработка 3D-игр","WebGL","Игровая механика","Физика в играх","Создание игр в браузере","Three.js руководство","3D-игры в браузере"],"ar":["Three.js Game","تطوير ألعاب 3D","WebGL","ميكانيكا اللعبة","فيزياء في الألعاب","إنشاء ألعاب في المتصفح","دليل Three.js","ألعاب 3D في المتصفح"]}},"owner":"natea","repo":"fitfinder","repoPath":"natea/fitfinder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"threejs-game","description":"Three.js game development. Use for 3D web games, WebGL rendering, game mechanics, physics integration, character controllers, camera systems, lighting, animations, and interactive 3D experiences in the browser.","bodyPreview":"# Three.js Game Development Skill\n\nComprehensive assistance with Three.js game development using WebGL, covering 3D rendering, game mechanics, physics, animations, and interactive browser-based games.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Building 3D web games with Three.js\n- Implementing game mechanics (player movement, collisions, scoring)\n- Setting up cameras, lighting, and scene management\n- Loading 3D models (GLTF, OBJ, FBX)\n- Handling user input (keyboard, mouse, touch, g","body":"# Three.js Game Development Skill\n\nComprehensive assistance with Three.js game development using WebGL, covering 3D rendering, game mechanics, physics, animations, and interactive browser-based games.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Building 3D web games with Three.js\n- Implementing game mechanics (player movement, collisions, scoring)\n- Setting up cameras, lighting, and scene management\n- Loading 3D models (GLTF, OBJ, FBX)\n- Handling user input (keyboard, mouse, touch, gamepad)\n- Creating animations and character controllers\n- Integrating physics engines (Cannon.js, Ammo.js)\n- Optimizing 3D game performance\n- Working with shaders and materials for game visuals\n\n## Quick Reference\n\n### Basic Game Setup\n\n```javascript\nimport * as THREE from ''three'';\n\n// Create scene, camera, renderer\nconst scene = new THREE.Scene();\nconst camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\nrenderer.setSize(window.innerWidth, window.innerHeight);\ndocument.body.appendChild(renderer.domElement);\n\n// Game loop\nfunction animate(time) {\n  requestAnimationFrame(animate);\n\n  // Update game logic here\n  updatePlayer(time);\n  updateEnemies(time);\n  checkCollisions();\n\n  renderer.render(scene, camera);\n}\n\nanimate();\n```\n\n### Player Controller (Third-Person)\n\n```javascript\nclass PlayerController {\n  constructor(camera, target) {\n    this.camera = camera;\n    this.target = target;\n    this.distance = 10;\n    this.height = 5;\n    this.rotationSpeed = 0.005;\n    this.moveSpeed = 0.1;\n  }\n\n  update(input) {\n    // Movement\n    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(this.target.quaternion);\n    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.target.quaternion);\n\n    if (input.forward) this.target.position.add(forward.multiplyScalar(this.moveSpeed));\n    if (input.backward) this.target.position.add(forward.multiplyScalar(-this.moveSpeed));\n    if (input.left) this.target.position.add(right.multiplyScalar(-this.moveSpeed));\n    if (input.right) this.target.position.add(right.multiplyScalar(this.moveSpeed));\n\n    // Rotation\n    if (input.rotateLeft) this.target.rotation.y += this.rotationSpeed;\n    if (input.rotateRight) this.target.rotation.y -= this.rotationSpeed;\n\n    // Update camera position\n    const offset = new THREE.Vector3(0, this.height, this.distance);\n    offset.applyQuaternion(this.target.quaternion);\n    this.camera.position.copy(this.target.position).add(offset);\n    this.camera.lookAt(this.target.position);\n  }\n}\n```\n\n### Input Handling\n\n```javascript\nclass InputManager {\n  constructor() {\n    this.keys = {};\n    this.mouse = { x: 0, y: 0, buttons: {} };\n\n    window.addEventListener(''keydown'', (e) => this.keys[e.code] = true);\n    window.addEventListener(''keyup'', (e) => this.keys[e.code] = false);\n    window.addEventListener(''mousemove'', (e) => {\n      this.mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n      this.mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n    });\n  }\n\n  getInput() {\n    return {\n      forward: this.keys[''KeyW''] || this.keys[''ArrowUp''],\n      backward: this.keys[''KeyS''] || this.keys[''ArrowDown''],\n      left: this.keys[''KeyA''] || this.keys[''ArrowLeft''],\n      right: this.keys[''KeyD''] || this.keys[''ArrowRight''],\n      jump: this.keys[''Space''],\n      action: this.keys[''KeyE''],\n      rotateLeft: this.keys[''KeyQ''],\n      rotateRight: this.keys[''KeyE'']\n    };\n  }\n}\n```\n\n### Collision Detection (Raycasting)\n\n```javascript\nfunction checkCollisions(player, obstacles) {\n  const raycaster = new THREE.Raycaster();\n  const directions = [\n    new THREE.Vector3(1, 0, 0),   // right\n    new THREE.Vector3(-1, 0, 0),  // left\n    new THREE.Vector3(0, 0, 1),   // forward\n    new THREE.Vector3(0, 0, -1),  // backward\n  ];\n\n  for (const direction of directions) {\n    raycaster.set(player.position, direction);\n    const intersects = raycaster.intersectObjects(obstacles);\n\n    if (intersects.length > 0 && intersects[0].distance < 1.0) {\n      return {\n        collision: true,\n        object: intersects[0].object,\n        distance: intersects[0].distance,\n        point: intersects[0].point\n      };\n    }\n  }\n\n  return { collision: false };\n}\n```\n\n### Loading 3D Models (GLTF)\n\n```javascript\nimport { GLTFLoader } from ''three/examples/jsm/loaders/GLTFLoader.js'';\n\nconst loader = new GLTFLoader();\n\nfunction loadCharacter(path) {\n  return new Promise((resolve, reject) => {\n    loader.load(\n      path,\n      (gltf) => {\n        const model = gltf.scene;\n        model.scale.set(1, 1, 1);\n        scene.add(model);\n\n        // Setup animations if available\n        const mixer = new THREE.AnimationMixer(model);\n        const animations = {};\n        gltf.animations.forEach(clip => {\n          animations[clip.name] = mixer.clipAction(clip);\n        });\n\n        resolve({ model, mixer, animations });\n      },\n      (progress) => {\n        console.log(`Loading: ${(progress.loaded / progress.total * 100).toFixed(2)}%`);\n      },\n      (error) => reject(error)\n    );\n  });\n}\n\n// Usage\nconst character = await loadCharacter(''/models/character.glb'');\ncharacter.animations.idle.play();\n```\n\n### Basic Physics (Gravity & Jumping)\n\n```javascript\nclass PhysicsBody {\n  constructor(mesh) {\n    this.mesh = mesh;\n    this.velocity = new THREE.Vector3();\n    this.onGround = false;\n    this.gravity = -9.8;\n    this.jumpPower = 5;\n  }\n\n  update(deltaTime) {\n    // Apply gravity\n    if (!this.onGround) {\n      this.velocity.y += this.gravity * deltaTime;\n    }\n\n    // Apply velocity\n    this.mesh.position.add(this.velocity.clone().multiplyScalar(deltaTime));\n\n    // Ground check\n    if (this.mesh.position.y <= 0) {\n      this.mesh.position.y = 0;\n      this.velocity.y = 0;\n      this.onGround = true;\n    }\n  }\n\n  jump() {\n    if (this.onGround) {\n      this.velocity.y = this.jumpPower;\n      this.onGround = false;\n    }\n  }\n}\n```\n\n### Interactive Objects (Picking)\n\n```javascript\nconst raycaster = new THREE.Raycaster();\nconst mouse = new THREE.Vector2();\n\nfunction onMouseClick(event) {\n  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;\n  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;\n\n  raycaster.setFromCamera(mouse, camera);\n  const intersects = raycaster.intersectObjects(interactableObjects);\n\n  if (intersects.length > 0) {\n    const object = intersects[0].object;\n    object.userData.onInteract?.();\n  }\n}\n\nwindow.addEventListener(''click'', onMouseClick);\n```\n\n### Health & Damage System\n\n```javascript\nclass Entity {\n  constructor(mesh, maxHealth) {\n    this.mesh = mesh;\n    this.maxHealth = maxHealth;\n    this.health = maxHealth;\n    this.isDead = false;\n  }\n\n  takeDamage(amount) {\n    if (this.isDead) return;\n\n    this.health = Math.max(0, this.health - amount);\n\n    if (this.health === 0) {\n      this.die();\n    }\n\n    return this.health;\n  }\n\n  heal(amount) {\n    this.health = Math.min(this.maxHealth, this.health + amount);\n    return this.health;\n  }\n\n  die() {\n    this.isDead = true;\n    this.mesh.visible = false;\n    // Trigger death animation, effects, etc.\n  }\n}\n```\n\n## Key Concepts\n\n### Scene Graph\n- Organize game objects hierarchically\n- Use groups for complex objects\n- Parent-child transformations\n\n### Game Loop\n- Use `requestAnimationFrame` for 60fps\n- Calculate delta time for frame-independent movement\n- Separate update logic from rendering\n\n### Camera Systems\n- **PerspectiveCamera**: First/third-person games\n- **OrthographicCamera**: 2D/isometric games\n- Implement camera follow and smooth transitions\n\n### Lighting\n- **AmbientLight**: Base illumination\n- **DirectionalLight**: Sun/moonlight with shadows\n- **PointLight**: Torches, explosions\n- **SpotLight**: Flashlights, stage lights\n\n### Performance Optimization\n- Use instancing for repeated objects\n- Implement frustum culling\n- Use LOD (Level of Detail) for distant objects\n- Minimize draw calls\n- Use texture atlases\n- Enable shadow map optimization\n\n### Asset Loading\n- Preload all assets before game start\n- Show loading progress bar\n- Use LoadingManager for coordination\n- Cache loaded assets\n\n## Common Game Patterns\n\n### State Machine (Game States)\n\n```javascript\nclass GameStateMachine {\n  constructor() {\n    this.states = {\n      menu: new MenuState(),\n      playing: new PlayingState(),\n      paused: new PausedState(),\n      gameOver: new GameOverState()\n    };\n    this.currentState = this.states.menu;\n  }\n\n  changeState(stateName) {\n    this.currentState.exit();\n    this.currentState = this.states[stateName];\n    this.currentState.enter();\n  }\n\n  update(deltaTime) {\n    this.currentState.update(deltaTime);\n  }\n}\n```\n\n### Object Pooling\n\n```javascript\nclass ObjectPool {\n  constructor(factory, initialSize = 10) {\n    this.factory = factory;\n    this.available = [];\n    this.inUse = [];\n\n    for (let i = 0; i < initialSize; i++) {\n      this.available.push(factory());\n    }\n  }\n\n  acquire() {\n    let obj = this.available.pop();\n    if (!obj) obj = this.factory();\n    this.inUse.push(obj);\n    return obj;\n  }\n\n  release(obj) {\n    const index = this.inUse.indexOf(obj);\n    if (index > -1) {\n      this.inUse.splice(index, 1);\n      this.available.push(obj);\n    }\n  }\n}\n\n// Usage\nconst bulletPool = new ObjectPool(() => createBullet(), 20);\nconst bullet = bulletPool.acquire();\n// ... use bullet\nbulletPool.release(bullet);\n```\n\n## Reference Files\n\nDetailed documentation organized by topic:\n\n- **getting_started.md** - Three.js fundamentals, setup, and basic concepts\n- **game_development.md** - Game loop, player controllers, game mechanics\n- **scene_graph.md** - Scene organization, hierarchy, transformations\n- **materials.md** - Material types, shaders, visual effects\n- **textures.md** - Texture loading, UV mapping, atlases\n- **lighting.md** - Light types, shadows, HDR\n- **cameras.md** - Camera types, controls, viewport management\n- **geometry.md** - Built-in geometries, custom geometry, buffers\n- **loading.md** - Asset loading (models, textures, audio)\n- **animation.md** - Animation system, skeletal animation, tweens\n- **interactivity.md** - Raycasting, picking, UI integration\n- **effects.md** - Post-processing, particles, fog\n\n## Resources\n\n### Official Documentation\n- Three.js Manual: https://threejs.org/manual/\n- Three.js API: https://threejs.org/docs/\n- Three.js Examples: https://threejs.org/examples/\n\n### Physics Integration\n- **Cannon.js**: Lightweight 3D physics\n- **Ammo.js**: Full Bullet physics engine port\n- **Rapier**: High-performance physics\n\n### Useful Libraries\n- **three-mesh-bvh**: Fast raycasting\n- **three-pathfinding**: Navigation meshes\n- **postprocessing**: Advanced effects\n\n## Working with This Skill\n\n### For Beginners\n1. Start with basic scene setup\n2. Learn the coordinate system\n3. Understand the game loop\n4. Practice with simple shapes before models\n\n### For Game Development\n1. Plan your game architecture\n2. Implement input handling first\n3. Build a simple player controller\n4. Add gameplay mechanics incrementally\n5. Optimize performance throughout\n\n### For Advanced Features\n1. Integrate physics engines\n2. Implement advanced shaders\n3. Add post-processing effects\n4. Build multiplayer networking\n\n## Notes\n\n- Three.js uses a right-handed coordinate system (X right, Y up, Z out)\n- Optimize early: profile regularly, minimize draw calls\n- Use development builds for debugging, production builds for release\n- Consider WebGL 2 features for modern browsers\n- Mobile performance requires careful optimization\n"},"lastSynced":"2026-03-08T02:01:19.284Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing immersive 3D web game development capabilities with Three.js and WebGL.","zh":"非常适合需要使用Three.js和WebGL进行沉浸式3D网页游戏开发的前端代理。","ja":"Three.jsとWebGLを使用したイマーシブな3Dウェブゲーム開発機能を必要とするフロントエンドエージェントに最適です。","ko":"Three.js와 WebGL을 사용하여 몰입형 3D 웹 게임 개발 기능이 필요한 프런트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan capacidades de desarrollo de juegos web 3D inmersivos con Three.js y WebGL.","fr":"Parfait pour les agents Frontend qui ont besoin de capacités de développement de jeux web 3D immersifs avec Three.js et WebGL.","de":"Perfekt für Frontend-Agents, die immersive 3D-Webgame-Entwicklungsfähigkeiten mit Three.js und WebGL benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de desenvolvimento de jogos web 3D imersivos com Three.js e WebGL.","ru":"Идеально подходит для агентов Frontend, которым необходимы возможности разработки иммерсивных 3D веб-игр с помощью Three.js и WebGL.","ar":"مثالي لوكلاء الواجهة الأمامية الذين يحتاجون إلى إمكانيات تطوير ألعاب الويب ثلاثية الأبعاد الغامرة مع Three.js و WebGL."},"recommendation":{"en":"Empowers agents to generate interactive 3D scenes with physics, animations, and user input handling using Three.js, supporting formats like GLTF, OBJ, and FBX, and enabling features such as camera and lighting management.","zh":"赋予代理生成具有物理、动画和用户输入处理的交互式3D场景的能力，使用Three.js，支持GLTF、OBJ和FBX等格式，并实现摄像机和照明管理等功能。","ja":"Three.jsを使用して物理、動画、ユーザー入力処理を備えたインタラクティブな3Dシーンを生成するエージェントの能力を提供し、GLTF、OBJ、FBXなどの形式をサポートし、カメラと照明管理などの機能を可能にします。","ko":"Three.js를 사용하여 물리학, 애니메이션 및 사용자 입력 처리를 갖춘 상호작용 3D 장면을 생성할 수 있는 에이전트의 능력을 제공하며, GLTF, OBJ, FBX 등의 형식을 지원하며, 카메라 및 조명 관리 등의 기능을 활성화합니다.","es":"Habilita a los agentes a generar escenas 3D interactivas con física, animaciones y manejo de entrada de usuario utilizando Three.js, que admite formatos como GLTF, OBJ y FBX, y permite funciones como la gestión de cámaras y luces.","fr":"Permet aux agents de générer des scènes 3D interactives avec physique, animations et gestion des entrées utilisateur à l''aide de Three.js, qui prend en charge des formats tels que GLTF, OBJ et FBX, et permet des fonctionnalités telles que la gestion de la caméra et de l''éclairage.","de":"Ermächtigt Agenten, interaktive 3D-Szenen mit Physik, Animationen und Benutzereingabehandling mit Three.js zu generieren, das Formate wie GLTF, OBJ und FBX unterstützt und Funktionen wie Kamera- und Beleuchtungsmanagement ermöglicht.","pt":"Habilita os agentes a gerar cenas 3D interativas com física, animações e tratamento de entrada do usuário usando Three.js, suportando formatos como GLTF, OBJ e FBX, e habilitando recursos como gerenciamento de câmera e iluminação.","ru":"Наделяет агентов возможностью генерировать интерактивные 3D-сцены с физикой, анимациями и обработкой пользовательского ввода с помощью Three.js, поддерживая форматы seperti GLTF, OBJ и FBX, и предоставляя функции, такие как управление камерой и освещением.","ar":"يمنح الوكلاء القدرة على توليد مشاهد 3D تفاعلية مع الفيزياء والرسوم المتحركة ومعالجة إدخال المستخدم باستخدام Three.js، مع دعم صيغ مثل GLTF و OBJ و FBX، وتمكين ميزات مثل إدارة الكاميرا والإضاءة."},"useCases":{"en":["Building immersive browser-based games with physics and animations","Implementing game mechanics like player movement and collisions","Loading and rendering 3D models in various formats"],"zh":["构建具有物理和动画的浏览器基于游戏","实现游戏机制，如玩家移动和碰撞","加载和渲染各种格式的3D模型"],"ja":["物理とアニメーションを備えたブラウザベースのゲームを構築する","ゲームメカニズム、たとえばプレイヤーの移動と衝突を実装する","様々な形式の3Dモデルを読み込みとレンダリングする"],"ko":["물리학 및 애니메이션을 갖춘 브라우저 기반 게임 구축","게임 메커니즘 구현, 예를 들어 플레이어 이동 및 충돌","다양한 형식의 3D 모델 로드 및 렌더링"],"es":["Construir juegos de navegador con física y animaciones inmersivos","Implementar mecánicas de juego como el movimiento del jugador y las colisiones","Cargar y renderizar modelos 3D en varios formatos"],"fr":["Créer des jeux de navigateur immersifs avec physique et animations","Mettre en œuvre des mécanismes de jeu tels que le mouvement du joueur et les collisions","Charger et afficher des modèles 3D dans différents formats"],"de":["Erstellen von immersiven Browser-Spielen mit Physik und Animationen","Implementieren von Spielmechaniken wie Spielerbewegung und Kollisionen","Laden und Rendern von 3D-Modellen in verschiedenen Formaten"],"pt":["Construir jogos de navegador imersivos com física e animações","Implementar mecânicas de jogo como movimento do jogador e colisões","Carregar e renderizar modelos 3D em vários formatos"],"ru":["Построение иммерсивных браузерных игр с физикой и анимациями","Реализация игровых механик, таких как движение игрока и столкновения","Загрузка и рендеринг 3D-моделей в различных форматах"],"ar":["بناء ألعاب متصفح غامرة مع الفيزياء والرسوم المتحركة","تنفيذ ميكانيكا اللعبة مثل حركة اللاعب والتصادمات","تحميل وتصيير نماذج 3D بصيغ مختلفة"]},"limitations":{"en":["Requires WebGL support","Limited to browser-based game development"],"zh":["需要WebGL支持","仅限浏览器基于游戏开发"],"ja":["WebGLのサポートが必要","ブラウザベースのゲーム開発のみ"],"ko":["WebGL 지원 필요","브라우저 기반 게임 개발만 해당"],"es":["Requiere soporte de WebGL","Limitado al desarrollo de juegos basados en navegador"],"fr":["Nécessite un support WebGL","Limité au développement de jeux basés sur navigateur"],"de":["Benötigt WebGL-Unterstützung","Begrenzt auf browserbasierte Spielentwicklung"],"pt":["Requer suporte a WebGL","Limitado ao desenvolvimento de jogos baseados em navegador"],"ru":["Требует поддержки WebGL","Ограничен разработкой браузерных игр"],"ar":["يتطلب دعم WebGL","محدود بتطوير ألعاب المتصفح"]},"version":4},"contentHash":"19ca677f9a3a81a37677353d715a0a4d12817e9c23406ca82489471cc97cfe71","qualityScore":57}');
