INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CongDon1207/AGENTS.md/angular-api-service', 'angular-api-service', 'CongDon1207', 'AGENTS.md', 'community', 'angular-api-service CongDon1207 AGENTS.md community The angular-api-service skill helps developers create new API services for backend communication, adding caching and custom headers. It benefits developers working with Angular applications. Angular API 服务是一种用于与后端进行通信的开发工作流程，包括创建新 API 服务、添加缓存和自定义头部 Angular API サービスはバックエンドとの通信に使用される開発ワークフローです Angular API 서비스는 백엔드와의 통신을 위해 사용되는 개발 워크플로우입니다 El servicio API de Angular facilita la comunicación con el backend y ofrece funciones como caché y encabezados personalizados Le service API Angular facilite la communication avec le backend et offre des fonctionnalités telles que le cache et les en-têtes personnalisés Der Angular API Service erleichtert die Kommunikation mit dem Backend und bietet Funktionen wie Cache und benutzerdefinierte Header O serviço de API Angular é uma ferramenta poderosa para comunicação de backend e cache. Aprenda a configurá-lo corretamente. Сервис API Angular - это мощный инструмент для коммуникации с бэкендом и кэширования. Узнайте, как его настроить. خدمة API Angular هي أداة قوية للتواصل مع الخادم الخلفي وذاكرة التخزين المؤقت. تعلم كيفية إعدادها بشكل صحيح. how to use angular-api-service angular-api-service setup guide angular-api-service vs REST API angular-api-service install what is angular-api-service angular-api-service alternative angular-api-service tutorial angular-api-service best practices angular-api-service example Angular API 服务 后端通信 API 调用 缓存 文件上传 自定义头部 AI 工具 开发工作流程 Creates new API services for backend communication Adds caching to API calls for improved performance Implements file upload/download functionality Supports custom headers and interceptors for API requests Identifies backend API base URL for service configuration Lists all endpoints to implement for comprehensive API coverage angular-api-service is a development workflow for creating and managing API services in Angular applications, including caching, file upload/download, and custom interceptors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rust-works/omni-dev/version-bump', 'community', 'rust-works', 'omni-dev', 'rust-works/omni-dev', 'version-bump', 0, 0, 57, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:23.575Z', 'cd0567b2d45fcc51305b0205921360ff4f47a2d5be8993e5e286f690c9336217', '{"id":"rust-works/omni-dev/version-bump","name":"version-bump","description":{"en":"The version-bump skill helps developers determine appropriate version bumps following Semantic Versioning, benefiting AI agent development and maintenance.","zh":"版本升级工具帮助您根据语义版本控制原则确定合适的版本升级，包括 MAJOR、MINOR 和 PATCH 版本","ja":"バージョンアップ AIエージェントは、Semantic Versioning の原則に従ってバージョンを決定します。MAJOR、MINOR、PATCH バージョンの違いを理解しましょう","ko":"버전 업그레이드 도구는 버전 관리를 위한 도구로, MAJOR、MINOR、PATCH 버전을 올바르게 관리할 수 있습니다","es":"Version-bump es una habilidad que ayuda a determinar los incrementos de versión adecuados siguiendo la versión semántica. Permite a los desarrolladores gestionar versiones de manera efectiva.","fr":"Version-bump est une compétence qui aide à déterminer les increments de version appropriés en suivant la version sémantique. Elle permet aux développeurs de gérer les versions de manière efficace.","de":"Version-bump ist eine Fähigkeit, die dabei hilft, die geeigneten Versionserhöhungen nach semantischer Version zu bestimmen. Sie ermöglicht es Entwicklern, Versionen effektiv zu verwalten.","pt":"O version-bump é uma habilidade que ajuda a determinar aumentos de versão apropriados com base no Semantic Versioning","ru":"Version-Bump — это навык, который помогает определять подходящие увеличения версий на основе Semantic Versioning для ИИ Агентов","ar":"Version-Bump هو مهارة تساعد على تحديد زيادات الإصدار المناسبة استنادًا إلى Semantic Versioning لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"version-bump: Semantic Versioning Setup Guide | AI Agent ...","zh":"版本升级工具 Setup Guide","ja":"バージョンアップ AIエージェント ベストプラクティス","ko":"버전 업그레이드 도구 사용법","es":"Guía de configuración de version-bump para agentes de IA","fr":"Mise en place de version-bump pour les outils d''IA","de":"Einrichtungsleitfaden für version-bump in KI-Tools","pt":"Guia de Configuração do Version-Bump para Desenvolvedores","ru":"Настройка Version-Bump: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد Version-Bump لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to use version-bump for AI agents, determine appropriate version bumps, and master Semantic Versioning with our expert guide - get started now!","zh":"了解版本升级工具的工作原理，实现语义版本控制，包括 MAJOR、MINOR 和 PATCH 版本","ja":"バージョンアップ AIエージェントを使用して、Semantic Versioning を実現します。MAJOR、MINOR、PATCH バージョンの決定方法を学びます","ko":"버전 업그레이드 도구를 사용하여 정확한 버전을 관리하고 배포합니다. 버전 관리를 위한 세부 정보를 확인하세요","es":"Aprende a utilizar version-bump para gestionar versiones semánticas en tus proyectos de desarrollo con agentes de IA","fr":"Découvrez comment utiliser version-bump pour gérer les versions sémantiques dans vos projets de développement avec des outils d''IA","de":"Erfahren Sie, wie Sie version-bump verwenden, um semantische Versionen in Ihren Entwicklungsprojekten mit KI-Tools zu verwalten","pt":"Aprenda a utilizar o version-bump para gerenciar versões de software com base no Semantic Versioning","ru":"Изучите, как использовать Version-Bump для управления версиями программного обеспечения с помощью Semantic Versioning для ИИ Агентов","ar":"تعرف على كيفية استخدام Version-Bump لإدارة إصدارات البرمجيات باستخدام Semantic Versioning لأدوات الذكاء الاصطناعي"},"definition":{"en":"version-bump is a skill that assists in determining appropriate version bumps following Semantic Versioning, using a MAJOR.MINOR.PATCH format.","zh":"版本升级工具是一种根据语义版本控制原则决定版本升级的工具","ja":"バージョンアップ AIエージェントとは、Semantic Versioning の原則に基づいてバージョンを決定するツールです","ko":"버전 업그레이드 도구는 버전 관리를 위한 도구로, 버전을 올바르게 관리할 수 있습니다","es":"Version-bump es una habilidad que sigue la versión semántica para determinar incrementos de versión","fr":"Version-bump est une compétence qui suit la version sémantique pour déterminer les increments de version","de":"Version-bump ist eine Fähigkeit, die der semantischen Version folgt, um Versionserhöhungen zu bestimmen","pt":"Version-Bump é uma técnica de gerenciamento de versões que segue o padrão Semantic Versioning","ru":"Version-Bump — это техника управления версиями, следующая стандарту Semantic Versioning","ar":"Version-Bump هو تقنية لإدارة الإصدارات تتبع معيار Semantic Versioning"},"features":{"en":["Determines MAJOR version bumps for breaking changes, such as removed public functions or API changes","Identifies MINOR version bumps for new features and backwards compatible changes","Applies PATCH version bumps for bug fixes and backwards compatible updates","Follows Semantic Versioning guidelines for version format and bump decision tree","Supports versioning decisions based on specific change types, including function signature changes"],"zh":["支持语义版本控制","自动确定 MAJOR、MINOR 和 PATCH 版本","兼容 API 变更","支持功能添加和 bug 修复"],"ja":["Semantic Versioning に対応","MAJOR、MINOR、PATCH バージョンの自動決定","API 変更に対応","機能追加とバグ修正のサポート"],"ko":["버전 관리를 위한 도구","MAJOR、MINOR、PATCH 버전 자동 관리","API 변경에 대응","기능 추가와 버그 수정 지원"],"es":["Soporte para versión semántica (MAJOR.MINOR.PATCH)","Incrementos de versión para cambios incompatibles (MAJOR)","Incrementos de versión para nuevas características compatibles (MINOR)","Incrementos de versión para correcciones de errores compatibles (PATCH)","Decision tree para determinar el tipo de incremento de versión","Compatibilidad con la gestión de versiones en proyectos de desarrollo"],"fr":["Prise en charge de la version sémantique (MAJOR.MINOR.PATCH)","Increments de version pour les changements incompatibles (MAJOR)","Increments de version pour les nouvelles fonctionnalités compatibles (MINOR)","Increments de version pour les corrections de bogues compatibles (PATCH)","Arbre de décision pour déterminer le type d''increment de version","Compatibilité avec la gestion de versions dans les projets de développement"],"de":["Unterstützung für semantische Version (MAJOR.MINOR.PATCH)","Versionserhöhungen für inkompatible Änderungen (MAJOR)","Versionserhöhungen für neue, kompatible Funktionen (MINOR)","Versionserhöhungen für kompatible Fehlerkorrekturen (PATCH)","Entscheidungsbaum zur Bestimmung des Versionserhöhungs-Typs","Kompatibilität mit der Versionsverwaltung in Entwicklungsprojekten"],"pt":["Suporte ao formato de versão MAJOR.MINOR.PATCH","Detecção de alterações de quebra de compatibilidade para aumento da versão MAJOR","Detecção de novas funcionalidades para aumento da versão MINOR","Detecção de correções de bugs para aumento da versão PATCH","Integração com o padrão Semantic Versioning","Tomada de decisões baseada em árvore de decisão de versão"],"ru":["Поддержка формата версии MAJOR.MINOR.PATCH","Обнаружение изменений, нарушающих совместимость, для увеличения версии MAJOR","Обнаружение новых функций для увеличения версии MINOR","Обнаружение исправлений ошибок для увеличения версии PATCH","Интеграция со стандартом Semantic Versioning для ИИ Агентов","Принятие решений на основе дерева решений версии"],"ar":["دعم صيغة الإصدار MAJOR.MINOR.PATCH","كشف التغييرات التي كسرت التوافق لزيادة الإصدار MAJOR","كشف الميزات الجديدة لزيادة الإصدار MINOR","كشف إصلاحات الأخطاء لزيادة الإصدار PATCH","التكامل مع معيار Semantic Versioning لأدوات الذكاء الاصطناعي","اتخاذ القرارات بناءً على شجرة قرار الإصدار"]},"keywords":{"en":["how to use version-bump","version-bump setup guide","Semantic Versioning best practices","version-bump alternative","version-bump vs semver","version-bump install","what is version-bump","version-bump for AI agents","Semantic Versioning for developers"],"zh":["版本升级工具","语义版本控制","MAJOR 版本","MINOR 版本","PATCH 版本","API 变更","功能添加","bug 修复"],"ja":["バージョンアップ AIエージェント","Semantic Versioning","MAJOR バージョン","MINOR バージョン","PATCH バージョン","API 変更","機能追加","バグ修正"],"ko":["버전 업그레이드 도구","버전 관리","MAJOR 버전","MINOR 버전","PATCH 버전","API 변경","기능 추가","버그 수정"],"es":["version-bump","agentes de IA","versión semántica","gestión de versiones","desarrollo de software","incrementos de versión","MAJOR.MINOR.PATCH","compatibilidad de versiones"],"fr":["version-bump","outils d''IA","version sémantique","gestion de versions","développement de logiciels","increments de version","MAJOR.MINOR.PATCH","compatibilité de versions"],"de":["version-bump","KI-Tools","semantische Version","Versionsverwaltung","Softwareentwicklung","Versionserhöhungen","MAJOR.MINOR.PATCH","Versionskompatibilität"],"pt":["version-bump","Semantic Versioning","gerenciamento de versões","desenvolvimento de software","formato de versão","aumento de versão","compatibilidade de software","correção de bugs"],"ru":["Version-Bump","Semantic Versioning","управление версиями","разработка программного обеспечения","формат версии","увеличение версии","совместимость программного обеспечения","исправление ошибок","ИИ Агенты"],"ar":["Version-Bump","Semantic Versioning","إدارة الإصدارات","تطوير البرمجيات","صيغة الإصدار","زيادة الإصدار","توافق البرمجيات","إصلاح الأخطاء","أدوات الذكاء الاصطناعي"]}},"owner":"rust-works","repo":"omni-dev","repoPath":"rust-works/omni-dev","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"version-bump","description":"Determines appropriate semantic version bumps based on changes. Use when deciding version numbers, evaluating breaking changes, or planning releases. Triggers on terms like version, semver, breaking change, major/minor/patch.","bodyPreview":"# Semantic Versioning Skill\n\nThis skill helps determine appropriate version bumps following [Semantic Versioning](https://semver.org/).\n\n## Version Format\n\n```\nMAJOR.MINOR.PATCH\n```\n\n- **MAJOR**: Breaking changes\n- **MINOR**: New features, backwards compatible\n- **PATCH**: Bug fixes, backwards compatible\n\n## Version Bump Decision Tree\n\n### MAJOR (X.0.0) - Breaking Changes\n\nBump MAJOR when you make incompatible API changes:\n\n- Removed public functions, methods, or types\n- Changed function signatu","body":"# Semantic Versioning Skill\n\nThis skill helps determine appropriate version bumps following [Semantic Versioning](https://semver.org/).\n\n## Version Format\n\n```\nMAJOR.MINOR.PATCH\n```\n\n- **MAJOR**: Breaking changes\n- **MINOR**: New features, backwards compatible\n- **PATCH**: Bug fixes, backwards compatible\n\n## Version Bump Decision Tree\n\n### MAJOR (X.0.0) - Breaking Changes\n\nBump MAJOR when you make incompatible API changes:\n\n- Removed public functions, methods, or types\n- Changed function signatures (parameters, return types)\n- Renamed public APIs\n- Changed default behavior that breaks existing usage\n- Removed CLI flags or changed their meaning\n- Changed configuration file format incompatibly\n\n### MINOR (0.X.0) - New Features\n\nBump MINOR when you add functionality in a backwards compatible manner:\n\n- New commands or subcommands\n- New CLI flags\n- New configuration options\n- New output formats\n- New integrations or providers\n\n### PATCH (0.0.X) - Bug Fixes\n\nBump PATCH when you make backwards compatible bug fixes:\n\n- Fix incorrect behavior\n- Fix crashes or errors\n- Performance improvements (no API changes)\n- Documentation fixes\n- Internal refactoring (no behavior changes)\n\n## Quick Reference\n\n| Change Type                      | Version Bump |\n|----------------------------------|--------------|\n| Breaking API change              | MAJOR        |\n| Removed feature                  | MAJOR        |\n| New command/feature              | MINOR        |\n| New CLI flag                     | MINOR        |\n| New provider/integration         | MINOR        |\n| Bug fix                          | PATCH        |\n| Performance fix                  | PATCH        |\n| Documentation only               | PATCH        |\n| Refactoring (no behavior change) | PATCH        |\n\n## Pre-1.0 Versioning\n\nFor versions < 1.0.0 (like this project):\n- MINOR can include breaking changes\n- PATCH is for bug fixes and small features\n- More flexibility before reaching stability\n\n## Instructions\n\n1. Review all changes since last release:\n   ```bash\n   git log --oneline $(git describe --tags --abbrev=0)..HEAD\n   ```\n\n2. Check for breaking changes:\n   - Removed or renamed public APIs?\n   - Changed default behaviors?\n   - Incompatible configuration changes?\n\n3. If breaking changes exist -> MAJOR bump\n\n4. If new features exist -> MINOR bump\n\n5. If only fixes/refactoring -> PATCH bump\n\n## Version Update Locations\n\nWhen bumping version, update:\n\n1. **Cargo.toml** - `version = \"X.Y.Z\"`\n2. **CHANGELOG.md** - Add `## [X.Y.Z] - YYYY-MM-DD` section\n3. **Version links** - Update comparison URLs at bottom of CHANGELOG.md\n"},"lastSynced":"2026-03-08T02:01:23.575Z","agentAnalysis":{"suitability":{"en":"Ideal for Maintenance Agents requiring precise Semantic Versioning management.","zh":"适合需要精确语义版本管理的维护代理。","ja":"メンテナンスエージェントが正確なセマンティックバージョニング管理を必要とする場合に最適です。","ko":"정확한 시맨틱 버전 관리가 필요한 유지 보수 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento que requieren una gestión precisa de Versionado Semántico.","fr":"Idéal pour les agents de maintenance nécessitant une gestion précise de la version sémantique.","de":"Ideal für Wartungsagenten, die eine präzise Verwaltung von Semantischer Versionierung erfordern.","pt":"Ideal para Agentes de Manutenção que exigem gerenciamento preciso de Versão Semântica.","ru":"Идеально для агентов обслуживания, требующих точного управления семантическим版本ированием.","ar":"مثالي لعميل الصيانة الذي يتطلب إدارة دقيقة لنسخة семантиكية."},"recommendation":{"en":"Empowers agents to determine appropriate version bumps following Semantic Versioning, handling MAJOR, MINOR, and PATCH updates with compatibility checks, including backwards compatible changes and breaking API modifications.","zh":"赋予代理人确定合适的版本升级的能力，遵循语义版本控制，处理MAJOR、MINOR和PATCH更新，包括向后兼容的更改和破坏API的修改。","ja":"エージェントがセマンティックバージョニングに従って適切なバージョンアップを決定する能力を提供します。MAJOR、MINOR、PATCHの更新をバックワードコンパチブルな変更や破壊的なAPI変更を含む互換性チェックで処理します。","ko":"에이전트가 시맨틱 버전 관리를 따라 적절한 버전 업그레이드를 결정할 수 있는 능력을 제공합니다. 주요, 중소, 패치 업데이트를 처리하며, 호환되는 변경 사항과 호환되지 않는 API 수정을 포함한 호환성 확인을 수행합니다.","es":"Habilita a los agentes a determinar los aumentos de versión adecuados siguiendo la Versionado Semántico, manejando actualizaciones de MAYOR, MENOR y CORRECCIÓN con comprobaciones de compatibilidad, incluyendo cambios compatibles con versiones anteriores y modificaciones de API de ruptura.","fr":"Permet aux agents de déterminer les augmentations de version appropriées suivant la version sémantique, en gérant les mises à jour MAJEURE, MINEURE et CORRECTION avec des vérifications de compatibilité, y compris les modifications compatibles avec les versions antérieures et les modifications d''API de rupture.","de":"Ermächtigt die Agenten, die geeigneten Versionsänderungen gemäß der Semantischen Versionierung zu bestimmen, indem sie Änderungen von MAJOR, MINOR und PATCH mit Kompatibilitätsprüfungen handhaben, einschließlich rückwärts kompatibler Änderungen und API-Änderungen mit Brechung.","pt":"Habilita os agentes a determinar aumentos de versão apropriados após a Versão Semântica, lidando com atualizações MAJOR, MINOR e PATCH com verificações de compatibilidade, incluindo alterações compatíveis com versões anteriores e modificações de API de quebra.","ru":"Наделяет агентов возможностью определять соответствующие повышения версий после семантического версионирования, обрабатывая обновления MAJOR, MINOR и PATCH с проверками совместимости, включая изменения, обратно совместимые с предыдущими версиями, и нарушающие модификации API.","ar":"يمكن العميل من تحديد زيادات الإصدار المناسبة بعد النسخة الصيغية، معالجة التحديثات الرئيسية و الثانوية والتصحيح مع فحص التوافق، بما في ذلك التغييرات المتوافقة مع الإصدارات السابقة وتعديلات واجهة برمجة التطبيقات التي لا توافقها."},"useCases":{"en":["Automating version updates for API changes","Determining MAJOR version bumps for breaking changes","Identifying MINOR version bumps for new backwards compatible features"],"zh":["自动化API更改的版本更新","确定破坏性更改的MAJOR版本升级","识别新向后兼容功能的MINOR版本升级"],"ja":["API変更のバージョンアップデートの自動化","破壊的な変更のMAJORバージョンアップの決定","新しい後方互換性のある機能のMINORバージョンアップの識別"],"ko":["API 변경에 대한 버전 업데이트의 자동화"," 破壊적인 변경에 대한 주요 버전 업그레이드의 결정","새로운 후방 호환 가능한 기능에 대한 중소 버전 업그레이드의 식별"],"es":["Automatizar actualizaciones de versiones para cambios de API","Determinar aumentos de versión MAYOR para cambios de ruptura","Identificar aumentos de versión MENOR para nuevas características compatibles con versiones anteriores"],"fr":["Automatiser les mises à jour de version pour les modifications d''API","Déterminer les augmentations de version MAJEURE pour les modifications de rupture","Identifier les augmentations de version MINEURE pour les nouvelles fonctionnalités compatibles avec les versions antérieures"],"de":["Automatisierung von Versionsaktualisierungen für API-Änderungen","Bestimmung von MAJOR-Versionssprüngen für Änderungen mit Brechung","Identifizierung von MINOR-Versionssprüngen für neue rückwärts kompatible Funktionen"],"pt":["Automatizar atualizações de versão para alterações de API","Determinar aumentos de versão MAJOR para alterações de quebra","Identificar aumentos de versão MINOR para novos recursos compatíveis com versões anteriores"],"ru":["Автоматизация обновлений версий для изменений API","Определение повышений версии MAJOR для изменений, нарушающих совместимость","Определение повышений версии MINOR для новых функций, обратно совместимых с предыдущими версиями"],"ar":["أتمتة تحديثات الإصدار لتحديثات واجهة برمجة التطبيقات","تحديد تحديثات الإصدار الرئيسي لتحديثات لا توافقها","تحديد تحديثات الإصدار الثانوي لسمات جديدة متوافقة مع الإصدارات السابقة"]},"limitations":{"en":["Requires understanding of Semantic Versioning specifications","Limited to version format MAJOR.MINOR.PATCH"],"zh":["需要理解语义版本规范","仅限MAJOR.MINOR.PATCH版本格式"],"ja":["セマンティックバージョニング仕様の理解が必要","バージョン形式はMAJOR.MINOR.PATCHに限定される"],"ko":["시맨틱 버전 규격을 이해해야 함","버전 형식은 주요.중소.패치로 제한됨"],"es":["Requiere comprensión de las especificaciones de Versionado Semántico","Limitado al formato de versión MAYOR.MENOR.CORRECCIÓN"],"fr":["Nécessite une compréhension des spécifications de version sémantique","Limité au format de version MAJEURE.MINEURE.CORRECTION"],"de":["Benötigt Verständnis für die Spezifikationen der Semantischen Versionierung","Begrenzt auf das Versionsformat MAJOR.MINOR.PATCH"],"pt":["Exige compreensão das especificações de Versão Semântica","Limitado ao formato de versão MAJOR.MINOR.PATCH"],"ru":["Требует понимания спецификаций семантического версионирования","Ограничен форматом версии MAJOR.MINOR.PATCH"],"ar":["يتطلب فهم مواصفات النسخة الصيغية","محدود بتنسيق الإصدار الرئيسي.الثانوي.التصحيح"]},"version":4},"contentHash":"cd0567b2d45fcc51305b0205921360ff4f47a2d5be8993e5e286f690c9336217","qualityScore":57}');
