INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('njculpin/BudgetZero/audit-style', 'audit-style', 'njculpin', 'BudgetZero', 'community', 'audit-style njculpin BudgetZero community The audit-style skill audits, normalizes, and refactors CSS to comply with BEM methodology, ensuring maintainability and consistency for developers. It identifies non-compliant selectors and proposes BEM-aligned solutions. audit-style 设计系统优化技能，用于审计、规范化和重构 CSS 以遵循 BEM 方法ology audit-style 設計システムの最適化スキルは、CSS を BEM 方法ology に従って審計、正規化、リファクタリングします audit-style 설계 시스템 최적화 스킬은 CSS 를 BEM 방법ology 에 따라 감사, 표준화 및 리팩토링합니다 Audit-style es una herramienta para auditar y normalizar CSS según la metodología BEM, mejorando la mantenibilidad y escalabilidad. L''audit de style est un outil pour auditer et normaliser le CSS selon la méthodologie BEM, améliorant la maintenabilité et l''évolutivité. Audit-style ist ein Tool, um CSS nach der BEM-Methode zu überprüfen und zu normalisieren, um die Wartbarkeit und Skalierbarkeit zu verbessern. O audit-style é uma habilidade que audita, normaliza e refatora CSS para cumprir com a metodologia BEM, melhorando a manutenção e escalabilidade. Audit-style - это навык, который аудитирует, нормализует и рефакторит CSS для соблюдения методологии BEM, улучшая поддерживаемость и масштабируемость. audit-style هي مهارة تقوم بفحص وتنظيم و إعادة هيكلة CSS لتحقيق طريقة BEM، و تحسين الصيانة وال قابليّة للتوسّع how to use audit-style what is audit-style audit-style alternative audit-style vs css linter audit-style install audit-style setup guide BEM methodology tutorial css audit tools css refactor techniques audit-style 设计系统优化 BEM 方法ology CSS 代码审计 设计系统最优化 可维护性 一致性 可扩展性 Identifies non-compliant CSS selectors Detects design token violations and naming collisions Proposes BEM-aligned refactorings for overly-specific rules Normalizes CSS code for maintainability and consistency Ensures architectural consistency across the Game Loopers application Applies BEM methodology for scalable and consistent design audit-style is a skill that audits and refactors CSS code to comply with the Block–Element–Modifier (BEM) methodology and design system.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SlanyCukr/riot-api-project/Zod v4', 'community', 'SlanyCukr', 'riot-api-project', 'SlanyCukr/riot-api-project', 'Zod v4', 0, 0, 57, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:35.047Z', '0bc4afb143b2965300ab6a2e171252aaa0d4b678efc0ea77e6b25aa0b91c4d70', '{"id":"SlanyCukr/riot-api-project/Zod v4","name":"Zod v4","description":{"en":"Zod v4 is a TypeScript-first schema declaration and validation library that provides static type inference, runtime validation, and exceptional performance for developers. It benefits developers who need efficient schema validation.","zh":"Zod v4 是一个 TypeScript-first 的 schema 声明和验证库，提供静态类型推断、运行时验证和卓越的性能","ja":"Zod v4 は TypeScript-first のスキーマ宣言と検証ライブラリで、静的型推論、実行時検証、優れたパフォーマンスを提供","ko":"Zod v4는 TypeScript-first의 스키마 선언 및 검증 라이브러리로서 정적 타입 추론, 실행 시간 검증 및卓越한 성능을 제공","es":"Zod v4 es una biblioteca de validación de esquemas TypeScript con inferencia de tipos estáticos y validación en tiempo de ejecución. Ofrece un rendimiento excepcional y bundles más pequeños","fr":"Zod v4 est une bibliothèque de validation de schémas TypeScript avec inférence de types statiques et validation à l''exécution. Elle offre des performances exceptionnelles et des bundles plus petits","de":"Zod v4 ist eine TypeScript-Bibliothek für die Validierung von Schemata mit statischer Typprüfung und Laufzeitvalidierung. Sie bietet außergewöhnliche Leistung und kleinere Bundles","pt":"Zod v4 é uma biblioteca de validação de esquemas TypeScript que fornece inferência de tipo estático e desempenho excepcional","ru":"Zod v4 - это библиотека валидации схем на основе TypeScript, обеспечивающая статическую типизацию и исключительное производительность","ar":"Zod v4 هي مكتبة للتحقق من صحة البيانات بالاعتماد على TypeScript وتوفر استنتاج نوع σταتيك و أداء استثنائي"},"seo":{"title":{"en":"Zod v4: TypeScript Schema Validation Setup Guide | AI Age...","zh":"Zod v4 Setup Guide - TypeScript-first Schema Validation","ja":"Zod v4 のセットアップガイド - TypeScript-first スキーマバリデーション","ko":"Zod v4 설정 가이드 - TypeScript-first 스키마 검증","es":"Guía de configuración de Zod v4 - Biblioteca de validació...","fr":"Guide de démarrage rapide de Zod v4 - Bibliothèque de val...","de":"Einrichtungsleitfaden für Zod v4 - Schema-Validierungsbib...","pt":"Guia de Configuração Zod v4: Biblioteca de Validação de E...","ru":"ИИ Агенты: Zod v4 - Настройка и Лучшие Практики","ar":"إعداد أداة Zod v4: مكتبة التحقق من الصحة"},"description":{"en":"Unlock 14x faster parsing and 66% smaller bundles with Zod v4. Learn how to install and use this TypeScript-first schema declaration library today!","zh":"了解 Zod v4 的特点和优势，包括静态类型推断、运行时验证和卓越的性能","ja":"Zod v4 の特徴と利点を学びます。静的型推論、実行時検証、優れたパフォーマンスを実現","ko":"Zod v4의 특징과 장점을 알아보세요. 정적 타입 추론, 실행 시간 검증 및卓越한 성능","es":"Aprende a utilizar Zod v4, una biblioteca de validación de esquemas TypeScript con inferencia de tipos estáticos y validación en tiempo de ejecución","fr":"Découvrez comment utiliser Zod v4, une bibliothèque de validation de schémas TypeScript avec inférence de types statiques et validation à l''exécution","de":"Erfahren Sie, wie Sie Zod v4 verwenden, eine TypeScript-Bibliothek für die Validierung von Schemata mit statischer Typprüfung und Laufzeitvalidierung","pt":"Aprenda a usar a biblioteca Zod v4 para validação de esquemas com inferência de tipo estático e desempenho excepcional","ru":"Узнайте, как настроить и использовать Zod v4 для валидации схем с静ической типизацией и исключительным производительностью","ar":"تعرف على كيفية استخدام مكتبة Zod v4 للتحقق من صحة البيانات مع استنتاج نوع σταتيك و أداء استثنائي"},"definition":{"en":"Zod v4 is a TypeScript-first schema declaration and validation library providing static type inference, runtime validation, and exceptional performance.","zh":"Zod v4 是一个 TypeScript-first 的 schema 验证库","ja":"Zod v4 は TypeScript-first のスキーマ検証ライブラリ","ko":"Zod v4는 TypeScript-first의 스키마 검증 라이브러리","es":"Zod v4 es una biblioteca de validación de esquemas que proporciona inferencia de tipos estáticos y validación en tiempo de ejecución para aplicaciones TypeScript","fr":"Zod v4 est une bibliothèque de validation de schémas qui fournit une inférence de types statiques et une validation à l''exécution pour les applications TypeScript","de":"Zod v4 ist eine Bibliothek für die Validierung von Schemata, die statische Typprüfung und Laufzeitvalidierung für TypeScript-Anwendungen bietet","pt":"O que é Zod v4? É uma biblioteca de validação de esquemas TypeScript","ru":"Что такое Zod v4? Это библиотека валидации схем на основе TypeScript","ar":"ما هي Zod v4? هي مكتبة للتحقق من صحة البيانات بالاعتماد على TypeScript"},"features":{"en":["Provides static type inference for TypeScript","Delivers 14x faster parsing for improved performance","Reduces bundle size by 66% for efficient deployment","Supports runtime validation for robust error handling","Allows for basic schema creation and validation using z.object()","Installs via npm using the command npm install zod@^4.0.0"],"zh":["静态类型推断","运行时验证","14 倍更快的解析速度","66% 更小的包体积","TypeScript-first 的 schema 声明"],"ja":["静的型推論","実行時検証","14 倍速いパース","66% 小さいバンドル","TypeScript-first のスキーマ宣言"],"ko":["정적 타입 추론","실행 시간 검증","14 배 빠른 파싱","66% 더 작은 번들","TypeScript-first의 스키마 선언"],"es":["Inferencia de tipos estáticos","Validación en tiempo de ejecución","Rendimiento excepcional","Bundles más pequeños","Compatibilidad con TypeScript","Instalación sencilla con npm"],"fr":["Inférence de types statiques","Validation à l''exécution","Performances exceptionnelles","Bundles plus petits","Compatibilité avec TypeScript","Installation simple avec npm"],"de":["Statische Typprüfung","Laufzeitvalidierung","Außergewöhnliche Leistung","Kleinere Bundles","Kompatibilität mit TypeScript","Einfache Installation mit npm"],"pt":["Inferência de tipo estático","Validação de esquemas em tempo de execução","Desempenho excepcional com 14x mais rápido de parsing","Pacotes 66% menores","Instalação via npm com ''npm install zod@^4.0.0''"],"ru":["Статическая типизация","Валидация схем в runtime","Исключительное производительность с 14x быстрее парсинга","Пакеты на 66% меньше","Установка через npm с ''npm install zod@^4.0.0''"],"ar":["استنتاج نوع σταتيك","التحقق من صحة البيانات في وقت التشغيل","أداء استثنائي مع 14x أسرع من تحليل البيانات","حزم أصغر بنسبة 66%","التثبيت عبر npm باستخدام ''npm install zod@^4.0.0''"]},"keywords":{"en":["how to use Zod v4","what is Zod v4","Zod v4 alternative","Zod v4 vs JSON Schema","Zod v4 install","Zod v4 setup guide","TypeScript schema validation","Zod v4 TypeScript example","Zod v4 performance optimization"],"zh":["Zod v4","TypeScript-first","schema 验证","静态类型推断","运行时验证","AIエージェント","JavaScript 库"],"ja":["Zod v4","TypeScript-first","スキーマ検証","静的型推論","実行時検証","AIエージェント","JavaScript ライブラリ"],"ko":["Zod v4","TypeScript-first","스키마 검증","정적 타입 추론","실행 시간 검증","AI 도구","JavaScript 라이브러리"],"es":["Zod v4","validación de esquemas","TypeScript","inferencia de tipos estáticos","validación en tiempo de ejecución","rendimiento excepcional","bundles más pequeños","npm","instalación sencilla"],"fr":["Zod v4","validation de schémas","TypeScript","inférence de types statiques","validation à l''exécution","performances exceptionnelles","bundles plus petits","npm","installation simple"],"de":["Zod v4","Validierung von Schemata","TypeScript","statische Typprüfung","Laufzeitvalidierung","außergewöhnliche Leistung","kleinere Bundles","npm","einfache Installation"],"pt":["Zod v4","validação de esquemas","TypeScript","inferência de tipo estático","desempenho excepcional","npm install zod","biblioteca de validação"],"ru":["Zod v4","валидация схем","TypeScript","статическая типизация","исключительное производительность","npm install zod","библиотека валидации"],"ar":["Zod v4","التحقق من صحة البيانات","TypeScript","استنتاج نوع σταتيك","أداء استثنائي","npm install zod","مكتبة التحقق من الصحة"]}},"owner":"SlanyCukr","repo":"riot-api-project","repoPath":"SlanyCukr/riot-api-project","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"Zod v4","description":"TypeScript-first schema validation library with static type inference and runtime validation","bodyPreview":"# Zod v4 - Schema Validation Skill\n\nZod v4 is a TypeScript-first schema declaration and validation library that provides static type inference, runtime validation, and exceptional performance. Version 4 delivers 14x faster parsing and 66% smaller bundles while maintaining full type safety.\n\n## Quick Start\n\n```bash\nnpm install zod@^4.0.0\n```\n\n```typescript\nimport * as z from \"zod\";\n\n// Basic schema creation and validation\nconst UserSchema = z.object({\n  id: z.number().int().positive(),\n  email: z","body":"# Zod v4 - Schema Validation Skill\n\nZod v4 is a TypeScript-first schema declaration and validation library that provides static type inference, runtime validation, and exceptional performance. Version 4 delivers 14x faster parsing and 66% smaller bundles while maintaining full type safety.\n\n## Quick Start\n\n```bash\nnpm install zod@^4.0.0\n```\n\n```typescript\nimport * as z from \"zod\";\n\n// Basic schema creation and validation\nconst UserSchema = z.object({\n  id: z.number().int().positive(),\n  email: z.email(),\n  username: z.string().min(3).max(20),\n  age: z.number().int().min(18).optional(),\n});\n\ntype User = z.infer<typeof UserSchema>;\n\n// Parse and validate\nconst user = UserSchema.parse({\n  id: 1,\n  email: \"user@example.com\",\n  username: \"johndoe\",\n  age: 25,\n});\n\n// Safe parsing with error handling\nconst result = UserSchema.safeParse(input);\nif (!result.success) {\n  console.log(result.error);\n}\n```\n\n## Common Patterns\n\n### Object Schemas with Validation\n\n```typescript\n// Comprehensive user validation\nconst UserProfile = z.object({\n  id: z.number().int().positive(),\n  email: z.email(),\n  username: z\n    .string()\n    .min(3, \"Username must be at least 3 characters\")\n    .max(20, \"Username cannot exceed 20 characters\")\n    .regex(/^[a-zA-Z0-9_]+$/, \"Only alphanumeric characters and underscores\"),\n  age: z.number().int().min(13).max(120),\n  role: z.enum([\"user\", \"admin\", \"moderator\"]).default(\"user\"),\n  bio: z.string().max(500).optional(),\n  website: z.url().optional(),\n  createdAt: z.date().default(() => new Date()),\n});\n\n// Extending schemas\nconst AdminProfile = UserProfile.extend({\n  permissions: z.array(z.string()),\n  accessLevel: z.number().min(1).max(10),\n});\n```\n\n### String Format Validation\n\n```typescript\n// Built-in format validators\nconst Validations = {\n  email: z.email(),\n  uuid: z.uuidv4(),\n  url: z.url(),\n  ipv4: z.ipv4(),\n  ipv6: z.ipv6(),\n  base64: z.base64(),\n  jwt: z.jwt(),\n\n  // ISO formats\n  isoDate: z.iso.date(),\n  isoDateTime: z.iso.datetime(),\n  isoTime: z.iso.time(),\n\n  // Custom email with specific pattern\n  strictEmail: z.email({ pattern: z.regexes.rfc5322Email }),\n};\n\n// Template literal validation\nconst VersionString = z.templateLiteral([\n  z.number(),\n  \".\",\n  z.number(),\n  \".\",\n  z.number(),\n]);\n\nconst CSSValue = z.templateLiteral([\n  z.number(),\n  z.enum([\"px\", \"em\", \"rem\", \"%\", \"vh\", \"vw\"]),\n]);\n```\n\n### Array and Collection Validation\n\n```typescript\n// Array with constraints\nconst NumberArray = z.array(z.number()).min(1).max(100);\n\n// Tuple validation\nconst Coordinates = z.tuple([z.number(), z.number()]);\nconst MixedTuple = z.tuple([z.string(), z.number()], z.boolean());\n\n// Set validation\nconst UniqueStrings = z.set(z.string()).min(3);\n\n// Map validation\nconst UserPermissions = z.map(\n  z.string(), // user ID\n  z.array(z.string()), // permissions\n);\n\n// Record validation\nconst StringToNumber = z.record(z.string(), z.number());\nconst StatusRecord = z.record(\n  z.enum([\"pending\", \"active\", \"complete\"]),\n  z.boolean(),\n);\n```\n\n### Union and Discriminated Unions\n\n```typescript\n// Simple union\nconst StringOrNumber = z.union([z.string(), z.number()]);\n\n// Discriminated union for API responses\nconst ApiResponse = z.discriminatedUnion(\"status\", [\n  z.object({\n    status: z.literal(\"success\"),\n    data: z.unknown(),\n  }),\n  z.object({\n    status: z.literal(\"error\"),\n    error: z.string(),\n    code: z.number(),\n  }),\n  z.object({\n    status: z.literal(\"loading\"),\n    message: z.string().optional(),\n  }),\n]);\n\n// Nested discriminated unions\nconst BaseError = z.object({\n  status: z.literal(\"error\"),\n  message: z.string(),\n});\n\nconst DetailedError = z.discriminatedUnion(\"code\", [\n  BaseError.extend({ code: z.literal(400), field: z.string() }),\n  BaseError.extend({ code: z.literal(401), realm: z.string() }),\n  BaseError.extend({ code: z.literal(500), stack: z.string() }),\n]);\n```\n\n### Custom Refinements and Validation\n\n```typescript\n// Custom validation with refinements\nconst PasswordSchema = z\n  .string()\n  .min(8, \"Password must be at least 8 characters\")\n  .refine((val) => /[A-Z]/.test(val), \"Must contain uppercase letter\")\n  .refine((val) => /[a-z]/.test(val), \"Must contain lowercase letter\")\n  .refine((val) => /[0-9]/.test(val), \"Must contain number\")\n  .refine((val) => /[^A-Za-z0-9]/.test(val), \"Must contain special character\");\n\n// Complex validation with superRefine\nconst UserRegistration = z\n  .object({\n    email: z.email(),\n    password: z.string(),\n    confirmPassword: z.string(),\n    age: z.number(),\n    termsAccepted: z.boolean(),\n  })\n  .superRefine((data, ctx) => {\n    if (data.password !== data.confirmPassword) {\n      ctx.addIssue({\n        code: \"custom\",\n        path: [\"confirmPassword\"],\n        message: \"Passwords must match\",\n      });\n    }\n\n    if (data.age < 18 && !data.termsAccepted) {\n      ctx.addIssue({\n        code: \"custom\",\n        path: [\"termsAccepted\"],\n        message: \"Parental consent required for users under 18\",\n      });\n    }\n  });\n```\n\n### Transformations and Data Processing\n\n```typescript\n// Transform data during validation\nconst StringToNumber = z\n  .string()\n  .transform((val) => parseInt(val, 10))\n  .refine((val) => !isNaN(val), \"Must be a valid number\");\n\nconst TimestampToDate = z\n  .number()\n  .transform((timestamp) => new Date(timestamp));\n\nconst NormalizeEmail = z.string().transform((val) => val.toLowerCase().trim());\n\n// Overwrite for type-preserving transforms\nconst RoundNumber = z.number().overwrite((val) => Math.round(val));\n\n// Pipeline transformations\nconst ProcessUrl = z\n  .string()\n  .transform((val) => val.trim())\n  .transform((val) => val.toLowerCase())\n  .transform((val) => {\n    try {\n      return new URL(val);\n    } catch {\n      throw new Error(\"Invalid URL format\");\n    }\n  });\n```\n\n### Recursive Schemas\n\n```typescript\n// Recursive category structure\nconst Category = z.object({\n  id: z.number(),\n  name: z.string(),\n  get subcategories() {\n    return z.array(Category);\n  },\n});\n\n// Mutually recursive types\nconst User = z.object({\n  id: z.number(),\n  name: z.string(),\n  get posts() {\n    return z.array(Post);\n  },\n});\n\nconst Post = z.object({\n  id: z.number(),\n  title: z.string(),\n  content: z.string(),\n  get author() {\n    return User;\n  },\n  get comments() {\n    return z.array(Comment);\n  },\n});\n\nconst Comment = z.object({\n  id: z.number(),\n  text: z.string(),\n  get author() {\n    return User.pick({ id: true, name: true });\n  },\n});\n```\n\n### File Validation\n\n```typescript\n// File upload validation\nconst ImageUpload = z.object({\n  avatar: z\n    .file()\n    .max(5_000_000, \"File must be less than 5MB\")\n    .mime([\"image/jpeg\", \"image/png\", \"image/webp\"], \"Must be an image\"),\n\n  banner: z\n    .file()\n    .max(10_000_000, \"File must be less than 10MB\")\n    .mime([\"image/jpeg\", \"image/png\"], \"Must be JPEG or PNG\")\n    .optional(),\n});\n\n// Document validation\nconst DocumentUpload = z\n  .file()\n  .min(1000, \"File must be at least 1KB\")\n  .max(50_000_000, \"File must be less than 50MB\")\n  .mime([\n    \"application/pdf\",\n    \"application/msword\",\n    \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\n  ]);\n```\n\n### Function Validation\n\n```typescript\n// Define validated functions\nconst CalculateTax = z.function({\n  input: [z.number().min(0), z.number().min(0).max(1)],\n  output: z.number(),\n});\n\nconst taxCalculator = CalculateTax.implement((amount, rate) => {\n  return amount * rate;\n});\n\n// Async function validation\nconst FetchUser = z.function({\n  input: [z.number().int().positive()],\n  output: z.object({\n    id: z.number(),\n    name: z.string(),\n    email: z.email(),\n  }),\n});\n\nconst getUser = FetchUser.implementAsync(async (id) => {\n  const response = await fetch(`/api/users/${id}`);\n  return response.json();\n});\n```\n\n### Error Handling\n\n```typescript\n// Custom error messages\nconst CustomValidation = z.object({\n  username: z\n    .string({\n      error: (issue) => {\n        if (issue.input === undefined) return \"Username is required\";\n        if (typeof issue.input !== \"string\") return \"Username must be a string\";\n        return \"Invalid username\";\n      },\n    })\n    .min(3, \"Username must be at least 3 characters\"),\n});\n\n// Error handling patterns\nconst validateInput = (input: unknown) => {\n  const result = UserSchema.safeParse(input);\n\n  if (!result.success) {\n    const error = result.error;\n\n    // Pretty print errors\n    console.log(z.prettifyError(error));\n\n    // Extract field errors\n    const fieldErrors = error.issues.reduce(\n      (acc, issue) => {\n        const field = issue.path.join(\".\");\n        acc[field] = issue.message;\n        return acc;\n      },\n      {} as Record<string, string>,\n    );\n\n    return { success: false, errors: fieldErrors };\n  }\n\n  return { success: true, data: result.data };\n};\n```\n\n### Default Values and Coercion\n\n```typescript\n// Schema with defaults\nconst ConfigSchema = z.object({\n  theme: z.enum([\"light\", \"dark\"]).default(\"light\"),\n  notifications: z.boolean().default(true),\n  fontSize: z.number().min(10).max(30).default(14),\n  timeout: z.number().default(5000),\n});\n\n// Type coercion\nconst CoercedConfig = z.object({\n  port: z.coerce.number().default(3000),\n  https: z.coerce.boolean().default(false),\n  maxConnections: z.coerce.number().int().positive().default(100),\n});\n\n// Environment variable parsing\nconst EnvSchema = z.object({\n  NODE_ENV: z\n    .enum([\"development\", \"production\", \"test\"])\n    .default(\"development\"),\n  PORT: z.coerce.number().default(3000),\n  DEBUG: z.stringbool().default(\"false\"),\n});\n```\n\n### Zod Mini (Tree-Shakable)\n\n```typescript\nimport * as z from \"zod/mini\";\n\n// Functional API for smaller bundles\nconst OptionalString = z.optional(z.string());\nconst StringArray = z.array(z.string());\nconst StringOrNumber = z.union([z.string(), z.number()]);\n\n// Check functions for validations\nconst ValidatedEmail = z\n  .string()\n  .check(z.regex(/@/), z.minLength(5), z.maxLength(100));\n\nconst PositiveInt = z.number().check(z.int(), z.positive(), z.lt(1000));\n\nconst NonEmptyArray = z.array(z.any()).check(z.minSize(1));\n```\n\n## Practical Examples\n\n### Form Validation\n\n```typescript\n// Contact form validation\nconst ContactForm = z.object({\n  name: z.string().min(1, \"Name is required\").max(100),\n  email: z.email(\"Please provide a valid email\"),\n  subject: z.string().min(5, \"Subject must be at least 5 characters\"),\n  message: z.string().min(10, \"Message must be at least 10 characters\"),\n  newsletter: z.boolean().default(false),\n});\n\n// React form integration\nconst handleSubmit = (formData: FormData) => {\n  const data = {\n    name: formData.get(\"name\"),\n    email: formData.get(\"email\"),\n    subject: formData.get(\"subject\"),\n    message: formData.get(\"message\"),\n    newsletter: formData.get(\"newsletter\") === \"on\",\n  };\n\n  const result = ContactForm.safeParse(data);\n  if (!result.success) {\n    const errors = result.error.flatten();\n    return { errors: errors.fieldErrors };\n  }\n\n  // Process valid data\n  return { success: true, data: result.data };\n};\n```\n\n### API Response Validation\n\n```typescript\n// API response schemas\nconst UserResponse = z.object({\n  data: z.object({\n    id: z.number(),\n    name: z.string(),\n    email: z.email(),\n    createdAt: z.string().transform((val) => new Date(val)),\n  }),\n  meta: z.object({\n    total: z.number(),\n    page: z.number(),\n    totalPages: z.number(),\n  }),\n});\n\n// Typed API client\nconst apiClient = {\n  async getUser(id: number): Promise<z.infer<typeof UserResponse>[\"data\"]> {\n    const response = await fetch(`/api/users/${id}`);\n    const data = await response.json();\n\n    const result = UserResponse.safeParse(data);\n    if (!result.success) {\n      throw new Error(`Invalid API response: ${result.error.message}`);\n    }\n\n    return result.data.data;\n  },\n};\n```\n\n### Configuration Validation\n\n```typescript\n// Application configuration\nconst AppConfig = z.object({\n  server: z.object({\n    port: z.coerce.number().min(1).max(65535).default(3000),\n    host: z.string().default(\"localhost\"),\n    cors: z.boolean().default(true),\n  }),\n  database: z.object({\n    url: z.string(),\n    ssl: z.boolean().default(false),\n    maxConnections: z.coerce.number().int().positive().default(10),\n  }),\n  auth: z.object({\n    jwtSecret: z.string().min(32),\n    tokenExpiry: z.string().default(\"24h\"),\n    refreshExpiry: z.string().default(\"7d\"),\n  }),\n});\n\n// Load and validate config\nconst loadConfig = (configPath: string) => {\n  const rawConfig = require(configPath);\n  const config = AppConfig.parse(rawConfig);\n  return config;\n};\n```\n\n## Requirements\n\n- **TypeScript**: 4.5+ (recommended for best inference)\n- **Runtime**: Node.js, browsers, Deno, Bun\n- **Bundle size**: 5.36kb gzipped (full), 1.88kb gzipped (mini)\n\n## Installation\n\n```bash\n# Full Zod v4\nnpm install zod@^4.0.0\n\n# For minimal bundle size\nnpm install zod@^4.0.0\n# Then import from \"zod/mini\"\n```\n\n## Key Features\n\n- **Static Type Inference**: Automatic TypeScript type generation from schemas\n- **Runtime Validation**: Comprehensive input validation with detailed errors\n- **Performance**: 14x faster parsing than v3, optimized for production\n- **Tree Shakable**: Zod Mini provides 85% bundle size reduction\n- **Template Literals**: Validate string patterns matching TypeScript template literals\n- **File Validation**: Built-in File object validation with size and MIME type constraints\n- **Recursive Types**: Full support for recursive and self-referential schemas\n- **JSON Schema**: First-party JSON Schema generation\n- **Function Validation**: Type-safe function definitions with validated inputs/outputs\n"},"lastSynced":"2026-03-08T02:01:35.047Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript-based AI Agents needing efficient schema validation and runtime type checking.","zh":"非常适合基于 TypeScript 的 AI Agent 进行高效的架构验证和运行时类型检查。","ja":"TypeScript ベースの AI エージェントが効率的なスキーマ検証とランタイム型チェックを必要とする場合に最適です。","ko":"TypeScript 기반 AI Agent가 효율적인 스키마 검증 및 런타임 유형 검사가 필요한 경우에 완벽합니다.","es":"Perfecto para Agentes de IA basados en TypeScript que necesitan una validación de esquema eficiente y una comprobación de tipo en tiempo de ejecución.","fr":"Parfait pour les Agents d''IA basés sur TypeScript nécessitant une validation de schéma efficace et une vérification de type à l''exécution.","de":"Ideal für TypeScript-basierte KI-Agents, die eine effiziente Schemavalidierung und eine Laufzeit-Typüberprüfung benötigen.","pt":"Perfeito para Agentes de IA baseados em TypeScript que necessitam de validação de esquema eficiente e verificação de tipo em tempo de execução.","ru":"Идеально подходит для агентов ИИ на основе TypeScript, которым необходима эффективная проверка схемы и проверка типов во время выполнения.","ar":"مثالي لعميل الذكاء الاصطناعي المبني على TypeScript الذي يحتاج إلى التحقق من مخطط فعال و فحص أنواع زمن التشغيل."},"recommendation":{"en":"Empowers agents to leverage static type inference and runtime validation with exceptional performance, utilizing TypeScript-first schema declaration and validation libraries like Zod v4, which delivers 14x faster parsing and 66% smaller bundles while maintaining full type safety.","zh":"使 Agent 能够利用静态类型推断和运行时验证，并获得卓越性能。它利用 Zod v4 等 TypeScript 优先的架构声明和验证库，可提供 14 倍更快的解析速度和 66% 更小的捆绑包，同时保持完整的类型安全。","ja":"エージェントが静的な型推論とランタイム検証を活用し、卓越したパフォーマンスを発揮できるようにします。Zod v4 のような TypeScript ファーストのスキーマ宣言および検証ライブラリを利用し、完全な型安全性を維持しながら、14 倍高速な解析と 66% 小さなバンドルを実現します。","ko":"Agent가 정적 유형 추론과 런타임 검증을 활용하여 탁월한 성능을 발휘할 수 있도록 합니다. Zod v4와 같은 TypeScript 우선 스키마 선언 및 검증 라이브러리를 활용하여 완전한 유형 안전성을 유지하면서 14배 더 빠른 구문 분석과 66% 더 작은 번들을 제공합니다.","es":"Habilita a los agentes a aprovechar la inferencia de tipo estático y la validación en tiempo de ejecución con un rendimiento excepcional, utilizando bibliotecas de declaración y validación de esquemas de primera generación de TypeScript como Zod v4, que ofrece un análisis 14 veces más rápido y paquetes un 66% más pequeños manteniendo la seguridad de tipo completa.","fr":"Permet aux agents d''exploiter l''inférence de type statique et la validation à l''exécution avec des performances exceptionnelles, en utilisant des bibliothèques de déclaration et de validation de schémas de première génération de TypeScript comme Zod v4, qui offre un parsing 14 fois plus rapide et des bundles 66% plus petits tout en maintenant la sécurité de type complète.","de":"Ermöglicht es den Agenten, die statische Typinferenz und Laufzeitvalidierung mit außergewöhnlicher Leistung zu nutzen, indem sie Bibliotheken für die Erklärung und Validierung von Schemata in erster Linie für TypeScript wie Zod v4 verwenden, die ein 14-mal schnelleres Parsen und 66% kleinere Pakete bei voller Typsicherheit bietet.","pt":"Habilita os agentes a aproveitar a inferência de tipo estático e a validação em tempo de execução com desempenho excepcional, utilizando bibliotecas de declaração e validação de esquema TypeScript-first como Zod v4, que oferece análise 14x mais rápida e pacotes 66% menores, mantendo a segurança total de tipo.","ru":"Предоставляет агентам возможность использовать статическую инференцию типов и проверку во время выполнения с исключительной производительностью, используя библиотеки объявления и проверки схемы на основе TypeScript, такие как Zod v4, которые обеспечивают парсинг 14 раз быстрее и пакеты на 66% меньше, сохраняя при этом полную безопасность типов.","ar":"تمكن الوكلاء من الاستفادة من الاستدلال الساكن لنوع والتحقق من الصحة في وقت التشغيل بأداء استثنائي، باستخدام مكتبات الإعلان والتحقق من مخطط أولي من النوع السكريبت مثل Zod v4، الذي يوفر تحليل أسرع 14 مرة وحزم أصغر بنسبة 66٪ مع الحفاظ على سلامة الكامل لنوع."},"useCases":{"en":["Validating user input data with custom schemas","Generating schema-based data models for runtime validation","Optimizing data parsing with Zod v4''s high-performance capabilities"],"zh":["使用自定义架构验证用户输入数据","为运行时验证生成基于架构的数据模型","利用 Zod v4 的高性能功能优化数据解析"],"ja":["カスタムスキーマを使用したユーザー入力データの検証","ランタイム検証のためのスキーマベースのデータモデルの生成","Zod v4 の高性能機能を利用したデータ解析の最適化"],"ko":["사용자 정의 스키마로 사용자 입력 데이터 검증","런타임 검증을 위한 스키마 기반 데이터 모델 생성","Zod v4의 고성능 기능으로 데이터 구문 분석 최적화"],"es":["Validar datos de entrada de usuario con esquemas personalizados","Generar modelos de datos basados en esquemas para validación en tiempo de ejecución","Optimizar el análisis de datos con las capacidades de alto rendimiento de Zod v4"],"fr":["Valider les données de saisie utilisateur avec des schémas personnalisés","Générer des modèles de données basés sur des schémas pour validation à l''exécution","Optimiser l''analyse des données avec les capacités de haute performance de Zod v4"],"de":["Benutzereingabedaten mit benutzerdefinierten Schemata validieren","Schemabasierte Datamodelle für Laufzeitvalidierung generieren","Datenparsen mit den Hochleistungs-Fähigkeiten von Zod v4 optimieren"],"pt":["Validar dados de entrada do usuário com esquemas personalizados","Gerar modelos de dados baseados em esquema para validação em tempo de execução","Otimizar o parsing de dados com as capacidades de alto desempenho do Zod v4"],"ru":["Проверка данных ввода пользователя с помощью пользовательских схем","Генерация моделей данных на основе схемы для проверки во время выполнения","Оптимизация парсинга данных с помощью возможностей высокого производительности Zod v4"],"ar":["التحقق من بيانات إدخال المستخدم بواسطة مخططات مخصصة","إنشاء نماذج بيانات مبنية على مخطط للتحقق في وقت التشغيل","تحسين تحليل بيانات باستخدام إمكانيات أداء عالية من Zod v4"]},"limitations":{"en":["Requires TypeScript environment","Version 4.0.0 or higher of Zod library"],"zh":["需要 TypeScript 环境","需要 Zod 库的 4.0.0 或更高版本"],"ja":["TypeScript 環境が必要","Zod ライブラリのバージョン 4.0.0 以上が必要"],"ko":["TypeScript 환경이 필요함","Zod 라이브러리 버전 4.0.0 이상 필요"],"es":["Requiere entorno de TypeScript","Versión 4.0.0 o superior de la biblioteca Zod"],"fr":["Nécessite un environnement TypeScript","Version 4.0.0 ou supérieure de la bibliothèque Zod"],"de":["Benötigt eine TypeScript-Umgebung","Version 4.0.0 oder höher der Zod-Bibliothek"],"pt":["Requer ambiente TypeScript","Versão 4.0.0 ou superior da biblioteca Zod"],"ru":["Требуется среда TypeScript","Версия 4.0.0 или выше библиотеки Zod"],"ar":["يتطلب بيئة TypeScript","الإصدار 4.0.0 أو أعلى من مكتبة Zod"]},"version":4},"contentHash":"0bc4afb143b2965300ab6a2e171252aaa0d4b678efc0ea77e6b25aa0b91c4d70","qualityScore":57}');
