INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SlanyCukr/riot-api-project/Zod v4', 'Zod v4', 'SlanyCukr', 'riot-api-project', 'community', 'Zod v4 SlanyCukr riot-api-project community Zod v4 is a TypeScript-first schema declaration and validation library that provides static type inference, runtime validation, and exceptional performance for developers. It benefits developers who need efficient schema validation. Zod v4 是一个 TypeScript-first 的 schema 声明和验证库，提供静态类型推断、运行时验证和卓越的性能 Zod v4 は TypeScript-first のスキーマ宣言と検証ライブラリで、静的型推論、実行時検証、優れたパフォーマンスを提供 Zod v4는 TypeScript-first의 스키마 선언 및 검증 라이브러리로서 정적 타입 추론, 실행 시간 검증 및卓越한 성능을 제공 Zod v4 es una biblioteca de validación de esquemas TypeScript con inferencia de tipos estáticos y validación en tiempo de ejecución. Ofrece un rendimiento excepcional y bundles más pequeños Zod v4 est une bibliothèque de validation de schémas TypeScript avec inférence de types statiques et validation à l''exécution. Elle offre des performances exceptionnelles et des bundles plus petits Zod v4 ist eine TypeScript-Bibliothek für die Validierung von Schemata mit statischer Typprüfung und Laufzeitvalidierung. Sie bietet außergewöhnliche Leistung und kleinere Bundles Zod v4 é uma biblioteca de validação de esquemas TypeScript que fornece inferência de tipo estático e desempenho excepcional Zod v4 - это библиотека валидации схем на основе TypeScript, обеспечивающая статическую типизацию и исключительное производительность Zod v4 هي مكتبة للتحقق من صحة البيانات بالاعتماد على TypeScript وتوفر استنتاج نوع σταتيك و أداء استثنائي how to use Zod v4 what is Zod v4 Zod v4 alternative Zod v4 vs JSON Schema Zod v4 install Zod v4 setup guide TypeScript schema validation Zod v4 TypeScript example Zod v4 performance optimization Zod v4 TypeScript-first schema 验证 静态类型推断 运行时验证 AIエージェント JavaScript 库 Provides static type inference for TypeScript Delivers 14x faster parsing for improved performance Reduces bundle size by 66% for efficient deployment Supports runtime validation for robust error handling Allows for basic schema creation and validation using z.object() Installs via npm using the command npm install zod@^4.0.0 Zod v4 is a TypeScript-first schema declaration and validation library providing static type inference, runtime validation, and exceptional performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenSourceSam/v2_heras_garden/image-analysis', 'community', 'OpenSourceSam', 'v2_heras_garden', 'OpenSourceSam/v2_heras_garden', 'image-analysis', 0, 0, 57, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:37.928Z', '53f4fcc4ae90f6c0d486dffed571eaf03d3fd8b6350bf74425b52b0a4818ca91', '{"id":"OpenSourceSam/v2_heras_garden/image-analysis","name":"image-analysis","description":{"en":"The image-analysis skill delegates image analysis tasks to GLM-4.6v subagent for visual quality assessment of game screenshots and sprites, benefiting game developers and testers.","zh":"图像分析技能用于评估游戏截图和精灵的视觉质量，支持GLM-4.6v子代理","ja":"画像分析スキルは、ゲームのスクリーンショットとスプライトの視覚品質を評価するために使用され、GLM-4.6vサブエージェントをサポートする","ko":"이미지 분석 스킬은 게임 스크린샷과 스프라이트의 시각 품질을 평가하는 데 사용되며 GLM-4.6v 서브 에이전트를 지원합니다","es":"El análisis de imágenes es una habilidad que permite a los desarrolladores evaluar la calidad visual de capturas de pantalla y sprites de juegos","fr":"L''analyse d''images est une compétence qui permet aux développeurs d''évaluer la qualité visuelle des captures d''écran et des sprites de jeux","de":"Die Bildanalyse ist eine Fähigkeit, die es Entwicklern ermöglicht, die visuelle Qualität von Spielscreenshots und -sprites zu bewerten","pt":"A análise de imagem é uma habilidade que delega tarefas de avaliação de qualidade visual de imagens ao subagente GLM-4.6v.","ru":"Анализ изображений - это навык, который делегирует задачи оценки визуального качества изображений субагенту GLM-4.6v.","ar":"تحليل الصور هو مهارة تفويض مهام تقييم الجودة البصرية للصور إلى الوكيل الفرعي GLM-4.6v."},"seo":{"title":{"en":"image-analysis: Visual Quality Assessment for AI Agents |...","zh":"图像分析技能设置指南 - 基于GLM-4.6v的视觉质量评估","ja":"画像分析スキル設定ガイド - GLM-4.6vを用いた視覚品質評価","ko":"이미지 분석 스킬 설정 가이드 - GLM-4.6v를 이용한 시각 품질 평가","es":"Análisis de Imágenes: Guía de Configuración para Desarrol...","fr":"Analyse d''Image : Guide d''Installation pour Développeurs","de":"Bildanalyse: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração de Análise de Imagem com Ferramentas...","ru":"Настройка анализа изображений с помощью ИИ Агентов","ar":"دليل إعداد تحليل الصور باستخدام أدوات الإيجنت الذكية"},"description":{"en":"Unlock the power of image-analysis for AI agents. Learn how to delegate visual quality assessment tasks and improve your game development workflow. Get start...","zh":"使用图像分析技能评估游戏截图和精灵的视觉质量，确保资产符合Harvest Moon SNES风格","ja":"画像分析スキルを使用してゲームのスクリーンショットとスプライトの視覚品質を評価し、Harvest Moon SNESスタイルに準拠したアセットを保証する","ko":"이미지 분석 스킬을 사용하여 게임 스크린샷과 스프라이트의 시각 품질을 평가하고 Harvest Moon SNES 스타일의 자산을 보장합니다","es":"Aprende a delegar tareas de análisis de imágenes a GLM-4.6v para evaluar la calidad visual de capturas de pantalla y sprites de juegos","fr":"Découvrez comment déléguer des tâches d''analyse d''images à GLM-4.6v pour évaluer la qualité visuelle des captures d''écran et des sprites de jeux","de":"Erfahren Sie, wie Sie Bildanalyseaufgaben an GLM-4.6v übertragen, um die visuelle Qualität von Spielscreenshots und -sprites zu bewerten","pt":"Aprenda a delegar tarefas de análise de imagem ao subagente GLM-4.6v para avaliar a qualidade visual de capturas de tela de jogos e sprites","ru":"Узнайте, как делегировать задачи анализа изображений субагенту GLM-4.6v для оценки визуального качества скриншотов игр и спрайтов","ar":"تعرف على كيفية تفويض مهام تحليل الصور إلى الوكيل الفرعي GLM-4.6v لتقييم الجودة البصرية لصور الشاشة وألعاب الsprite"},"definition":{"en":"image-analysis is a skill that enables AI agents to assess visual quality of images, including game screenshots and sprites, for quality validation and comparison.","zh":"图像分析技能是一种AI工具，用于委托GLM-4.6v子代理评估游戏截图和精灵的视觉质量","ja":"画像分析スキルは、GLM-4.6vサブエージェントにゲームのスクリーンショットとスプライトの視覚品質を評価するタスクを委任するAIエージェントの一種","ko":"이미지 분석 스킬은 게임 스크린샷과 스프라이트의 시각 품질을 평가하기 위해 GLM-4.6v 서브 에이전트에 태스크를 위임하는 AI 에이전트의 일종입니다","es":"Análisis de imágenes es la capacidad de evaluar la calidad visual de imágenes utilizando técnicas de procesamiento de imágenes","fr":"L''analyse d''images est la capacité d''évaluer la qualité visuelle des images à l''aide de techniques de traitement d''images","de":"Bildanalyse ist die Fähigkeit, die visuelle Qualität von Bildern mithilfe von Bildverarbeitungstechniken zu bewerten","pt":"Análise de imagem é uma técnica que utiliza algoritmos para avaliar a qualidade visual de imagens.","ru":"Анализ изображений - это техника, которая использует алгоритмы для оценки визуального качества изображений.","ar":"تحليل الصور هو تقنية تستخدم الخوارزميات لتقييم الجودة البصرية للصور."},"features":{"en":["Delegates image analysis tasks to GLM-4.6v subagent","Supports visual quality assessment of game screenshots and sprites","Validates images for blocky backgrounds or transparency issues","Compares assets against Harvest Moon SNES style","Integrates with glm-image-gen for new sprite generation","Enables direct vs delegated analysis via Claude Opus"],"zh":["支持GLM-4.6v子代理","评估游戏截图和精灵的视觉质量","检查块状背景或透明度问题","比较资产与Harvest Moon SNES风格","支持新精灵生成和截图捕获"],"ja":["GLM-4.6vサブエージェントをサポート","ゲームのスクリーンショットとスプライトの視覚品質を評価","ブロック状の背景や透明度の問題をチェック","アセットをHarvest Moon SNESスタイルと比較","新しいスプライトの生成とスクリーンショットのキャプチャをサポート"],"ko":["GLM-4.6v 서브 에이전트 지원","게임 스크린샷과 스프라이트의 시각 품질 평가","블록状 배경이나 투명도 문제 확인","자산을 Harvest Moon SNES 스타일과 비교","새로운 스프라이트 생성과 스크린샷 캡처 지원"],"es":["Delegación de tareas de análisis de imágenes a GLM-4.6v","Evaluación de la calidad visual de capturas de pantalla y sprites de juegos","Detección de fondos bloqueados o problemas de transparencia","Comparación de activos con el estilo Harvest Moon SNES","Integración con glm-image-gen para la generación de sprites","Análisis directo y delegado mediante Claude Opus"],"fr":["Délégation de tâches d''analyse d''images à GLM-4.6v","Évaluation de la qualité visuelle des captures d''écran et des sprites de jeux","Détection d''arrières-plans bloqués ou de problèmes de transparence","Comparaison d''actifs avec le style Harvest Moon SNES","Intégration avec glm-image-gen pour la génération de sprites","Analyse directe et déléguée via Claude Opus"],"de":["Übertragung von Bildanalyseaufgaben an GLM-4.6v","Bewertung der visuellen Qualität von Spielscreenshots und -sprites","Erkennung von blockierten Hintergründen oder Transparenzproblemen","Vergleich von Assets mit dem Harvest Moon SNES-Stil","Integration mit glm-image-gen für die Erzeugung von Sprites","Direkte und delegierte Analyse mittels Claude Opus"],"pt":["Avaliação de qualidade visual de capturas de tela de jogos","Análise de sprites gerados via glm-image-gen","Validação de qualidade visual antes de commits","Detecção de fundos blocados ou problemas de transparência","Comparação de ativos com o estilo Harvest Moon SNES"],"ru":["Оценка визуального качества скриншотов игр","Анализ спрайтов, сгенерированных через glm-image-gen","Валидация визуального качества перед коммитами","Обнаружение блокированных фонов или проблем прозрачности","Сравнение активов со стилем Harvest Moon SNES"],"ar":["تقييم الجودة البصرية لصور الشاشة للألعاب","تحليل sprites المنشأة عبر glm-image-gen","التحقق من الجودة البصرية قبل الإلتزام","كشف الخلفيات المحجوبة أو مشاكل الشفافية","مقارنة الأصول بنمط Harvest Moon SNES"]},"keywords":{"en":["how to use image-analysis","image-analysis alternative","image-analysis setup guide","what is image-analysis","image-analysis vs computer vision","image-analysis install for AI agents","visual quality assessment tools","game development with image-analysis","glm-image-gen integration"],"zh":["图像分析技能","GLM-4.6v","视觉质量评估","游戏截图","精灵生成","AI工具","图像分析AI","游戏开发","视觉品质"],"ja":["画像分析スキル","GLM-4.6v","視覚品質評価","ゲームスクリーンショット","スプライト生成","AIエージェント","画像分析AI","ゲーム開発","視覚品質"],"ko":["이미지 분석 스킬","GLM-4.6v","시각 품질 평가","게임 스크린샷","스프라이트 생성","AI 에이전트","이미지 분석 AI","게임 개발","시각 품질"],"es":["análisis de imágenes","GLM-4.6v","evaluación de calidad visual","capturas de pantalla de juegos","sprites de juegos","detección de fondos bloqueados","comparación de activos","glm-image-gen","Claude Opus","herramientas de AI para desarrolladores"],"fr":["analyse d''images","GLM-4.6v","évaluation de la qualité visuelle","captures d''écran de jeux","sprites de jeux","détection d''arrières-plans bloqués","comparaison d''actifs","glm-image-gen","Claude Opus","outils d''IA pour développeurs"],"de":["Bildanalyse","GLM-4.6v","Bewertung der visuellen Qualität","Spielscreenshots","Sprites von Spielen","Erkennung von blockierten Hintergründen","Vergleich von Assets","glm-image-gen","Claude Opus","KI-Tools für Entwickler"],"pt":["análise de imagem","ferramentas de ia","glm-4.6v","qualidade visual","capturas de tela de jogos","sprites","glm-image-gen","validação de qualidade"],"ru":["анализ изображений","ии агенты","glm-4.6v","визуальное качество","скриншоты игр","спрайты","glm-image-gen","валидация качества"],"ar":["تحليل الصور","أدوات الإيجنت الذكية","glm-4.6v","الجودة البصرية","صور الشاشة للألعاب","sprites","glm-image-gen","التحقق من الجودة"]}},"owner":"OpenSourceSam","repo":"v2_heras_garden","repoPath":"OpenSourceSam/v2_heras_garden","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"image-analysis","description":"GLM-4.6v image analysis subagent for game screenshot and sprite quality assessment","bodyPreview":"# Image Analysis Skill\n\n**Purpose:** Delegate image analysis tasks to GLM-4.6v subagent for visual quality assessment of game screenshots and sprites.\n\n## When to Use\n\nInvoke this skill when:\n- New sprites are generated (via glm-image-gen)\n- Screenshots captured during playtesting\n- Visual quality validation needed before commits\n- Checking for blocky backgrounds or transparency issues\n- Comparing assets against Harvest Moon SNES style\n\n## Direct vs Delegated Analysis\n\n**Claude Opus can analyze","body":"# Image Analysis Skill\n\n**Purpose:** Delegate image analysis tasks to GLM-4.6v subagent for visual quality assessment of game screenshots and sprites.\n\n## When to Use\n\nInvoke this skill when:\n- New sprites are generated (via glm-image-gen)\n- Screenshots captured during playtesting\n- Visual quality validation needed before commits\n- Checking for blocky backgrounds or transparency issues\n- Comparing assets against Harvest Moon SNES style\n\n## Direct vs Delegated Analysis\n\n**Claude Opus can analyze images directly** via the Read tool. Choose the right approach:\n\n| Scenario | Approach | Why |\n|----------|----------|-----|\n| 1-3 images | Claude Direct | No overhead, faster |\n| Quick quality check | Claude Direct | Immediate feedback |\n| Batch analysis (10+) | MiniMax Parallel | Token efficiency |\n| Extensive visual QA | MiniMax Parallel | 50x cheaper |\n\n### Claude Direct Pattern\n```\nRead image file → Analyze in-context → Continue workflow\n```\n\n### MiniMax/GLM Delegation Pattern (for batches)\n```\nSpawn parallel agents → Each analyzes subset → Aggregate results\n```\n\n**Default:** Use Claude Direct for small tasks, delegate batches to save tokens.\n\n## Quick Start\n\n### Analyze Screenshot\n```bash\nmcp__4_5v_mcp__analyze_image \\\n  --imageSource \"temp/screenshots/[filename].png\" \\\n  --prompt \"Analyze this game screenshot for visual quality. Check for: blocky backgrounds, tiling seams, sprite transparency issues, pixel art scaling problems, overall Harvest Moon SNES readability. Provide specific, actionable feedback.\"\n```\n\n### Analyze Sprite Asset\n```bash\nmcp__4_5v_mcp__analyze_image \\\n  --imageSource \"assets/sprites/placeholders/[filename].png\" \\\n  --prompt \"Analyze this pixel art sprite for Harvest Moon SNES style quality. Check: transparency (clean edges), silhouette (strong/readable), proportions (compact not stretched), color palette (dusk-friendly), pixel detail (minimal noise). Reference: assets/sprites/PLACEHOLDER_ASSET_SPEC.txt\"\n```\n\n### Analyze NPC Sprite\n```bash\nmcp__4_5v_mcp__analyze_image \\\n  --imageSource \"assets/sprites/placeholders/npc_[name].png\" \\\n  --prompt \"Analyze this 64x64 NPC sprite. Target proportions: ~48h x 32w centered. Check: strong silhouette, Mediterranean theme alignment, clean transparency, no elongation. Harvest Moon SNES style reference.\"\n```\n\n## Standard Prompts\n\n### Full Quality Assessment\n```\nAnalyze this image for Circe''s Garden game quality standards:\n\nVisual Style:\n- Harvest Moon SNES readability (clean pixel art, strong silhouettes)\n- Stardew Valley influence (but more mythic/moody)\n- Mediterranean ancient Greek island theme\n- Dusk-friendly palette (muted, not oversaturated)\n- 32px tiles, 2x camera zoom\n\nCheck For:\n1. Background issues: blocky patterns, tiling seams, color banding\n2. Transparency: clean edges (no halos), proper alpha channel\n3. Pixel art: minimal noise, clear details, proper scaling\n4. Proportions: compact bodies, not stretched/elongated\n5. Colors: natural earth tones, muted jewel accents\n6. Lighting: soft ambient, no harsh specular\n7. Silhouette: strong, recognizable at small size\n\nProvide specific feedback: what works, what needs fixing, file references.\n```\n\n### Transparency Check (Focused)\n```\nCheck this sprite for transparency issues:\n- Halo effect (light/dark ring around edges)\n- Color bleeding (background showing through)\n- Harsh edges (no smooth curves on diagonals)\n- Partial transparency (should be opaque or transparent, not in-between)\n\nReport specific pixel locations and severity.\n```\n\n### Style Comparison\n```\nCompare this asset to Harvest Moon SNES style:\n- Clean pixel art with minimal noise\n- Strong silhouette (recognizable at 32x32)\n- Soft, natural color palette\n- Proper alpha blending\n- No anti-aliasing on edges\n- Cozy, approachable aesthetic\n\nReport what matches style and what deviates.\n```\n\n## Output Format\n\nExpected response should include:\n\n```markdown\n## Analysis Summary\n[One-line assessment: PASS / NEEDS WORK / FAIL]\n\n### Issues Found\n**Critical (P0):**\n- [Specific issue with location]\n\n**Important (P1):**\n- [Issue description]\n\n**Minor (P2):**\n- [Minor detail]\n\n### What Works\n- [Positive aspects to preserve]\n\n### Recommendations\n1. [Actionable fix 1]\n2. [Actionable fix 2]\n```\n\n## Common Issues\n\n| Issue | Detection | Fix |\n|-------|-----------|-----|\n| Blocky background | Visible pixel grid, tiling patterns | Regenerate with better seam handling |\n| Halo effect | Light/dark ring around sprite | Fix alpha channel, clean edges |\n| Color bleeding | Background color in transparent pixels | Re-export with proper transparency |\n| Stretched proportions | Elongated body/limbs | Regenerate with compact proportions |\n| Oversaturated colors | Too bright/vibrant | Adjust palette to dusk-friendly tones |\n| Poor silhouette | Not recognizable at small size | Strengthen outline, simplify details |\n\n## File Locations\n\n**Input:**\n- Screenshots: `temp/screenshots/`\n- Sprites: `assets/sprites/`\n- Placeholders: `assets/sprites/placeholders/`\n\n**Reference:**\n- Asset specs: `assets/sprites/PLACEHOLDER_ASSET_SPEC.txt`\n- Style guide: `assets/sprites/PLACEHOLDER_README.md`\n\n## Integration\n\n### With glm-image-gen\n```bash\n# After generating new sprite\n./generate-image.sh ''{\"subject\":\"...\"}'' 1024x1024 standard\n./process-image.sh \"$TEMP\" \"32x32\" \"assets/sprites/output.png\"\n\n# Then analyze quality\nmcp__4_5v_mcp__analyze_image --imageSource \"assets/sprites/output.png\" --prompt \"[standard prompt]\"\n```\n\n### With HPV (Playtesting)\n```bash\n# During screenshot review\nls temp/screenshots/\nmcp__4_5v_mcp__analyze_image --imageSource \"temp/screenshots/world_map.png\" --prompt \"[screenshot prompt]\"\n```\n\n### Pre-commit Check\n```bash\n# Before committing asset changes\ngit status\nmcp__4_5v_mcp__analyze_image --imageSource \"assets/sprites/new_asset.png\" --prompt \"[validation prompt]\"\n```\n\n## Subagent Role\n\nFull subagent configuration: `.claude/roles/image-analysis-subagent.md`\n\n**Model:** GLM-4.6v (vision-capable)\n**Tool:** `mcp__4_5v_mcp__analyze_image`\n**Purpose:** Specialized visual quality assessment\n\n## Success Criteria\n\nAnalysis is effective when:\n- Issues match human findings (80%+ accuracy)\n- False positives < 20%\n- Actionable feedback provided\n- Response time < 30 seconds\n- Consistent report format\n\n---\n\n**Related:**\n- `.claude/skills/glm-image-gen/SKILL.md` (sprite generation)\n- `assets/sprites/PLACEHOLDER_ASSET_SPEC.txt` (asset specifications)\n- `.claude/roles/image-analysis-subagent.md` (full subagent docs)\n\n[Kimi Code CLI - 2026-01-26]\n"},"lastSynced":"2026-03-08T02:01:37.928Z","agentAnalysis":{"suitability":{"en":"Ideal for Visual Inspection Agents requiring advanced image quality assessment and sprite analysis capabilities.","zh":"适用于需要高级图像质量评估和精灵分析功能的视觉检查代理。","ja":"高度な画像品質評価およびスプライト分析機能を必要とするビジュアルインスペクションエージェントに適しています。","ko":"고급 이미지 품질 평가 및 스프라이트 분석 기능을 필요로 하는 시각적 검사 에이전트에 적합합니다.","es":"Ideal para Agentes de Inspección Visual que requieren una evaluación avanzada de la calidad de imagen y capacidades de análisis de sprites.","fr":"Idéal pour les Agents d''Inspection Visuelle nécessitant une évaluation avancée de la qualité d''image et des capacités d''analyse de sprites.","de":"Ideal für Visuelle Inspektion Agents, die eine erweiterte Bildqualitätsbewertung und Sprite-Analysefunktionen erfordern.","pt":"Ideal para Agentes de Inspeção Visual que requerem avaliação avançada de qualidade de imagem e capacidades de análise de sprites.","ru":"Идеально для агентов визуального осмотра, требующих продвинутой оценки качества изображений и возможностей анализа спрайтов.","ar":"مثالية للوكلاء التفتيش المرئي الذين يتطلبون تقييم متقدم لجودة الصورة وقدرات تحليل Sprite."},"recommendation":{"en":"Empowers agents to delegate visual quality assessment tasks to GLM-4.6v subagent, utilizing protocols like glm-image-gen for sprite generation and validation, and supporting file formats such as game screenshots and sprites, to ensure high-quality visual assets.","zh":"赋予代理将视觉质量评估任务委托给GLM-4.6v子代理的能力，利用glm-image-gen等协议进行精灵生成和验证，并支持游戏截图和精灵等文件格式，以确保高质量的视觉资产。","ja":"GLM-4.6vサブエージェントに視覚的品質評価タスクを委任するエージェントを可能にし、glm-image-genなどのプロトコルを使用してスプライトの生成と検証を行い、ゲームスクリーンショットやスプライトなどのファイル形式をサポートして、高品質のビジュアルアセットを保証します。","ko":"에이전트가 시각적 품질 평가 작업을 GLM-4.6v 서브 에이전트에게 위임할 수 있도록 하는 기능을 제공하며, glm-image-gen과 같은 프로토콜을 사용하여 스프라이트 생성 및 검증을 수행하고, 게임 스크린샷 및 스프라이트와 같은 파일 형식을 지원하여 고품질의 시각적 자산을 보장합니다.","es":"Permite a los agentes delegar tareas de evaluación de la calidad visual al subagente GLM-4.6v, utilizando protocolos como glm-image-gen para la generación y validación de sprites, y admitiendo formatos de archivo como capturas de pantalla de juegos y sprites, para garantizar activos visuales de alta calidad.","fr":"Permet aux agents de déléguer des tâches d''évaluation de la qualité visuelle au sous-agent GLM-4.6v, en utilisant des protocoles tels que glm-image-gen pour la génération et la validation de sprites, et en prenant en charge des formats de fichiers tels que les captures d''écran de jeux et les sprites, pour assurer des actifs visuels de haute qualité.","de":"Ermächtigt Agents, visuelle Qualitätsbewertungsaufgaben an den GLM-4.6v-Subagent zu übertragen, indem Protokolle wie glm-image-gen für die Sprite-Generierung und -Validierung verwendet werden und Dateiformate wie Spiel-Screenshots und Sprites unterstützt werden, um hochwertige visuelle Assets sicherzustellen.","pt":"Habilita os agentes a delegar tarefas de avaliação de qualidade visual ao subagente GLM-4.6v, utilizando protocolos como glm-image-gen para geração e validação de sprites, e suportando formatos de arquivo como capturas de tela de jogos e sprites, para garantir ativos visuais de alta qualidade.","ru":"Наделяет агентов возможностью делегировать задачи оценки визуального качества субагенту GLM-4.6v, используя протоколы типа glm-image-gen для генерации и проверки спрайтов, и поддерживая форматы файлов, такие как скриншоты игр и спрайты, для обеспечения высококачественных визуальных активов.","ar":"تمكين الوكلاء من تفويض مهام تقييم الجودة البصرية إلى وكيل فرعي GLM-4.6v ، باستخدام بروتوكولات مثل glm-image-gen لتوليد Sprites والتحقق منها ، ودعم تنسيقات الملفات مثل لقطات الشاشة والألعاب Sprite ، لضمان الموارد البصرية عالية الجودة."},"useCases":{"en":["Automating visual quality validation for game screenshots","Debugging blocky backgrounds or transparency issues in sprites","Comparing game assets against specific styles, such as Harvest Moon SNES","Validating visual quality before commits","Analyzing newly generated sprites"],"zh":["自动化游戏截图的视觉质量验证","调试精灵中的块状背景或透明度问题","将游戏资产与特定风格（如Harvest Moon SNES）进行比较","提交前验证视觉质量","分析新生成的精灵"],"ja":["ゲームスクリーンショットの視覚的品質の検証を自動化する","スプライトのブロック状背景や透明度の問題をデバッグする","ゲームアセットを特定のスタイル（例：Harvest Moon SNES）と比較する","コミット前の視覚的品質を検証する","新しく生成されたスプライトを分析する"],"ko":["게임 스크린샷의 시각적 품질 검증을 자동화하는","스프라이트의 블록状 배경 또는 투명도 문제를 디버깅하는","게임 자산을 특정 스타일(Harvest Moon SNES 등)과 비교하는","커밋 전 시각적 품질을 검증하는","새로 생성된 스프라이트를 분석하는"],"es":["Automatizar la validación de la calidad visual para capturas de pantalla de juegos","Depurar fondos bloqueados o problemas de transparencia en sprites","Comparar activos de juego con estilos específicos, como Harvest Moon SNES","Validar la calidad visual antes de los commits","Analizar sprites recién generados"],"fr":["Automatiser la validation de la qualité visuelle pour les captures d''écran de jeux","Déboguer les fonds bloqués ou les problèmes de transparence dans les sprites","Comparer les actifs de jeu à des styles spécifiques, tels que Harvest Moon SNES","Valider la qualité visuelle avant les commits","Analyser les sprites récemment générés"],"de":["Automatisieren der visuellen Qualitätsvalidierung für Spiel-Screenshots","Debuggen von blockierten Hintergründen oder Transparenzproblemen in Sprites","Vergleichen von Spiel-Assets mit spezifischen Stilen, wie Harvest Moon SNES","Validieren der visuellen Qualität vor Commits","Analysieren von neu generierten Sprites"],"pt":["Automatizar a validação de qualidade visual para capturas de tela de jogos","Depurar fundos quadriculados ou problemas de transparência em sprites","Comparar ativos de jogos com estilos específicos, como Harvest Moon SNES","Validar a qualidade visual antes dos commits","Analizar sprites recém-gerados"],"ru":["Автоматизация проверки визуального качества скриншотов игр","Отладка пиксельных фонов или проблем с прозрачностью спрайтов","Сравнение активов игр с конкретными стилями, такими как Harvest Moon SNES","Проверка визуального качества перед коммитами","Анализ новых сгенерированных спрайтов"],"ar":["تأتمتة التحقق من جودة الصورة للصور المصغرة للألعاب","تصحيح الخلفيات ذات البكسل أو مشاكل الشفافية في Sprites","مقارنة أصول الألعاب بأسلوب معين ، مثل Harvest Moon SNES","التحقق من جودة الصورة قبل الإلتزامات","تحليل Sprites التي تم توليدها حديثًا"]},"limitations":{"en":["Requires GLM-4.6v subagent integration","Specifically designed for game development and testing use cases","May require additional configuration for custom image analysis tasks"],"zh":["需要GLM-4.6v子代理集成","专门为游戏开发和测试用例设计","可能需要额外的配置来实现自定义图像分析任务"],"ja":["GLM-4.6vサブエージェントの統合が必要","ゲーム開発およびテスト用途のために特別に設計されています","カスタム画像分析タスクを実現するために追加のコンフィギュレーションが必要になる場合があります"],"ko":["GLM-4.6v 서브 에이전트 통합이 필요합니다","게임 개발 및 테스트 용도로 특별히 설계되었습니다","사용자 정의 이미지 분석 작업을 수행하기 위해 추가 구성이 필요할 수 있습니다"],"es":["Requiere la integración del subagente GLM-4.6v","Diseñado específicamente para casos de uso de desarrollo y prueba de juegos","Puede requerir configuración adicional para tareas de análisis de imagen personalizadas"],"fr":["Nécessite l''intégration du sous-agent GLM-4.6v","Conçu spécifiquement pour les cas d''utilisation de développement et de test de jeux","Peut nécessiter une configuration supplémentaire pour des tâches d''analyse d''image personnalisées"],"de":["Erfordert die Integration des GLM-4.6v-Subagents","Speziell für Spiel-Entwicklungs- und Testanwendungsfälle konzipiert","Kann zusätzliche Konfiguration für benutzerdefinierte Bildanalysesaufgaben erfordern"],"pt":["Requer integração do subagente GLM-4.6v","Projetado especificamente para casos de uso de desenvolvimento e teste de jogos","Pode requerer configuração adicional para tarefas de análise de imagem personalizadas"],"ru":["Требует интеграции с субагентом GLM-4.6v","Спецально разработан для случаев использования разработки и тестирования игр","Может потребовать дополнительной настройки для пользовательских задач анализа изображений"],"ar":["يتطلب تكامل الوكيل الفرعي GLM-4.6v","صمم خصيصًا لحالات استخدام تطوير وتجريب الألعاب","يمكن أن يتطلب تكوينًا إضافيًا لمهام تحليل الصور المخصصة"]},"version":4},"contentHash":"53f4fcc4ae90f6c0d486dffed571eaf03d3fd8b6350bf74425b52b0a4818ca91","qualityScore":57}');
